function handleKelasDocUpload_(request, session) {
  requirePengurus_(session);
  var kelasId = cleanString_(request.kelasId);
  if (!kelasId) throw createError_('kelasId diperlukan.', 400);

  var state = readSheetState_('kelasSiang');
  var existing = findSheetRowById_(state.rows, kelasId);
  if (!existing) throw createError_('Kelas tidak ditemukan.', 404);

  var dataUrl = cleanString_(request.dataUrl);
  var originalName = cleanString_(request.name) || 'file';

  if (!dataUrl) throw createError_('File data diperlukan.', 400);
  if (dataUrl.length > MAX_KELAS_DOC_BYTES * 1.4) throw createError_('Ukuran file maksimal 20 MB.', 400);

  var match = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) throw createError_('Format file tidak valid.', 400);

  var mimeType = match[1].toLowerCase();
  var bytes = Buffer.from(match[2], 'base64');
  if (bytes.length > MAX_KELAS_DOC_BYTES) throw createError_('Ukuran file maksimal 20 MB.', 400);

  var ext = ALLOWED_KELAS_DOC_MIME_MAP[mimeType];
  if (!ext) {
    var nameParts = originalName.split('.');
    var rawExt = nameParts.length > 1 ? nameParts[nameParts.length - 1].toLowerCase() : '';
    ext = ALLOWED_KELAS_DOC_EXTENSIONS[rawExt];
  }
  if (!ext) throw createError_('Tipe file tidak diizinkan.', 400);

  fs.mkdirSync(KELAS_DOCS_DIR, { recursive: true });
  var safeName = originalName.replace(/[^a-zA-Z0-9._\-]/g, '_').slice(0, 80);
  var filename = kelasId + '-' + Date.now() + '-' + crypto.randomBytes(4).toString('hex') + '-' + safeName;
  if (!filename.endsWith('.' + ext)) filename = filename.replace(/\.[^.]*$/, '') + '.' + ext;
  var filePath = path.join(KELAS_DOCS_DIR, filename);
  fs.writeFileSync(filePath, bytes);

  var existingFiles = [];
  try { existingFiles = JSON.parse(existing.files_json || '[]'); } catch (e) {}
  existingFiles.push({ name: originalName, path: KELAS_DOCS_DIR_NAME + '/' + filename, size: bytes.length, type: mimeType, uploadedAt: nowIso_() });
  updateSheetRow_(state, existing._rowNumber, { files_json: JSON.stringify(existingFiles) });

  return { ok: true, timestamp: nowIso_(), data: { message: 'File berhasil diunggah.', files: existingFiles } };
}

function handleKelasDocDelete_(request, session) {
  requirePengurus_(session);
  var kelasId = cleanString_(request.kelasId);
  var fileIndex = Number(request.fileIndex);
  if (!kelasId) throw createError_('kelasId diperlukan.', 400);
  if (isNaN(fileIndex)) throw createError_('fileIndex diperlukan.', 400);

  var state = readSheetState_('kelasSiang');
  var existing = findSheetRowById_(state.rows, kelasId);
  if (!existing) throw createError_('Kelas tidak ditemukan.', 404);

  var files = [];
  try { files = JSON.parse(existing.files_json || '[]'); } catch (e) {}
  if (fileIndex < 0 || fileIndex >= files.length) throw createError_('File tidak ditemukan.', 404);

  var removed = files.splice(fileIndex, 1)[0];
  if (removed && removed.path) {
    var fullPath = path.join(FRONTEND_DIR, removed.path);
    try { fs.unlinkSync(fullPath); } catch (e) {}
  }

  updateSheetRow_(state, existing._rowNumber, { files_json: JSON.stringify(files) });
  return { ok: true, timestamp: nowIso_(), data: { message: 'File berhasil dihapus.', files: files } };
}

