/* ===================== Input Kelas Level (tingkat/marhalah santri) ===================== */

// Map level santri per tahun ajaran -> { "<santriId>|<taId>": levelString }
function buildSantriKelasLevelMap_() {
  var state = readSheetState_('santriKelasLevel');
  var map = {};
  state.rows.forEach(function (row) {
    if (cleanString_(row.status) === STATUS_LABELS.santriKelasLevel.inactive) return;
    var sid = cleanString_(row.id_santri);
    var taId = cleanString_(row.tahun_ajaran_id);
    if (!sid) return;
    map[sid + '|' + taId] = {
      id: cleanString_(row.id),
      level: cleanString_(row.level),
      rowNumber: row._rowNumber
    };
  });
  return map;
}

function resolveTahunAjaranId_(requestedId, dataset) {
  var list = (dataset.tahunAjaran || []).map(normalizeTahunAjaranSafe_);
  var reqId = cleanString_(requestedId);
  if (reqId && list.some(function (t) { return t.id === reqId; })) return reqId;
  var aktif = list.filter(function (t) { return t.isAktif; })[0];
  if (aktif) return aktif.id;
  return list.length ? list[0].id : '';
}

function normalizeTahunAjaranSafe_(t) {
  // dataset.tahunAjaran sudah dinormalisasi bila lewat loadDataset_; jaga-jaga bila row mentah
  if (t && typeof t.isAktif === 'boolean') return t;
  return normalizeTahunAjaran_(t);
}

function handleKelasLevelKelasList_(request, session) {
  var dataset = loadDataset_();
  var taList = sortTahunAjaranList_((dataset.tahunAjaran || []).map(normalizeTahunAjaranSafe_));
  var tahunAjaranId = resolveTahunAjaranId_(request.tahunAjaranId, dataset);
  var levelMap = buildSantriKelasLevelMap_();
  var statusFilter = cleanString_(request.status).toLowerCase();

  var p = session && session.permissions;
  var isFullAccess = !!(p && (p.isSuperAdmin || p.isAdmin || p.isAcademic));
  var allowedKelasIds = null;
  if (!isFullAccess) {
    allowedKelasIds = {};
    (session && session.kelasIds || []).forEach(function (id) { allowedKelasIds[id] = true; });
  }

  var kelasList = (dataset.kelasSiang || []).filter(function (k) {
    if (statusFilter === 'active' && !k.active) return false;
    if (statusFilter === 'inactive' && k.active) return false;
    if (tahunAjaranId && k.tahunAjaranId !== tahunAjaranId) return false;
    if (allowedKelasIds && !allowedKelasIds[k.id]) return false;
    return true;
  }).map(function (k) {
    var santriIds = k.santriIds || [];
    var filled = 0;
    santriIds.forEach(function (sid) {
      var entry = levelMap[sid + '|' + tahunAjaranId];
      if (entry && entry.level) filled += 1;
    });
    return {
      id: k.id,
      name: k.name,
      jam: k.jam,
      jenis: k.jenis,
      genderGroup: k.genderGroup,
      active: k.active,
      pengajarLabels: (k.pengajarIds || []).map(function (id) { return labelFromIndex_(dataset.indexes.pengurusById, id); }),
      badalLabels: (k.badalIds || []).map(function (id) { return labelFromIndex_(dataset.indexes.pengurusById, id); }),
      santriLabels: santriIds.map(function (id) { return labelFromIndex_(dataset.indexes.santriById, id); }),
      santriCount: santriIds.length,
      filledCount: filled
    };
  }).sort(function (a, b) { return a.name.localeCompare(b.name); });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      tahunAjaranId: tahunAjaranId,
      tahunAjaranList: taList.map(function (t) { return { id: t.id, nama: t.nama, semester: t.semester, namaDisplay: t.namaDisplay, isAktif: t.isAktif }; }),
      kelasList: kelasList
    }
  };
}

function handleKelasLevelSantriList_(request, session) {
  var dataset = loadDataset_();
  var kelasId = cleanString_(request.kelasId || request.id_kelas);
  var tahunAjaranId = resolveTahunAjaranId_(request.tahunAjaranId, dataset);
  var kelas = (dataset.kelasSiang || []).filter(function (k) { return k.id === kelasId; })[0];
  if (!kelas) throw createError_('Kelas tidak ditemukan.', 404);

  var p2 = session && session.permissions;
  if (!(p2 && (p2.isSuperAdmin || p2.isAdmin || p2.isAcademic))) {
    if ((session && session.kelasIds || []).indexOf(kelasId) === -1) {
      throw createError_('Akses ditolak. Kelas ini bukan kelas Anda.', 403);
    }
  }

  var levelMap = buildSantriKelasLevelMap_();
  var santriList = (kelas.santriIds || []).map(function (sid) {
    var s = dataset.indexes.santriById[sid];
    if (!s) return null;
    var entry = levelMap[sid + '|' + tahunAjaranId];
    return {
      id: s.id,
      name: cleanString_(s.name),
      noInduk: cleanString_(s.noInduk),
      level: entry ? entry.level : ''
    };
  }).filter(Boolean).sort(function (a, b) { return a.name.localeCompare(b.name); });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      kelas: { id: kelas.id, name: kelas.name, jenis: kelas.jenis },
      tahunAjaranId: tahunAjaranId,
      santriList: santriList
    }
  };
}

function handleKelasLevelSave_(request, session) {
  var record = parseRecordPayload_(request);
  var dataset = loadDataset_();
  var santriId = cleanString_(record.santriId || record.id_santri);
  var tahunAjaranId = resolveTahunAjaranId_(record.tahunAjaranId, dataset);
  var level = cleanString_(record.level);
  if (!santriId) throw createError_('Santri wajib dipilih.', 400);
  if (!tahunAjaranId) throw createError_('Tahun ajaran wajib dipilih.', 400);
  if (!dataset.indexes.santriById[santriId]) throw createError_('Santri tidak ditemukan.', 404);
  requireTahunAjaranNotLocked_(tahunAjaranId);

  var state = readSheetState_('santriKelasLevel');
  var existing = state.rows.filter(function (r) {
    return cleanString_(r.id_santri) === santriId &&
      cleanString_(r.tahun_ajaran_id) === tahunAjaranId &&
      cleanString_(r.status) !== STATUS_LABELS.santriKelasLevel.inactive;
  })[0] || null;

  var writable = {
    id_santri: santriId,
    tahun_ajaran_id: tahunAjaranId,
    level: level,
    id_pengisi: cleanString_(session.id),
    status: STATUS_LABELS.santriKelasLevel.active,
    updated_at: nowIso_()
  };

  if (existing) {
    updateSheetRow_(state, existing._rowNumber, writable);
  } else {
    writable.id = String(nextId_(state.rows));
    appendSheetRow_(state, writable);
  }

  return { ok: true, timestamp: nowIso_(), data: { message: 'Tingkat kelas santri disimpan.', santriId: santriId, level: level } };
}

