function handlePengurusAutoSetUsernames_(session) {
  requireSuperAdmin_(session);
  var state = readSheetState_('pengurus');
  var usernameSet = {};
  state.rows.forEach(function (row) {
    var u = cleanString_(row.username);
    if (isUsernameValid_(u)) usernameSet[normalizeLoginName_(u)] = true;
  });

  var updated = 0;
  var skipped = 0;
  state.rows.forEach(function (row) {
    if (isUsernameValid_(row.username)) { skipped += 1; return; }
    var base = getValidName_([row.name])
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, '')
      .trim()
      .replace(/\s+/g, '_');
    if (!base || USERNAME_PLACEHOLDER_VALUES.indexOf(base) !== -1) { skipped += 1; return; }
    var candidate = base;
    var suffix = 1;
    while (usernameSet[candidate]) {
      candidate = base + '_' + suffix;
      suffix += 1;
    }
    usernameSet[candidate] = true;
    updateSheetRow_(state, row._rowNumber, { username: candidate });
    updated += 1;
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      updated: updated,
      skipped: skipped,
      message: updated + ' username baru di-set, ' + skipped + ' dilewati (sudah punya username).'
    }
  };
}

function handleClearInvalidUsernames_(session) {
  requireSuperAdmin_(session);
  var santriState = readSheetState_('santri');
  var pengurusState = readSheetState_('pengurus');
  var count = 0;
  santriState.rows.forEach(function (row) {
    var u = cleanString_(row.username);
    if (u && !isUsernameValid_(u)) {
      updateSheetRow_(santriState, row._rowNumber, { username: '' });
      count += 1;
    }
  });
  pengurusState.rows.forEach(function (row) {
    var u = cleanString_(row.username);
    if (u && !isUsernameValid_(u)) {
      updateSheetRow_(pengurusState, row._rowNumber, { username: '' });
      count += 1;
    }
  });
  return {
    ok: true,
    timestamp: nowIso_(),
    data: { count: count, message: count + ' username tidak valid (none/null/dst) berhasil dihapus.' }
  };
}

function handlePengurusExportCredentials_(session, request) {
  requireSuperAdmin_(session);
  var DEFAULT_PASS = 'password123';
  var statusFilter = normalizePengurusStatusFilter_(request && request.status);
  var state = readSheetState_('pengurus');
  var rows = state.rows.filter(function (row) {
    return !statusFilter || getPengurusStatusKey_(row.status) === statusFilter;
  }).map(function (row) {
    var pw = cleanString_(row.password);
    var passwordStatus;
    if (!pw) {
      passwordStatus = 'belum diset';
    } else if (isHashedPassword_(pw)) {
      passwordStatus = bcrypt.compareSync(DEFAULT_PASS, pw) ? 'password123' : 'custom';
    } else {
      passwordStatus = pw === DEFAULT_PASS ? 'password123' : 'custom';
    }
    return {
      nama: cleanString_(row.name),
      username: cleanString_(row.username),
      passwordStatus: passwordStatus,
      status: normalizeStatusForSheet_('pengurus', row.status || 'Active')
    };
  });
  return {
    ok: true,
    timestamp: nowIso_(),
    data: { rows: rows }
  };
}

