// Daftar nama pengurus aktif saja (tanpa detail lain) — dipakai utk autocomplete/datalist di form bebas-teks
// (mis. "Nama Penguji" di ujianHafalan), jadi sengaja dibuka utk semua pengurus (bukan hanya yg bisa
// kelola data pengurus, beda dgn handlePengurusDropdown_ yg mengembalikan data lebih lengkap).
function handlePengurusNamesList_() {
  var dataset = loadDataset_();
  var names = uniqueList_(dataset.pengurus.filter(function (p) { return p.active; }).map(function (p) { return cleanString_(p.name); }).filter(Boolean));
  names.sort(function (a, b) { return a.localeCompare(b, 'id'); });
  return { ok: true, timestamp: nowIso_(), data: { names: names } };
}

function handlePengurusDropdown_() {
  var dataset = loadDataset_();
  var items = dataset.pengurus
    .filter(function (p) { return p.active !== false && cleanString_(p.status || '').toLowerCase() !== 'inactive'; })
    .map(function (p) {
      var enriched = enrichPengurus_(p, dataset);
      return {
        id: enriched.id,
        name: enriched.name,
        jabatanLabels: enriched.jabatanLabels,
        primaryJabatanLabel: enriched.primaryJabatanLabel,
        jabatanDisplay: enriched.jabatanLabels.length ? enriched.jabatanLabels.join(', ') : ''
      };
    });
  items.sort(function (a, b) { return (a.name || '').localeCompare(b.name || '', 'id'); });
  return { ok: true, timestamp: nowIso_(), data: { items: items } };
}

