function handleHalaqohAttendanceGet_(request, session) {
  var dataset = loadDataset_();
  var requestedRecordId = cleanString_(request.id || request.recordId);
  var requestedDate = cleanString_(request.tanggal);
  var targetDate = requestedDate ? normalizeDateOnly_(requestedDate) : nowIso_().slice(0, 10);
  var halaqohId = cleanString_(request.halaqohId || request.id_halaqoh);
  var requestedWindowSize = normalizeHalaqohAttendanceWindowSize_(request.windowSize || request.days || request.jumlahHari);
  var targetRecord = null;

  if (requestedDate && !targetDate) {
    throw createError_('Tanggal absensi tidak valid.', 400);
  }

  if (requestedRecordId) {
    targetRecord = dataset.absensiHalaqoh.filter(function (item) {
      return item.active && cleanString_(item.id) === requestedRecordId;
    })[0] || null;
    if (!targetRecord) {
      throw createError_('Data absensi halaqoh tidak ditemukan.', 404);
    }
    halaqohId = targetRecord.halaqohId;
    if (!requestedDate) {
      targetDate = targetRecord.tanggal;
    }
  }

  var halaqoh = findAccessibleHalaqohAttendanceItem_(session, halaqohId, dataset);
  if (!halaqoh) {
    throw createError_('Halaqoh yang dipilih tidak ditemukan atau tidak dapat diakses.', 404);
  }

  var halaqohRecords = dataset.absensiHalaqoh.filter(function (item) {
    return item.active && cleanString_(item.halaqohId) === halaqoh.id;
  });

  // Jika request spesifik satu record (untuk copy-latest), kembalikan record tunggal.
  if (requestedRecordId) {
    return {
      ok: true,
      timestamp: nowIso_(),
      data: {
        halaqoh: buildHalaqohAttendanceCardView_(halaqoh, halaqohRecords, dataset, nowIso_().slice(0, 10)),
        record: buildHalaqohAttendanceEditorRecord_(targetRecord, halaqoh, dataset, targetDate)
      }
    };
  }

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      halaqoh: buildHalaqohAttendanceCardView_(halaqoh, halaqohRecords, dataset, nowIso_().slice(0, 10)),
      window: buildHalaqohAttendanceWindowViewAllSesi_(halaqohRecords, halaqoh, dataset, targetDate, requestedWindowSize)
    }
  };
}

function handleHalaqohAttendanceSave_(request, session) {
  var dataset = loadDataset_();
  var record = parseRecordPayload_(request);
  var halaqohId = cleanString_(record.halaqohId || record.id_halaqoh);
  var halaqoh = findAccessibleHalaqohAttendanceItem_(session, halaqohId, dataset);

  if (!halaqoh) {
    throw createError_('Halaqoh yang dipilih tidak ditemukan atau tidak dapat diakses.', 404);
  }
  var tanggal = assertValidDateOnly_(record.tanggal, 'Tanggal absensi');
  requireTahunAjaranNotLocked_(cleanString_(halaqoh.tahunAjaranId || halaqoh.tahun_ajaran_id));

  var sesi = normalizeHalaqohSesi_(record.sesi);
  var santriPayload = buildHalaqohAttendanceSantriPayload_(halaqoh, dataset, tanggal);
  var santriIdMap = {};
  santriPayload.items.forEach(function (item) {
    santriIdMap[item.id] = true;
  });

  var state = readSheetState_('absensiHalaqoh');
  var requestedId = cleanString_(record.id);
  var existingRow = requestedId ? findSheetRowById_(state.rows, requestedId) : null;
  // Dedup hanya dalam (halaqoh, tanggal, SESI) yang sama — sesi lain pada hari yang sama dipertahankan.
  var sameDaySesiRows = state.rows.filter(function (row) {
    return cleanString_(row.id_halaqoh) === halaqoh.id &&
      normalizeDateOnly_(row.tanggal) === tanggal &&
      normalizeHalaqohSesi_(row.sesi) === sesi;
  });
  var targetRow = requestedId && existingRow ? existingRow : (sameDaySesiRows[0] || null);

  if (requestedId && !existingRow) {
    throw createError_('Data absensi halaqoh yang akan diubah tidak ditemukan.', 404);
  }
  if (existingRow && cleanString_(existingRow.id_halaqoh) !== halaqoh.id) {
    throw createError_('Data absensi halaqoh tidak sesuai dengan halaqoh aktif.', 403);
  }
  if (existingRow && (normalizeDateOnly_(existingRow.tanggal) !== tanggal || normalizeHalaqohSesi_(existingRow.sesi) !== sesi) && sameDaySesiRows.length) {
    targetRow = sameDaySesiRows[0];
  }

  var normalizedEntries = normalizeHalaqohAbsensiEntries_(record.entries || record.data_absensi);
  var entryMap = mapHalaqohAttendanceEntries_(normalizedEntries.filter(function (entry) {
    return !!santriIdMap[entry.id_santri];
  }));
  var mergedEntries = santriPayload.items.map(function (santri) {
    var source = entryMap[santri.id] || {};
    return {
      id_santri: santri.id,
      status: normalizeAttendanceStatusOptional_(source.status),
      keterangan: cleanString_(source.keterangan)
    };
  });

  // Santri yang sudah dikeluarkan dari halaqoh tapi punya riwayat absensi di record ini
  // (targetRow) tetap dipertahankan — boleh diedit lewat payload, tapi tidak bisa dibuatkan
  // entri baru kalau sebelumnya belum pernah tercatat.
  if (targetRow) {
    var previousEntries = mapHalaqohAttendanceEntries_(normalizeHalaqohAbsensiEntries_(targetRow.data_absensi));
    var submittedEntryMap = mapHalaqohAttendanceEntries_(normalizedEntries);
    Object.keys(previousEntries).forEach(function (sid) {
      if (santriIdMap[sid]) {
        return;
      }
      // Bedakan "santri ini tidak disertakan di payload" (pertahankan apa adanya) dari
      // "disertakan dengan status dikosongkan" (harus bisa dikosongkan) -- sebelumnya pakai
      // `||` yang membuat status/keterangan kosong selalu jatuh balik ke nilai lama, jadi
      // status yang sudah terlanjur salah (mis. tercatat sebelum santri pindah halaqoh)
      // tidak bisa dihapus/dikosongkan, cuma bisa diganti ke status lain yang non-kosong.
      var hasEdit = Object.prototype.hasOwnProperty.call(submittedEntryMap, sid);
      var edited = submittedEntryMap[sid] || {};
      mergedEntries.push({
        id_santri: sid,
        status: hasEdit ? edited.status : previousEntries[sid].status,
        keterangan: hasEdit ? edited.keterangan : previousEntries[sid].keterangan
      });
    });
  }

  var writable = pickWritableValues_(record, state.schema.columns);
  writable.tanggal = tanggal;
  writable.sesi = String(sesi);
  writable.id_halaqoh = halaqoh.id;
  writable.id_pengurus_input = cleanString_(session.id);
  writable.catatan = cleanString_(record.catatan);
  writable.data_absensi = stringifyJsonValue_(mergedEntries);
  writable.status = normalizeStatusForSheet_(
    'absensiHalaqoh',
    writable.status || (targetRow ? targetRow.status : STATUS_LABELS.absensiHalaqoh.active)
  );

  if (targetRow) {
    updateSheetRow_(state, targetRow._rowNumber, writable);
    sameDaySesiRows.filter(function (row) {
      return row._rowNumber !== targetRow._rowNumber;
    }).forEach(function (row) {
      deleteSheetRows_(state, [row._rowNumber]);
    });
    return {
      ok: true,
      timestamp: nowIso_(),
      data: {
        id: cleanString_(targetRow.id || requestedId),
        message: 'Absensi halaqoh berhasil diperbarui.',
        summary: summarizeHalaqohAttendanceEntries_(mergedEntries, santriPayload.items.map(function (item) { return item.id; }))
      }
    };
  }

  writable.id = String(nextId_(state.rows));
  appendSheetRow_(state, writable);
  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      id: writable.id,
      message: 'Absensi halaqoh berhasil ditambahkan.',
      summary: summarizeHalaqohAttendanceEntries_(mergedEntries, santriPayload.items.map(function (item) { return item.id; }))
    }
  };
}

