function saveUploadedProfilePhoto_(record, accountType, displayName) {
  var dataUrl = cleanString_(record.photo_file_data_url || record.photoFileDataUrl);
  if (!dataUrl) {
    return '';
  }

  var match = dataUrl.match(/^data:([^;,]+);base64,([a-z0-9+/=\s]+)$/i);
  if (!match) {
    throw createError_('Format file foto profil tidak valid.', 400);
  }

  var mimeType = cleanString_(record.photo_file_type || record.photoFileType || match[1]).toLowerCase();
  var fileName = cleanString_(record.photo_file_name || record.photoFileName);
  var extension = resolveProfilePhotoExtension_(mimeType, fileName);
  if (!extension) {
    throw createError_('Foto profil harus berupa PNG, JPG, WEBP, atau GIF.', 400);
  }

  var bytes = Buffer.from(match[2].replace(/\s+/g, ''), 'base64');
  if (!bytes.length) {
    throw createError_('File foto profil kosong.', 400);
  }
  if (bytes.length > MAX_PROFILE_PHOTO_BYTES) {
    throw createError_('Ukuran foto profil maksimal 5 MB.', 400);
  }

  fs.mkdirSync(PROFILE_PHOTO_DIR, { recursive: true });
  var filename = sanitizeProfilePhotoStem_(accountType, displayName || fileName || 'photo') + '-' + Date.now() + '-' + crypto.randomBytes(4).toString('hex') + '.' + extension;
  fs.writeFileSync(path.join(PROFILE_PHOTO_DIR, filename), bytes);
  return PROFILE_PHOTO_DIR_NAME + '/' + filename;
}

function saveSantriDoc_(dataUrl, fileName, santriId, fieldKey) {
  var match = dataUrl.match(/^data:([^;,]+);base64,(.+)$/);
  if (!match) throw createError_('Format file dokumen tidak valid.', 400);
  var mimeType = match[1].toLowerCase();
  var bytes = Buffer.from(match[2], 'base64');
  if (bytes.length > MAX_SANTRI_DOC_BYTES) throw createError_('Ukuran file dokumen maksimal 20 MB.', 400);
  var ext = ALLOWED_SANTRI_DOC_MIME_MAP[mimeType];
  if (!ext && fileName) {
    var parts = fileName.split('.');
    var rawExt = parts.length > 1 ? parts[parts.length - 1].toLowerCase() : '';
    ext = ALLOWED_SANTRI_DOC_EXTENSIONS[rawExt];
  }
  if (!ext) throw createError_('Tipe file tidak diizinkan. Gunakan JPG, PNG, WEBP, atau PDF.', 400);
  fs.mkdirSync(SANTRI_DOCS_DIR, { recursive: true });
  var stem = (fieldKey || 'doc') + '-' + (santriId || 'new') + '-' + Date.now() + '-' + crypto.randomBytes(4).toString('hex');
  var filename = stem + '.' + ext;
  fs.writeFileSync(path.join(SANTRI_DOCS_DIR, filename), bytes);
  return SANTRI_DOCS_DIR_NAME + '/' + filename;
}

function deleteSantriDoc_(fileUrl) {
  if (!fileUrl) return;
  var targetPath = path.join(FRONTEND_DIR, fileUrl);
  var root = path.resolve(SANTRI_DOCS_DIR) + path.sep;
  if (path.resolve(targetPath).indexOf(root) !== 0) return;
  try { fs.unlinkSync(targetPath); } catch (_) {}
}

