    organizationEmail: normalizePortalBrandEmail_(row && row.organization_email),
    organizationWebsite: normalizePortalBrandWebsite_(row && row.organization_website),
    landingGalleryTitle: normalizePortalLandingGalleryTitle_(row && row.landing_gallery_title),
    landingGallerySubtitle: normalizePortalLandingGallerySubtitle_(row && row.landing_gallery_subtitle),
    carouselItems: normalizePortalCarouselItems_(row && row.landing_carousel_json),
