function handleExportData_(request, session) {
  var sheetKeys = parseSheetKeyList_(request.sheetKeys || request.sheetKey);
  if (!sheetKeys.length || (sheetKeys.length === 1 && sheetKeys[0] === 'all')) {
    if (!session.permissions || !session.permissions.canExportAll) {
      throw createError_('Download semua data hanya untuk Super Admin.', 403);
    }
    sheetKeys = getExportableSheetKeys_();
  }

  var datasets = {};
  sheetKeys.forEach(function (sheetKey) {
    sheetKey = normalizeSheetKey_(sheetKey);
    authorizeSheetRead_(session, sheetKey);
    var state = readSheetState_(sheetKey);
    var exportColumns = state.columns.filter(function (column) {
      if ((sheetKey === 'pengurus' || sheetKey === 'santri') && column.key === 'photo_url') {
        return false;
      }
      if (sheetKey === 'kegiatanSop' && (column.key === 'id_pengurus' || column.key === 'id_pengurus_utama')) {
        return false;
      }
      return true;
    });
    datasets[sheetKey] = {
      sheetName: state.schema.sheetName,
      columns: exportColumns.map(function (column) {
        return {
          key: column.key,
          header: column.header
        };
      }),
      rows: state.rows.map(function (row) {
        var output = {};
        exportColumns.forEach(function (column) {
          output[column.key] = row[column.key];
        });
        return output;
      })
    };
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      sheetKeys: sheetKeys,
      datasets: datasets
    }
  };
}

// Versi ringan loadDataset_() khusus buat buildReferencePayload_(): cuma baca 7 tabel yang
// benar-benar dipakai buat isi dropdown/filter (pengurus, santri, jabatan, halaqoh, kelasSiang,
// regu, tahunAjaran), bukan 18 tabel penuh. Action 'references' dipanggil tiap kali salah satu
// dari 5 halaman (santriSakit, survey, pelanggaran, pengumuman, izinPulang) dibuka, jadi 11 tabel
// lain (absensi*/nilaiUp/kegiatanSop*/content/halaqohTasmi/pengurus_jabatan) yang dibaca+
// dinormalize tapi langsung dibuang di buildReferencePayload_() lama, sekarang tidak ikut dibaca.
function loadReferenceDataset_() {
  var pengurusState = readSheetState_('pengurus');
  var santriState = readSheetState_('santri');
  var jabatanState = readSheetState_('jabatan');
  var halaqohState = readSheetState_('halaqoh');
  var kelasState = readSheetState_('kelasSiang');
  var reguState = readSheetState_('regu');
  var tahunAjaranState = readSheetState_('tahunAjaran');

  return {
    pengurus: pengurusState.rows.map(normalizePengurus_),
    santri: santriState.rows.map(normalizeSantri_),
    jabatan: jabatanState.rows.map(normalizeJabatan_),
    halaqoh: halaqohState.rows.map(normalizeHalaqoh_),
    kelasSiang: kelasState.rows.map(normalizeKelas_),
    regu: reguState.rows.map(normalizeRegu_),
    tahunAjaran: sortTahunAjaranList_(tahunAjaranState.rows.map(normalizeTahunAjaran_))
  };
}

function buildReferencePayload_() {
  var dataset = loadReferenceDataset_();
  return {
    pengurus: dataset.pengurus.filter(function (item) { return item.active; }).map(function (item) {
      return { id: item.id, name: item.name, username: item.username, status: item.status, statusLabel: getPengurusStatusKey_(item.status) === 'dibekukan' ? 'Dibekukan' : 'Aktif' };
    }),
    santri: dataset.santri.filter(function (item) { return item.active; }).map(function (item) {
      // namaLain = varian nama yang TIDAK ditampilkan (biar pencarian di checklist picker
      // tetap bisa cocok ke nama KK/akte/panggilan walau yang tampil nama-setelah-diubah).
      var namaLain = [item.namaSetelahDiubah, item.namaLengkapKk, item.namaLengkap, item.namaPanggilan]
        .filter(function (x) { return x && cleanString_(x).toLowerCase() !== cleanString_(item.name).toLowerCase(); })
        .join(' ');
      return { id: item.id, name: item.name, namaLain: namaLain, noInduk: item.noInduk, status: item.status, statusLabel: getSantriStatusKey_(item.status) === 'dibekukan' ? 'Dibekukan' : 'Aktif' };
    }),
    jabatan: dataset.jabatan.filter(function (item) { return item.active; }).map(function (item) {
      return { id: item.id, name: item.name, level: item.level };
    }),
    halaqoh: dataset.halaqoh.filter(function (item) { return item.active; }).map(function (item) {
      return { id: item.id, name: item.name, genderGroup: item.genderGroup };
    }),
    kelas: dataset.kelasSiang.filter(function (item) { return item.active; }).map(function (item) {
      return { id: item.id, name: item.name, jam: item.jam, genderGroup: item.genderGroup };
    }),
    regu: dataset.regu.filter(function (item) { return item.active; }).map(function (item) {
      return { id: item.id, name: item.name, genderGroup: item.genderGroup };
    }),
    attendanceStatusOptions: ['hadir', 'sakit', 'izin', 'alfa', 'tugas', 'hari_tidak_aktif'],
    attendanceDayOptions: ['aktif', 'libur', 'nonaktif'],
    contentStatusOptions: [STATUS_LABELS.content.active, STATUS_LABELS.content.inactive],
    contentTargetRoleOptions: ['pengurus', 'umum', 'santri'],
    genderGroupOptions: [
      ENTITY_GENDER_GROUP_LABELS.ikhwan,
      ENTITY_GENDER_GROUP_LABELS.akhowat,
      ENTITY_GENDER_GROUP_LABELS.campur,
      ENTITY_GENDER_GROUP_LABELS.none
    ],
    statusOptions: {
      common: ['Active', 'Dibekukan', 'Inactive'],
      lokal: ['Aktif', 'Nonaktif']
    },
    tahunAjaran: dataset.tahunAjaran.map(function (item) {
      return { id: item.id, nama: item.nama, semester: item.semester, namaDisplay: item.namaDisplay, tanggalMulai: item.tanggalMulai, tanggalSelesai: item.tanggalSelesai, isAktif: item.isAktif, isLocked: item.isLocked };
    })
  };
}

function buildScopedReferencePayload_(sheetKey, session) {
  var full = buildReferencePayload_();
  // Jabatan super admin tidak boleh muncul di daftar pilihan manapun
  var superKws = ACCESS_CONTROL.superAdminJabatanKeywords || [];
  var filteredFull = superKws.length ? Object.assign({}, full, {
    jabatan: full.jabatan.filter(function (j) {
      var jName = normalizeAccessText_(j.name || '');
      return !superKws.some(function (kw) { return jName.indexOf(normalizeAccessText_(kw)) !== -1; });
    })
  }) : full;
  var perms = (session && session.permissions) || {};
  var isAdminOrSuper = !!(perms.canDelete || perms.isAdmin);
  if (!sheetKey) return filteredFull;
  if (isAdminOrSuper) return filteredFull;
  var base = {
    genderGroupOptions: full.genderGroupOptions,
    statusOptions: full.statusOptions,
    attendanceStatusOptions: full.attendanceStatusOptions,
    attendanceDayOptions: full.attendanceDayOptions,
    contentStatusOptions: full.contentStatusOptions,
    contentTargetRoleOptions: full.contentTargetRoleOptions,
  };
  switch (normalizeSheetKey_(sheetKey)) {
    case 'halaqoh':
      return Object.assign({}, base, { pengurus: full.pengurus, santri: full.santri, halaqoh: full.halaqoh, tahunAjaran: full.tahunAjaran });
    case 'halaqohTasmi':
      return Object.assign({}, base, { pengurus: full.pengurus, santri: full.santri, tahunAjaran: full.tahunAjaran });
    case 'kelassiang':
      return Object.assign({}, base, { pengurus: full.pengurus, santri: full.santri, kelas: full.kelas, tahunAjaran: full.tahunAjaran });
    case 'regu':
      return Object.assign({}, base, { pengurus: full.pengurus, santri: full.santri, regu: full.regu, tahunAjaran: full.tahunAjaran });
    case 'santri':
      return Object.assign({}, base, { halaqoh: full.halaqoh, kelas: full.kelas, regu: full.regu, tahunAjaran: full.tahunAjaran });
    case 'absensi':
      return Object.assign({}, base, { pengurus: full.pengurus });
    default:
      return full;
  }
}

function loadDataset_() {
  var pengurusState = readSheetState_('pengurus');
  var jabatanState = readSheetState_('jabatan');
  var pengurusJabatanState = readSheetState_('pengurus_jabatan');
  var santriState = readSheetState_('santri');
  var halaqohState = readSheetState_('halaqoh');
  var halaqohTasmiState = readSheetState_('halaqohTasmi');
  var kelasState = readSheetState_('kelasSiang');
  var reguState = readSheetState_('regu');
  var nilaiUpState = readSheetState_('nilaiUp');
  var absensiGuruState = readSheetState_('absensiGuru');
  var absensiHalaqohState = readSheetState_('absensiHalaqoh');
  var absensiKelasState = readSheetState_('absensiKelas');
  var absensiReguState = readSheetState_('absensiRegu');
  var kegiatanSopState = readSheetState_('kegiatanSop');
  var kegiatanSopItemState = readSheetState_('kegiatanSopItem');
  var kegiatanSopLampiranState = readSheetState_('kegiatanSopLampiran');
  var contentState = readSheetState_('content');
  var tahunAjaranState = readSheetState_('tahunAjaran');

  var dataset = {
    states: {
      pengurus: pengurusState,
      jabatan: jabatanState,
      pengurus_jabatan: pengurusJabatanState,
      santri: santriState,
      halaqoh: halaqohState,
      halaqohTasmi: halaqohTasmiState,
      kelasSiang: kelasState,
      regu: reguState,
      nilaiUp: nilaiUpState,
      absensiGuru: absensiGuruState,
      absensiHalaqoh: absensiHalaqohState,
      absensiKelas: absensiKelasState,
      absensiRegu: absensiReguState,
      kegiatanSop: kegiatanSopState,
      kegiatanSopItem: kegiatanSopItemState,
      kegiatanSopLampiran: kegiatanSopLampiranState,
      content: contentState,
      tahunAjaran: tahunAjaranState
    },
    pengurus: pengurusState.rows.map(normalizePengurus_),
    jabatan: jabatanState.rows.map(normalizeJabatan_),
    pengurusJabatan: pengurusJabatanState.rows.map(normalizePengurusJabatan_),
    santri: santriState.rows.map(normalizeSantri_),
    halaqoh: halaqohState.rows.map(normalizeHalaqoh_),
    halaqohTasmi: halaqohTasmiState.rows.map(normalizeHalaqohTasmi_),
    kelasSiang: kelasState.rows.map(normalizeKelas_),
    regu: reguState.rows.map(normalizeRegu_),
    nilaiUp: nilaiUpState.rows.map(normalizeNilaiUp_),
    absensiGuru: absensiGuruState.rows.map(normalizeAbsensiGuru_),
    absensiHalaqoh: absensiHalaqohState.rows.map(normalizeAbsensiHalaqoh_),
    absensiKelas: absensiKelasState.rows.map(normalizeAbsensiKelas_),
    absensiRegu: absensiReguState.rows.map(normalizeAbsensiRegu_),
    kegiatanSop: kegiatanSopState.rows.map(normalizeKegiatanSop_),
    kegiatanSopItems: kegiatanSopItemState.rows.map(normalizeKegiatanSopItem_),
    kegiatanSopLampiran: kegiatanSopLampiranState.rows.map(normalizeKegiatanSopLampiran_),
    content: contentState.rows.map(normalizeContent_),
    tahunAjaran: sortTahunAjaranList_(tahunAjaranState.rows.map(normalizeTahunAjaran_))
  };

  dataset.indexes = {
    pengurusById: indexById_(dataset.pengurus),
    jabatanById: indexById_(dataset.jabatan),
    santriById: indexById_(dataset.santri),
    halaqohById: indexById_(dataset.halaqoh),
    halaqohTasmiById: indexById_(dataset.halaqohTasmi),
    kelasById: indexById_(dataset.kelasSiang),
    reguById: indexById_(dataset.regu),
    nilaiUpById: indexById_(dataset.nilaiUp),
    absensiGuruById: indexById_(dataset.absensiGuru),
    absensiHalaqohById: indexById_(dataset.absensiHalaqoh),
    absensiKelasById: indexById_(dataset.absensiKelas),
    absensiReguById: indexById_(dataset.absensiRegu),
    kegiatanSopById: indexById_(dataset.kegiatanSop),
    kegiatanSopItemById: indexById_(dataset.kegiatanSopItems),
    kegiatanSopLampiranById: indexById_(dataset.kegiatanSopLampiran),
    contentById: indexById_(dataset.content),
    tahunAjaranById: indexById_(dataset.tahunAjaran)
  };

  dataset.jabatanByPengurus = {};
  dataset.pengurusJabatan.forEach(function (row) {
    if (!dataset.jabatanByPengurus[row.idPengurus]) {
      dataset.jabatanByPengurus[row.idPengurus] = [];
    }
    dataset.jabatanByPengurus[row.idPengurus].push(row);
  });

  dataset.membership = buildMembershipMaps_(dataset);
  dataset.tahunAjaranAktif = dataset.tahunAjaran.filter(function (t) { return t.isAktif; })[0] || null;
  dataset.membershipAktifTa = dataset.tahunAjaranAktif ? buildMembershipMaps_(dataset, dataset.tahunAjaranAktif.id) : dataset.membership;
  return dataset;
}

