// Persen bobot akumulasi: angka 0–100 (boleh desimal), default 0 = tidak ikut akumulasi.
function clampPersen_(value) {
  var p = parseFloat(value);
  if (isNaN(p) || p <= 0) return 0;
  if (p > 100) p = 100;
  return Math.round(p * 100) / 100;
}

