// Sesi absensi halaqoh: 1–4 (default 1). Satu hari bisa ada 4 sesi absensi.
function normalizeHalaqohSesi_(value) {
  var n = parseInt(cleanString_(value), 10);
  if (isNaN(n) || n < 1) return 1;
  if (n > 4) return 4;
  return n;
}

// `entries` di-parse lazy (baru JSON.parse saat betul-betul diakses) karena mayoritas
// pemanggil (dashboard/audit) cuma butuh tanggal/status per baris riwayat, bukan detail
// entri per santri -- baris riwayat absensi menumpuk terus tiap hari jadi parse eager
// di sini kena ke semua histori tiap kali dataset dimuat, bukan cuma yang dibutuhkan.
function defineLazyEntries_(target, row) {
  var cached = null;
  Object.defineProperty(target, 'entries', {
    enumerable: true,
    get: function () {
      if (cached === null) cached = normalizeHalaqohAbsensiEntries_(row.data_absensi);
      return cached;
    }
  });
  return target;
}

