// Urutan manual (aktif selalu di posisi teratas); baris tanpa urutan tenggelam ke bawah, tie-break tanggal_mulai terbaru.
function sortTahunAjaranList_(list) {
  return list.slice().sort(function (a, b) {
    if (a.isAktif && !b.isAktif) return -1;
    if (!a.isAktif && b.isAktif) return 1;
    var ua = a.urutan === null || a.urutan === undefined ? Infinity : a.urutan;
    var ub = b.urutan === null || b.urutan === undefined ? Infinity : b.urutan;
    if (ua !== ub) return ua - ub;
    return (b.tanggalMulai || '').localeCompare(a.tanggalMulai || '');
  });
}

function requireTahunAjaranNotLocked_(tahunAjaranId) {
  if (!tahunAjaranId) return;
  var state = readSheetState_('tahunAjaran');
  var row = findSheetRowById_(state.rows, tahunAjaranId);
  if (!row) return;
  if (row.is_locked === '1' || row.is_locked === 1 || row.is_locked === true) {
    throw createError_('Tidak dapat mengubah data: tahun ajaran berstatus Close (terkunci).', 403);
  }
}

