// Rekonstruksi keanggotaan halaqoh "per tanggal tertentu" berdasarkan riwayatPindahHalaqoh —
// dipakai supaya form absensi utk tanggal lampau tetap menampilkan santri yang saat itu
// masih/sudah jadi anggota, walau keanggotaan SEKARANG sudah berubah karena mutasi setelahnya.
// Cuma bisa merekonstruksi mutasi yang lewat halaqoh.pindahkanSantri (yang tercatat dgn
// tanggal pasti) — mutasi lewat edit manual halaqoh.save tidak punya tanggal utk ditelusuri.
// Inti rekonstruksi, dipisah dari computeHalaqohMembershipIdsAsOfDate_ supaya pemanggil yang
// butuh mengulang rekonstruksi utk BANYAK tanggal sekaligus (mis. audit gap hafalanHarian yang
// mengecek tiap hari sejak awal TA) bisa baca riwayatPindahHalaqoh SEKALI lalu pakai ulang
// array-nya, bukan query ulang tabel di tiap iterasi tanggal x halaqoh.
function reconstructHalaqohMembershipIds_(currentIds, halaqohId, pindahRows, asOfDate) {
  var idSet = {};
  (currentIds || []).forEach(function (id) { idSet[cleanString_(id)] = true; });
  pindahRows.forEach(function (r) {
    // Mutasi yang dinonaktifkan dianggap tidak pernah terjadi utk rekonstruksi ini —
    // mis. kalau ternyata dicatat keliru, menonaktifkannya otomatis "membatalkan" efeknya
    // di audit absensi tanpa perlu ubah data lain secara manual. Mutasi yang dihapus
    // permanen otomatis sudah tidak ada lagi di sini sama sekali.
    if (!isActiveStatus_(r.status)) return;
    var tanggalPindah = normalizeDateOnly_(r.tanggal_pindah);
    // Mutasi yang terjadi pada/sebelum tanggal target sudah tercermin di keanggotaan
    // sekarang (kalau belum ada mutasi lain sesudahnya) — cuma mutasi yg terjadi SETELAH
    // tanggal target yang perlu "dibatalkan" utk merekonstruksi kondisi saat itu.
    if (!tanggalPindah || tanggalPindah <= asOfDate) return;
    var sid = cleanString_(r.id_santri);
    if (!sid) return;
    if (cleanString_(r.id_halaqoh_tujuan) === halaqohId) {
      delete idSet[sid];
    }
    if (cleanString_(r.id_halaqoh_asal) === halaqohId) {
      idSet[sid] = true;
    }
  });
  return Object.keys(idSet);
}

// Rekonstruksi keanggotaan halaqoh "per tanggal tertentu" berdasarkan riwayatPindahHalaqoh —
// dipakai supaya form absensi utk tanggal lampau tetap menampilkan santri yang saat itu
// masih/sudah jadi anggota, walau keanggotaan SEKARANG sudah berubah karena mutasi setelahnya.
// Cuma bisa merekonstruksi mutasi yang lewat halaqoh.pindahkanSantri (yang tercatat dgn
// tanggal pasti) — mutasi lewat edit manual halaqoh.save tidak punya tanggal utk ditelusuri.
function computeHalaqohMembershipIdsAsOfDate_(halaqoh, asOfDate) {
  var currentIds = (halaqoh && halaqoh.santriIds ? halaqoh.santriIds : []);
  var d = normalizeDateOnly_(asOfDate);
  if (!d) return currentIds;
  return reconstructHalaqohMembershipIds_(currentIds, halaqoh.id, readSheetState_('riwayatPindahHalaqoh').rows, d);
}

function buildHalaqohAttendanceSantriPayload_(halaqoh, dataset, asOfDate) {
  var seen = {};
  var inactiveAssignedCount = 0;
  var items = [];
  var memberIds = asOfDate
    ? computeHalaqohMembershipIdsAsOfDate_(halaqoh, asOfDate)
    : (halaqoh && halaqoh.santriIds ? halaqoh.santriIds : []);

  (memberIds || []).forEach(function (santriId) {
    var targetId = cleanString_(santriId);
    var santri = dataset && dataset.indexes && dataset.indexes.santriById
      ? dataset.indexes.santriById[targetId]
      : null;
    if (!targetId || seen[targetId]) {
      return;
    }
    seen[targetId] = true;
    if (!santri || !santri.active) {
      inactiveAssignedCount += 1;
      return;
    }
    items.push({
      id: santri.id,
      name: santri.name,
      noInduk: santri.noInduk,
      photoUrl: santri.photoUrl || ''
    });
  });

  items.sort(function (a, b) {
    return [a.name || '', a.noInduk || '', a.id || ''].join('||').localeCompare([b.name || '', b.noInduk || '', b.id || ''].join('||'));
  });

  return {
    items: items,
    inactiveAssignedCount: inactiveAssignedCount
  };
}

// Santri yang pernah punya riwayat absensi di halaqoh ini tapi sudah dikeluarkan dari
// keanggotaan halaqoh (bukan yang dinonaktifkan/dihapus secara global). Dipakai supaya
// nama + riwayat absensi lama mereka tetap tampil dan bisa diedit, tanpa mengizinkan
// entri absensi baru untuk mereka.
function buildHalaqohFormerMembers_(halaqoh, dataset) {
  var currentIds = {};
  (halaqoh && halaqoh.santriIds ? halaqoh.santriIds : []).forEach(function (id) {
    currentIds[cleanString_(id)] = true;
  });

  var seen = {};
  var items = [];
  (dataset.absensiHalaqoh || []).filter(function (row) {
    return row.active && cleanString_(row.halaqohId) === halaqoh.id;
  }).forEach(function (row) {
    (row.entries || []).forEach(function (entry) {
      var sid = cleanString_(entry.id_santri);
      if (!sid || currentIds[sid] || seen[sid]) {
        return;
      }
      var santri = dataset.indexes.santriById[sid];
      if (!santri || !santri.active) {
        return;
      }
      seen[sid] = true;
      items.push({ id: santri.id, name: santri.name, noInduk: santri.noInduk, photoUrl: santri.photoUrl || '' });
    });
  });

  items.sort(function (a, b) {
    return [a.name || '', a.noInduk || '', a.id || ''].join('||').localeCompare([b.name || '', b.noInduk || '', b.id || ''].join('||'));
  });

  return items;
}

