function enrichKegiatanSop_(item, dataset) {
  var sopItems = (dataset.kegiatanSopItems || [])
    .filter(function (si) { return si.idKegiatan === item.id; })
    .sort(function (a, b) { return a.urutan - b.urutan; });
  var pjLabels = [];
  sopItems.forEach(function (si) {
    if (si.pjLabel && pjLabels.indexOf(si.pjLabel) === -1) pjLabels.push(si.pjLabel);
  });
  var sopText = sopItems.map(function (si) { return si.sopText; }).join(' ');
  var lampiranItems = (dataset.kegiatanSopLampiran || [])
    .filter(function (l) { return l.idKegiatan === item.id; })
    .sort(function (a, b) { return a.urutan - b.urutan; })
    .map(function (l) { return { id: l.id, idKegiatan: l.idKegiatan, nama: l.nama, jenis: l.jenis, isi: l.isi, urutan: l.urutan }; });
  return {
    id: item.id,
    name: item.name,
    jabatanUtama: Array.isArray(item.jabatanUtama) ? item.jabatanUtama : [],
    description: item.description,
    sopItems: sopItems,
    pjLabels: pjLabels,
    jabatanLabels: pjLabels,
    jabatanCount: pjLabels.length,
    jabatanUtamaLabel: Array.isArray(item.jabatanUtama) ? item.jabatanUtama.join(', ') : (item.jabatanUtama || ''),
    sopText: sopText,
    sopPreview: summarizeText_(sopText, 220),
    lampiranItems: lampiranItems,
    lampiranCount: lampiranItems.length,
    status: item.status,
    active: item.active,
    createdAt: cleanString_(item.record.created_at),
    updatedAt: cleanString_(item.record.updated_at),
    record: clonePlainObject_(item.record)
  };
}

function buildContentView_(item) {
  return {
    id: item.id,
    title: item.title,
    slug: item.slug,
    summary: item.summary,
    body: item.body,
    targetRole: item.targetRole,
    publishedAt: item.publishedAt,
    status: item.status
  };
}

function htmlToPlainText_(html) {
  return cleanString_(String(html == null ? '' : html)
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\s*\/p\s*>/gi, '\n')
    .replace(/<\s*\/div\s*>/gi, '\n')
    .replace(/<\s*\/li\s*>/gi, '\n')
    .replace(/<\s*li[^>]*>/gi, '• ')
    .replace(/<\s*\/h[1-6]\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n'));
}

function summarizeText_(text, limit) {
  var safeLimit = Math.max(24, toInt_(limit, 160));
  var value = cleanString_(text);
  if (value.length <= safeLimit) {
    return value;
  }
  return value.slice(0, safeLimit - 3).replace(/\s+\S*$/, '').trim() + '...';
}

function collectAudit_(dataset) {
  var activeSantri = dataset.santri.filter(function (item) {
    return getSantriStatusKey_(item.status) === 'active';
  });
  var frozenSantri = dataset.santri.filter(function (item) {
    return getSantriStatusKey_(item.status) === 'dibekukan';
  });
  var inactiveSantri = dataset.santri.filter(function (item) {
    return getSantriStatusKey_(item.status) === 'inactive';
  });
  var activePengurus = dataset.pengurus.filter(function (item) { return item.active; });
  var activeHalaqoh = dataset.halaqoh.filter(function (item) { return item.active; });
  var activeKelas = dataset.kelasSiang.filter(function (item) { return item.active; });
  var activeRegu = dataset.regu.filter(function (item) { return item.active; });
  var activeKegiatanSop = dataset.kegiatanSop.filter(function (item) { return item.active; });

  var membership = dataset.membership.santri;

  var aktiveTahunAjaran = (dataset.tahunAjaran || []).find(function (ta) { return ta.isAktif; });
  var aktiveTahunAjaranId = aktiveTahunAjaran ? aktiveTahunAjaran.id : '';
  var kelasIdInAktifTahunAjaran = {};
  activeKelas.forEach(function (k) {
    if (!aktiveTahunAjaranId || k.tahunAjaranId === aktiveTahunAjaranId) {
      kelasIdInAktifTahunAjaran[k.id] = true;
    }
  });
  var halaqohIdInAktifTahunAjaran = {};
  activeHalaqoh.forEach(function (h) {
    if (!aktiveTahunAjaranId || h.tahunAjaranId === aktiveTahunAjaranId) {
      halaqohIdInAktifTahunAjaran[h.id] = true;
    }
  });
  var reguIdInAktifTahunAjaran = {};
  activeRegu.forEach(function (r) {
    if (!aktiveTahunAjaranId || r.tahunAjaranId === aktiveTahunAjaranId) {
      reguIdInAktifTahunAjaran[r.id] = true;
    }
  });

  var issueGroups = [];
  var missingHalaqoh = [];
  var santriMultipleHalaqoh = [];
  var missingThreeClasses = [];
  var missingRegu = [];
  var frozenWithoutAssignments = [];
  var inactiveStillAssigned = [];
  var incompleteDocuments = [];
  var pengurusWithoutJabatan = [];
  var halaqohWithoutPengampu = [];
  var halaqohGenderMismatch = [];
  var kelasWithoutPengajar = [];
  var kelasWithoutJam = [];
  var kelasGenderMismatch = [];
  var reguWithoutPembina = [];
  var reguGenderMismatch = [];
  var invalidReferences = [];
  var kegiatanSopWithoutJabatan = [];
  var kegiatanSopWithoutSop = [];
  var kegiatanSopWithoutPrimaryJabatan = [];
  var kegiatanSopWithoutCategory = [];
  var santriIncompleteData = [];
  var pengampuTanpaJabatan = [];
  var pengajarTanpaJabatan = [];
  var pembinaTanpaJabatan = [];

  var pengurusJabatanLabelMap = {};
  activePengurus.forEach(function (p) {
    var rows = (dataset.jabatanByPengurus[p.id] || []).filter(function (r) { return r.active; });
    pengurusJabatanLabelMap[p.id] = rows.map(function (r) {
      var j = dataset.indexes.jabatanById[r.idJabatan];
      return j ? normalizeAccessText_(j.name) : '';
    }).filter(Boolean);
  });
  function pengurusHasKeyword_(pengurusId, keywords) {
    var labels = pengurusJabatanLabelMap[pengurusId] || [];
    return labels.some(function (lbl) {
      return keywords.some(function (kw) { return lbl.indexOf(kw) !== -1; });
    });
  }

  activeSantri.forEach(function (santri) {
    var rel = membership[santri.id] || { halaqohIds: [], kelasIds: [], reguIds: [] };
    var halaqohAktifIds = rel.halaqohIds.filter(function (id) { return !!halaqohIdInAktifTahunAjaran[id]; });
    if (!halaqohAktifIds.length) {
      missingHalaqoh.push(miniSantriIssue_(santri, rel));
    }
    if (halaqohAktifIds.length > 1) {
      santriMultipleHalaqoh.push({
        id: santri.id,
        name: santri.name,
        noInduk: santri.noInduk,
        halaqohCount: halaqohAktifIds.length,
        halaqohIds: halaqohAktifIds.slice(),
        halaqohNames: halaqohAktifIds.map(function (halaqohId) {
          return labelFromIndex_(dataset.indexes.halaqohById, halaqohId);
        })
      });
    }
    var kelasAktifCount = rel.kelasIds.filter(function (id) { return !!kelasIdInAktifTahunAjaran[id]; }).length;
    if (kelasAktifCount < 3) {
      missingThreeClasses.push(miniSantriIssue_(santri, rel));
    }
    var reguAktifCount = rel.reguIds.filter(function (id) { return !!reguIdInAktifTahunAjaran[id]; }).length;
    if (!reguAktifCount) {
      missingRegu.push(miniSantriIssue_(santri, rel));
    }
    if (!(isDocumentFilled_(santri.adminKk) && isDocumentFilled_(santri.adminKtp) && isDocumentFilled_(santri.adminAkta))) {
      incompleteDocuments.push({
        id: santri.id,
        name: santri.name,
        noInduk: santri.noInduk,
        kk: santri.adminKk,
        ktp: santri.adminKtp,
        akta: santri.adminAkta
      });
    }
    var mfFields = [];
    if (!cleanString_(santri.name)) mfFields.push('Nama');
    if (!cleanString_(santri.noInduk)) mfFields.push('NIS');
    if (!cleanString_(santri.tempatLahir)) mfFields.push('Tempat Lahir');
    if (!cleanString_(santri.tanggalLahir)) mfFields.push('Tanggal Lahir');
    if (!cleanString_(santri.jenisKelamin || santri.gender)) mfFields.push('Jenis Kelamin');
    if (!cleanString_(santri.alamat)) mfFields.push('Alamat');
    if (mfFields.length) santriIncompleteData.push({ id: santri.id, name: cleanString_(santri.name), noInduk: cleanString_(santri.noInduk), missingFields: mfFields });
  });

  frozenSantri.forEach(function (santri) {
    var rel = membership[santri.id] || { halaqohIds: [], kelasIds: [], reguIds: [] };
    var frozenAssignmentIssue = buildFrozenSantriPlacementIssue_(santri, rel);
    if (frozenAssignmentIssue) {
      frozenWithoutAssignments.push(frozenAssignmentIssue);
    }
  });

  inactiveSantri.forEach(function (santri) {
    var rel = membership[santri.id] || { halaqohIds: [], kelasIds: [], reguIds: [] };
    if (rel.halaqohIds.length || rel.kelasIds.length || rel.reguIds.length) {
      inactiveStillAssigned.push({
        id: santri.id,
        name: santri.name,
        halaqohCount: rel.halaqohIds.length,
        kelasCount: rel.kelasIds.length,
        reguCount: rel.reguIds.length
      });
    }
  });

  activePengurus.forEach(function (pengurus) {
    var assignments = (dataset.jabatanByPengurus[pengurus.id] || []).filter(function (row) { return row.active; });
    if (!assignments.length) {
      pengurusWithoutJabatan.push({
        id: pengurus.id,
        name: pengurus.name,
        email: pengurus.email,
        noHp: pengurus.noHp
      });
    }
  });

  activeHalaqoh.forEach(function (halaqoh) {
    var genderMismatch;
    if (!halaqoh.pengampuIds.length) {
      halaqohWithoutPengampu.push({ id: halaqoh.id, name: halaqoh.name });
    }
    halaqoh.pengampuIds.concat(halaqoh.badalIds).forEach(function (pengurusId) {
      var p = dataset.indexes.pengurusById[pengurusId];
      if (!p) {
        invalidReferences.push({
          entity: 'halaqoh', entityId: halaqoh.id, entityName: halaqoh.name,
          field: 'pengampu', missingId: pengurusId
        });
      } else if (!pengurusHasKeyword_(pengurusId, ACCESS_CONTROL.pengampuHalaqohJabatanKeywords)) {
        pengampuTanpaJabatan.push({
          pengurusId: pengurusId, pengurusName: cleanString_(p.name),
          entityId: halaqoh.id, entityName: cleanString_(halaqoh.name)
        });
      }
    });
    halaqoh.santriIds.forEach(function (santriId) {
      if (!dataset.indexes.santriById[santriId]) {
        invalidReferences.push({
          entity: 'halaqoh',
          entityId: halaqoh.id,
          entityName: halaqoh.name,
          field: 'santri',
          missingId: santriId
        });
      }
    });
    genderMismatch = buildEntityGenderMismatchIssue_(halaqoh, 'halaqoh', dataset);
    if (genderMismatch) {
      halaqohGenderMismatch.push(genderMismatch);
    }
  });

  activeKelas.forEach(function (kelas) {
    var kelasGenderIssue;
    if (!kelas.pengajarIds.length) {
      kelasWithoutPengajar.push({ id: kelas.id, name: kelas.name });
    }
    if (!cleanString_(kelas.jam)) {
      kelasWithoutJam.push({ id: kelas.id, name: kelas.name });
    }
    kelas.pengajarIds.concat(kelas.badalIds).forEach(function (pengurusId) {
      var p = dataset.indexes.pengurusById[pengurusId];
      if (!p) {
        invalidReferences.push({
          entity: 'kelasSiang', entityId: kelas.id, entityName: kelas.name,
          field: 'pengajar', missingId: pengurusId
        });
      } else if (!pengurusHasKeyword_(pengurusId, ACCESS_CONTROL.pengajarJabatanKeywords)) {
        pengajarTanpaJabatan.push({
          pengurusId: pengurusId, pengurusName: cleanString_(p.name),
          entityId: kelas.id, entityName: cleanString_(kelas.name)
        });
      }
    });
    kelas.santriIds.forEach(function (santriId) {
      if (!dataset.indexes.santriById[santriId]) {
        invalidReferences.push({
          entity: 'kelasSiang',
          entityId: kelas.id,
          entityName: kelas.name,
          field: 'santri',
          missingId: santriId
        });
      }
    });
    kelasGenderIssue = buildEntityGenderMismatchIssue_(kelas, 'kelasSiang', dataset);
    if (kelasGenderIssue) {
      kelasGenderMismatch.push(kelasGenderIssue);
    }
  });

  activeRegu.forEach(function (regu) {
    var reguGenderIssue;
    if (!regu.pembinaIds.length) {
      reguWithoutPembina.push({ id: regu.id, name: regu.name });
    }
    regu.pembinaIds.forEach(function (pengurusId) {
      var p = dataset.indexes.pengurusById[pengurusId];
      if (!p) {
        invalidReferences.push({
          entity: 'regu', entityId: regu.id, entityName: regu.name,
          field: 'pembina', missingId: pengurusId
        });
      } else if (!pengurusHasKeyword_(pengurusId, ['pembina'])) {
        pembinaTanpaJabatan.push({
          pengurusId: pengurusId, pengurusName: cleanString_(p.name),
          entityId: regu.id, entityName: cleanString_(regu.name)
        });
      }
    });
    regu.santriIds.forEach(function (santriId) {
      if (!dataset.indexes.santriById[santriId]) {
        invalidReferences.push({
          entity: 'regu',
          entityId: regu.id,
          entityName: regu.name,
          field: 'santri',
          missingId: santriId
        });
      }
    });
    reguGenderIssue = buildEntityGenderMismatchIssue_(regu, 'regu', dataset);
    if (reguGenderIssue) {
      reguGenderMismatch.push(reguGenderIssue);
    }
  });

  activeKegiatanSop.forEach(function (rawKegiatan) {
    var kegiatan = enrichKegiatanSop_(rawKegiatan, dataset);
    var kBase = { id: kegiatan.id, name: kegiatan.name };
    if (!kegiatan.sopItems.length || !kegiatan.pjLabels.length) kegiatanSopWithoutJabatan.push(kBase);
    if (!kegiatan.sopText) kegiatanSopWithoutSop.push(kBase);
    if (!kegiatan.jabatanUtama.length) kegiatanSopWithoutPrimaryJabatan.push(kBase);
    if (!cleanString_(kegiatan.description)) kegiatanSopWithoutCategory.push(kBase);
  });

  pushIssueGroup_(issueGroups, 'active_without_halaqoh', 'Santri aktif belum masuk halaqoh dengan tahun ajaran yang aktif', 'high', missingHalaqoh, 'Perlu dipetakan ke halaqoh aktif pada tahun ajaran aktif.');
  pushIssueGroup_(issueGroups, 'santri_multiple_halaqoh', 'Santri aktif masuk lebih dari 1 halaqoh dengan tahun ajaran yang aktif', 'high', santriMultipleHalaqoh, 'Setiap santri seharusnya hanya berada pada satu halaqoh aktif pada tahun ajaran aktif.');
  pushIssueGroup_(issueGroups, 'active_without_three_classes', 'Santri aktif belum masuk 3 kelas siang (tahun ajaran aktif)', 'high', missingThreeClasses, 'Target minimal 3 kelas aktif pada tahun ajaran aktif per santri.');
  pushIssueGroup_(issueGroups, 'active_without_regu', 'Santri aktif belum masuk regu dengan tahun ajaran yang aktif', 'medium', missingRegu, 'Perlu pembagian regu aktif pada tahun ajaran aktif.');
  pushIssueGroup_(issueGroups, 'frozen_without_assignments', 'Santri dibekukan belum lengkap penempatannya', 'neutral', frozenWithoutAssignments, 'Catatan informatif. Santri dibekukan boleh belum masuk halaqoh, kelas, atau regu, tetapi tetap ditampilkan agar mudah dipantau.');
  pushIssueGroup_(issueGroups, 'inactive_still_assigned', 'Santri inactive masih terdaftar di halaqoh, kelas, atau regu', 'high', inactiveStillAssigned, 'Perlu pembersihan relasi setelah santri nonaktif.');
  pushIssueGroup_(issueGroups, 'incomplete_documents', 'Santri aktif dengan administrasi belum lengkap', 'medium', incompleteDocuments, 'Cek dokumen KK, KTP, dan akta.');
  pushIssueGroup_(issueGroups, 'pengurus_without_jabatan', 'Pengurus aktif belum punya jabatan aktif', 'medium', pengurusWithoutJabatan, 'Lengkapi sheet pengurus_jabatan.');
  pushIssueGroup_(issueGroups, 'halaqoh_without_pengampu', 'Halaqoh aktif belum punya pengampu', 'medium', halaqohWithoutPengampu, 'Tambahkan pengampu utama atau badal.');
  pushIssueGroup_(issueGroups, 'halaqoh_gender_mismatch', 'Halaqoh ikhwan/akhowat berisi santri tidak sesuai', 'medium', halaqohGenderMismatch, 'Periksa kategori gender halaqoh dan anggota santrinya.');
  pushIssueGroup_(issueGroups, 'kelas_without_pengajar', 'Kelas aktif belum punya pengajar', 'medium', kelasWithoutPengajar, 'Tambahkan guru utama atau badal.');
  pushIssueGroup_(issueGroups, 'kelas_without_jam', 'Kelas aktif belum memiliki jam', 'low', kelasWithoutJam, 'Lengkapi penjadwalan kelas siang.');
  pushIssueGroup_(issueGroups, 'kelas_gender_mismatch', 'Kelas ikhwan/akhowat berisi murid tidak sesuai', 'medium', kelasGenderMismatch, 'Periksa kategori gender kelas dan daftar muridnya.');
  pushIssueGroup_(issueGroups, 'regu_without_pembina', 'Regu aktif belum memiliki pembina', 'medium', reguWithoutPembina, 'Tambahkan pembina regu.');
  pushIssueGroup_(issueGroups, 'regu_gender_mismatch', 'Regu ikhwan/akhowat berisi santri tidak sesuai', 'medium', reguGenderMismatch, 'Periksa kategori gender regu dan anggota santrinya.');
  pushIssueGroup_(issueGroups, 'santri_incomplete_data', 'Santri aktif dengan data penting yang kosong', 'medium', santriIncompleteData, 'Lengkapi nama, NIS, tempat/tanggal lahir, jenis kelamin, dan alamat.');
  pushIssueGroup_(issueGroups, 'kegiatan_sop_without_jabatan', 'Kegiatan operasional aktif belum punya penanggung jawab', 'high', kegiatanSopWithoutJabatan, 'Tambahkan minimal satu item SOP dengan kolom PJ terisi.');
  pushIssueGroup_(issueGroups, 'kegiatan_sop_without_sop', 'Kegiatan operasional aktif belum punya SOP', 'high', kegiatanSopWithoutSop, 'Isi SOP agar kegiatan punya langkah kerja yang bisa diaudit.');
  pushIssueGroup_(issueGroups, 'kegiatan_sop_without_primary_jabatan', 'Kegiatan operasional aktif belum punya jabatan PJ utama', 'medium', kegiatanSopWithoutPrimaryJabatan, 'Tetapkan jabatan penanggung jawab utama pada kegiatan ini.');
  pushIssueGroup_(issueGroups, 'kegiatan_sop_without_category', 'Kegiatan operasional aktif belum punya deskripsi/kategori', 'low', kegiatanSopWithoutCategory, 'Isi deskripsi kegiatan agar mudah dikategorikan.');
  pushIssueGroup_(issueGroups, 'invalid_references', 'Ada relasi menuju ID yang tidak ditemukan', 'high', invalidReferences, 'Periksa referensi santri atau pengurus pada sheet relasi.');
  pushIssueGroup_(issueGroups, 'pengampu_tanpa_jabatan', 'Pengampu halaqoh tidak menjabat sebagai pengampu halaqoh', 'medium', pengampuTanpaJabatan, 'Pengurus ini ditugaskan sebagai pengampu/badal halaqoh tetapi jabatannya tidak mengandung kata kunci pengampu halaqoh.');
  pushIssueGroup_(issueGroups, 'pengajar_tanpa_jabatan', 'Pengajar kelas tidak menjabat sebagai pengajar', 'medium', pengajarTanpaJabatan, 'Pengurus ini ditugaskan sebagai pengajar/badal kelas tetapi jabatannya tidak mengandung kata kunci pengajar/ustadz/guru.');
  pushIssueGroup_(issueGroups, 'pembina_tanpa_jabatan', 'Pembina regu tidak menjabat sebagai pembina', 'medium', pembinaTanpaJabatan, 'Pengurus ini ditugaskan sebagai pembina regu tetapi jabatannya tidak mengandung kata kunci pembina.');

  var duplicateNik = collectDuplicates_(dataset.santri, 'nik', 'NIK');
  var duplicateNoInduk = collectDuplicates_(dataset.santri, 'noInduk', 'NIS');
  pushIssueGroup_(issueGroups, 'duplicate_nik', 'Ada NIK santri yang duplikat', 'high', duplicateNik, 'Rawan salah identitas santri.');
  pushIssueGroup_(issueGroups, 'duplicate_no_induk', 'Ada NIS santri yang duplikat', 'high', duplicateNoInduk, 'Perlu diseragamkan agar relasi aman.');

  issueGroups.sort(sortIssueGroups_);

  return {
    summary: {
      santri: buildSummaryCount_(dataset.santri),
      pengurus: buildSummaryCount_(dataset.pengurus),
      jabatan: buildSummaryCount_(dataset.jabatan),
      halaqoh: buildSummaryCount_(dataset.halaqoh),
      kelasSiang: buildSummaryCount_(dataset.kelasSiang),
      regu: buildSummaryCount_(dataset.regu),
      nilaiUp: buildSummaryCount_(dataset.nilaiUp),
      absensiGuru: buildSummaryCount_(dataset.absensiGuru),
      absensiHalaqoh: buildSummaryCount_(dataset.absensiHalaqoh),
      absensiKelas: buildSummaryCount_(dataset.absensiKelas),
      absensiRegu: buildSummaryCount_(dataset.absensiRegu),
      kegiatanSop: buildSummaryCount_(dataset.kegiatanSop),
      content: buildSummaryCount_(dataset.content),
      coverage: {
        activeSantri: activeSantri.length,
        punyaHalaqoh: activeSantri.length - missingHalaqoh.length,
        punyaTigaKelas: activeSantri.length - missingThreeClasses.length,
        punyaRegu: activeSantri.length - missingRegu.length
      }
    },
    issueGroups: issueGroups
  };
}

function buildMembershipMaps_(dataset, tahunAjaranId) {
  var map = { santri: {} };
  var taId = cleanString_(tahunAjaranId);

  dataset.halaqoh.filter(function (item) {
    if (!item.active) return false;
    if (taId && item.tahunAjaranId !== taId) return false;
    return true;
  }).forEach(function (halaqoh) {
    halaqoh.santriIds.forEach(function (santriId) {
      ensureSantriMembershipEntry_(map.santri, santriId).halaqohIds.push(halaqoh.id);
    });
  });

  dataset.kelasSiang.filter(function (item) {
    if (!item.active) return false;
    if (taId && item.tahunAjaranId !== taId) return false;
    return true;
  }).forEach(function (kelas) {
    kelas.santriIds.forEach(function (santriId) {
      ensureSantriMembershipEntry_(map.santri, santriId).kelasIds.push(kelas.id);
    });
  });

  dataset.regu.filter(function (item) {
    if (!item.active) return false;
    if (taId && item.tahunAjaranId !== taId) return false;
    return true;
  }).forEach(function (regu) {
    regu.santriIds.forEach(function (santriId) {
      ensureSantriMembershipEntry_(map.santri, santriId).reguIds.push(regu.id);
    });
  });

  return map;
}

function ensureSantriMembershipEntry_(map, santriId) {
  if (!map[santriId]) {
    map[santriId] = {
      halaqohIds: [],
      kelasIds: [],
      reguIds: []
    };
  }
  return map[santriId];
}

function syncPengurusJabatan_(pengurusId, jabatanIds, primaryJabatanId, peranMap) {
  var state = readSheetState_('pengurus_jabatan');
  var existing = state.rows.filter(function (row) {
    return cleanString_(row.id_pengurus) === cleanString_(pengurusId);
  });
  var desiredMap = {};
  jabatanIds.forEach(function (id) {
    desiredMap[id] = true;
  });
  var resolvedPeranMap = (peranMap && typeof peranMap === 'object') ? peranMap : {};

  existing.forEach(function (row) {
    var jabatanId = cleanString_(row.id_jabatan);
    var isActive = !!desiredMap[jabatanId];
    updateSheetRow_(state, row._rowNumber, {
      status: isActive ? STATUS_LABELS.pengurus_jabatan.active : STATUS_LABELS.pengurus_jabatan.inactive,
      is_utama: normalizeBooleanText_(isActive && jabatanId === primaryJabatanId),
      peran: isActive ? (resolvedPeranMap[jabatanId] || '') : ''
    });
    delete desiredMap[jabatanId];
  });

  Object.keys(desiredMap).forEach(function (jabatanId) {
    var newId = String(nextId_(state.rows));
    appendSheetRow_(state, {
      id: newId,
      id_pengurus: pengurusId,
      id_jabatan: jabatanId,
      is_utama: normalizeBooleanText_(jabatanId === primaryJabatanId),
      peran: resolvedPeranMap[jabatanId] || '',
      status: STATUS_LABELS.pengurus_jabatan.active
    });
    state.rows.push({
      id: newId,
      id_pengurus: pengurusId,
      id_jabatan: jabatanId,
      is_utama: normalizeBooleanText_(jabatanId === primaryJabatanId),
      peran: resolvedPeranMap[jabatanId] || '',
      status: STATUS_LABELS.pengurus_jabatan.active,
      _rowNumber: state.sheet.getLastRow()
    });
  });
}

function applyScopeToPermissions_(scopeLabel, enriched, dataset, existingPerms) {
  var normalizedScope = normalizeAccessText_(scopeLabel);
  var jabatanLabels = enriched.jabatanLabels || [];
  var isSuperAdmin = !!(existingPerms && existingPerms.canDelete);
  // "Pembina Regu" bukan selalu nama jabatan resmi — status ini ditentukan dari
  // penugasan di data regu (pembinaIds), bukan judul jabatan. Jadi scope ini tetap
  // valid untuk pengurus yang benar-benar ditugaskan sebagai pembina regu, walau
  // jabatan resminya bukan "Pembina Regu".
  var isPembinaReguScope = !!(existingPerms && existingPerms.isPembinaRegu) &&
    listHasAccessKeyword_([normalizedScope], ACCESS_CONTROL.pembinaReguJabatanKeywords);
  var isValid = isSuperAdmin || isPembinaReguScope || jabatanLabels.some(function (label) {
    return normalizeAccessText_(label) === normalizedScope;
  });
  if (!isValid) return null;
  // Build permissions from a single scoped label; use a fake id to bypass
  // isPrimaryProtectedPengurusId_ so the scope is fully respected
  var scopedPengurus = {
    id: '__scoped__',
    name: enriched.name,
    jabatanLabels: [scopeLabel],
    jabatanLevels: [],
    primaryJabatanLabel: scopeLabel
  };
  var p = resolvePengurusPermissions_(scopedPengurus, dataset);
  // Restore assignment data using real pengurus ID — these don't change with scope
  p.kelasIds = collectPengurusKelasIds_(enriched.id, dataset);
  p.pembinaReguIds = collectPembinaReguIds_(enriched.id, dataset);
  // Jangan timpa isPembinaRegu yang sudah true dari kecocokan judul scope (mis. akun
  // Super Admin yang sengaja scope ke "Pembina Regu" walau ID aslinya tidak terdaftar
  // di pembinaIds regu manapun) — gabungkan dengan OR, bukan overwrite.
  p.isPembinaRegu = p.isPembinaRegu || p.pembinaReguIds.length > 0;
  // canManageAbsensi might be false if hasTeachingAssignment was false for __scoped__ ID;
  // correct it now that kelasIds reflect real assignments.
  if (p.kelasIds.length > 0 && !p.canManageAbsensi) p.canManageAbsensi = true;
  return p;
}

// Versi ringan loadDataset_() khusus buat authenticateRequest_(): cuma baca 6 tabel yang
// benar-benar dipakai buat cocokin token + hitung hak akses (pengurus, santri, jabatan,
// pengurus_jabatan, kelasSiang buat collectPengurusKelasIds_, regu buat collectPembinaReguIds_),
// bukan 18 tabel penuh seperti loadDataset_(). Menghindari baca+normalize absensi*/nilaiUp/
// kegiatanSop/content/tahunAjaran yang tak dipakai sama sekali di jalur auth, padahal jalur ini
// dieksekusi di SETIAP request (bukan cuma yang butuh dataset penuh).
function loadAuthDataset_() {
  var pengurusState = readSheetState_('pengurus');
  var santriState = readSheetState_('santri');
  var jabatanState = readSheetState_('jabatan');
  var pengurusJabatanState = readSheetState_('pengurus_jabatan');
  var kelasState = readSheetState_('kelasSiang');
  var reguState = readSheetState_('regu');

  var dataset = {
    pengurus: pengurusState.rows.map(normalizePengurus_),
    santri: santriState.rows.map(normalizeSantri_),
    jabatan: jabatanState.rows.map(normalizeJabatan_),
    pengurusJabatan: pengurusJabatanState.rows.map(normalizePengurusJabatan_),
    kelasSiang: kelasState.rows.map(normalizeKelas_),
    regu: reguState.rows.map(normalizeRegu_)
  };

  dataset.indexes = {
    jabatanById: indexById_(dataset.jabatan)
  };

  dataset.jabatanByPengurus = {};
  dataset.pengurusJabatan.forEach(function (row) {
    if (!dataset.jabatanByPengurus[row.idPengurus]) {
      dataset.jabatanByPengurus[row.idPengurus] = [];
    }
    dataset.jabatanByPengurus[row.idPengurus].push(row);
  });

  return dataset;
}

function authenticateRequest_(token, allowSantri, scopeLabel) {
  var cleanedToken = cleanString_(token);
  if (!cleanedToken) {
    throw createError_('Token tidak ditemukan.', 401);
  }

  var dataset = loadAuthDataset_();
  var pengurus = dataset.pengurus.filter(function (item) {
    return item.active && parseSessionTokens_(item.token).indexOf(cleanedToken) !== -1;
  })[0];

  if (pengurus) {
    var enriched = enrichPengurus_(pengurus, dataset);
    var rawPermissions = resolvePengurusPermissions_(enriched, dataset);
    var permissions = rawPermissions;
    var cleanedScope = cleanString_(scopeLabel);
    if (cleanedScope) {
      var scoped = applyScopeToPermissions_(cleanedScope, enriched, dataset, rawPermissions);
      if (scoped) permissions = scoped;
    }
    return {
      role: 'pengurus',
      id: enriched.id,
      name: enriched.name,
      token: cleanedToken,
      photoUrl: enriched.photoUrl || '',
      jabatanIds: enriched.jabatanIds,
      jabatanLabels: enriched.jabatanLabels,
      primaryJabatanLabel: enriched.primaryJabatanLabel || '',
      roleScopeOptions: buildRoleScopeOptions_(rawPermissions, enriched.jabatanLabels, enriched.primaryJabatanLabel),
      kelasIds: permissions.kelasIds || [],
      scopeLabel: cleanedScope || '',
      permissions: permissions,
      rawPermissions: rawPermissions
    };
  }

  if (allowSantri) {
    var santri = dataset.santri.filter(function (item) {
      return item.active && parseSessionTokens_(item.token).indexOf(cleanedToken) !== -1;
    })[0];
    if (santri) {
      return {
        role: 'santri',
        id: santri.id,
        name: santri.name,
        token: cleanedToken,
        noInduk: santri.noInduk,
        photoUrl: santri.photoUrl || ''
      };
    }
  }

  throw createError_('Token tidak valid atau status pengguna tidak aktif.', 401);
}

function requirePengurus_(session) {
  if (!session || session.role !== 'pengurus') {
    throw createError_('Akses hanya untuk token pengurus aktif.', 403);
  }
  if (!session.permissions || !session.permissions.canAccessPanel) {
    throw createError_('Akses hanya untuk pengurus yang memiliki izin panel.', 403);
  }
}

function requireSuperAdmin_(session) {
  requirePengurus_(session);
  if (!session.permissions || !session.permissions.canDelete) {
    throw createError_('Aksi ini hanya untuk Super Admin.', 403);
  }
}

function requireAdmin_(session) {
  requirePengurus_(session);
  if (!session.permissions || !session.permissions.isAdmin) {
    throw createError_('Aksi ini hanya untuk Admin.', 403);
  }
}

function requireAdminOrSuperAdmin_(session) {
  requirePengurus_(session);
  if (!session.permissions || (!session.permissions.canDelete && !session.permissions.isAdmin)) {
    throw createError_('Aksi ini hanya untuk Admin atau Super Admin.', 403);
  }
}

function requireAdminOrSdm_(session) {
  requirePengurus_(session);
  if (!session.permissions || (!session.permissions.canDelete && !session.permissions.isAdmin && !session.permissions.isBagianSdm)) {
    throw createError_('Aksi ini hanya untuk Admin, SDM, atau Super Admin.', 403);
  }
}

function resolvePengurusPermissions_(pengurus, dataset) {
  var name = normalizeAccessText_(pengurus.name);
  var labelTokens = (pengurus.jabatanLabels || []).map(normalizeAccessText_);
  var levelSet = {};
  (pengurus.jabatanLevels || []).forEach(function (level) {
    levelSet[cleanString_(level)] = true;
  });

  var isSuperAdmin =
    isPrimaryProtectedPengurusId_(pengurus.id) ||
    listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.superAdminJabatanKeywords) ||
    hasAnyKey_(levelSet, ACCESS_CONTROL.superAdminJabatanLevels);

  // 'operator jam digital' tidak boleh naik ke full-admin hanya karena mengandung kata 'operator'
  var hasJamDigitalOpLabel = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.jamDigitalOperatorKeywords);
  var isAdmin = isSuperAdmin ||
    listHasAccessKeyword_(labelTokens, ['admin', 'administrator']) ||
    (!hasJamDigitalOpLabel && listHasAccessKeyword_(labelTokens, ['operator']));

  var isHalaqohCoordinator = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.halaqohCoordinatorJabatanKeywords);
  var isPengampuHalaqoh = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pengampuHalaqohJabatanKeywords);
  var isPengujiHafalan = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pengujiHafalanJabatanKeywords);
  var isAcademic = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.academicJabatanKeywords);
  var hasPengajarKeyword = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pengajarJabatanKeywords);
  var isBagianHukuman = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.hukumanJabatanKeywords);
  var isKsantrian = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.ksantrianJabatanKeywords);
  var isBagianKesehatan = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.kesehatanJabatanKeywords);
  var isBagianSdm = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.sdmJabatanKeywords);
  var isMudir = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.mudirJabatanKeywords);
  var isKebersihan = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.kebersihanJabatanKeywords);
  var hasMading = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.madingJabatanKeywords);
  var isPengawasLapangan = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pengawasLapanganJabatanKeywords);
  var isKetuaYayasan = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.ketuaYayasanJabatanKeywords);
  var isPembinaYayasan = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pembinaYayasanJabatanKeywords);
  var kelasIds = collectPengurusKelasIds_(pengurus.id, dataset);
  var pembinaReguIds = collectPembinaReguIds_(pengurus.id, dataset);
  // "Pembina Regu" boleh didapat dari dua jalur: benar-benar ditugaskan di data regu
  // (pembinaReguIds), ATAU jabatannya/scope-nya memang berjudul "Pembina Regu" dkk —
  // konsisten dengan flag peran lain (isKsantrian, isHalaqohCoordinator, dst) yang
  // semuanya berbasis judul jabatan, bukan penugasan per-record.
  var isPembinaRegu = pembinaReguIds.length > 0 || listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pembinaReguJabatanKeywords);
  var hasTeachingAssignment = kelasIds.length > 0;
  var canManageHalaqoh = isAdmin || isHalaqohCoordinator || isPengampuHalaqoh;
  var canManageKelasSiang = isAdmin || isAcademic;
  // Raport & Rekam Jejak
  var canManageKelasLevel = isAdmin || isAcademic || hasPengajarKeyword;  // input tingkat/marhalah santri
  var canManageRaport = isAdmin || isAcademic || isHalaqohCoordinator || isKsantrian; // lihat & cetak raport/rekam jejak semua santri
  var canManageAkhlak = isAdmin || isKsantrian;          // akhlak: kesantrian+admin semua regu; pembina hanya regunya (cek terpisah)
  var canManageNilaiUp = isAdmin || isAcademic || hasPengajarKeyword;
  var canManageAbsensi = isAdmin || isAcademic || isHalaqohCoordinator || isPengampuHalaqoh || hasTeachingAssignment || hasPengajarKeyword;
  var canManageBuku = isAdmin || isAcademic;
  var canUploadSoal = isSuperAdmin || isAdmin || isAcademic || hasPengajarKeyword;
  var isJamDigitalOperator = hasJamDigitalOpLabel && !isAdmin;
  var canAccessJamDigital = isAdmin || isJamDigitalOperator;
  var canManageKegiatanSop = isAdmin || isBagianSdm || isMudir;
  var canManageContent = isAdmin || hasMading;
  var canManageJadwalIbadah = isAdmin || isHalaqohCoordinator;
  var canManageDataKelompokManual = isAdmin || isMudir || isBagianSdm;
  var canManagePelajaran = isAdmin || isAcademic;
  var isPengabdian = cleanString_(pengurus.jenisPengurus).toLowerCase() === 'pengabdian';
  var canAccessPanel = true;
  // Semua pengurus boleh melihat data santri (halaman & API santri.list), kecuali pengurus
  // berstatus "pengabdian" — sengaja tidak boleh akses halaman/data Daftar Santri.
  var canViewSantri = canAccessPanel && !isPengabdian;

  // Shim {jabatanIds, permissions} dipakai canAccessLevel_/canManageAddon_ (lewat
  // buildAddonsCanManageMap_/buildLockedLevelAccessMap_) -- BUKAN objek `permissions` final
  // (belum selesai dibangun di titik ini), dirakit dari variabel lokal yg sudah dihitung di atas.
  var addonAccessShimSession_ = {
    jabatanIds: pengurus.jabatanIds,
    permissions: {
      isSuperAdmin: isSuperAdmin, isAdmin: isAdmin, isMudir: isMudir, isPembinaRegu: isPembinaRegu,
      isAcademic: isAcademic, isHalaqohCoordinator: isHalaqohCoordinator, isKsantrian: isKsantrian,
      isPengampuHalaqoh: isPengampuHalaqoh, isPengujiHafalan: isPengujiHafalan,
      canUploadSoal: canUploadSoal, canManageJadwalIbadah: canManageJadwalIbadah,
      canAccessJamDigital: canAccessJamDigital, canManageContent: canManageContent,
      canManageNilaiUp: canManageNilaiUp, canManageBuku: canManageBuku,
      canManageKelasLevel: canManageKelasLevel, canManageAkhlak: canManageAkhlak,
      canManagePelajaran: canManagePelajaran, canManageHalaqoh: canManageHalaqoh,
      canManageKelasSiang: canManageKelasSiang, isBagianKesehatan: isBagianKesehatan
    }
  };

  var permissions = {
    isAdmin: isAdmin,
    isSuperAdmin: isSuperAdmin,
    isHalaqohCoordinator: isHalaqohCoordinator,
    isPengampuHalaqoh: isPengampuHalaqoh,
    isPengujiHafalan: isPengujiHafalan,
    isAcademic: isAcademic,
    isPengabdian: isPengabdian,
    canDelete: isSuperAdmin,
    canAccessPanel: canAccessPanel,
    canViewSantri: canViewSantri,
    canManageSantri: isAdmin,
    canManagePengurus: isAdmin,
    canManageJabatan: isAdmin,
    canManageRegu: isAdmin || isKsantrian,
    canManageHalaqoh: canManageHalaqoh,
    canManageKelasSiang: canManageKelasSiang,
    canManageNilaiUp: canManageNilaiUp,
    canManageAbsensi: canManageAbsensi,
    canAccessJamDigital: canAccessJamDigital,
    // Kelola Addons (2026-09-12): dikirim ke SEMUA sesi pengurus supaya PAGE_RULES di
    // frontend/shared-access.js bisa sembunyikan menu/tolak akses tanpa panggilan API
    // terpisah. false = addon dimatikan Admin; field tak dikenal dianggap aktif (lihat
    // isAddonActive_ di server.js, default aman kalau addon baru belum dikenal frontend lama).
    // Dibangun dari ADDONS_REGISTRY_ (bukan ditulis manual satu-satu) supaya addon baru yang
    // ditambahkan ke registry otomatis ikut terkirim ke frontend tanpa perlu ubah baris ini lagi.
    addonsActive: buildAddonsActiveMap_(),
    // Sinyal kasar "apakah sesi ini boleh MENGELOLA tiap addon" (bukan cuma memakai) -- dipakai
    // PAGE_RULES utk halaman yang SELURUHNYA halaman pengelola (kelolaMading, pengumuman,
    // survey, quizDigital, rekapZoom, jamDigitalRemote). Shim {permissions,jabatanIds} dibangun
    // dari variabel lokal yg sudah dihitung di atas -- BUKAN objek `permissions` final (belum
    // selesai dibangun di titik ini), lihat canManageAddon_/ADDON_MANAGE_FALLBACK_.
    addonsCanManage: buildAddonsCanManageMap_(addonAccessShimSession_),
    // Level akses (Lihat/Kelola) untuk 4 kelompok halaman TERKUNCI yang sudah diaktifkan
    // pengaturannya (lihat `levels` di ADDONS_LOCKED_REGISTRY_ & LOCKED_LEVEL_FALLBACK_) --
    // kelompok terkunci lain (tanpa `levels`) sengaja tidak muncul di sini sama sekali.
    lockedLevelAccess: buildLockedLevelAccessMap_(addonAccessShimSession_),
    canManageKegiatanSop: canManageKegiatanSop,
    canManageContent: canManageContent,
    isBagianHukuman: isBagianHukuman,
    isBagianKesehatan: isBagianKesehatan,
    isBagianSdm: isBagianSdm,
    isMudir: isMudir,
    isKsantrian: isKsantrian,
    isPembinaRegu: isPembinaRegu,
    pembinaReguIds: pembinaReguIds,
    hasMading: hasMading,
    canManageKelasLevel: canManageKelasLevel,
    canManageRaport: canManageRaport,
    canManageAkhlak: canManageAkhlak,
    canAccessIzinPulang: isAdmin || isKsantrian,
    canAccessSantriSakit: isAdmin || isBagianKesehatan || isKsantrian,
    canEditSantriSakit: isAdmin || isBagianKesehatan || isKsantrian,
    canInputPelanggaran: canAccessPanel,
    canAssignHukuman: isAdmin || isBagianHukuman,
    canManageKoordinatAbsensi: isAdmin || isBagianSdm,
    // canManageSdmJurnalAll: hak penuh (tambah/edit/hapus-pengajuan/sahkan/fingerprint/data lapangan) utk SEMUA pengurus.
    // canViewSdmJurnalAll: cuma Mudir — lihat semua pengurus (read-only), tapi tetap boleh isi kegiatan miliknya sendiri.
    // Selain dua ini, setiap pengurus tetap bisa akses halaman jurnalSdm utk kegiatan miliknya sendiri saja
    // (diverifikasi per-request di handler, bukan lewat flag global).
    canManageSdmJurnalAll: isAdmin || isBagianSdm,
    canViewSdmJurnalAll: isMudir,
    canManageBuku: canManageBuku,
    canUploadSoal: canUploadSoal,
    canManageSoal: isSuperAdmin || isAdmin || isAcademic,
    isKebersihan: isKebersihan,
    isPengawasLapangan: isPengawasLapangan,
    isKetuaYayasan: isKetuaYayasan,
    isPembinaYayasan: isPembinaYayasan,
    canManageJadwalIbadah: canManageJadwalIbadah,
    canManageDataKelompokManual: canManageDataKelompokManual,
    canManagePelajaran: canManagePelajaran,
    canImportData: isSuperAdmin,
    canExportData: isSuperAdmin,
    canExportAll: isSuperAdmin,
    kelasIds: kelasIds,
    accessLevel: isSuperAdmin ? 'super_admin' : (isAdmin ? 'admin' : (isJamDigitalOperator ? 'operator_jam_digital' : (isAcademic ? 'akademik' : (isHalaqohCoordinator ? 'koordinator_halaqoh' : (isPengampuHalaqoh ? 'pengampu_halaqoh' : (isPengujiHafalan ? 'penguji_hafalan' : (canManageNilaiUp ? 'pengajar' : (isBagianKesehatan ? 'kesehatan' : (isBagianSdm ? 'sdm' : (isKsantrian ? 'ksantrian' : (isKebersihan ? 'kebersihan' : (isPembinaRegu ? 'pembina_regu' : (hasMading ? 'mading' : (isPengawasLapangan ? 'pengawas_lapangan' : 'staff')))))))))))))),
    label: isSuperAdmin ? 'Super Admin' : (isAdmin ? 'Admin' : (isJamDigitalOperator ? 'Operator Jam Digital' : (isAcademic ? 'Akademik' : (isHalaqohCoordinator ? 'Koordinator Halaqoh' : (isPengampuHalaqoh ? 'Pengampu Halaqoh' : (isPengujiHafalan ? 'Penguji Hafalan' : (canManageNilaiUp ? 'Pengajar' : (isBagianKesehatan ? 'Kesehatan' : (isBagianSdm ? 'SDM' : (isKsantrian ? 'Kesantrian' : (isKebersihan ? 'Kebersihan' : (isPembinaRegu ? 'Pembina Regu' : (hasMading ? 'Mading' : (isPengawasLapangan ? 'Pengawas Lapangan' : 'Pengurus')))))))))))))),
    navVisiblePages: isAdmin
      ? []
      : isMudir
        ? []
      : isJamDigitalOperator
        ? ['index.html', 'daftarSantri.html', 'jadwalIbadah.html', 'jamDigital.html', 'jamDigitalRemote.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html']
      : isAcademic
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'strukturOrganisasi.html', 'jadwalIbadah.html', 'dashboardAkademik.html', 'editKelas.html', 'inputKelasLevel.html', 'kelasAbsensi.html', 'nilaiUjian.html', 'editSoal.html', 'quizDigital.html', 'editKaldik.html', 'raport&rekamJejak.html', 'kelolaMading.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html', 'masterPelajaran.html', 'progPelajaran.html']
      : isHalaqohCoordinator
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'dashboardKoordHalaqoh.html', 'editHalaqoh.html', 'editHalaqohTasmi.html', 'halaqohAbsensi.html', 'hafalanHarian.html', 'tasmiSetoran.html', 'ujianHafalan.html', 'nilaiUas.html', 'raport&rekamJejak.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isPengampuHalaqoh
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'halaqohAbsensi.html', 'hafalanHarian.html', 'tasmiSetoran.html', 'ujianHafalan.html', 'nilaiUas.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isPengujiHafalan
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'ujianHafalan.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : canManageNilaiUp
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'kelasAbsensi.html', 'nilaiUjian.html', 'editSoal.html', 'quizDigital.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isBagianKesehatan
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'santriSakit.html', 'pelanggaran.html', 'izinPulang.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isBagianSdm
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'koordinatAbsensi.html', 'kegiatanSop.html', 'rekapAbsensiPengurus.html', 'jurnalSdm.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'dashboardSdm.html', 'editPengurus.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isKsantrian
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'strukturOrganisasi.html', 'jadwalIbadah.html', 'dashboardKesantrian.html', 'editRegu.html', 'reguAbsensi.html', 'perkembanganSantri.html', 'perkembanganTemplate.html', 'raport&rekamJejak.html', 'akhlakKepribadian.html', 'deskripsiSantri.html', 'jenisPelanggaran.html', 'santriSakit.html', 'izinPulang.html', 'pelanggaran.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isKebersihan
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'strukturOrganisasi.html', 'jadwalPiket.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isPembinaRegu
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'strukturOrganisasi.html', 'jadwalIbadah.html', 'reguAbsensi.html', 'perkembanganSantri.html', 'akhlakKepribadian.html', 'deskripsiSantri.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : hasMading
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'strukturOrganisasi.html', 'kelolaMading.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : isPengawasLapangan
        ? ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'jadwalHarianPengurus.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
      : ['index.html', 'kaldik.html', 'daftarSantri.html', 'jadwalIbadah.html', 'pelanggaran.html', 'izinPulang.html', 'santriSakit.html', 'inputAbsensiPengurus.html', 'jurnalSdm.html', 'catatanku.html', 'accountProfile.html', 'changePassword.html', 'logout.html', 'bukuDigital.html', 'bankSoal.html']
  };
  permissions.roleScopeOptions = buildRoleScopeOptions_(permissions, pengurus.jabatanLabels, pengurus.primaryJabatanLabel);
  return permissions;
}

function buildRoleScopeOptions_(permissions, jabatanLabels, primaryJabatanLabel) {
  var labels = Array.isArray(jabatanLabels) ? jabatanLabels.filter(Boolean) : [];
  var isSuperAdmin = !!(permissions && permissions.isSuperAdmin);
  if (isSuperAdmin) {
    try {
      var jabatanState = readSheetState_('jabatan');
      var jabatanNames = jabatanState.rows
        .filter(function (row) { return !isInactiveStatus_(row.status) && cleanString_(row.name); })
        .map(function (row) { return cleanString_(row.name); });
      if (jabatanNames.length) return jabatanNames;
    } catch (e) { /* fallback to hardcode */ }
    return [
      'Super Admin', 'Mudir \'Amm', 'Mudir / Mudiroh', 'Admin', 'Akademik',
      'Bendahara', 'Hotline Service', 'Kesantrian', 'Koordinator Halaqoh', 'Madin',
      'Pengawas Lapangan', 'Pengelolaan Data', 'Perpustakaan', 'Sarpras', 'SDM',
      'Wirawiri', 'Bahasa', 'Dapur', 'Kebersihan Diri', 'Kebersihan Lingkungan',
      'Kesehatan', 'Pengampu Halaqoh', 'Pengajar', 'Pembina Regu', 'Penguji', 'Tarbiyah'
    ];
  }
  // Tambahkan "Pembina Regu" sebagai opsi scope kalau pengurus benar-benar ditugaskan
  // sebagai pembina regu (lewat data regu), walau itu bukan salah satu judul jabatannya.
  var options = labels.slice();
  var hasPembinaReguLabel = listHasAccessKeyword_(
    options.map(normalizeAccessText_),
    ACCESS_CONTROL.pembinaReguJabatanKeywords
  );
  if (!hasPembinaReguLabel && permissions && permissions.isPembinaRegu) {
    options.push('Pembina Regu');
  }

  if (options.length >= 2) {
    var primary = cleanString_(primaryJabatanLabel);
    if (primary && options.indexOf(primary) !== -1) {
      return [primary].concat(options.filter(function (l) { return l !== primary; }));
    }
    return options;
  }
  return [];
}

function allowSantriAction_(action) {
  return action === 'session' ||
    action === 'account.self' ||
    action === 'account.changePassword' ||
    action === 'account.profile.save' ||
    action === 'logout' ||
    action === 'account.logoutAllSessions' ||
    action === 'santri.self' ||
    action === 'content.public.list' ||
    action === 'rekamJejak.data' ||
    action === 'santri.kondisi.pelanggaran' ||
    action === 'santri.kondisi.sakit' ||
    action === 'santri.kondisi.pulang' ||
    action === 'santri.kondisi.zoom' ||
    action === 'jabatan.struktur' ||
    action === 'kaldik.list' ||
    action === 'quiz.santri.list' ||
    action === 'quiz.santri.browse' ||
    action === 'quiz.santri.get' ||
    action === 'quiz.santri.start' ||
    action === 'quiz.santri.answer' ||
    action === 'quiz.santri.submit' ||
    action === 'quiz.santri.result' ||
    action === 'quiz.santri.doc.get' ||
    action === 'quiz.santri.doc.progress';
}

function authorizeAction_(session, action, request) {
  if (!session) {
    throw createError_('Sesi tidak ditemukan.', 401);
  }

  if (session.role === 'santri') {
    if (allowSantriAction_(action)) {
      return;
    }
    throw createError_('Santri hanya bisa melihat data dirinya sendiri.', 403);
  }

  requirePengurus_(session);
  switch (action) {
    case 'logout':
    case 'account.logoutAllSessions':
    case 'session':
    case 'account.self':
    case 'account.changePassword':
    case 'account.profile.save':
    case 'references':
    case 'content.self.list':
    case 'jabatan.names':
    case 'jabatan.struktur':
    case 'pengurus.namesList':
    case 'pengumuman.owed':
    case 'pengumuman.markSeen':
    case 'pengumuman.respond':
    case 'absensi.owed':
    case 'auditBawahan.list':
    case 'survey.owed':
    case 'survey.answer.check':
    case 'survey.complete':
      return;
    case 'loginSession.settings.get':
    case 'loginSession.settings.save':
      requireSuperAdmin_(session);
      return;
    case 'excel.template':
      requireSuperAdmin_(session);
      return;
    case 'dashboard':
      if (session.permissions.isAdmin) return;
      break;
    case 'audit':
      if (session.permissions.isAdmin || session.permissions.canManageHalaqoh || session.permissions.canManageKelasSiang || session.permissions.canManageAbsensi) return;
      break;
    case 'content.public.list':
      return;
    case 'santri.list':
      if (session.permissions.canManageSantri || session.permissions.canViewSantri) return;
      break;
    case 'santri.get':
      if (session.permissions.canManageSantri || session.permissions.isMudir) return;
      break;
    case 'santri.placements':
      if (session.permissions.canManageSantri || session.permissions.canViewSantri) return;
      break;
    case 'santri.duplicates':
    case 'santri.nameSimilar':
    case 'santri.save':
    case 'santri.catatan.save':
    case 'santri.resetPassword':
      if (session.permissions.canManageSantri) return;
      break;
    case 'santri.resetAllPasswords':
    case 'santri.autoSetUsernames':
      requireSuperAdmin_(session);
      return;
    case 'santri.quickImportPreview':
    case 'santri.quickImportExport':
      requireSuperAdmin_(session);
      return;
    case 'santri.summaryPdfData':
    case 'santri.detailPdfData':
    case 'santri.detailTablePdfData':
      if (session.permissions.canManageSantri || session.permissions.canDelete) return;
      break;
    case 'santri.toggle':
      if (session.permissions.canManageSantri) return;
      break;
    case 'santri.delete':
    case 'santri.deleteAll':
    case 'system.deleteAllData':
      requireSuperAdmin_(session);
      return;
    case 'pengurus.list':
    case 'pengurus.dropdown':
    case 'pengurus.get':
      // isBagianSdm ikut diizinkan lihat (bukan cuma isAdmin/isMudir) — SDM butuh daftar pengurus
      // utk halaman Edit Pengurus & Jurnal SDM, sesuai matriks akses ("Edit Pengurus: ...bagian SDM").
      if (session.permissions.canManagePengurus || session.permissions.isMudir || session.permissions.isBagianSdm) return;
      break;
    case 'pengurus.save':
    case 'pengurus.ttd.save':
    case 'pengurus.toggle':
      if (session.permissions.canManagePengurus) return;
      break;
    case 'pengurus.quickImportPreview':
    case 'pengurus.quickImportExport':
      requireSuperAdmin_(session);
      return;
    case 'pengurus.summaryPdfData':
      if (session.permissions.canManagePengurus || session.permissions.canDelete) return;
      break;
    case 'pengurus.delete':
    case 'pengurus.resetAllPasswords':
    case 'pengurus.autoSetUsernames':
    case 'pengurus.exportCredentials':
    case 'santri.exportCredentials':
    case 'admin.clearAllSessions':
    case 'admin.clearInvalidUsernames':
      requireSuperAdmin_(session);
      return;
    case 'jabatan.list':
    case 'jabatan.save':
    case 'jabatan.toggle':
    case 'jabatan.getRelasi':
    case 'jabatan.saveRelasi':
      if (session.permissions.canManageJabatan) return;
      break;
    case 'jabatan.quickImportPreview':
    case 'jabatan.quickImportExport':
      requireSuperAdmin_(session);
      return;
    case 'jabatan.summaryPdfData':
      if (session.permissions.canManageJabatan || session.permissions.canDelete) return;
      break;
    case 'jabatan.delete':
      requireSuperAdmin_(session);
      return;
    case 'halaqoh.list':
      if (session.permissions.canManageHalaqoh || session.permissions.canAccessPanel) return;
      break;
    case 'halaqoh.save':
    case 'halaqoh.toggle':
    case 'halaqoh.pindahkanSantri':
      if (session.permissions.canManageHalaqoh) return;
      break;
    case 'riwayat.list':
      // View-tier "Riwayat / Log Perubahan" (lihat ADDONS_LOCKED_REGISTRY_) -- bawaan: semua
      // pengurus. Hapus (satuan/semua) & pengaturan batas riwayat TETAP di requireRiwayatSuperAdminScope_,
      // tidak ikut diatur di sini.
      if (canAccessLevel_(session, 'riwayatLog', 'view', function () { return true; })) return;
      break;
    case 'pindahHalaqoh.list':
      if (session.permissions.canManageHalaqoh || session.permissions.canAccessPanel) return;
      break;
    case 'pindahHalaqoh.edit':
    case 'pindahHalaqoh.toggle':
      if (canAccessLevel_(session, 'riwayatLog', 'manage', function (s) { return !!(s.permissions && s.permissions.canManageHalaqoh); })) return;
      break;
    case 'pindahHalaqoh.delete':
      requireSuperAdmin_(session);
      return;
    case 'halaqoh.quickImportPreview':
    case 'halaqoh.quickImportExport':
      requireSuperAdmin_(session);
      return;
    case 'halaqoh.summaryPdfData':
      if (session.permissions.canManageHalaqoh || session.permissions.canManageSantri || session.permissions.canDelete) return;
      break;
    case 'halaqoh.delete':
    case 'halaqoh.deleteAll':
    case 'halaqoh.restore':
    case 'halaqoh.purge':
      requireSuperAdmin_(session);
      return;
    case 'halaqohTasmi.list':
      if (session.permissions.canManageHalaqoh || session.permissions.canAccessPanel) return;
      break;
    case 'halaqohTasmi.save':
    case 'halaqohTasmi.toggle':
    case 'halaqohTasmi.autoGenerate.preview':
    case 'halaqohTasmi.autoGenerate.save':
      if (canAccessLevel_(session, 'halaqohTasmi', 'manageStruktur', function (s) { return !!(s.permissions && s.permissions.canManageHalaqoh); })) return;
      break;
    case 'halaqohTasmi.summaryPdfData':
      if (session.permissions.canManageHalaqoh || session.permissions.canManageSantri || session.permissions.canDelete) return;
      break;
    case 'tasmiSetoran.halaqohList':
    case 'tasmiSetoran.list':
    case 'tasmiSetoran.save':
    case 'tasmiSetoran.rekapBulanan':
    case 'tasmiSetoran.rekapBulananLengkap':
      if (canAccessTasmiSetoran_(session)) return;
      break;
    case 'tasmiSetoran.rekapBulananLengkapSemua':
      if (canAccessTasmiSetoranPdfExport_(session)) return;
      break;
    case 'halaqohTasmi.delete':
    case 'halaqohTasmi.restore':
    case 'halaqohTasmi.purge':
      requireSuperAdmin_(session);
      return;
    case 'kelas.list':
      if (session.permissions.canManageKelasSiang || session.permissions.canManageNilaiUp || session.permissions.canAccessPanel) return;
      break;
    case 'kelas.quickImportPreview':
    case 'kelas.quickImportExport':
      requireSuperAdmin_(session);
      return;
    case 'kelas.schedulePdfData':
      if (session.permissions.canManageSantri || session.permissions.canDelete) return;
      break;
    case 'kelas.save':
    case 'kelas.toggle':
      if (session.permissions.canManageKelasSiang) return;
      break;
    case 'kelas.delete':
    case 'kelas.deleteAll':
      requireSuperAdmin_(session);
      return;
    case 'kelas.silabus.list':
    case 'kelas.silabus.toggle':
      if (session.permissions.canManageKelasSiang || session.permissions.canManageNilaiUp) return;
      break;
    case 'kelas.silabus.save':
    case 'kelas.silabus.delete':
    case 'kelas.silabus.reorder':
      if (session.permissions.canManageKelasSiang) return;
      break;
    case 'regu.list':
      if (session.permissions.canManageRegu || session.permissions.canAccessPanel) return;
      break;
    case 'regu.save':
    case 'regu.toggle':
    case 'regu.pindahkanSantri':
      if (session.permissions.canManageRegu) return;
      break;
    case 'pindahRegu.list':
      if (session.permissions.canManageRegu || session.permissions.canAccessPanel) return;
      break;
    case 'pindahRegu.edit':
    case 'pindahRegu.toggle':
      if (canAccessLevel_(session, 'riwayatLog', 'manage', function (s) { return !!(s.permissions && s.permissions.canManageRegu); })) return;
      break;
    case 'pindahRegu.delete':
      requireSuperAdmin_(session);
      return;
    case 'regu.quickImportPreview':
    case 'regu.quickImportExport':
      requireSuperAdmin_(session);
      return;
    case 'regu.summaryPdfData':
      if (session.permissions.canManageRegu || session.permissions.canManageSantri || session.permissions.canDelete) return;
      break;
    case 'regu.delete':
    case 'regu.deleteAll':
      requireSuperAdmin_(session);
      return;
    case 'tahunAjaran.list':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'tahunAjaran.save':
      // edit (ada id) = admin boleh; buat baru (tanpa id) = super admin saja
      if (session.permissions.canDelete) return;
      if (session.permissions.isAdmin && cleanString_((request.record || request).id)) return;
      break;
    case 'tahunAjaran.setActive':
    case 'tahunAjaran.duplicate':
      requireSuperAdmin_(session);
      return;
    case 'tahunAjaran.lock':
    case 'tahunAjaran.reorder':
      if (session.permissions.isAdmin) return;
      break;
    case 'tahunAjaran.deletePreview':
    case 'tahunAjaran.delete':
      requireSuperAdmin_(session);
      return;
    case 'kelasLevel.kelasList':
    case 'kelasLevel.santriList':
      if (session.permissions.canManageKelasLevel || session.permissions.isMudir) return;
      break;
    case 'kelasLevel.save':
      if (canManageAddon_(session, 'raportRekamJejak', function (s) { return !!(s.permissions && s.permissions.canManageKelasLevel); })) return;
      break;
    case 'jadwalHarianPengurus.list':
    case 'jadwalHarianPengurus.saveBulk':
      if (session.permissions.isAdmin || session.permissions.isPengawasLapangan) return;
      break;
    case 'jadwalHarianPengurus.forJurnal':
      // Ikut visibilitas popup Sahkan Kegiatan di jurnalSdm, bukan gate halaman jadwalHarianPengurus --
      // kepemilikan/self-view diverifikasi lebih detail di handler lewat sdmCanViewTarget_.
      if (session.permissions.canManageSdmJurnalAll || session.permissions.canViewSdmJurnalAll) return;
      if (session.permissions.canAccessPanel && cleanString_(request.pengurusId) === String(session.id)) return;
      break;
    case 'jadwalFingerprint.list':
    case 'jadwalFingerprint.saveOverride':
    case 'jadwalFingerprint.resetOverride':
    case 'jadwalFingerprint.unmatchedList':
      if (session.permissions.isAdmin || session.permissions.isPengawasLapangan) return;
      break;
    case 'jadwalFingerprint.deleteUnmatchedScan':
      requireSuperAdmin_(session);
      return;
    case 'perkembangan.reguList':
    case 'perkembangan.santriList':
    case 'perkembangan.entryList':
      if (canAccessLevel_(session, 'reguPerkembangan', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isKsantrian || p.isPembinaRegu || p.isMudir)); })) return;
      break;
    case 'perkembangan.save':
    case 'perkembangan.delete':
      if (canAccessLevel_(session, 'reguPerkembangan', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isKsantrian || p.isPembinaRegu)); })) return;
      break;
    case 'perkembangan.template.list':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin || session.permissions.isKsantrian || session.permissions.isPembinaRegu || session.permissions.isMudir) return;
      break;
    case 'perkembangan.template.save':
    case 'perkembangan.template.delete':
      if (canAccessLevel_(session, 'reguPerkembangan', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isKsantrian)); })) return;
      break;
    case 'akhlak.reguList':
    case 'akhlak.santriList':
    case 'deskripsi.reguList':
    case 'deskripsi.santriList':
    case 'deskripsi.template.list':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin || session.permissions.isKsantrian || session.permissions.isPembinaRegu || session.permissions.isMudir) return;
      break;
    case 'akhlak.save':
    case 'deskripsi.save':
    case 'deskripsi.template.save':
    case 'deskripsi.template.delete':
      if (canManageAddon_(session, 'raportRekamJejak', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isSuperAdmin || p.isKsantrian || p.isPembinaRegu)); })) return;
      break;
    case 'dataKelompokManual.get':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'dataKelompokManual.save':
      if (session.permissions.canManageDataKelompokManual) return;
      break;
    case 'rekamJejak.santriList':
      // Halaman raport&rekamJejak dibuka untuk semua pengurus (view-only), sama seperti
      // rekamJejak.data/raport.data di bawah -- tombol cetak/PDF tetap di-gate di frontend
      // berdasarkan canManageRaport.
      if (session.permissions.canAccessPanel) return;
      break;
    case 'rekamJejak.data':
      // Halaman raport&rekamJejak dibuka untuk semua pengurus (view-only).
      // Tombol cetak/PDF tetap di-gate di frontend berdasarkan canManageRaport.
      if (session.permissions.canAccessPanel) return;
      if (session.role === 'santri') return;
      break;
    case 'raport.data':
      // Halaman raport&rekamJejak dibuka untuk semua pengurus (view-only).
      // Tombol cetak/PDF tetap di-gate di frontend berdasarkan canManageRaport.
      if (session.permissions.canAccessPanel) return;
      break;
    case 'dashboard.admin.audit':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin || session.permissions.isMudir) return;
      break;
    case 'dashboard.koord.audit':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin || session.permissions.isMudir || session.permissions.isHalaqohCoordinator) return;
      break;
    case 'jadwal.ibadah.get':
    case 'jadwal.khutbah.list':
    case 'jadwal.ibadah.beranda.carousel':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'jadwal.ibadah.saveSlot':
    case 'jadwal.ibadah.saveMeta':
    case 'jadwal.khutbah.save':
    case 'jadwal.khutbah.delete':
      if (canManageAddon_(session, 'jadwalIbadah', ADDON_MANAGE_FALLBACK_.jadwalIbadah)) return;
      break;
    case 'kaldik.list':
      // View-tier "Kalender Akademik" (lihat ADDONS_LOCKED_REGISTRY_) -- bawaan: semua pengurus.
      // Santri TIDAK lewat sini sama sekali (sudah selesai duluan di allowSantriAction_ di atas).
      if (canAccessLevel_(session, 'kalenderAkademik', 'view', function () { return true; })) return;
      break;
    case 'kaldik.save':
    case 'kaldik.delete':
    case 'kaldik.quickImportPreview':
    case 'kaldik.quickImport':
      if (canAccessLevel_(session, 'kalenderAkademik', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isSuperAdmin || p.isAcademic)); })) return;
      break;
    case 'kaldik.deleteAll':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin) return;
      break;
    case 'pelajaran.list':
    case 'pelajaran.level.list':
      if (canAccessLevel_(session, 'masterPelajaran', 'view', function (s) { var p = s.permissions; return !!(p && (p.canManagePelajaran || p.isMudir)); })) return;
      break;
    case 'santriPelajaran.list':
    case 'santriPelajaran.detail':
      if (session.permissions.canManagePelajaran || session.permissions.isMudir) return;
      break;
    case 'pelajaran.save':
    case 'pelajaran.level.save':
    case 'pelajaran.level.delete':
    case 'pelajaran.level.reorder':
      if (canAccessLevel_(session, 'masterPelajaran', 'manage', function (s) { return !!(s.permissions && s.permissions.canManagePelajaran); })) return;
      break;
    case 'santriPelajaran.save':
    case 'santriPelajaran.delete':
      if (session.permissions.canManagePelajaran) return;
      break;
    case 'pelajaran.delete':
      requireSuperAdmin_(session);
      return;
    case 'dashboard.akademik.audit':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin || session.permissions.isMudir || session.permissions.isAcademic) return;
      break;
    case 'dashboard.kesantrian.audit':
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin || session.permissions.isMudir || session.permissions.isKsantrian) return;
      break;
    case 'kegiatanSop.list':
    case 'kegiatanSop.byPengurus':
    case 'kegiatanSop.byJabatan':
    case 'kegiatanSop.save':
    case 'kegiatanSop.toggle':
    case 'kegiatanSopLampiran.list':
    case 'kegiatanSopLampiran.save':
      if (session.permissions.canManageKegiatanSop) return;
      break;
    case 'kegiatanSop.delete':
    case 'kegiatanSopLampiran.delete':
      requireSuperAdmin_(session);
      return;
    // ── Catatan & Dokumen (pages/catatanku) ──────────────────────────────────
    // Semua pengurus boleh membuka halaman & melihat dokumen yang dibagikan padanya;
    // kontrol per-dokumen (pemilik / target berbagi) dikerjakan di dalam tiap handler.
    case 'catatan.refs':
    case 'catatan.list':
    case 'catatan.get':
    case 'catatan.saveContent':
    case 'catatan.rename':
    case 'catatan.pin':
    case 'catatan.share.list':
    case 'catatan.share.set':
    case 'catatan.versions':
    case 'catatan.version.get':
    case 'catatan.version.restore':
    case 'catatan.delete':
    case 'catatan.discardEmpty':
    case 'catatan.restore':
      return;
    case 'catatan.create':
      // Bawaan: hanya Mudir, Admin, dan Super Admin yang boleh membuat dokumen baru -- bisa
      // digantikan lewat Jabatan Pengelola di Kelola Addons (lihat canManageAddon_).
      if (canManageAddon_(session, 'catatanku', ADDON_MANAGE_FALLBACK_.catatanku)) return;
      throw createError_('Hanya Mudir, Admin, Super Admin, atau jabatan yang diatur di Kelola Addons yang dapat membuat dokumen.', 403);
    case 'catatan.purge':
      requireSuperAdmin_(session);
      return;
    case 'nilaiup.list':
    case 'nilaiup.by.kelas':
    case 'nilaiup.absensi.summary':
      if (session.permissions.canManageNilaiUp || session.permissions.isMudir) return;
      break;
    case 'nilaiup.save':
    case 'nilaiup.toggle':
    case 'nilaiup.session.delete':
      if (canAccessLevel_(session, 'kelasSiangNilai', 'manage', function (s) { return !!(s.permissions && s.permissions.canManageNilaiUp); })) return;
      break;
    case 'nilaiup.delete':
    case 'nilaiup.excel.save':
      requireSuperAdmin_(session);
      return;
    case 'absensi.list':
    case 'absensi.save':
    case 'absensi.toggle':
      if (session.permissions.canManageAbsensi) return;
      break;
    case 'absensi.delete':
      requireSuperAdmin_(session);
      return;
    // ROLE (permission gate): butuh salah satu role Super Admin / Admin / Koordinator Halaqoh / Pengampu Halaqoh.
    // Pengecekan scope (halaqoh mana yang boleh diakses) dilakukan terpisah di getAccessibleHalaqohAttendanceItems_().
    case 'halaqoh.absensi.dashboard':
    case 'halaqoh.absensi.get':
      if (session.permissions.canManageHalaqoh || session.permissions.isMudir) return;
      break;
    case 'halaqoh.absensi.save':
      if (canAccessLevel_(session, 'misiTahfizh', 'manage', function (s) { return !!(s.permissions && s.permissions.canManageHalaqoh); })) return;
      break;
    case 'kelas.absensi.dashboard':
    case 'kelas.absensi.get':
      if (canAccessLevel_(session, 'kelasSiangNilai', 'manage', function (s) { var p = s.permissions; return !!(p && (p.canManageKelasSiang || p.canManageNilaiUp || p.isMudir)); })) return;
      break;
    case 'kelas.absensi.save':
      if (canAccessLevel_(session, 'kelasSiangNilai', 'manage', function (s) { var p = s.permissions; return !!(p && (p.canManageKelasSiang || p.canManageNilaiUp)); })) return;
      break;
    // ROLE (permission gate): butuh salah satu role Super Admin / Admin / Kesantryan / Pembina Regu.
    // Pengecekan scope (regu mana yang boleh diakses) dilakukan terpisah di getAccessibleReguAttendanceItems_().
    case 'regu.absensi.dashboard':
    case 'regu.absensi.get':
      if (session.permissions.canManageRegu || session.permissions.isPembinaRegu || session.permissions.isMudir) return;
      break;
    case 'regu.absensi.save':
      if (canAccessLevel_(session, 'reguPerkembangan', 'manage', function (s) { var p = s.permissions; return !!(p && (p.canManageRegu || p.isPembinaRegu)); })) return;
      break;
    case 'content.list':
      if (canManageAddon_(session, 'madingDigital', ADDON_MANAGE_FALLBACK_.madingDigital)) return;
      break;
    case 'content.save':
    case 'content.toggle':
      if (canManageAddon_(session, 'madingDigital', ADDON_MANAGE_FALLBACK_.madingDigital)) return;
      break;
    case 'content.delete':
      requireSuperAdmin_(session);
      return;
    case 'pengumuman.list':
    case 'pengumuman.save':
    case 'pengumuman.discardMedia':
    case 'pengumuman.toggle':
    case 'pengumuman.responses':
    case 'pengumuman.seenList':
    case 'pengumuman.respon.delete':
    case 'pengumuman.respon.deleteAll':
    case 'pengumuman.seen.delete':
    case 'pengumuman.seen.deleteAll':
    case 'survey.list':
    case 'survey.save':
    case 'survey.toggle':
    case 'survey.completionList':
    case 'survey.completion.delete':
    case 'survey.completion.deleteAll':
      if (canManageAddon_(session, 'pengumumanSurvey', ADDON_MANAGE_FALLBACK_.pengumumanSurvey)) return;
      break;
    case 'audit.settings.get':
    case 'audit.settings.set':
      if (canAccessLevel_(session, 'sistemAudit', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isMudir)); })) return;
      break;
    case 'addons.settings.get':
    case 'addons.settings.set':
      // Kelola Addons: Admin/Super Admin saja (BEDA dari audit.settings di atas yang ikut
      // membolehkan Mudir) -- disamakan dengan portalSettings/backup, bukan kelolaAudit.
      if (session.permissions.isAdmin || session.permissions.isSuperAdmin) return;
      break;
    case 'auditBawahan.settings.get':
    case 'auditBawahan.settings.set':
    case 'auditBawahan.settings.setAudiences':
      // auditBawahan.list SENGAJA TIDAK di sini -- lihat komentar di handleAuditBawahanList_
      // (gerbangnya lebih longgar, pengurus mana pun boleh manggil, difilter per-kind sendiri
      // di dalam). Sengaja pakai canManageAuditBawahan_ (rawPermissions, BUKAN
      // session.permissions) -- lihat komentar di fungsi itu.
      if (canManageAuditBawahan_(session)) return;
      break;
    case 'pengumuman.delete':
    case 'survey.delete':
      requireSuperAdmin_(session);
      return;
    // Quiz Digital: gerbang peran = sama dengan Edit Soal / Nilai Ujian (canManageNilaiUp =
    // Admin/Akademik/pengajar-berjabatan, plus Mudir). Scope "kelas mana yang boleh" dicek
    // per-record di handler lewat assertCanManageQuizKelas_. Tempat sampah (trash/restore/
    // delete permanen) & folder = gerbang peran SAMA (bukan super-admin-only) — sesuai
    // permintaan: pengelola quiz kelas boleh semua aksi.
    case 'quiz.browse':
    case 'quiz.get':
    case 'quiz.save':
    case 'quiz.duplicate':
    case 'quiz.toggle':
    case 'quiz.publish':
    case 'quiz.releaseResults':
    case 'quiz.results':
    case 'quiz.results.notDone':
    case 'quiz.doc.readers':
    case 'quiz.grade':
    case 'quiz.trash':
    case 'quiz.restore':
    case 'quiz.delete':
    case 'quiz.setFolder':
    case 'quizFolder.children':
    case 'quizFolder.get':
    case 'quizFolder.save':
    case 'quizFolder.duplicate':
    case 'quizFolder.delete':
      if (canManageAddon_(session, 'quizDigital', ADDON_MANAGE_FALLBACK_.quizDigital)) return;
      break;
    case 'portal.brand.get':
      if (session.permissions && session.permissions.isMudir) return;
      requireSuperAdmin_(session);
      return;
    case 'portal.brand.save':
      requireSuperAdmin_(session);
      return;
    case 'hafalan.harian.list':
    case 'hafalan.harian.halaqoh.list':
    case 'hafalan.harian.rekap':
    case 'hafalan.harian.rekap.semua':
    case 'hafalan.harian.top.ziyadah':
    case 'hafalan.harian.santriDetail':
    case 'hafalan.harian.lastPosisi':
    case 'hafalan.harian.auditKontinuitas':
      if (canAccessHafalanHarian_(session) || (session.permissions && session.permissions.isMudir)) return;
      break;
    case 'hafalan.harian.save':
      if (canAccessHafalanHarian_(session)) return;
      break;
    case 'hafalan.harian.delete':
      if (canAccessHafalanHarian_(session)) return;
      break;
    case 'hafalan.harian.hapus.semua':
      requireSuperAdmin_(session);
      return;
    case 'ujian.hafalan.list':
      if (canAccessUjianHafalan_(session) || (session.permissions && session.permissions.isMudir)) return;
      break;
    case 'ujian.hafalan.save':
    case 'ujian.hafalan.set.status':
      if (canAccessUjianHafalan_(session)) return;
      break;
    case 'ujian.hafalan.delete':
      if (canGradeUjianHafalan_(session)) return;
      break;
    case 'uas.list':
      if (canAccessNilaiUas_(session) || (session.permissions && session.permissions.isMudir)) return;
      break;
    case 'uas.save':
      if (canAccessNilaiUas_(session)) return;
      break;
    case 'uas.delete':
      if (session.permissions && (session.permissions.isAdmin || session.permissions.isSuperAdmin)) return;
      break;
    case 'santri.sakit.list':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'santri.sakit.save':
    case 'santri.sakit.setStatus':
    case 'santri.sakit.update':
    case 'santri.sakit.foto.upload':
    case 'santri.sakit.foto.delete':
      if (canAccessLevel_(session, 'pelanggaranKondisi', 'manage', function (s) { return !!(s.permissions && s.permissions.canAccessSantriSakit); })) return;
      break;
    case 'buku.list':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'buku.save':
    case 'buku.update':
    case 'buku.delete':
    case 'buku.quill.save':
      if (canManageAddon_(session, 'bukuDigital', ADDON_MANAGE_FALLBACK_.bukuDigital)) return;
      break;
    case 'banksoal.list':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'banksoal.save':
    case 'banksoal.quill.save':
      if (canManageAddon_(session, 'bankSoal', ADDON_MANAGE_FALLBACK_.bankSoal)) return;
      break;
    case 'banksoal.update':
    case 'banksoal.delete':
      if (canManageAddon_(session, 'bankSoal', ADDON_MANAGE_FALLBACK_.bankSoal)) return; // handler checks ownership
      break;
    case 'izin.pulang.list':
      if (session.permissions.canAccessPanel) return; // semua pengurus bisa lihat
      break;
    case 'izin.pulang.save':
    case 'izin.pulang.update':
    case 'izin.pulang.setStatus':
    case 'izin.pulang.foto.upload':
    case 'izin.pulang.foto.delete':
      if (canAccessLevel_(session, 'pelanggaranKondisi', 'manage', function (s) { return !!(s.permissions && s.permissions.canAccessIzinPulang); })) return;
      break;
    case 'santri.sakit.delete':
    case 'santri.sakit.deleteAll':
      requireSuperAdmin_(session);
      return;
    case 'izin.pulang.delete':
    case 'izin.pulang.deleteAll':
      requireSuperAdmin_(session);
      return;
    case 'pelanggaran.jenis.list':
    case 'zoom.santriList':
      if (session.permissions.canAccessPanel) return;
      break;
    case 'zoom.kehadiran.save':
    case 'zoom.kunjungan.save':
      if (canManageAddon_(session, 'rekapZoom', ADDON_MANAGE_FALLBACK_.rekapZoom)) return;
      break;
    case 'pelanggaran.list':
    case 'pelanggaran.save':
      if (canAccessLevel_(session, 'pelanggaranKondisi', 'input', function (s) { return !!(s.permissions && s.permissions.canInputPelanggaran); })) return;
      break;
    case 'pelanggaran.update':
    case 'pelanggaran.toggle':
    case 'pelanggaran.foto.upload':
    case 'pelanggaran.foto.delete':
      if (session.permissions.canAssignHukuman) return;
      break;
    case 'pelanggaran.assign.hukuman':
      if (session.permissions.canAssignHukuman) return;
      break;
    case 'pelanggaran.jenis.save':
    case 'pelanggaran.jenis.toggle':
      if (canAccessLevel_(session, 'pelanggaranKondisi', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isKsantrian)); })) return;
      break;
    case 'pelanggaran.delete':
    case 'pelanggaran.deleteAll':
    case 'pelanggaran.jenis.delete':
      requireSuperAdmin_(session);
      return;
    case 'lokasi.absensi.list':
      if (session.permissions.canManageKoordinatAbsensi || session.permissions.isMudir) return;
      break;
    case 'lokasi.absensi.save':
      if (session.permissions.canManageKoordinatAbsensi) return;
      break;
    case 'lokasi.absensi.delete':
      requireAdmin_(session);
      return;
    case 'koordinat.absensi.list':
      if (session.permissions.canManageKoordinatAbsensi || session.permissions.isMudir) return;
      break;
    case 'koordinat.absensi.save':
      if (session.permissions.canManageKoordinatAbsensi) return;
      break;
    case 'koordinat.absensi.delete':
      requireAdmin_(session);
      return;
    case 'pengurus.absensi.list':
    case 'pengurus.absensi.cekGeo':
    case 'pengurus.absensi.save':
    case 'pengurus.absensi.foto.upload':
    case 'pengurus.absensi.foto.delete':
    case 'pengurus.absensi.delete':
      // Hapus diizinkan untuk pengurus; kepemilikan (atau hak manager) diverifikasi di handler.
      if (session.permissions.canAccessPanel) return;
      break;
    case 'rekap.absensi.pengurus.list':
    case 'rekap.absensi.pengurus.detail':
      if (session.permissions.canManageKoordinatAbsensi || session.permissions.isMudir) return;
      break;
    case 'sdm.jurnal.pilihanKegiatan':
    case 'sdm.jurnal.bulan.detail':
      assertNoPendingAudit_(session);
      // Admin/SDM (semua pengurus) & Mudir (semua, read-only) boleh lihat siapa saja;
      // pengurus biasa cuma boleh lihat data miliknya sendiri.
      if (session.permissions.canManageSdmJurnalAll || session.permissions.canViewSdmJurnalAll) return;
      if (session.permissions.canAccessPanel && cleanString_(request.pengurusId) === String(session.id)) return;
      break;
    case 'sdm.jurnal.entry.save':
    case 'sdm.jurnal.izin.save':
    case 'sdm.jurnal.izin.entry.update':
      assertNoPendingAudit_(session);
      // Semua pengurus boleh coba isi/ubah kegiatan/izin; kepemilikan & aturan tanggal
      // (utk yang bukan Admin/SDM) diverifikasi di handler.
      if (session.permissions.canAccessPanel) return;
      break;
    case 'sdm.jurnal.entry.pengesahan':
    case 'sdm.fingerprint.save':
    case 'sdm.dataLapangan.save':
      assertNoPendingAudit_(session);
      if (session.permissions.canManageSdmJurnalAll) return;
      break;
    case 'sdm.jurnal.entry.delete':
      requireSuperAdmin_(session);
      return;
    case 'entity.deletePreview':
      requireSuperAdmin_(session);
      return;
    case 'import.preview':
    case 'batch.save':
    case 'bulk.toggle':
    case 'bulk.setStatus':
    case 'bulk.setTahunAjaran':
    case 'bulk.delete':
    case 'export.data':
      return authorizeGenericRequest_(session, action, request);
    default:
      return;
  }

  throw createError_('Aksi ini tidak diizinkan untuk akun Anda.', 403);
}

function authorizeGenericRequest_(session, action, request) {
  if (action === 'export.data') {
    requireSuperAdmin_(session);
    var sheetKeys = parseSheetKeyList_(request.sheetKeys || request.sheetKey);
    if (!sheetKeys.length || (sheetKeys.length === 1 && sheetKeys[0] === 'all')) {
      if (!session.permissions || !session.permissions.canExportAll) {
        throw createError_('Download semua data hanya untuk Super Admin.', 403);
      }
      return;
    }
    sheetKeys.forEach(function (sheetKey) {
      authorizeSheetRead_(session, sheetKey);
    });
    return;
  }

  var sheetKey = normalizeSheetKey_(request.sheetKey);
  if (action === 'import.preview' || action === 'batch.save') {
    requireSuperAdmin_(session);
  }
  if (action === 'bulk.delete') {
    requireSuperAdmin_(session);
    return;
  }
  if (action === 'bulk.toggle' && sheetKey === 'santri') {
    requireAdminOrSuperAdmin_(session);
  }
  authorizeSheetMutation_(session, sheetKey, (action === 'batch.save' || action === 'import.preview') ? 'save' : 'toggle');
}

function authorizeSheetRead_(session, sheetKey) {
  authorizeSheetMutation_(session, normalizeSheetKey_(sheetKey), 'read');
}

function authorizeSheetMutation_(session, sheetKey, mode) {
  requirePengurus_(session);
  switch (normalizeSheetKey_(sheetKey)) {
    case 'santri':
      if (session.permissions.canManageSantri) return;
      break;
    case 'pengurus':
      if (session.permissions.canManagePengurus) return;
      break;
    case 'jabatan':
      if (session.permissions.canManageJabatan) return;
      break;
    case 'halaqoh':
      if (mode === 'save' || mode === 'read') {
        if (!session.permissions.canDelete) {
          throw createError_('Template, Import, dan Export Excel halaqoh hanya untuk Super Admin.', 403);
        }
      }
      if (session.permissions.canManageHalaqoh) return;
      break;
    case 'halaqohTasmi':
      if (session.permissions.canManageHalaqoh) return;
      break;
    case 'kelasSiang':
      if (session.permissions.canManageKelasSiang) return;
      break;
    case 'regu':
      if (session.permissions.canManageRegu) return;
      break;
    case 'nilaiUp':
      if (session.permissions.canManageNilaiUp) return;
      break;
    case 'absensiGuru':
      if (session.permissions.canManageAbsensi) return;
      break;
    case 'kegiatanSop':
      if (session.permissions.canManageKegiatanSop) return;
      break;
    case 'content':
      if (session.permissions.canManageContent || mode === 'read') return;
      break;
    case 'izinPulang':
      if (session.permissions.canDelete) return;
      throw createError_('Import, Export, dan Template Excel Izin Pulang hanya untuk Super Admin.', 403);
    case 'santriSakit':
      if (session.permissions.canDelete) return;
      throw createError_('Import, Export, dan Template Excel Santri Sakit hanya untuk Super Admin.', 403);
    case 'pelanggaran':
      if (session.permissions.canDelete) return;
      throw createError_('Import, Export, dan Template Excel Pelanggaran hanya untuk Super Admin.', 403);
  }
  throw createError_('Anda tidak memiliki akses ke data ini.', 403);
}

function normalizeSheetKey_(sheetKey) {
  var key = cleanString_(sheetKey);
  switch (key) {
    case 'santri':
    case 'pengurus':
    case 'jabatan':
    case 'halaqoh':
    case 'halaqohTasmi':
    case 'regu':
    case 'content':
      return key;
    case 'halaqohtasmi':
      return 'halaqohTasmi';
    case 'kelas':
    case 'kelasSiang':
      return 'kelasSiang';
    case 'nilaiup':
    case 'nilaiUp':
      return 'nilaiUp';
    case 'absensi':
    case 'absensiGuru':
      return 'absensiGuru';
    case 'kegiatan_sop':
    case 'kegiatansop':
    case 'kegiatanSop':
      return 'kegiatanSop';
    case 'izinPulang':
    case 'izin_pulang':
    case 'izinpulang':
      return 'izinPulang';
    case 'santriSakit':
    case 'santri_sakit':
    case 'santrisakit':
      return 'santriSakit';
    case 'pelanggaran':
      return 'pelanggaran';
    default:
      throw createError_('Sheet key tidak dikenal: ' + key, 400);
  }
}

function parseSheetKeyList_(value) {
  if (Array.isArray(value)) {
    return value.map(function (item) { return cleanString_(item); }).filter(Boolean);
  }
  var cleaned = cleanString_(value);
  if (!cleaned) {
    return [];
  }
  return cleaned.split(/[,\n;]/).map(function (item) {
    return cleanString_(item);
  }).filter(Boolean);
}

function getExportableSheetKeys_() {
  return ['santri', 'pengurus', 'jabatan', 'halaqoh', 'kelasSiang', 'regu', 'nilaiUp', 'absensiGuru', 'kegiatanSop', 'content'];
}

function saveRecordBySheetKey_(sheetKey, request, session) {
  switch (normalizeSheetKey_(sheetKey)) {
    case 'santri':
      return handleSantriSave_(request, session);
    case 'pengurus':
      return handlePengurusSave_(request, session);
    case 'jabatan':
      return handleJabatanSave_(request, session);
    case 'halaqoh':
      return handleHalaqohSave_(request, session);
    case 'kelasSiang':
      return handleKelasSave_(request, session);
    case 'regu':
      return handleReguSave_(request, session);
    case 'nilaiUp':
      return handleNilaiUpSave_(request, session);
    case 'absensiGuru':
      return handleAbsensiGuruSave_(request, session);
    case 'kegiatanSop':
      return handleKegiatanSopSave_(request, session);
    case 'content':
      return handleContentSave_(request, session);
    default:
      throw createError_('Sheet key tidak dikenal: ' + sheetKey, 400);
  }
}

function collectPengurusKelasIds_(pengurusId, dataset) {
  if (!dataset || !dataset.kelasSiang) {
    return [];
  }
  return dataset.kelasSiang.filter(function (kelas) {
    return kelas.active && (
      kelas.pengajarIds.indexOf(cleanString_(pengurusId)) !== -1 ||
      kelas.badalIds.indexOf(cleanString_(pengurusId)) !== -1
    );
  }).map(function (kelas) {
    return kelas.id;
  });
}

// Regu yang dibina oleh pengurus ini (sebagai pembina regu) — untuk scoping Raport/Rekam Jejak
function collectPembinaReguIds_(pengurusId, dataset) {
  var target = cleanString_(pengurusId);
  if (!target || !dataset || !dataset.regu) {
    return [];
  }
  return dataset.regu.filter(function (regu) {
    return regu.active && (
      (regu.pembinaIds || []).indexOf(target) !== -1 ||
      (regu.badalIds || []).indexOf(target) !== -1
    );
  }).map(function (regu) {
    return regu.id;
  });
}

function collectPengurusHalaqohIds_(pengurusId, dataset) {
  var target = cleanString_(pengurusId);
  if (!target || !dataset || !dataset.halaqoh) {
    return [];
  }
  return dataset.halaqoh.filter(function (halaqoh) {
    return halaqoh.active && (
      halaqoh.pengampuIds.indexOf(target) !== -1 ||
      halaqoh.badalIds.indexOf(target) !== -1
    );
  }).map(function (halaqoh) {
    return halaqoh.id;
  });
}

/* ===================== Jadwal Harian Pengurus (jam ibadah harian) ===================== */

var JADWAL_HARIAN_PENGURUS_FIELD_KEYS = [
  'jam_tetap_shubuh', 'jam_hadir_shubuh',
  'jam_0800', 'jam_0900', 'jam_1000', 'jam_1300', 'jam_1400',
  'jam_tetap_isya', 'jam_hadir_isya'
];

function buildJadwalHarianPengurusEntryView_(row) {
  if (!row) return null;
  var view = { id: cleanString_(row.id), tanggal: cleanString_(row.tanggal) };
  JADWAL_HARIAN_PENGURUS_FIELD_KEYS.forEach(function (key) {
    view[key] = cleanString_(row[key]);
  });
  return view;
}

function handleJadwalHarianPengurusList_(request) {
  var dataset = loadDataset_();
  var tahunAjaranId = resolveTahunAjaranId_(request.tahunAjaranId, dataset);
  var tanggal = normalizeDateOnly_(request.tanggal) || nowIso_().slice(0, 10);
  var genderFilter = cleanString_(request.gender).toLowerCase();
  var jabatanFilter = cleanString_(request.jabatanId || '');

  var activePengurus = dataset.pengurus.filter(function (p) {
    if (!p.active) return false;
    if (genderFilter && cleanString_(p.gender).toLowerCase() !== genderFilter) return false;
    return true;
  });

  var state = readSheetState_('jadwalHarianPengurus');
  var rowsByPengurus = {};
  state.rows.forEach(function (row) {
    if (isInactiveStatus_(row.status)) return;
    var pid = cleanString_(row.id_pengurus);
    if (!pid) return;
    (rowsByPengurus[pid] = rowsByPengurus[pid] || []).push(row);
  });

  var items = activePengurus.map(function (p) {
    return { p: p, enriched: enrichPengurus_(p, dataset) };
  }).filter(function (x) {
    if (!jabatanFilter) return true;
    return x.enriched.jabatanIds.indexOf(jabatanFilter) !== -1;
  }).map(function (x) {
    var p = x.p, enriched = x.enriched;
    var labelTokens = (enriched.jabatanLabels || []).map(normalizeAccessText_);
    var hasHalaqoh = collectPengurusHalaqohIds_(p.id, dataset).length > 0;
    var hasKelas = collectPengurusKelasIds_(p.id, dataset).length > 0;
    var isPenguji = listHasAccessKeyword_(labelTokens, ACCESS_CONTROL.pengujiHafalanJabatanKeywords);
    var sortTier = (hasHalaqoh && hasKelas) ? 0 : (hasHalaqoh ? 1 : (hasKelas ? 2 : (isPenguji ? 3 : 4)));

    var todayRow = (rowsByPengurus[p.id] || []).filter(function (r) { return cleanString_(r.tanggal) === tanggal; })[0] || null;

    return {
      id: p.id,
      name: p.name,
      gender: p.gender,
      primaryJabatanLabel: enriched.primaryJabatanLabel,
      sortTier: sortTier,
      todayEntry: buildJadwalHarianPengurusEntryView_(todayRow)
    };
  });

  items.sort(function (a, b) {
    if (a.sortTier !== b.sortTier) return a.sortTier - b.sortTier;
    return (a.name || '').localeCompare(b.name || '');
  });

  var jabatanList = dataset.jabatan.filter(function (j) { return j.active; })
    .map(function (j) { return { id: j.id, name: j.name }; })
    .sort(function (a, b) { return (a.name || '').localeCompare(b.name || ''); });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      tahunAjaranId: tahunAjaranId,
      tahunAjaranList: taSelectorList_(dataset),
      tanggal: tanggal,
      jabatanList: jabatanList,
      items: items
    }
  };
}

// Dipakai halaman jurnalSdm (popup Sahkan Kegiatan) utk menampilkan satu entri jadwal
// harian pengurus (read-only) sesuai pengurus & tanggal yang sedang dibuka di sana.
// Aksesnya SENGAJA dipisah dari 'jadwalHarianPengurus.list'/'.saveBulk' (yang cuma buat
// Admin/Pengawas Lapangan) -- di sini ikut visibilitas popup jurnalSdm sendiri: full
// manager/Mudir boleh lihat siapa saja, pengurus biasa cuma boleh lihat miliknya sendiri.
function handleJadwalHarianPengurusForJurnal_(request, session) {
  var pengurusId = cleanString_(request.pengurusId || '');
  if (!pengurusId) throw createError_('pengurusId wajib.', 400);
  if (!sdmCanViewTarget_(session, pengurusId)) throw createError_('Anda hanya bisa mengakses data milik sendiri.', 403);
  var tanggal = normalizeDateOnly_(request.tanggal);
  if (!tanggal) throw createError_('Tanggal tidak valid.', 400);

  var state = readSheetState_('jadwalHarianPengurus');
  var row = state.rows.filter(function (r) {
    return !isInactiveStatus_(r.status) &&
      cleanString_(r.id_pengurus) === pengurusId &&
      cleanString_(r.tanggal) === tanggal;
  })[0] || null;

  return {
    ok: true,
    timestamp: nowIso_(),
    data: { entry: buildJadwalHarianPengurusEntryView_(row) }
  };
}

function handleJadwalHarianPengurusSaveBulk_(request) {
  var tanggal = normalizeDateOnly_(request.tanggal);
  if (!tanggal) throw createError_('Tanggal tidak valid.', 400);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var entries = Array.isArray(request.entries) ? request.entries : [];

  var dataset = loadDataset_();
  var state = readSheetState_('jadwalHarianPengurus');

  var savedCount = 0;
  entries.forEach(function (entry) {
    var pengurusId = cleanString_(entry && entry.id_pengurus);
    if (!pengurusId) return;
    var pengurus = dataset.indexes.pengurusById[pengurusId];
    if (!pengurus) return;

    var record = {
      id_pengurus: pengurusId,
      pengurus_nama: pengurus.name,
      tanggal: tanggal,
      id_tahun_ajaran: tahunAjaranId,
      status: STATUS_LABELS.jadwalHarianPengurus.active
    };
    var hasValue = false;
    JADWAL_HARIAN_PENGURUS_FIELD_KEYS.forEach(function (key) {
      var v = cleanString_(entry ? entry[key] : '');
      record[key] = v;
      if (v) hasValue = true;
    });

    var existing = state.rows.filter(function (row) {
      return !isInactiveStatus_(row.status) &&
        cleanString_(row.id_pengurus) === pengurusId &&
        cleanString_(row.tanggal) === tanggal;
    })[0] || null;

    if (!existing && !hasValue) return;

    var writable = pickWritableValues_(record, state.schema.columns);
    if (existing) {
      updateSheetRow_(state, existing._rowNumber, writable);
    } else {
      writable.id = String(nextId_(state.rows));
      appendSheetRow_(state, writable);
    }
    savedCount += 1;
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: { message: 'Jadwal harian pengurus disimpan (' + savedCount + ' entri).', savedCount: savedCount }
  };
}

/* ===================== Fingerprint (raw scan ingest + jadwal turunan otomatis) ===================== */

// Pemetaan jam scan mentah -> kolom checkpoint, sama seperti jadwalHarianPengurus tapi tanpa
// kolom "jam_tetap_*" (itu jadwal target, bukan kehadiran aktual). Batas jam ini masih perkiraan
// awal -- wajar disesuaikan lagi setelah lihat pola scan asli dari alat di lokasi.
var FINGERPRINT_CHECKPOINT_WINDOWS = [
  { key: 'jam_hadir_shubuh', start: '00:00', end: '06:30' },
  { key: 'jam_0800', start: '06:31', end: '08:30' },
  { key: 'jam_0900', start: '08:31', end: '09:30' },
  { key: 'jam_1000', start: '09:31', end: '11:30' },
  { key: 'jam_1300', start: '11:31', end: '13:30' },
  { key: 'jam_1400', start: '13:31', end: '15:30' },
  { key: 'jam_hadir_isya', start: '18:00', end: '23:59' }
];
var JADWAL_FINGERPRINT_FIELD_KEYS = FINGERPRINT_CHECKPOINT_WINDOWS.map(function (w) { return w.key; });

// fingerprintLog & jadwalFingerprintOverride pakai label soft-delete 'Dihapus' (bukan
// 'Nonaktif'/'Inactive'), jadi TIDAK bisa pakai isInactiveStatus_ (itu buat sinonim lain) --
// harus dicek eksplisit, sama seperti pola sdmFingerprint/sdmDataLapangan.
function isFingerprintRowDeleted_(status) {
  return cleanString_(status || '').toLowerCase() === 'dihapus';
}

function fingerprintTimeToMinutes_(hhmm) {
  var parts = (hhmm || '00:00').split(':');
  return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
}

// scans: array jam "HH:MM" (belum tentu terurut) dalam satu hari -> ambil scan PERTAMA
// yang jatuh di tiap window sebagai jam checkpoint.
function computeFingerprintCheckpoints_(scans) {
  var sorted = scans.slice().sort();
  var result = {};
  FINGERPRINT_CHECKPOINT_WINDOWS.forEach(function (win) {
    var startM = fingerprintTimeToMinutes_(win.start);
    var endM = fingerprintTimeToMinutes_(win.end);
    result[win.key] = sorted.filter(function (t) {
      var m = fingerprintTimeToMinutes_(t);
      return m >= startM && m <= endM;
    })[0] || '';
  });
  return result;
}

// Insert satu scan mentah ke tabel fingerprintLog, dedupe by (id_pengurus, tanggal, waktu).
// `state`/`dataset` dikirim dari caller supaya bisa dipakai berulang saat insert banyak scan
// sekaligus (satu kali baca tabel, bukan re-read tiap baris).
function ingestOneFingerprintScan_(state, dataset, raw) {
  var idPengurus = cleanString_(raw.idPengurus || '');
  if (!idPengurus) return false;
  var tanggal = normalizeDateOnly_(raw.tanggal);
  var waktu = hhmm_(raw.waktu);
  if (!tanggal || !/^\d{2}:\d{2}$/.test(waktu)) return false;

  // PIN yang tidak cocok dengan id_pengurus manapun TETAP disimpan (bukan dibuang) --
  // supaya scan mentah dari alat tidak pernah hilang, walaupun PIN-nya salah/belum terdaftar.
  // Baris begini tidak akan muncul di halaman jadwalFingerprint (yang dikelompokkan per
  // pengurus terdaftar), tapi tetap tercatat di tabel fingerprintLog untuk ditelusuri manual.
  var pengurus = dataset.indexes.pengurusById[idPengurus] || null;
  var dup = state.rows.some(function (row) {
    return !isFingerprintRowDeleted_(row.status) &&
      cleanString_(row.id_pengurus) === idPengurus &&
      cleanString_(row.tanggal) === tanggal &&
      hhmm_(row.waktu) === waktu;
  });
  if (dup) return false;

  var writable = pickWritableValues_({
    id_pengurus: idPengurus,
    pengurus_nama: pengurus ? pengurus.name : '',
    tanggal: tanggal,
    waktu: waktu,
    tipe: cleanString_(raw.tipe || ''),
    sumber: cleanString_(raw.sumber || ''),
    device_sn: cleanString_(raw.deviceSn || ''),
    catatan: cleanString_(raw.catatan || '') || (pengurus ? '' : 'PIN tidak cocok id_pengurus manapun'),
    status: STATUS_LABELS.fingerprintLog.active
  }, state.schema.columns);
  writable.id = String(nextId_(state.rows));
  appendSheetRow_(state, writable);
  state.rows.push(writable); // biar dedupe scan berikutnya dlm batch yg sama ikut ke-detect
  return true;
}

// Dipanggil script bridge lokal (tools/fingerprintBridge) -- otentikasi pakai bridgeKey yang
// diatur dari halaman jadwalFingerprint (fingerprintSettingsState), BUKAN token login pengurus,
// karena ini machine-to-machine (lihat handleRequest_).
function handleFingerprintBridgeIngest_(request) {
  var bridgeKey = cleanString_(request.bridgeKey || '');
  if (!fingerprintSettingsState.bridgeKey || bridgeKey !== fingerprintSettingsState.bridgeKey) {
    throw createError_('Bridge key tidak valid.', 401);
  }
  fingerprintConnectionState.bridgePushAt = nowIso_();
  var records;
  try {
    records = typeof request.records === 'string' ? JSON.parse(request.records || '[]') : (request.records || []);
  } catch (e) {
    throw createError_('Format records tidak valid (harus JSON array).', 400);
  }
  if (!Array.isArray(records)) throw createError_('records harus berupa array.', 400);

  var dataset = loadDataset_();
  var state = readSheetState_('fingerprintLog');
  var inserted = 0, skipped = 0;
  records.forEach(function (r) {
    var dt = cleanString_((r && (r.waktu || r.time)) || ''); // "YYYY-MM-DD HH:MM:SS"
    var ok = dt.length >= 16 && ingestOneFingerprintScan_(state, dataset, {
      idPengurus: r.pin || r.idPengurus,
      tanggal: dt.slice(0, 10),
      waktu: dt.slice(11, 16),
      tipe: r.tipe || r.type,
      sumber: 'bridgePull',
      deviceSn: r.deviceSn || r.sn
    });
    if (ok) inserted += 1; else skipped += 1;
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: { message: 'Diterima ' + inserted + ' scan baru (' + skipped + ' dilewati/duplikat).', inserted: inserted, skipped: skipped }
  };
}

function handleJadwalFingerprintList_(request) {
  var dataset = loadDataset_();
  var tahunAjaranId = resolveTahunAjaranId_(request.tahunAjaranId, dataset);
  var tanggal = normalizeDateOnly_(request.tanggal) || nowIso_().slice(0, 10);
  var genderFilter = cleanString_(request.gender).toLowerCase();
  var jabatanFilter = cleanString_(request.jabatanId || '');

  var activePengurus = dataset.pengurus.filter(function (p) {
    if (!p.active) return false;
    if (genderFilter && cleanString_(p.gender).toLowerCase() !== genderFilter) return false;
    return true;
  });

  var scanState = readSheetState_('fingerprintLog');
  var scansByPengurus = {};
  scanState.rows.forEach(function (row) {
    if (isFingerprintRowDeleted_(row.status)) return;
    if (cleanString_(row.tanggal) !== tanggal) return;
    var pid = cleanString_(row.id_pengurus);
    if (!pid) return;
    (scansByPengurus[pid] = scansByPengurus[pid] || []).push(hhmm_(row.waktu));
  });

  var overrideState = readSheetState_('jadwalFingerprintOverride');
  var overrideByPengurus = {};
  overrideState.rows.forEach(function (row) {
    if (isFingerprintRowDeleted_(row.status)) return;
    if (cleanString_(row.tanggal) !== tanggal) return;
    var pid = cleanString_(row.id_pengurus);
    if (!pid) return;
    overrideByPengurus[pid] = row;
  });

  var items = activePengurus.map(function (p) {
    return { p: p, enriched: enrichPengurus_(p, dataset) };
  }).filter(function (x) {
    if (!jabatanFilter) return true;
    return x.enriched.jabatanIds.indexOf(jabatanFilter) !== -1;
  }).map(function (x) {
    var p = x.p, enriched = x.enriched;
    var computed = computeFingerprintCheckpoints_(scansByPengurus[p.id] || []);
    var overrideRow = overrideByPengurus[p.id] || null;
    var entry = {};
    JADWAL_FINGERPRINT_FIELD_KEYS.forEach(function (key) {
      entry[key] = overrideRow ? cleanString_(overrideRow[key]) : (computed[key] || '');
    });
    return {
      id: p.id,
      name: p.name,
      gender: p.gender,
      primaryJabatanLabel: enriched.primaryJabatanLabel,
      hasOverride: !!overrideRow,
      scanCount: (scansByPengurus[p.id] || []).length,
      entry: entry
    };
  });

  items.sort(function (a, b) { return (a.name || '').localeCompare(b.name || ''); });

  var jabatanList = dataset.jabatan.filter(function (j) { return j.active; })
    .map(function (j) { return { id: j.id, name: j.name }; })
    .sort(function (a, b) { return (a.name || '').localeCompare(b.name || ''); });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      tahunAjaranId: tahunAjaranId,
      tahunAjaranList: taSelectorList_(dataset),
      tanggal: tanggal,
      jabatanList: jabatanList,
      items: items
    }
  };
}

function handleJadwalFingerprintSaveOverride_(request) {
  var tanggal = normalizeDateOnly_(request.tanggal);
  if (!tanggal) throw createError_('Tanggal tidak valid.', 400);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var entries = Array.isArray(request.entries) ? request.entries : [];

  var dataset = loadDataset_();
  var state = readSheetState_('jadwalFingerprintOverride');

  var savedCount = 0;
  entries.forEach(function (entry) {
    var pengurusId = cleanString_(entry && entry.id_pengurus);
    if (!pengurusId) return;
    var pengurus = dataset.indexes.pengurusById[pengurusId];
    if (!pengurus) return;

    var record = {
      id_pengurus: pengurusId,
      pengurus_nama: pengurus.name,
      tanggal: tanggal,
      id_tahun_ajaran: tahunAjaranId,
      status: STATUS_LABELS.jadwalFingerprintOverride.active
    };
    JADWAL_FINGERPRINT_FIELD_KEYS.forEach(function (key) {
      record[key] = cleanString_(entry ? entry[key] : '');
    });

    var existing = state.rows.filter(function (row) {
      return !isFingerprintRowDeleted_(row.status) &&
        cleanString_(row.id_pengurus) === pengurusId &&
        cleanString_(row.tanggal) === tanggal;
    })[0] || null;

    var writable = pickWritableValues_(record, state.schema.columns);
    if (existing) {
      updateSheetRow_(state, existing._rowNumber, writable);
    } else {
      writable.id = String(nextId_(state.rows));
      appendSheetRow_(state, writable);
    }
    savedCount += 1;
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: { message: 'Koreksi manual disimpan (' + savedCount + ' entri).', savedCount: savedCount }
  };
}

function handleJadwalFingerprintResetOverride_(request) {
  var pengurusId = cleanString_(request.pengurusId || '');
  var tanggal = normalizeDateOnly_(request.tanggal);
  if (!pengurusId || !tanggal) throw createError_('pengurusId dan tanggal wajib diisi.', 400);

  var state = readSheetState_('jadwalFingerprintOverride');
  var existing = state.rows.filter(function (row) {
    return !isFingerprintRowDeleted_(row.status) &&
      cleanString_(row.id_pengurus) === pengurusId &&
      cleanString_(row.tanggal) === tanggal;
  })[0] || null;
  if (existing) {
    updateSheetRow_(state, existing._rowNumber, { status: STATUS_LABELS.jadwalFingerprintOverride.inactive });
  }
  return { ok: true, timestamp: nowIso_(), data: { message: 'Koreksi manual dihapus, kembali ke data otomatis.' } };
}

// List scan mentah di fingerprintLog yang PIN-nya TIDAK cocok id_pengurus manapun (lihat catatan
// di ingestOneFingerprintScan_ -- baris begini tetap disimpan, bukan dibuang, biar tidak ada data
// alat yang hilang). Dicek ULANG terhadap dataset pengurus saat ini (bukan cuma pengurus_nama yang
// kosong), supaya kalau pengurusnya baru didaftarkan belakangan, baris lama otomatis lepas dari list ini.
function handleJadwalFingerprintUnmatchedList_(request) {
  var dataset = loadDataset_();
  var state = readSheetState_('fingerprintLog');
  var rows = state.rows.filter(function (row) {
    if (isFingerprintRowDeleted_(row.status)) return false;
    var pid = cleanString_(row.id_pengurus);
    if (!pid) return false;
    return !dataset.indexes.pengurusById[pid];
  });
  rows.sort(function (a, b) {
    var ka = cleanString_(a.tanggal) + ' ' + hhmm_(a.waktu);
    var kb = cleanString_(b.tanggal) + ' ' + hhmm_(b.waktu);
    return ka < kb ? 1 : ka > kb ? -1 : 0;
  });
  var totalCount = rows.length;
  var items = rows.slice(0, 300).map(function (row) {
    return {
      id: row.id,
      idPengurus: cleanString_(row.id_pengurus),
      tanggal: cleanString_(row.tanggal),
      waktu: hhmm_(row.waktu),
      tipe: cleanString_(row.tipe || ''),
      sumber: cleanString_(row.sumber || ''),
      deviceSn: cleanString_(row.device_sn || ''),
      catatan: cleanString_(row.catatan || '')
    };
  });
  return {
    ok: true,
    timestamp: nowIso_(),
    data: { totalCount: totalCount, items: items }
  };
}

// Hapus satu baris scan tak-dikenal (soft-delete) -- dibatasi Super Admin, sama seperti aturan
// hapus data global di aplikasi ini.
function handleJadwalFingerprintDeleteUnmatchedScan_(request, session) {
  requireSuperAdmin_(session);
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('id wajib diisi.', 400);
  var state = readSheetState_('fingerprintLog');
  var existing = state.rows.filter(function (row) {
    return !isFingerprintRowDeleted_(row.status) && String(row.id) === id;
  })[0] || null;
  if (!existing) throw createError_('Data scan tidak ditemukan.', 404);
  updateSheetRow_(state, existing._rowNumber, { status: STATUS_LABELS.fingerprintLog.inactive });
  return { ok: true, timestamp: nowIso_(), data: { message: 'Data scan dihapus.' } };
}

// Kunci bridge dikelola dari halaman jadwalFingerprint sendiri (bukan env var) supaya bisa
// diganti/di-generate ulang tanpa restart server. Dibatasi Admin/Super Admin karena ini kredensial.
function handleFingerprintSettingsGet_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) {
    throw createError_('Hanya admin atau super admin.', 403);
  }
  return {
    ok: true,
    timestamp: nowIso_(),
    data: { bridgeKey: fingerprintSettingsState.bridgeKey, connection: fingerprintConnectionState }
  };
}

function handleFingerprintSettingsSave_(request, session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) {
    throw createError_('Hanya admin atau super admin.', 403);
  }
  if (isTruthy_(request.generate)) {
    fingerprintSettingsState.bridgeKey = crypto.randomBytes(24).toString('hex');
  } else {
    fingerprintSettingsState.bridgeKey = cleanString_(request.bridgeKey || '');
  }
  saveFingerprintSettings_();
  return handleFingerprintSettingsGet_(session);
}

function getAccessibleHalaqohAttendanceItems_(session, dataset) {
  // SCOPE (filter data): menentukan halaqoh mana saja yang boleh diakses pengurus.
  // - Super Admin / Admin / Koordinator Halaqoh → SEMUA halaqoh aktif.
  //   CATATAN: jika super admin sedang dalam scope non-super-admin (misal scopeLabel="Pengampu Halaqoh"),
  //   maka session.permissions.isSuperAdmin = false (di-downgrade via applyScopeToPermissions_)
  //   dan ia akan diperlakukan sama seperti pengampu halaqoh biasa di bawah.
  // - Pengampu Halaqoh → hanya halaqoh tempat dia bertugas (pengampu/badal).
  var allHalaqoh = (dataset && dataset.halaqoh ? dataset.halaqoh : []).filter(function (halaqoh) {
    return halaqoh.active;
  });
  var p = session && session.permissions;
  if (canAccessLevel_(session, 'misiTahfizh', 'manageAllHalaqoh', function (s) {
    var sp = s.permissions; return !!(sp && (sp.isAdmin || sp.isHalaqohCoordinator));
  })) {
    return allHalaqoh;
  }
  var halaqohIdMap = {};
  collectPengurusHalaqohIds_(session && session.id, dataset).forEach(function (id) {
    halaqohIdMap[id] = true;
  });
  return allHalaqoh.filter(function (halaqoh) {
    return !!halaqohIdMap[halaqoh.id];
  });
}

function findAccessibleHalaqohAttendanceItem_(session, halaqohId, dataset) {
  var target = cleanString_(halaqohId);
  return getAccessibleHalaqohAttendanceItems_(session, dataset).filter(function (halaqoh) {
    return cleanString_(halaqoh.id) === target;
  })[0] || null;
}

function canAccessHafalanHarian_(session) {
  if (!session || session.role !== 'pengurus' || !session.permissions) return false;
  return canAccessLevel_(session, 'misiTahfizh', 'manage', function (s) {
    var p = s.permissions;
    return !!(p.isAdmin || p.isHalaqohCoordinator || p.isPengampuHalaqoh);
  });
}

function getAccessibleHafalanHalaqoh_(session, dataset) {
  if (!session || !session.permissions) return [];
  var p = session.permissions;
  var allHalaqoh = (dataset.halaqoh || []).filter(function (h) { return h.active; });
  if (p.isSuperAdmin || p.isAdmin || p.isHalaqohCoordinator) {
    return allHalaqoh;
  }
  return getAccessibleHalaqohAttendanceItems_(session, dataset);
}

// Jenis entri hafalan → kategori field. quran: juz+halaman+nilai; level: level+nilai; nomor: nomor+nilai.
var HAFALAN_JENIS = {
  ziyadah: 'quran', ziyadah_ulang: 'quran', sabaqi: 'quran', manzili: 'quran', muroja_umum: 'quran',
  iqro: 'iqro', talaqqi_sendiri: 'talaqqi', talaqqi_jamai: 'talaqqi', tilawah_mandiri: 'talaqqi',
  tahsin_sendiri: 'talaqqi', tahsin_jamai: 'talaqqi',
  mufrodat: 'level', hadits: 'nomor', adzkar: 'nomor',
  catatan: 'catatan',
  awal_quran: 'quran', awal_hadits: 'nomor', awal_mufrodat: 'level', awal_adzkar: 'nomor',
  awal_iqro: 'iqro', awal_talaqqi_sendiri: 'talaqqi', awal_talaqqi_jamai: 'talaqqi', awal_tilawah_mandiri: 'talaqqi',
  awal_tahsin_sendiri: 'talaqqi', awal_tahsin_jamai: 'talaqqi'
};

// Jumlah halaman maksimal per juz. Standar 20, kecuali Juz 1 (21 hlm) dan Juz 30 (23 hlm)
// — sesuai jumlah halaman riil juz tsb di Mushaf Madinah standar Indonesia.
// SYNC: samakan dengan getJuzHalamanMax() di frontend/pages/hafalanHarian/index.html kalau berubah.
function getJuzHalamanMax_(juz) {
  var j = parseInt(juz, 10);
  if (j === 1) return 21;
  if (j === 30) return 23;
  return 20;
}

// Jumlah halaman (volume) untuk entri kategori Qur'an.
// Konvensi BARU: halamanDari = 0 berarti posisi PALING AWAL juz (sebelum halaman 1 sama
// sekali) -- jarak ke halamanSampai dihitung langsung (sampai - dari), tanpa +1, supaya
// setoran sebagian halaman (mis. setengah halaman = sampai 0.5) tidak salah hitung jadi
// 1.5 halaman seperti kalau masih pakai konvensi lama. Konvensi LAMA (halamanDari = nomor
// halaman asli, mulai dari 1) tetap dihitung inklusif (sampai - dari + 1) SUPAYA DATA LAMA
// yang sudah tersimpan (sebelum konvensi ini ada) tidak berubah angkanya.
// SYNC: cara deteksi (dari === 0) ini juga dipakai di mergePageRanges_ di bawah.
// Angka halaman desimal (peninggalan konvensi kelipatan 0.25 yang sekarang sudah tidak
// dipakai lagi utk 5 jenis inti) DIBULATKAN KE BAWAH khusus utk perhitungan akumulasi --
// data mentah di database TIDAK diubah/dimigrasi, cuma cara hitungnya yang membulatkan.
// Berlaku permanen utk semua jenis berbasis halaman (bukan cuma data lama).
function hafalanPages_(item) {
  var d = Math.floor(parseFloat(item.halamanDari)), s = Math.floor(parseFloat(item.halamanSampai));
  if (isNaN(d) || isNaN(s) || s < d) return 0;
  return d === 0 ? (s - d) : (s - d) + 1;
}

// Merge overlapping page ranges lalu hitung total halaman unik. Range yang PALING KECIL
// "dari"-nya dalam satu grup gabungan menentukan konvensi grup itu -- kalau 0, seluruh
// grup dianggap konvensi baru (tanpa +1); kalau bukan (data lama), tetap inklusif (+1).
// Setiap range dibulatkan ke bawah dulu (lihat catatan hafalanPages_ di atas) sebelum
// digabung/dihitung.
function mergePageRanges_(ranges) {
  if (!ranges || !ranges.length) return 0;
  var floored = (ranges || []).map(function(r) { return [Math.floor(r[0]), Math.floor(r[1])]; });
  var sorted = floored.slice().sort(function(a, b) { return a[0] - b[0]; });
  var merged = [[sorted[0][0], sorted[0][1]]];
  for (var i = 1; i < sorted.length; i++) {
    var last = merged[merged.length - 1];
    if (sorted[i][0] <= last[1]) last[1] = Math.max(last[1], sorted[i][1]);
    else merged.push([sorted[i][0], sorted[i][1]]);
  }
  var total = 0;
  merged.forEach(function(r) { total += r[0] === 0 ? (r[1] - r[0]) : (r[1] - r[0] + 1); });
  return total;
}

// Kumpulkan range halaman per juz dari daftar item (filter jenis tertentu).
function collectRangesByJuz_(items, jenisList) {
  var byJuz = {};
  items.forEach(function(item) {
    if (jenisList.indexOf(item.jenis) === -1) return;
    var d = parseFloat(item.halamanDari), s = parseFloat(item.halamanSampai);
    if (isNaN(d) || isNaN(s) || s < d || d < 0) return;
    var juz = item.juz || '0';
    if (!byJuz[juz]) byJuz[juz] = [];
    byJuz[juz].push([d, s]);
  });
  var total = 0;
  Object.keys(byJuz).forEach(function(juz) { total += mergePageRanges_(byJuz[juz]); });
  return total;
}

// Merge ranges dan kembalikan array [dari, sampai] yang sudah di-merge (tanpa hitung total).
function mergeRangesOnly_(ranges) {
  if (!ranges || !ranges.length) return [];
  var sorted = ranges.slice().sort(function(a, b) { return a[0] - b[0]; });
  var merged = [[sorted[0][0], sorted[0][1]]];
  for (var i = 1; i < sorted.length; i++) {
    var last = merged[merged.length - 1];
    if (sorted[i][0] <= last[1]) last[1] = Math.max(last[1], sorted[i][1]);
    else merged.push([sorted[i][0], sorted[i][1]]);
  }
  return merged;
}

// Kumpulkan range nomor (hadits/adzkar) dari daftar item, merge overlap, hitung unik.
function collectNomorRanges_(items, jenisList) {
  var ranges = [];
  items.forEach(function(item) {
    if (jenisList.indexOf(item.jenis) === -1) return;
    var d = parseFloat(item.nomor), s = parseFloat(item.nomorSampai || item.nomor);
    if (isNaN(d) || d < 0) return;
    if (isNaN(s) || s < d) s = d;
    ranges.push([d, s]);
  });
  return mergePageRanges_(ranges);
}

// Kurangi (set difference) sekumpulan range dari sekumpulan range lain. Dipakai untuk dapat
// RINCIAN range bersih (bukan cuma total angka) -- mis. gabungan setoran+awal dikurangi awal
// -- supaya bagian yang overlap dgn baseline betul-betul dipotong dari rangenya, bukan cuma
// dikurangi di angka totalnya. Semua range di-floor dulu spy konsisten dgn mergePageRanges_.
function subtractRangeSets_(baseRanges, removeRanges) {
  var base = mergeRangesOnly_((baseRanges || []).map(function (r) { return [Math.floor(r[0]), Math.floor(r[1])]; }));
  var remove = mergeRangesOnly_((removeRanges || []).map(function (r) { return [Math.floor(r[0]), Math.floor(r[1])]; }));
  var result = base;
  remove.forEach(function (r) {
    var next = [];
    result.forEach(function (b) {
      if (r[1] < b[0] || r[0] > b[1]) { next.push(b); return; } // tidak overlap
      if (b[0] < r[0]) next.push([b[0], r[0] - 1]);
      if (b[1] > r[1]) next.push([r[1] + 1, b[1]]);
    });
    result = next;
  });
  return result;
}

// Rincian halaman BERSIH (murni periode ini, sudah dikurangi overlap dgn posisi awal) per juz --
// dipakai dialog Detail Setoran biar kelihatan pecahan juznya, bukan cuma angka total. Konsisten
// dgn netZ di collectRangesByJuz_: hasil di sini kalau dijumlah = angka netZ yang sama.
function computeNetBreakdownByJuz_(murniItems, awalItems) {
  var byJuzMurni = {}, byJuzAwal = {};
  (murniItems || []).forEach(function (item) {
    var d = parseFloat(item.halamanDari), s = parseFloat(item.halamanSampai);
    if (isNaN(d) || isNaN(s) || s < d || d < 0) return;
    var juz = item.juz || '0';
    (byJuzMurni[juz] = byJuzMurni[juz] || []).push([d, s]);
  });
  (awalItems || []).forEach(function (item) {
    var d = parseFloat(item.halamanDari), s = parseFloat(item.halamanSampai);
    if (isNaN(d) || isNaN(s) || s < d || d < 0) return;
    var juz = item.juz || '0';
    (byJuzAwal[juz] = byJuzAwal[juz] || []).push([d, s]);
  });
  var juzKeys = Object.keys(byJuzMurni);
  juzKeys.sort(function (a, b) { return (parseFloat(a) || 0) - (parseFloat(b) || 0); });
  var out = [];
  juzKeys.forEach(function (juz) {
    var combined = (byJuzMurni[juz] || []).concat(byJuzAwal[juz] || []);
    var net = subtractRangeSets_(combined, byJuzAwal[juz] || []);
    if (!net.length) return;
    var pages = 0;
    net.forEach(function (r) { pages += r[0] === 0 ? (r[1] - r[0]) : (r[1] - r[0] + 1); });
    out.push({ juz: juz, ranges: net.map(function (r) { return { halamanDari: r[0], halamanSampai: r[1] }; }), pages: Math.round(pages * 10) / 10 });
  });
  return out;
}

// Rincian nomor (hadits) BERSIH periode ini, sudah dikurangi overlap dgn posisi awal. Sama
// polanya dgn computeNetBreakdownByJuz_ tapi tanpa pengelompokan juz (hadits tidak per-juz).
function computeNetBreakdownNomor_(murniItems, awalItems) {
  var murniRanges = [], awalRanges = [];
  (murniItems || []).forEach(function (item) {
    var d = parseFloat(item.nomor), s = parseFloat(item.nomorSampai || item.nomor);
    if (isNaN(d) || d < 0) return;
    if (isNaN(s) || s < d) s = d;
    murniRanges.push([d, s]);
  });
  (awalItems || []).forEach(function (item) {
    var d = parseFloat(item.nomor), s = parseFloat(item.nomorSampai || item.nomor);
    if (isNaN(d) || d < 0) return;
    if (isNaN(s) || s < d) s = d;
    awalRanges.push([d, s]);
  });
  var net = subtractRangeSets_(murniRanges.concat(awalRanges), awalRanges);
  return net.map(function (r) { return { nomor: r[0], nomorSampai: r[1] }; });
}

// Hitung, untuk tiap entri (id), berapa halaman/nomor yang BENERAN baru ("bersih") setelah
// dipotong tumpang-tindih dgn entri lain yang lebih dulu (baseline "awal" ATAU entri murni
// bertanggal lebih lama), dan dari mana saja overlap itu berasal. Dipakai anotasi per-baris di
// dialog Detail Setoran (kolom "+ Halaman"/"+ Nomor") -- BEDA dgn netTotal/netBreakdown yang cuma
// kasih angka/rincian AGREGAT, bukan per-baris. Diproses berurutan kronologis (awal dulu, lalu
// murni ascending tanggal+id) supaya entri yg lebih lama "menang" -- entri belakangan yang
// tumpang tindih dianggap redundan thd yang sudah lebih dulu tercatat.
function computeRowOverlaps_(entries) {
  entries = (entries || []).slice().sort(function (a, b) {
    if (a.isAwal !== b.isAwal) return a.isAwal ? -1 : 1;
    if (!a.isAwal && a.tanggal !== b.tanggal) return a.tanggal < b.tanggal ? -1 : 1;
    return (parseInt(a.id, 10) || 0) - (parseInt(b.id, 10) || 0);
  });
  var covered = []; // { range:[d,s], isAwal, tanggal, jenis } -- jenis/tanggal dipakai utk label sumber overlap
  var out = {};
  entries.forEach(function (e) {
    if (e.isAwal) { covered.push({ range: [e.d, e.s], isAwal: true }); return; }
    var remaining = [[e.d, e.s]];
    var overlapByKey = {}; // key -> { pages, isAwal, tanggal, jenis }
    covered.forEach(function (seg) {
      var next = [];
      remaining.forEach(function (r) {
        var interD = Math.max(r[0], seg.range[0]), interS = Math.min(r[1], seg.range[1]);
        if (interD <= interS) {
          var pages = interD === 0 ? (interS - interD) : (interS - interD + 1);
          var key = seg.isAwal ? 'awal' : (seg.tanggal + '|' + seg.jenis);
          if (!overlapByKey[key]) overlapByKey[key] = { pages: 0, isAwal: seg.isAwal, tanggal: seg.tanggal, jenis: seg.jenis };
          overlapByKey[key].pages += pages;
          if (r[0] < interD) next.push([r[0], interD - 1]);
          if (r[1] > interS) next.push([interS + 1, r[1]]);
        } else next.push(r);
      });
      remaining = next;
    });
    var netPages = 0;
    remaining.forEach(function (r) { netPages += r[0] === 0 ? (r[1] - r[0]) : (r[1] - r[0] + 1); });
    out[e.id] = {
      netPages: netPages,
      overlaps: Object.keys(overlapByKey).map(function (k) {
        var o = overlapByKey[k];
        return o.isAwal
          ? { source: 'awal', pages: o.pages }
          : { source: 'entry', tanggal: o.tanggal, jenis: o.jenis, pages: o.pages };
      })
    };
    // bagian baru (belum tumpang tindih) jadi acuan utk entri belakangan, dibawa jenis/tanggal
    // entri ini sendiri supaya kalau entri LAIN lagi numpuk di atasnya, label-nya jelas.
    remaining.forEach(function (r) { covered.push({ range: r, isAwal: false, tanggal: e.tanggal, jenis: e.jenis }); });
  });
  return out;
}

// Wrapper computeRowOverlaps_ per-juz (Qur'an) -- overlap cuma relevan dalam juz yang sama.
function computeRowOverlapsByJuz_(murniItems, awalItems) {
  var byJuz = {};
  function push(item, isAwal) {
    var d = parseFloat(item.halamanDari), s = parseFloat(item.halamanSampai);
    if (isNaN(d) || isNaN(s) || s < d || d < 0) return;
    var juz = item.juz || '0';
    (byJuz[juz] = byJuz[juz] || []).push({ id: item.id, tanggal: item.tanggal, isAwal: isAwal, jenis: item.jenis, d: Math.floor(d), s: Math.floor(s) });
  }
  (awalItems || []).forEach(function (it) { push(it, true); });
  (murniItems || []).forEach(function (it) { push(it, false); });
  var out = {};
  Object.keys(byJuz).forEach(function (juz) {
    var res = computeRowOverlaps_(byJuz[juz]);
    Object.keys(res).forEach(function (id) { out[id] = res[id]; });
  });
  return out;
}

// Wrapper computeRowOverlaps_ utk hadits (nomor, tanpa pengelompokan juz).
function computeRowOverlapsNomor_(murniItems, awalItems) {
  var entries = [];
  function push(item, isAwal) {
    var d = parseFloat(item.nomor), s = parseFloat(item.nomorSampai || item.nomor);
    if (isNaN(d) || d < 0) return;
    if (isNaN(s) || s < d) s = d;
    entries.push({ id: item.id, tanggal: item.tanggal, isAwal: isAwal, jenis: item.jenis, d: d, s: s });
  }
  (awalItems || []).forEach(function (it) { push(it, true); });
  (murniItems || []).forEach(function (it) { push(it, false); });
  return computeRowOverlaps_(entries);
}

// Akumulasi volume hafalan (halaman) per santri untuk rekap/top — dukung baris lama & item baru.
function accumulateHafalan_(acc, item) {
  var jenis = item.jenis;
  if (!jenis) { // baris lama sebelum fitur per-item (ziyadah/sabaqi/manzili gabungan)
    acc.ziyadah += parseFloat(item.ziyadah || 0) || 0;
    acc.sabaqi += parseFloat(item.murojaaSabaqi || 0) || 0;
    acc.manzili += parseFloat(item.murojaaManzili || 0) || 0;
    return;
  }
  var pages = hafalanPages_(item);
  if (jenis === 'ziyadah' || jenis === 'ziyadah_ulang') acc.ziyadah += pages;
  else if (jenis === 'sabaqi') acc.sabaqi += pages;
  else if (jenis === 'manzili') acc.manzili += pages;
  else if (jenis === 'muroja_umum') acc.murojaah += pages;
  // mufrodat/hadits/adzkar tidak berbasis halaman → hanya terhitung di `entries`
}

// 5 jenis inti Al-Qur'an yang tunduk ke aturan integer + nyicil + nilai wajib (bukan hafalan
// awal `awal_quran`).
var CORE_QURAN_JENIS_ = { ziyadah: 1, ziyadah_ulang: 1, sabaqi: 1, manzili: 1, muroja_umum: 1 };

// 5 varian Talaqqi/Tahsin/Tilawah harian (bukan hafalan awal) -- pakai Nama Surat + halaman
// integer, nilai wajib min 70, TANPA nyicil.
var TALAQQI_HARIAN_JENIS_ = { talaqqi_sendiri: 1, talaqqi_jamai: 1, tilawah_mandiri: 1, tahsin_sendiri: 1, tahsin_jamai: 1 };

// Daftar 114 nama surat Al-Qur'an (urutan mushaf) -- dipakai validasi field "Nama Surat" di
// Talaqqi/Tahsin/Tilawah harian. SYNC: samakan dengan SURAT_LIST di frontend/pages/hafalanHarian/index.html.
var SURAT_LIST_ = [
  "Al-Fatihah","Al-Baqarah","Ali 'Imran","An-Nisa","Al-Ma'idah","Al-An'am","Al-A'raf","Al-Anfal",
  "At-Taubah","Yunus","Hud","Yusuf","Ar-Ra'd","Ibrahim","Al-Hijr","An-Nahl","Al-Isra","Al-Kahf",
  "Maryam","Ta-Ha","Al-Anbiya","Al-Hajj","Al-Mu'minun","An-Nur","Al-Furqan","Asy-Syu'ara","An-Naml",
  "Al-Qasas","Al-'Ankabut","Ar-Rum","Luqman","As-Sajdah","Al-Ahzab","Saba","Fatir","Ya-Sin",
  "As-Saffat","Sad","Az-Zumar","Gafir","Fussilat","Asy-Syura","Az-Zukhruf","Ad-Dukhan","Al-Jasiyah",
  "Al-Ahqaf","Muhammad","Al-Fath","Al-Hujurat","Qaf","Az-Zariyat","At-Tur","An-Najm","Al-Qamar",
  "Ar-Rahman","Al-Waqi'ah","Al-Hadid","Al-Mujadalah","Al-Hasyr","Al-Mumtahanah","As-Saff",
  "Al-Jumu'ah","Al-Munafiqun","At-Tagabun","At-Talaq","At-Tahrim","Al-Mulk","Al-Qalam","Al-Haqqah",
  "Al-Ma'arij","Nuh","Al-Jinn","Al-Muzzammil","Al-Muddassir","Al-Qiyamah","Al-Insan","Al-Mursalat",
  "An-Naba","An-Nazi'at","'Abasa","At-Takwir","Al-Infitar","Al-Mutaffifin","Al-Insyiqaq","Al-Buruj",
  "At-Tariq","Al-A'la","Al-Gasyiyah","Al-Fajr","Al-Balad","Asy-Syams","Al-Lail","Ad-Duha",
  "Asy-Syarh","At-Tin","Al-'Alaq","Al-Qadr","Al-Bayyinah","Az-Zalzalah","Al-'Adiyat","Al-Qari'ah",
  "At-Takasur","Al-'Asr","Al-Humazah","Al-Fil","Quraisy","Al-Ma'un","Al-Kausar","Al-Kafirun",
  "An-Nasr","Al-Lahab","Al-Ikhlas","Al-Falaq","An-Nas"
];
var SURAT_SET_ = {};
SURAT_LIST_.forEach(function (s) { SURAT_SET_[s] = 1; });

// Jumlah ayat per surat (urutan sama persis dengan SURAT_LIST_ di atas) -- dipakai batas
// maksimal "Ayat sampai" di Talaqqi/Tahsin/Tilawah harian. SYNC: samakan dengan
// SURAT_AYAT_COUNT di frontend/pages/hafalanHarian/index.html.
var SURAT_AYAT_COUNT_ = [
  7,286,200,176,120,165,206,75,129,109,123,111,43,52,99,128,111,110,98,135,112,78,118,64,77,227,93,
  88,69,60,34,30,73,54,45,83,182,88,75,85,54,53,89,59,37,35,38,29,18,45,60,49,62,55,78,96,29,22,24,
  13,14,11,11,18,12,12,30,52,52,44,28,28,20,56,40,31,50,40,46,42,29,19,36,25,22,17,19,26,30,20,15,21,
  11,8,8,19,5,8,8,11,11,8,3,9,5,4,7,3,6,3,5,4,5,6
];
var SURAT_AYAT_MAX_ = {};
SURAT_LIST_.forEach(function (s, i) { SURAT_AYAT_MAX_[s] = SURAT_AYAT_COUNT_[i]; });

// Tentukan apakah satu entri hafalan DIAKUMULASIKAN/DIANGGAP SAH atau tidak:
// - Ziyadah/Ziyadah Ulang/Iqro': tidak dihitung kalau ditandai "nyicil" (belum genap 1 halaman).
// - Sabaqi: minimal 5 halaman per entri, kurang dari itu dianggap nyicil (tidak dihitung).
// - Manzili: minimal 1 juz penuh per entri, kurang dari itu tidak dihitung.
// - Muroja'ah (bebas): minimal 1 halaman (selalu terpenuhi lewat validasi save), selalu dihitung.
// - 5 jenis inti + Iqro' + Talaqqi/Tahsin/Tilawah harian: kalau nilai diisi dan <70 (gagal),
//   tidak dianggap sah (harus mengulang). Nilai kosong (data lama) dianggap lulus.
// Jenis lain (mufrodat/hadits/adzkar/awal_*/baris lama tanpa `jenis`) selalu true — di luar
// scope aturan ini.
function isHafalanEntryCounted_(item) {
  var jenis = item.jenis;
  var isCoreQ = jenis && !!CORE_QURAN_JENIS_[jenis];
  var isIqro = jenis === 'iqro';
  var isTalaqqiHarian = jenis && !!TALAQQI_HARIAN_JENIS_[jenis];
  var isHaditsAdzkarHarian = jenis === 'hadits' || jenis === 'adzkar';
  if (!jenis || (!isCoreQ && !isIqro && !isTalaqqiHarian && !isHaditsAdzkarHarian)) return true;

  // Hadits/Adzkar harian cuma digate oleh nyicil -- TIDAK ada aturan nilai wajib min 70 di sini.
  if (isHaditsAdzkarHarian) return !item.nyicil;

  var nilaiRaw = cleanString_(item.nilai);
  if (nilaiRaw !== '') {
    var n = parseFloat(nilaiRaw);
    if (!isNaN(n) && n < 70) return false;
  }
  if (isCoreQ) {
    if (jenis === 'ziyadah' || jenis === 'ziyadah_ulang') return !item.nyicil;
    var pages = hafalanPages_(item);
    if (jenis === 'sabaqi') return pages >= 5;
    if (jenis === 'manzili') return pages >= getJuzHalamanMax_(item.juz);
    return true; // muroja_umum
  }
  if (isIqro) return !item.nyicil;
  return true; // talaqqi harian: cuma gate nilai di atas
}

function normalizeHafalanHarian_(row) {
  var status = normalizeStatusForSheet_('hafalanHarian', row.status || STATUS_LABELS.hafalanHarian.active);
  var item = {
    id: cleanString_(row.id),
    tanggal: normalizeDateOnly_(row.tanggal),
    halaqohId: cleanString_(row.id_halaqoh),
    santriId: cleanString_(row.id_santri),
    pengurusId: cleanString_(row.id_pengurus),
    jenis: cleanString_(row.jenis),
    juz: cleanString_(row.juz),
    halamanDari: cleanString_(row.halaman_dari),
    halamanSampai: cleanString_(row.halaman_sampai),
    level: cleanString_(row.level),
    levelSampai: cleanString_(row.level_sampai),
    jumlah: cleanString_(row.jumlah),
    jumlahSampai: cleanString_(row.jumlah_sampai),
    nomor: cleanString_(row.nomor),
    nomorSampai: cleanString_(row.nomor_sampai),
    nilai: cleanString_(row.nilai),
    nyicil: isTruthy_(row.nyicil),
    tahunAjaranId: cleanString_(row.tahun_ajaran_id),
    ziyadah: cleanString_(row.ziyadah),
    murojaaSabaqi: cleanString_(row.muroja_sabaqi),
    murojaaManzili: cleanString_(row.muroja_manzili),
    catatan: cleanString_(row.catatan),
    status: status,
    active: isActiveStatus_(status),
    record: clonePlainObject_(row)
  };
  item.counted = item.active ? isHafalanEntryCounted_(item) : false;
  return item;
}

// loadDataset_() penuh membaca+normalize 19 tabel sekaligus (termasuk absensiGuru/Halaqoh/Kelas/
// Regu, kegiatanSop, content, dst yg SAMA SEKALI tidak dipakai di handleHafalanHarianList_) --
// jadi dashboard hafalanHarian (dipanggil tiap kali halaman dibuka) tetap lambat walau jumlah
// halaqoh yg ditampilkan cuma 1-2 item, karena biayanya bukan dari jumlah halaqoh melainkan dari
// ~15 tabel lain (beberapa di antaranya tabel transaksi besar juga) yg ikut ke-load percuma.
// Fungsi ini cuma baca 4 tabel yg benar-benar dipakai fungsi tsb.
function loadHafalanHarianListDataset_() {
  var pengurusState = readSheetState_('pengurus');
  var santriState = readSheetState_('santri');
  var halaqohState = readSheetState_('halaqoh');
  var tahunAjaranState = readSheetState_('tahunAjaran');

  var dataset = {
    pengurus: pengurusState.rows.map(normalizePengurus_),
    santri: santriState.rows.map(normalizeSantri_),
    halaqoh: halaqohState.rows.map(normalizeHalaqoh_),
    tahunAjaran: sortTahunAjaranList_(tahunAjaranState.rows.map(normalizeTahunAjaran_))
  };
  dataset.indexes = {
    pengurusById: indexById_(dataset.pengurus),
    santriById: indexById_(dataset.santri),
    halaqohById: indexById_(dataset.halaqoh),
    tahunAjaranById: indexById_(dataset.tahunAjaran)
  };
  return dataset;
}

// Varian RINGKAS dari handleHafalanHarianList_ (mode dashboard): daftar halaqoh (paginated) +
// tahunAjaranList buat mengisi filter -- TANPA membaca tabel entri `hafalanHarian` sama sekali.
// Konsekuensinya tidak ada badge `todayCount` (justru loop itu yang bikin handler lama ikut
// men-scan seluruh riwayat entri tiap kali kartu di-render). Akses & scope halaqoh IDENTIK dgn
// hafalan.harian.list: gate canAccessHafalanHarian_/isMudir di requirePermissionForAction_ +
// getAccessibleHafalanHalaqoh_ (pengampu = halaqoh sendiri). pageSize di-clamp 1..100 (bukan
// 6..50). Bentuk response sengaja dibikin drop-in buat loadDashboard() di frontend:
//   { halaqohList, page, pageSize, total, totalPages, tahunAjaranList, tahunAjaranId }
function handleHafalanHarianHalaqohList_(request, session) {
  var dataset = loadHafalanHarianListDataset_();
  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);

  var q = cleanString_(request.q).toLowerCase();
  var genderFilter = cleanString_(request.genderGroup || request.gender);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var page = toInt_(request.page, 1);
  var pageSize = clamp_(toInt_(request.pageSize, 10), 1, 100);

  // Samakan dgn hafalan.harian.list: kalau TA belum dikirim (buka halaman pertama kali), pakai
  // TA aktif -- supaya kartu tidak mencampur halaqoh lintas tahun ajaran.
  if (!tahunAjaranId) {
    var activeTaObj = (dataset.tahunAjaran || []).filter(function (ta) { return ta.isAktif; })[0];
    if (activeTaObj) tahunAjaranId = activeTaObj.id;
  }

  var halaqohList = accessible.filter(function (h) {
    if (tahunAjaranId && h.tahunAjaranId !== tahunAjaranId) return false;
    if (genderFilter && h.genderGroup !== genderFilter) return false;
    return true;
  }).map(function (h) {
    var pengampuNames = (h.pengampuIds || []).map(function (pid) {
      var p = dataset.indexes.pengurusById[pid];
      return p ? cleanString_(p.name) : '';
    }).filter(Boolean);
    var badalNames = (h.badalIds || []).map(function (pid) {
      var p = dataset.indexes.pengurusById[pid];
      return p ? cleanString_(p.name) : '';
    }).filter(Boolean);
    // santriNames sengaja TIDAK di-filter(Boolean) -- harus sejajar 1:1 dgn santriIds
    // (dipakai frontend buat pairing nama+id di picker Riwayat Hafalan Santri).
    var santriNames = (h.santriIds || []).map(function (sid) {
      var s = dataset.indexes.santriById[sid];
      return s ? cleanString_(s.name) : '';
    });
    return {
      id: h.id,
      name: h.name,
      genderGroup: h.genderGroup,
      santriCount: (h.santriIds || []).length,
      pengampuNames: pengampuNames,
      badalNames: badalNames,
      santriNames: santriNames,
      santriIds: (h.santriIds || []).slice()
    };
  }).filter(function (h) {
    if (!q) return true;
    var haystack = [h.name, h.pengampuNames.join(' '), h.badalNames.join(' '), h.santriNames.join(' ')].join(' ').toLowerCase();
    return haystack.indexOf(q) !== -1;
  }).sort(function (a, b) {
    return (a.name || '').localeCompare(b.name || '');
  });

  var total = halaqohList.length;
  var totalPages = Math.max(1, Math.ceil(total / pageSize));
  page = Math.min(Math.max(1, page), totalPages);
  var pageItems = halaqohList.slice((page - 1) * pageSize, page * pageSize);

  // Badge audit kuning per kartu -- definisi "bolong" DISAMAKAN persis dgn popup nag "Kelola
  // Audit" (collectHafalanGapItems_) lewat helper bersama computeHafalanHarianGapDates_. Ikut
  // saklar auditSettingsState.hafalanActive + hanya halaqoh di TA AKTIF (TA lama tidak dinagih,
  // sama spt popup). Dihitung cuma utk 1 halaman kartu yg tampil (pageItems), bukan seluruh
  // halaqoh -- loop harian dari awal TA lumayan berat kalau dikali semua halaqoh koordinator.
  var auditActiveTa = (dataset.tahunAjaran || []).filter(function (ta) { return ta.isAktif; })[0];
  var auditTaStart = auditActiveTa ? normalizeDateOnly_(auditActiveTa.tanggalMulai) : '';
  if (auditSettingsState.hafalanActive && auditActiveTa && auditTaStart) {
    var auditCutoff = auditCutoffDate_();
    var auditDibekukanSet = getDibekukanSantriIdSet_();
    var auditPindahRows = readSheetState_('riwayatPindahHalaqoh').rows;
    // filledSantriByDate digabung LINTAS HALAQOH (keputusan user 2026-08-11) -- sama spt collector.
    // Cukup baris dalam jendela [awal TA aktif .. cutoff]: computeHafalanHarianGapDates_ tidak
    // pernah melihat tanggal di luar rentang itu, jadi menarik seluruh riwayat lintas TA hanya
    // menambah biaya normalize sia-sia (tabel ini menumpuk tiap hari). tanggal tersimpan ISO
    // 'YYYY-MM-DD' sehingga perbandingan string di SQL aman. Pakai idx_hafalanHarian_tanggal.
    var auditFilledByDate = {};
    readSheetStateWhere_('hafalanHarian', '"tanggal" >= ? AND "tanggal" <= ?', [auditTaStart, auditCutoff]).rows.forEach(function (row) {
      if (!isActiveStatus_(normalizeStatusForSheet_('hafalanHarian', row.status))) return;
      if (!HAFALAN_GAP_COUNTING_JENIS_[cleanString_(row.jenis)]) return;
      var tgl = normalizeDateOnly_(row.tanggal);
      var sid = cleanString_(row.id_santri);
      if (!tgl || !sid) return;
      if (!auditFilledByDate[tgl]) auditFilledByDate[tgl] = {};
      auditFilledByDate[tgl][sid] = true;
    });
    pageItems.forEach(function (item) {
      var raw = (dataset.indexes.halaqohById || {})[item.id];
      if (!raw || raw.tahunAjaranId !== auditActiveTa.id) {
        item.audit = { active: false, since: '', missingCount: 0, missingDatesSample: [] };
        return;
      }
      var gap = computeHafalanHarianGapDates_(raw.santriIds, item.id, raw.record && raw.record.created_at, auditFilledByDate, auditDibekukanSet, auditPindahRows, auditTaStart, auditCutoff);
      item.audit = { active: true, since: gap.since, missingCount: gap.missingDates.length, missingDatesSample: gap.missingDates.slice(0, 5) };
    });
  }

  var tahunAjaranList = (dataset.tahunAjaran || []).map(function (ta) {
    return { id: ta.id, nama: ta.nama, namaDisplay: ta.namaDisplay, isAktif: ta.isAktif, tanggalMulai: ta.tanggalMulai || '', tanggalSelesai: ta.tanggalSelesai || '' };
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      halaqohList: pageItems,
      page: page,
      pageSize: pageSize,
      total: total,
      totalPages: totalPages,
      tahunAjaranList: tahunAjaranList,
      tahunAjaranId: tahunAjaranId
    }
  };
}

function handleHafalanHarianList_(request, session) {
  var dataset = loadHafalanHarianListDataset_();
  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
  var accessibleIdMap = {};
  accessible.forEach(function (h) { accessibleIdMap[h.id] = true; });

  var halaqohId = cleanString_(request.halaqohId || request.id_halaqoh);
  var tanggal = cleanString_(request.tanggal);
  var dateFrom = cleanString_(request.dateFrom);
  var dateTo = cleanString_(request.dateTo);
  var santriId = cleanString_(request.santriId || request.id_santri);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var tipe = cleanString_(request.tipe) || 'harian'; // 'harian' | 'awal'
  var genderFilter = cleanString_(request.genderGroup || request.gender);
  var q = cleanString_(request.q).toLowerCase();
  var page = Math.max(1, parseInt(cleanString_(request.page) || '1', 10));
  var pageSize = Math.min(50, Math.max(6, parseInt(cleanString_(request.pageSize) || '12', 10)));
  var normFrom = dateFrom ? normalizeDateOnly_(dateFrom) : '';
  var normTo = dateTo ? normalizeDateOnly_(dateTo) : '';

  // Kalau frontend belum kirim tahunAjaranId (pertama kali buka halaman), langsung pakai TA aktif
  // di sini -- supaya frontend tidak perlu fetch dulu buat tau TA aktif lalu fetch ULANG dgn filter
  // yang benar (dulu begitu, bikin loading dobel tiap buka halaman).
  if (!tahunAjaranId && tipe !== 'awal') {
    var activeTaObj = (dataset.tahunAjaran || []).filter(function (ta) { return ta.isAktif; })[0];
    if (activeTaObj) tahunAjaranId = activeTaObj.id;
  }

  // Jika tahunAjaranId dikirim dan tidak ada dateFrom/dateTo, gunakan range TA
  if (tahunAjaranId && !normFrom && !normTo && !tanggal) {
    var taObj = dataset.indexes.tahunAjaranById[tahunAjaranId] || null;
    if (taObj) {
      normFrom = taObj.tanggalMulai ? normalizeDateOnly_(taObj.tanggalMulai) : '';
      normTo = taObj.tanggalSelesai ? normalizeDateOnly_(taObj.tanggalSelesai) : '';
    }
  }

  // `items` (detail per-entri) cuma dibutuhkan saat dialog per-halaqoh dibuka (halaqohId
  // dikirim). Panggilan dashboard (tanpa halaqohId) tidak pernah membaca data.items di
  // frontend, jadi jangan dihitung sama sekali -- dulu ini yang bikin respons dashboard
  // bisa 50rb+ baris JSON karena isinya seluruh entri satu tahun ajaran dari semua halaqoh.
  var items = [];
  // Halaqoh yang diminta harus ada di scope akses user (superadmin/admin/koordinator = semua,
  // pengampu = halaqoh miliknya saja) -- kalau tidak, jangan bocorkan data halaqoh lain.
  var halaqohObj = (halaqohId && accessibleIdMap[halaqohId]) ? (dataset.indexes.halaqohById[halaqohId] || null) : null;

  // Rentang tanggal yang lagi dibuka pengurus di dialog -- mode Hari: satu tanggal; mode Bulan:
  // dateFrom..dateTo; mode Posisi Awal: tidak relevan (biarkan kosong).
  var rangeFrom = tanggal ? normalizeDateOnly_(tanggal) : normFrom;
  var rangeTo = tanggal ? normalizeDateOnly_(tanggal) : normTo;
  // currentRosterIdSet: keanggotaan halaqoh SEKARANG. extraMemberIds: santri yang BUKAN
  // anggota sekarang tapi terbukti anggota di SEBAGIAN rentang yang lagi dibuka (baru pindah
  // keluar) -- supaya pengurus tetap bisa melihat & melengkapi entri lampau mereka, baik di
  // mode Hari maupun mode Bulan (dulu cuma dilebarkan di mode Hari, bikin santri yang sudah
  // pindah hilang total dari filter per-bulan walau sebagian bulan itu dia masih anggota).
  // joinInfoBySantri/leftInfoBySantri dipakai buat badge di UI + batas redup sel tanggal
  // (aktifDariTanggal/aktifSampaiTanggal) di mode Bulan.
  var currentRosterIdSet = {};
  var extraMemberIds = [];
  var joinInfoBySantri = {};
  var leftInfoBySantri = {};
  if (halaqohObj) {
    (halaqohObj.santriIds || []).forEach(function (sid) { currentRosterIdSet[sid] = true; });
    if (rangeFrom && rangeTo && tipe !== 'awal') {
      var pindahRowsHalaqohIni = readSheetState_('riwayatPindahHalaqoh').rows.filter(function (r) {
        return cleanString_(r.id_halaqoh_asal) === halaqohId || cleanString_(r.id_halaqoh_tujuan) === halaqohId;
      });
      var latestMasukBySantri = {};
      var earliestKeluarBySantri = {};
      pindahRowsHalaqohIni.forEach(function (r) {
        if (!isActiveStatus_(r.status)) return;
        var sid = cleanString_(r.id_santri);
        var tglPindah = normalizeDateOnly_(r.tanggal_pindah);
        if (!sid || !tglPindah) return;
        if (cleanString_(r.id_halaqoh_tujuan) === halaqohId) {
          var exIn = latestMasukBySantri[sid];
          if (!exIn || tglPindah > normalizeDateOnly_(exIn.tanggal_pindah)) latestMasukBySantri[sid] = r;
        }
        if (cleanString_(r.id_halaqoh_asal) === halaqohId) {
          var exOut = earliestKeluarBySantri[sid];
          if (!exOut || tglPindah < normalizeDateOnly_(exOut.tanggal_pindah)) earliestKeluarBySantri[sid] = r;
        }
      });
      Object.keys(latestMasukBySantri).forEach(function (sid) {
        var r = latestMasukBySantri[sid];
        var tglPindah = normalizeDateOnly_(r.tanggal_pindah);
        if (tglPindah > rangeFrom) {
          joinInfoBySantri[sid] = { halaqohAsalName: cleanString_(r.nama_halaqoh_asal) || '-', tanggalPindah: tglPindah };
        }
      });
      Object.keys(earliestKeluarBySantri).forEach(function (sid) {
        if (currentRosterIdSet[sid]) return; // masih anggota sekarang, bukan kasus "sudah keluar"
        var r = earliestKeluarBySantri[sid];
        var tglPindah = normalizeDateOnly_(r.tanggal_pindah);
        if (tglPindah > rangeFrom) {
          leftInfoBySantri[sid] = { halaqohTujuanName: cleanString_(r.nama_halaqoh_tujuan) || '-', tanggalPindah: tglPindah };
          extraMemberIds.push(sid);
        }
      });
    }
  }

  if (halaqohId && halaqohObj) {
    // rosterSantriIdMap = keanggotaan santri di halaqoh yang sedang dibuka + extraMemberIds
    // (santri yang sudah pindah keluar tapi masih relevan di sebagian rentang yang dibuka --
    // lihat currentRosterIdSet/extraMemberIds di atas). Tampilan per santri tidak terikat ke
    // halaqoh tempat entri direkam (id_halaqoh baris data): entri yang dulu direkam di halaqoh
    // lain tetap harus muncul di sini, jadi JANGAN difilter pakai accessibleIdMap pada
    // item.halaqohId.
    var rosterSantriIdMap = {};
    Object.keys(currentRosterIdSet).forEach(function (sid) { rosterSantriIdMap[sid] = true; });
    extraMemberIds.forEach(function (sid) { rosterSantriIdMap[sid] = true; });

    // Cukup normalize baris milik santri di roster ini (pakai idx_hafalanHarian_santri), bukan
    // scan + normalize SELURUH tabel hafalanHarian yang menumpuk tiap hari. Roster 1 halaqoh
    // kecil (puluhan) sehingga bind vars aman jauh di bawah batas SQLite. Filter JS
    // `if (!rosterSantriIdMap[item.santriId])` di bawah tetap jadi sumber kebenaran -- klausa
    // IN ini padanannya persis.
    var rosterSantriIds = Object.keys(rosterSantriIdMap);
    var normalizedHafalanRows = rosterSantriIds.length
      ? readSheetStateWhere_(
          'hafalanHarian',
          '"id_santri" IN (' + rosterSantriIds.map(function () { return '?'; }).join(', ') + ')',
          rosterSantriIds
        ).rows.map(normalizeHafalanHarian_)
      : [];
    // Utk santri di extraMemberIds (sudah pindah keluar, BUKAN anggota sekarang), batasi
    // entrinya sampai hari terakhir dia beneran anggota (aktifSampaiTanggal) -- supaya entri
    // yang dia buat di halaqoh BARUnya (sesudah pindah) tidak ikut nongol saat dilihat dari
    // halaqoh LAMA ini. Santri anggota sekarang tidak dibatasi (perilaku lama, lihat komentar
    // di atas: riwayat lengkapnya sengaja tetap tampil dari halaqoh manapun dia dilihat).
    var aktifSampaiBySantriId = {};
    Object.keys(leftInfoBySantri).forEach(function (sid) {
      aktifSampaiBySantriId[sid] = shiftDateOnly_(leftInfoBySantri[sid].tanggalPindah, -1);
    });
    items = normalizedHafalanRows.filter(function (item) {
      if (!item.active) return false;
      if (!rosterSantriIdMap[item.santriId]) return false;
      var aktifSampai = aktifSampaiBySantriId[item.santriId];
      if (aktifSampai && item.tanggal > aktifSampai) return false;
      var isAwalJenis = item.jenis && item.jenis.indexOf('awal_') === 0;
      if (tipe === 'awal') {
        if (!isAwalJenis) return false;
        if (tahunAjaranId && item.tahunAjaranId !== tahunAjaranId) return false;
        if (santriId && item.santriId !== santriId) return false;
        return true;
      }
      // harian mode: exclude awal_ entries
      if (isAwalJenis) return false;
      if (tanggal && item.tanggal !== normalizeDateOnly_(tanggal)) return false;
      if (!tanggal && normFrom && item.tanggal < normFrom) return false;
      if (!tanggal && normTo && item.tanggal > normTo) return false;
      if (tahunAjaranId && item.tahunAjaranId && item.tahunAjaranId !== tahunAjaranId) return false;
      if (santriId && item.santriId !== santriId) return false;
      return true;
    });

    items.sort(function (a, b) {
      if (a.tanggal !== b.tanggal) return b.tanggal.localeCompare(a.tanggal);
      return parseInt(b.id || '0', 10) - parseInt(a.id || '0', 10);
    });
  }

  var today = nowIso_().slice(0, 10);
  var todayCountByHalaqoh = {};
  // Badge "entri hari ini": cukup tarik baris bertanggal hari ini (pakai idx_hafalanHarian_tanggal),
  // bukan iterasi seluruh riwayat hafalanHarian yang menumpuk tiap hari. tanggal tersimpan ISO
  // 'YYYY-MM-DD' jadi `"tanggal" = ?` setara dgn cek normalizeDateOnly_ di bawah (tetap dijaga).
  readSheetStateWhere_('hafalanHarian', '"tanggal" = ?', [today]).rows.forEach(function (row) {
    var halaqohIdRow = cleanString_(row.id_halaqoh);
    if (!accessibleIdMap[halaqohIdRow]) return;
    if (normalizeDateOnly_(row.tanggal) !== today) return;
    var jenisRow = cleanString_(row.jenis);
    if (jenisRow && jenisRow.indexOf('awal_') === 0) return; // exclude awal from today count
    var statusRow = normalizeStatusForSheet_('hafalanHarian', row.status || STATUS_LABELS.hafalanHarian.active);
    if (!isActiveStatus_(statusRow)) return;
    todayCountByHalaqoh[halaqohIdRow] = (todayCountByHalaqoh[halaqohIdRow] || 0) + 1;
  });

  // halaqohList & tahunAjaranList hanya relevan buat layar dashboard (kartu halaqoh + filter
  // TA). Request dialog per-halaqoh (halaqohId ada) sudah punya keduanya dari load dashboard
  // sebelumnya, jadi tidak perlu dihitung & dikirim ulang.
  var halaqohListAll = [];
  var halaqohList = [];
  var total = 0;
  var totalPages = 1;
  var tahunAjaranList = [];
  if (!halaqohId) {
    // In awal mode: don't filter halaqoh list by TA (we need all halaqoh)
    var filteredAccessible = (tahunAjaranId && tipe !== 'awal')
      ? accessible.filter(function (h) { return h.tahunAjaranId === tahunAjaranId; })
      : accessible;

    halaqohListAll = filteredAccessible.map(function (h) {
      var pengampuNames = (h.pengampuIds || []).map(function (pid) {
        var p = dataset.indexes.pengurusById[pid];
        return p ? cleanString_(p.name) : '';
      }).filter(Boolean);
      // TIDAK di-filter(Boolean) -- sengaja dibiarkan 1:1 selaras index dgn santriIds (dipakai
      // pairing nama+id di frontend utk picker santri Riwayat Hafalan).
      var santriNames = (h.santriIds || []).map(function (sid) {
        var s = dataset.indexes.santriById[sid];
        return s ? cleanString_(s.name) : '';
      });
      return {
        id: h.id,
        name: h.name,
        genderGroup: h.genderGroup,
        santriCount: (h.santriIds || []).length,
        pengampuNames: pengampuNames,
        santriNames: santriNames,
        santriIds: (h.santriIds || []).slice(),
        todayCount: todayCountByHalaqoh[h.id] || 0
      };
    }).filter(function (h) {
      if (genderFilter && h.genderGroup !== genderFilter) return false;
      if (q) {
        var haystack = [h.name, h.pengampuNames.join(' '), h.santriNames.join(' ')].join(' ').toLowerCase();
        if (haystack.indexOf(q) === -1) return false;
      }
      return true;
    }).sort(function (a, b) { return (a.name || '').localeCompare(b.name || ''); });

    total = halaqohListAll.length;
    totalPages = Math.max(1, Math.ceil(total / pageSize));
    page = Math.min(page, totalPages);
    halaqohList = halaqohListAll.slice((page - 1) * pageSize, page * pageSize);

    tahunAjaranList = (dataset.tahunAjaran || []).map(function (ta) {
      return { id: ta.id, nama: ta.nama, namaDisplay: ta.namaDisplay, isAktif: ta.isAktif, tanggalMulai: ta.tanggalMulai || '', tanggalSelesai: ta.tanggalSelesai || '' };
    });
  }

  var santriList = [];
  if (halaqohId && halaqohObj) {
    // rosterIdsForList = anggota SEKARANG + extraMemberIds (santri yang sudah pindah keluar
    // tapi masih anggota di sebagian rentang yang dibuka -- lihat currentRosterIdSet/
    // extraMemberIds/joinInfoBySantri/leftInfoBySantri di atas, dipakai bareng utk items
    // filter di atas supaya keduanya konsisten).
    var rosterIdsForList = Object.keys(currentRosterIdSet).concat(extraMemberIds);
    santriList = rosterIdsForList.map(function (id) {
      var s = dataset.indexes.santriById[id];
      if (!s) return null;
      var result = { id: s.id, name: s.name, statusKey: getSantriStatusKey_(s.status) };
      var joinInfo = joinInfoBySantri[id];
      if (joinInfo) {
        result.belumPindahInfo = { halaqohAsalName: joinInfo.halaqohAsalName, tanggalPindah: joinInfo.tanggalPindah };
        // aktifDariTanggal: hari pertama dia beneran jadi anggota halaqoh ini -- dipakai UI
        // (terutama mode Bulan) buat meredupkan sel tanggal SEBELUM ini (bukan "bolong",
        // memang belum jadi anggota).
        result.aktifDariTanggal = joinInfo.tanggalPindah;
      }
      var leftInfo = leftInfoBySantri[id];
      if (leftInfo) {
        result.sudahPindahInfo = { halaqohTujuanName: leftInfo.halaqohTujuanName, tanggalPindah: leftInfo.tanggalPindah };
        // aktifSampaiTanggal: hari TERAKHIR dia masih anggota (H-1 dari tanggal pindah) --
        // sel tanggal SESUDAH ini diredupkan di mode Bulan.
        result.aktifSampaiTanggal = shiftDateOnly_(leftInfo.tanggalPindah, -1);
      }
      return result;
    }).filter(Boolean).sort(function (a, b) { return (a.name || '').localeCompare(b.name || ''); });
  }

  var responseData = {
    items: items.map(function (item) {
      var santri = dataset.indexes.santriById[item.santriId];
      var halaqoh = dataset.indexes.halaqohById[item.halaqohId];
      return {
        id: item.id,
        tanggal: item.tanggal,
        halaqohId: item.halaqohId,
        halaqohName: halaqoh ? halaqoh.name : '',
        santriId: item.santriId,
        santriName: santri ? santri.name : '',
        jenis: item.jenis,
        juz: item.juz,
        halamanDari: item.halamanDari,
        halamanSampai: item.halamanSampai,
        level: item.level,
        levelSampai: item.levelSampai,
        jumlah: item.jumlah,
        jumlahSampai: item.jumlahSampai,
        nomor: item.nomor,
        nomorSampai: item.nomorSampai,
        nilai: item.nilai,
        nyicil: item.nyicil,
        counted: item.counted,
        tahunAjaranId: item.tahunAjaranId,
        ziyadah: item.ziyadah,
        murojaaSabaqi: item.murojaaSabaqi,
        murojaaManzili: item.murojaaManzili,
        catatan: item.catatan
      };
    }),
    santriList: santriList,
    today: today,
    tahunAjaranId: tahunAjaranId
  };

  // halaqohList/tahunAjaranList/page/total cuma disertakan buat request dashboard (tanpa
  // halaqohId). Kalau selalu disertakan sebagai array kosong, frontend bisa keliru menimpa
  // state.tahunAjaranList yang sudah ke-load sebelumnya -- karena `if (data.tahunAjaranList)`
  // di frontend anggap array kosong itu truthy juga.
  if (!halaqohId) {
    responseData.halaqohList = halaqohList;
    responseData.page = page;
    responseData.pageSize = pageSize;
    responseData.total = total;
    responseData.totalPages = totalPages;
    responseData.tahunAjaranList = tahunAjaranList;
  }

  return {
    ok: true,
    timestamp: nowIso_(),
    data: responseData
  };
}

function handleHafalanHarianRekap_(request, session) {
  var dataset = loadDataset_();
  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
  var accessibleIdMap = {};
  accessible.forEach(function (h) { accessibleIdMap[h.id] = true; });

  var halaqohId = cleanString_(request.halaqohId);
  var dateFrom = cleanString_(request.dateFrom);
  var dateTo = cleanString_(request.dateTo);
  var page = clamp_(toInt_(request.page, 1), 1, 100000);
  var pageSize = clamp_(toInt_(request.pageSize, 10), 1, 100);

  if (!halaqohId || !accessibleIdMap[halaqohId]) {
    return { ok: true, timestamp: nowIso_(), data: { items: [], page: 1, pageSize: pageSize, total: 0, totalPages: 1, totals: null } };
  }

  var normFrom = dateFrom ? normalizeDateOnly_(dateFrom) : '';
  var normTo = dateTo ? normalizeDateOnly_(dateTo) : '';

  // Roster santri = keanggotaan halaqoh SAAT INI, tapi setoran digabung dari halaqoh
  // manapun selama masih dalam tahun ajaran yang sama (santri bisa pindah halaqoh
  // di tengah tahun ajaran tanpa kehilangan akumulasi hafalannya).
  var halaqohObj = dataset.indexes.halaqohById[halaqohId] || null;
  var scopeTaId = halaqohObj ? halaqohObj.tahunAjaranId : '';
  var santriIds = halaqohObj ? (halaqohObj.santriIds || []) : [];

  var emptyTotals = { totZ: 0, totS: 0, totM: 0, totMu: 0, totT: 0, totE: 0 };
  if (!santriIds.length) {
    return { ok: true, timestamp: nowIso_(), data: { items: [], page: 1, pageSize: pageSize, total: 0, totalPages: 1, totals: emptyTotals } };
  }

  // Filter di level SQLite: hanya tarik baris milik santri di roster halaqoh ini (+ tahun
  // ajaran-nya kalau ada), bukan scan seluruh tabel hafalanHarian tiap fetch. Roster 1
  // halaqoh kecil (puluhan), jadi jumlah bind vars aman jauh di bawah batas SQLite.
  var whereSql = '"id_santri" IN (' + santriIds.map(function () { return '?'; }).join(', ') + ')';
  var whereParams = santriIds.slice();
  if (scopeTaId) {
    whereSql += ' AND "tahun_ajaran_id" = ?';
    whereParams.push(scopeTaId);
  }

  var hState = readSheetStateWhere_('hafalanHarian', whereSql, whereParams);
  var items = hState.rows.map(normalizeHafalanHarian_).filter(function (item) {
    if (!item.active) return false;
    if (item.tahunAjaranId !== scopeTaId) return false;
    if (item.jenis && item.jenis.indexOf('awal_') === 0) return false; // exclude hafalan awal
    if (normFrom && item.tanggal < normFrom) return false;
    if (normTo && item.tanggal > normTo) return false;
    return true;
  });

  var byS = {};
  items.forEach(function (item) {
    var sid = item.santriId;
    if (!byS[sid]) byS[sid] = { items: [], legacyZ: 0, legacyS: 0, legacyM: 0, entries: 0 };
    if (!item.jenis) {
      byS[sid].legacyZ += parseFloat(item.ziyadah || 0) || 0;
      byS[sid].legacyS += parseFloat(item.murojaaSabaqi || 0) || 0;
      byS[sid].legacyM += parseFloat(item.murojaaManzili || 0) || 0;
    } else {
      byS[sid].items.push(item);
    }
    byS[sid].entries++;
  });

  var result = santriIds.map(function (sid) {
    var s = dataset.indexes.santriById[sid];
    var acc = byS[sid] || { items: [], legacyZ: 0, legacyS: 0, legacyM: 0, entries: 0 };
    // Cuma entri yang "counted" (bukan nyicil, penuhi ambang batas, lulus nilai) yang
    // diakumulasikan -- entri lain tetap tersimpan & terhitung di `entries` tapi tidak
    // menambah total halaman.
    var its = (acc.items || []).filter(function (it) { return it.counted; });
    var z  = (acc.legacyZ || 0) + collectRangesByJuz_(its, ['ziyadah', 'ziyadah_ulang']);
    var sb = (acc.legacyS || 0) + collectRangesByJuz_(its, ['sabaqi']);
    var mz = (acc.legacyM || 0) + collectRangesByJuz_(its, ['manzili']);
    var mu = collectRangesByJuz_(its, ['muroja_umum']);
    var tot = z + sb + mz + mu;
    return {
      santriId: sid,
      santriName: s ? cleanString_(s.name) : sid,
      ziyadah: Math.round(z * 10) / 10,
      sabaqi: Math.round(sb * 10) / 10,
      manzili: Math.round(mz * 10) / 10,
      murojaah: Math.round(mu * 10) / 10,
      entries: acc.entries,
      total: Math.round(tot * 10) / 10
    };
  });

  result.sort(function (a, b) { return b.total - a.total; });

  // tfoot "Total" harus mencerminkan SEMUA santri, bukan cuma halaman aktif
  var totals = { totZ: 0, totS: 0, totM: 0, totMu: 0, totT: 0, totE: 0 };
  result.forEach(function (r) {
    totals.totZ += r.ziyadah;
    totals.totS += r.sabaqi;
    totals.totM += r.manzili;
    totals.totMu += (r.murojaah || 0);
    totals.totT += r.total;
    totals.totE += r.entries;
  });
  ['totZ', 'totS', 'totM', 'totMu', 'totT'].forEach(function (k) { totals[k] = Math.round(totals[k] * 10) / 10; });

  var paged = paginate_(result, page, pageSize);
  paged.totals = totals;
  return { ok: true, timestamp: nowIso_(), data: paged };
}

// Cache hasil agregasi berat (dipakai "Hafalan Santri" / rekap.semua). Kunci = parameter yang
// mempengaruhi hasil (TA + jenis + scope halaqoh); "fingerprint" = COUNT + MAX(_rowid) +
// MAX(updated_at) tiap tabel sumber -> menangkap insert/update/delete APAPUN jalurnya (termasuk
// SQL mentah), karena updateStateRow_ SELALU set updated_at. Ceiling TTL sebagai jaring pengaman.
// Nilai cache HANYA dibaca (filter/slice) di hilir, tidak pernah dimutasi -> aman dibagi antar-request.
var HAFALAN_AGG_CACHE_TTL_MS = 20000;
var HAFALAN_AGG_CACHE_MAX_ENTRIES = 100;
var hafalanAggCache_ = {};

function hafalanAggSourceFingerprint_(sheetKeys) {
  return sheetKeys.map(function (k) {
    var name = quoteIdentifier_(SCHEMAS[k].sheetName);
    var row = getStatement_('SELECT COUNT(*) AS c, MAX(_rowid) AS r, MAX("updated_at") AS u FROM ' + name, []) || {};
    return k + ':' + (row.c || 0) + '/' + (row.r || 0) + '/' + (row.u || '');
  }).join('|');
}

function hafalanAggCacheGet_(ns, key, fp) {
  var hit = hafalanAggCache_[ns + '|' + key];
  if (!hit || hit.fp !== fp || (Date.now() - hit.at) >= HAFALAN_AGG_CACHE_TTL_MS) return null;
  return hit.value;
}

function hafalanAggCacheSet_(ns, key, fp, value) {
  if (Object.keys(hafalanAggCache_).length >= HAFALAN_AGG_CACHE_MAX_ENTRIES) hafalanAggCache_ = {};
  hafalanAggCache_[ns + '|' + key] = { fp: fp, at: Date.now(), value: value };
}

function handleHafalanHarianRekapSemua_(request, session) {
  // Dataset RINGKAS (4 tabel: pengurus/santri/halaqoh/tahunAjaran) -- handler ini cuma butuh
  // nama santri, roster halaqoh, dan tanggal tahun ajaran. loadDataset_() penuh membaca+normalize
  // 19 tabel (absensi*/kegiatanSop/content/dst) yang tak dipakai di sini, padahal dialog "Hafalan
  // Santri" memanggil ulang tiap ganti filter/halaman/ketik nama. getAccessibleHafalanHalaqoh_
  // sudah kompatibel dgn dataset ringkas (dipakai handleHafalanHarianHalaqohList_).
  var dataset = loadHafalanHarianListDataset_();
  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
  var accessibleIdSet = {};
  accessible.forEach(function(h) { accessibleIdSet[h.id] = true; });

  var halaqohId = cleanString_(request.halaqohId);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var jenisFilter = cleanString_(request.jenis) || 'quran'; // 'quran' | 'hadits'
  var namaQuery = cleanString_(request.nama).toLowerCase();
  var page = clamp_(toInt_(request.page, 1), 1, 100000);
  var pageSize = clamp_(toInt_(request.pageSize, 10), 1, 100);

  // Tentukan filter halaqoh
  var halaqohFilter = {};
  if (halaqohId && accessibleIdSet[halaqohId]) {
    halaqohFilter[halaqohId] = true;
  } else {
    halaqohFilter = accessibleIdSet;
  }

  // Tentukan filter tanggal dari tahun ajaran
  var normFrom = '', normTo = '';
  if (tahunAjaranId) {
    var ta = dataset.indexes.tahunAjaranById[tahunAjaranId] || null;
    if (ta) {
      normFrom = ta.tanggalMulai ? normalizeDateOnly_(ta.tanggalMulai) : '';
      normTo = ta.tanggalSelesai ? normalizeDateOnly_(ta.tanggalSelesai) : '';
    }
  }

  // Cache hasil agregasi: kunci = TA + jenis + scope halaqoh (yg mempengaruhi hasil). nama/page/
  // pageSize diterapkan SETELAH cache. Fingerprint tabel sumber + ceiling TTL -> hafalanAggCacheGet_.
  var rsAggKey = [tahunAjaranId, jenisFilter, Object.keys(halaqohFilter).sort().join(',')].join('~');
  var rsAggFp = hafalanAggSourceFingerprint_(['hafalanHarian', 'santri', 'halaqoh', 'tahunAjaran']);
  var result = hafalanAggCacheGet_('rekapSemua', rsAggKey, rsAggFp);

  if (!result) {
  // Pre-narrow di level SQLite. Klausa 1 (`id_halaqoh IN`) persis padanan baris
  // `if (!halaqohFilter[item.halaqohId]) return false;` di bawah. Klausa 2 (opsional, kalau ada
  // TA / rentang tanggal) menyingkirkan baris TA lama dari scan -- ditulis SUPERSET (OR) supaya
  // hanya baris yang PASTI ditolak filter JS di bawah yang hilang (tagged TA lain DAN di luar
  // rentang TA); baris awal_ tanggalnya bebas jadi selalu diikutkan. Hasil akhir identik --
  // filter JS di bawah tetap sumber kebenaran. tanggal tersimpan ISO 'YYYY-MM-DD' -> aman.
  var halaqohFilterIds = Object.keys(halaqohFilter);
  var hState = { rows: [] };
  if (halaqohFilterIds.length) {
    var rsWhereParts = ['"id_halaqoh" IN (' + halaqohFilterIds.map(function () { return '?'; }).join(', ') + ')'];
    var rsWhereParams = halaqohFilterIds.slice();
    var rsNarrowOr = [];
    var rsNarrowParams = [];
    if (tahunAjaranId) { rsNarrowOr.push('"tahun_ajaran_id" = ?'); rsNarrowParams.push(tahunAjaranId); }
    if (normFrom && normTo) { rsNarrowOr.push('("tanggal" >= ? AND "tanggal" <= ?)'); rsNarrowParams.push(normFrom, normTo); }
    if (rsNarrowOr.length) {
      rsNarrowOr.push('"jenis" GLOB \'awal_*\'');
      rsWhereParts.push('(' + rsNarrowOr.join(' OR ') + ')');
      rsWhereParams = rsWhereParams.concat(rsNarrowParams);
    }
    hState = readSheetStateWhere_('hafalanHarian', rsWhereParts.join(' AND '), rsWhereParams);
  }
  var items = hState.rows.map(normalizeHafalanHarian_).filter(function(item) {
    if (!item.active) return false;
    if (!halaqohFilter[item.halaqohId]) return false;
    var isAwal = item.jenis && item.jenis.indexOf('awal_') === 0;
    if (isAwal) {
      // Hafalan sebelumnya: filter by tahunAjaranId jika ada
      if (tahunAjaranId && item.tahunAjaranId && item.tahunAjaranId !== tahunAjaranId) return false;
      return true;
    }
    // Harian: filter by date range
    if (normFrom && item.tanggal < normFrom) return false;
    if (normTo && item.tanggal > normTo) return false;
    return true;
  });

  // Quran jenis yang dihitung sebagai halaman (termasuk hafalan sebelumnya)
  var QURAN_JENIS = ['ziyadah', 'ziyadah_ulang', 'sabaqi', 'manzili', 'muroja_umum', 'awal_quran'];
  var isQuran = jenisFilter === 'quran';
  // jenis non-quran yang pakai nomor (hadits, adzkar) atau level (mufrodat)
  var NOMOR_JENIS = { hadits: true, adzkar: true };
  var isMufrodat = jenisFilter === 'mufrodat';
  var isNomorJenis = !!NOMOR_JENIS[jenisFilter];

  var byS = {};
  items.forEach(function(item) {
    var sid = item.santriId;
    if (!byS[sid]) byS[sid] = { byJuz: {}, legacyTotal: 0, halaqohIds: {}, nonQuranItems: [] };
    if (isQuran) {
      if (!item.jenis) {
        var legSum = (parseFloat(item.ziyadah || 0) || 0)
                   + (parseFloat(item.murojaaSabaqi || 0) || 0)
                   + (parseFloat(item.murojaaManzili || 0) || 0);
        byS[sid].legacyTotal += legSum;
      } else if (QURAN_JENIS.indexOf(item.jenis) !== -1 && item.counted) {
        var d = parseFloat(item.halamanDari), s = parseFloat(item.halamanSampai);
        if (!isNaN(d) && !isNaN(s) && s >= d && d >= 0) {
          var juz = item.juz ? parseInt(item.juz) : 0;
          if (!byS[sid].byJuz[juz]) byS[sid].byJuz[juz] = [];
          byS[sid].byJuz[juz].push([d, s]);
        }
      }
    } else {
      if (item.jenis === jenisFilter && item.counted) byS[sid].nonQuranItems.push(item);
    }
    byS[sid].halaqohIds[item.halaqohId] = true;
  });

  // Kumpulkan semua santri dari halaqoh yang difilter
  var santriIds = [];
  var seen = {};
  Object.keys(halaqohFilter).forEach(function(hid) {
    var h = dataset.indexes.halaqohById[hid];
    if (!h) return;
    (h.santriIds || []).forEach(function(sid) {
      if (!seen[sid]) { seen[sid] = true; santriIds.push(sid); }
    });
  });
  Object.keys(byS).forEach(function(sid) {
    if (!seen[sid]) { seen[sid] = true; santriIds.push(sid); }
  });

  if (!isQuran) {
    result = santriIds.map(function(sid) {
      var s = dataset.indexes.santriById[sid];
      var acc = byS[sid] || { halaqohIds: {}, nonQuranItems: [] };
      var halaqohNames = Object.keys(acc.halaqohIds).map(function(hid) {
        var h = dataset.indexes.halaqohById[hid];
        return h ? cleanString_(h.name) : hid;
      }).join(', ');
      var rawRanges = [];
      (acc.nonQuranItems || []).forEach(function(item) {
        var d, sv;
        if (isMufrodat) {
          d = parseFloat(item.level); sv = parseFloat(item.levelSampai || item.level);
        } else {
          d = parseFloat(item.nomor); sv = parseFloat(item.nomorSampai || item.nomor);
        }
        if (!isNaN(d) && d >= 0) rawRanges.push([d, isNaN(sv) || sv < d ? d : sv]);
      });
      var ranges = mergeRangesOnly_(rawRanges);
      var total = ranges.reduce(function(sum, r) { return sum + (r[0] === 0 ? (r[1] - r[0]) : (r[1] - r[0] + 1)); }, 0);
      return {
        santriId: sid,
        santriName: s ? cleanString_(s.name) : sid,
        halaqohName: halaqohNames,
        ranges: ranges,
        total: total
      };
    }).filter(function(r) { return r.total > 0; });
    result.sort(function(a, b) { return a.santriName.localeCompare(b.santriName); });
  } else {
    result = santriIds.map(function(sid) {
      var s = dataset.indexes.santriById[sid];
      var acc = byS[sid] || { byJuz: {}, legacyTotal: 0, halaqohIds: {} };
      var halaqohNames = Object.keys(acc.halaqohIds).map(function(hid) {
        var h = dataset.indexes.halaqohById[hid];
        return h ? cleanString_(h.name) : hid;
      }).join(', ');
      var juzList = Object.keys(acc.byJuz).map(function(j) { return parseInt(j); })
        .sort(function(a, b) { return a - b; });
      var perJuz = juzList.map(function(juz) {
        return { juz: juz, halaman: mergePageRanges_(acc.byJuz[juz]) };
      });
      var totalHlm = perJuz.reduce(function(s, x) { return s + x.halaman; }, 0)
                   + (acc.legacyTotal || 0);
      return {
        santriId: sid,
        santriName: s ? cleanString_(s.name) : sid,
        halaqohName: halaqohNames,
        perJuz: perJuz,
        legacyTotal: Math.round((acc.legacyTotal || 0) * 10) / 10,
        totalHlm: Math.round(totalHlm * 10) / 10
      };
    }).filter(function(r) { return r.totalHlm > 0; });
    result.sort(function(a, b) { return a.santriName.localeCompare(b.santriName); });
  }

  hafalanAggCacheSet_('rekapSemua', rsAggKey, rsAggFp, result);
  }

  if (namaQuery) {
    result = result.filter(function(r) {
      return (r.santriName || '').toLowerCase().indexOf(namaQuery) !== -1;
    });
  }

  // Pagination server-side: dialog "Hafalan Santri" fetch per halaman (default 10/hal)
  var paged = paginate_(result, page, pageSize);
  return { ok: true, timestamp: nowIso_(), data: paged };
}

function handleHafalanHarianTopZiyadah_(request, session) {
  var dataset = loadDataset_();
  // Top Ziyadah sengaja TIDAK di-scope per pengampu — beda dari daftar hafalan/rekap
  // yang hanya menampilkan halaqoh milik sendiri. Siapa pun yang bisa akses halaman
  // ini (canAccessHafalanHarian_) berhak lihat papan Top Ziyadah seluruh pesantren.
  var accessible = (dataset.halaqoh || []).filter(function (h) { return h.active; });
  var accessibleIdSet = {};
  accessible.forEach(function(h) { accessibleIdSet[h.id] = true; });

  var dateFrom = cleanString_(request.dateFrom);
  var dateTo = cleanString_(request.dateTo);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var gender = (cleanString_(request.gender) || '').toLowerCase();
  var jenisFilter = cleanString_(request.jenisFilter) || 'ziyadah';
  // Default TRUE (Ziyadah Ulang dianggap Ziyadah) -- perilaku lama sebelum filter ini ada.
  // Cuma jadi false kalau eksplisit dikirim false/0 dari frontend.
  var treatUlangRaw = request.treatZiyadahUlangAsZiyadah;
  var treatUlangAsZiyadah = (treatUlangRaw === undefined || treatUlangRaw === null || cleanString_(treatUlangRaw) === '')
    ? true
    : isTruthy_(treatUlangRaw);
  var ziyadahJenisList = treatUlangAsZiyadah ? ['ziyadah', 'ziyadah_ulang', 'awal_quran'] : ['ziyadah', 'awal_quran'];
  var topN = parseInt(request.topN) || 10;
  if (topN < 1) topN = 1;
  if (topN > 100) topN = 100;

  if (gender === 'ikhwan' || gender === 'akhowat') {
    accessible = accessible.filter(function(h) {
      var g = (h.genderGroup || '').toLowerCase();
      return gender === 'ikhwan' ? g === 'ikhwan' : g === 'akhowat';
    });
    accessibleIdSet = {};
    accessible.forEach(function(h) { accessibleIdSet[h.id] = true; });
  }

  var normFrom = dateFrom ? normalizeDateOnly_(dateFrom) : '';
  var normTo = dateTo ? normalizeDateOnly_(dateTo) : '';

  // Baris awal_ (baseline) dibutuhkan LINTAS SEMUA TA/tanggal (lihat komentar di bawah), jadi
  // SELALU diikutkan lewat GLOB. Baris non-awal cukup yang cocok filter papan (TA / rentang
  // tanggal); kondisi accessible & counted tetap disaring di JS. Kalau tidak ada TA maupun
  // rentang tanggal -> papan "semua waktu", tetap scan penuh. tanggal ISO -> perbandingan aman.
  var tzNarrow = [];
  var tzNarrowParams = [];
  if (tahunAjaranId) {
    tzNarrow.push('("tahun_ajaran_id" = ? OR "tahun_ajaran_id" = \'\' OR "tahun_ajaran_id" IS NULL)');
    tzNarrowParams.push(tahunAjaranId);
  }
  if (normFrom) { tzNarrow.push('"tanggal" >= ?'); tzNarrowParams.push(normFrom); }
  if (normTo) { tzNarrow.push('"tanggal" <= ?'); tzNarrowParams.push(normTo); }
  var hState = tzNarrow.length
    ? readSheetStateWhere_('hafalanHarian', '("jenis" GLOB \'awal_*\' OR (' + tzNarrow.join(' AND ') + '))', tzNarrowParams)
    : readSheetState_('hafalanHarian');
  var allNormalized = hState.rows.map(normalizeHafalanHarian_).filter(function (item) { return item.active; });

  // Baseline "Hafalan Awal" (posisi sebelum sistem ini mulai dipakai) per santri -- SENGAJA
  // diambil dari SELURUH baris (bukan `items` di bawah yang sudah difilter accessible/tahun
  // ajaran/rentang tanggal), karena posisi awal berlaku selamanya, tidak terikat filter papan.
  // Dipakai utk mengurangi overlap supaya bagian yg sudah dicatat SEBELUM tracking ini mulai
  // tidak ikut terhitung sbg ziyadah/hadits BARU di papan Top Ziyadah -- pola SAMA PERSIS dgn
  // `netTotal` di handleHafalanHarianSantriDetail_ (dialog detail per-santri), yang sebelumnya
  // sudah dikoreksi begini tapi papan ranking utama ini terlewat, jadi 2 angka itu bisa beda
  // (ranking di sini lebih tinggi dari detail per-santrinya kalau ada baseline yang overlap).
  var awalQuranBySantri = {};
  var awalHaditsBySantri = {};
  allNormalized.forEach(function (item) {
    if (item.jenis === 'awal_quran') {
      (awalQuranBySantri[item.santriId] = awalQuranBySantri[item.santriId] || []).push(item);
    } else if (item.jenis === 'awal_hadits') {
      (awalHaditsBySantri[item.santriId] = awalHaditsBySantri[item.santriId] || []).push(item);
    }
  });

  var items = allNormalized.filter(function(item) {
    if (!accessibleIdSet[item.halaqohId]) return false;
    if (item.jenis && item.jenis.indexOf('awal_') === 0) return false; // baseline ditangani terpisah di atas
    if (!item.counted) return false; // nyicil/di bawah ambang batas/gagal nilai tidak masuk papan
    if (tahunAjaranId && item.tahunAjaranId && item.tahunAjaranId !== tahunAjaranId) return false;
    if (normFrom && item.tanggal < normFrom) return false;
    if (normTo && item.tanggal > normTo) return false;
    return true;
  });

  var byS = {};
  items.forEach(function(item) {
    var sid = item.santriId;
    if (!byS[sid]) byS[sid] = { items: [], legacyZ: 0, halaqohIds: {} };
    if (!item.jenis) {
      byS[sid].legacyZ += parseFloat(item.ziyadah || 0) || 0;
    } else {
      byS[sid].items.push(item);
    }
    byS[sid].halaqohIds[item.halaqohId] = true;
  });

  var result = Object.keys(byS).map(function(sid) {
    var s = dataset.indexes.santriById[sid];
    var acc = byS[sid];
    var its = acc.items || [];
    var halaqohIdKeys = Object.keys(acc.halaqohIds);
    var halaqohNames = halaqohIdKeys.map(function(hid) {
      var h = dataset.indexes.halaqohById[hid];
      return h ? cleanString_(h.name) : hid;
    }).join(', ');
    // Nama pengampu dari SEMUA halaqoh yg nyumbang entri di periode ini (biasanya cuma 1,
    // tapi bisa lebih kalau santri sempat pindah halaqoh dalam periode yg lagi dilihat).
    var pengampuNameSet = {};
    halaqohIdKeys.forEach(function(hid) {
      var h = dataset.indexes.halaqohById[hid];
      (h && h.pengampuIds || []).forEach(function(pid) {
        var p = dataset.indexes.pengurusById[pid];
        if (p) pengampuNameSet[cleanString_(p.name)] = true;
      });
    });
    var pengampuNames = Object.keys(pengampuNameSet).join(', ');
    var badalNameSet = {};
    halaqohIdKeys.forEach(function(hid) {
      var h = dataset.indexes.halaqohById[hid];
      (h && h.badalIds || []).forEach(function(pid) {
        var p = dataset.indexes.pengurusById[pid];
        if (p) badalNameSet[cleanString_(p.name)] = true;
      });
    });
    var badalNames = Object.keys(badalNameSet).join(', ');
    var awalQ = awalQuranBySantri[sid] || [];
    var netZ = collectRangesByJuz_(its.concat(awalQ), ziyadahJenisList) - collectRangesByJuz_(awalQ, ['awal_quran']);
    var z = (acc.legacyZ || 0) + netZ;
    var awalH = awalHaditsBySantri[sid] || [];
    var h = collectNomorRanges_(its.concat(awalH), ['hadits', 'awal_hadits']) - collectNomorRanges_(awalH, ['awal_hadits']);
    return {
      santriId: sid,
      santriName: s ? cleanString_(s.name) : sid,
      halaqohName: halaqohNames,
      pengampuNames: pengampuNames,
      badalNames: badalNames,
      ziyadah: Math.round(z * 10) / 10,
      hadits: Math.round(h * 10) / 10,
    };
  });

  if (jenisFilter === 'hadits') {
    result.sort(function(a, b) { return b.hadits - a.hadits; });
    result = result.filter(function(r) { return r.hadits > 0; });
  } else {
    result.sort(function(a, b) { return b.ziyadah - a.ziyadah; });
    result = result.filter(function(r) { return r.ziyadah > 0; });
  }
  // topN = ukuran KOLAM papan (mis. Top 25/50/100), bukan ukuran halaman.
  // Paginasi dilakukan di dalam kolam itu, 1 fetch per klik halaman.
  var pool = result.slice(0, topN);
  var page = clamp_(toInt_(request.page, 1), 1, 100000);
  var pageSize = clamp_(toInt_(request.pageSize, 10), 1, 100);
  return { ok: true, timestamp: nowIso_(), data: paginate_(pool, page, pageSize) };
}

// Detail semua setoran (semua jenis, kecuali hafalan awal) satu santri dalam satu periode --
// dipakai dialog detail per-santri di Top Ziyadah. Sengaja TIDAK di-scope per halaqoh pengampu,
// samakan dengan Top Ziyadah sendiri (siapapun yg bisa akses papan itu boleh lihat detailnya).
function handleHafalanHarianSantriDetail_(request, session) {
  var dataset = loadDataset_();
  var santriId = cleanString_(request.santriId);
  var dateFrom = cleanString_(request.dateFrom);
  var dateTo = cleanString_(request.dateTo);
  var jenisFilter = cleanString_(request.jenisFilter) || 'ziyadah';
  // Default TRUE, sinkron dgn filter yang sama di papan Top Ziyadah -- lihat catatan di
  // handleHafalanHarianTopZiyadah_.
  var treatUlangRawDetail = request.treatZiyadahUlangAsZiyadah;
  var treatUlangAsZiyadah = (treatUlangRawDetail === undefined || treatUlangRawDetail === null || cleanString_(treatUlangRawDetail) === '')
    ? true
    : isTruthy_(treatUlangRawDetail);
  if (!santriId) throw createError_('Santri wajib dipilih.', 400);

  var santri = dataset.indexes.santriById[santriId];
  if (!santri) throw createError_('Santri tidak ditemukan.', 404);

  var normFrom = dateFrom ? normalizeDateOnly_(dateFrom) : '';
  var normTo = dateTo ? normalizeDateOnly_(dateTo) : '';

  var hState = readSheetStateWhere_('hafalanHarian', '"id_santri" = ?', [santriId]);
  var allSantriItems = hState.rows.map(normalizeHafalanHarian_).filter(function (item) {
    return item.active;
  });

  var isHaditsMode = jenisFilter === 'hadits';
  var utamaJenis = isHaditsMode ? ['hadits'] : (treatUlangAsZiyadah ? ['ziyadah', 'ziyadah_ulang'] : ['ziyadah']);
  var awalJenis = isHaditsMode ? 'awal_hadits' : 'awal_quran';

  // List yang ditampilkan: sesuai mode Top Ziyadah yang lagi aktif (Ziyadah/Ziyadah Ulang,
  // atau Hadits), yang counted (diakumulasikan), dalam periode yang sama.
  var items = allSantriItems.filter(function (item) {
    if (utamaJenis.indexOf(item.jenis) === -1) return false;
    if (!item.counted) return false;
    if (normFrom && item.tanggal < normFrom) return false;
    if (normTo && item.tanggal > normTo) return false;
    return true;
  });
  items.sort(function (a, b) {
    if (a.tanggal !== b.tanggal) return b.tanggal.localeCompare(a.tanggal);
    return (parseInt(b.id, 10) || 0) - (parseInt(a.id, 10) || 0);
  });

  // Total bersih = gabungan (posisi awal + setoran MURNI periode ini), dikurangi posisi awal
  // sendiri -- supaya yang udah dicatat di Hafalan Awal (sebelum tracking ini mulai) tidak ikut
  // kehitung sebagai setoran baru. Disamakan dgn angka ranking Top Ziyadah: mode Qur'an jenis
  // "ziyadah" + "ziyadah_ulang", mode Hadits jenis "hadits".
  var murniItems = isHaditsMode
    ? items.filter(function (item) { return item.jenis === 'hadits'; })
    : items.filter(function (item) { return utamaJenis.indexOf(item.jenis) !== -1; });
  var awalItems = allSantriItems.filter(function (item) { return item.jenis === awalJenis; });
  var netTotal, posisiAwal, netBreakdown;
  if (isHaditsMode) {
    var combinedH = collectNomorRanges_(murniItems.concat(awalItems), ['hadits', 'awal_hadits']);
    var awalOnlyH = collectNomorRanges_(awalItems, ['awal_hadits']);
    netTotal = Math.round((combinedH - awalOnlyH) * 10) / 10;
    posisiAwal = awalItems.map(function (item) { return { nomor: item.nomor, nomorSampai: item.nomorSampai }; });
    netBreakdown = computeNetBreakdownNomor_(murniItems, awalItems);
  } else {
    var combinedZ = collectRangesByJuz_(murniItems.concat(awalItems), (treatUlangAsZiyadah ? ['ziyadah', 'ziyadah_ulang'] : ['ziyadah']).concat(['awal_quran']));
    var awalOnlyZ = collectRangesByJuz_(awalItems, ['awal_quran']);
    netTotal = Math.round((combinedZ - awalOnlyZ) * 10) / 10;
    posisiAwal = awalItems.map(function (item) { return { juz: item.juz, halamanDari: item.halamanDari, halamanSampai: item.halamanSampai }; });
    netBreakdown = computeNetBreakdownByJuz_(murniItems, awalItems);
  }

  // Anotasi per-baris: berapa dari halaman/nomor entri ini yang BENERAN baru ("bersih"), dan
  // dari mana overlap-nya berasal (posisi awal, atau entri murni lain yang tanggalnya lebih
  // lama) -- lihat computeRowOverlaps_ di atas.
  var rowOverlaps = isHaditsMode
    ? computeRowOverlapsNomor_(murniItems, awalItems)
    : computeRowOverlapsByJuz_(murniItems, awalItems);

  var result = items.map(function (item) {
    var h = dataset.indexes.halaqohById[item.halaqohId];
    var pages;
    if (isHaditsMode) {
      var nd = parseFloat(item.nomor), ns = parseFloat(item.nomorSampai || item.nomor);
      pages = (isNaN(nd) || isNaN(ns) || ns < nd) ? 0 : (nd === 0 ? (ns - nd) : (ns - nd + 1));
    } else {
      pages = hafalanPages_(item);
    }
    var ov = rowOverlaps[item.id];
    var overlapInfo = (ov && ov.overlaps.length) ? {
      netPages: Math.round(ov.netPages * 10) / 10,
      overlaps: ov.overlaps.map(function (o) {
        return o.source === 'awal'
          ? { source: 'awal', pages: Math.round(o.pages * 10) / 10 }
          : { source: 'entry', tanggal: o.tanggal, jenisLabel: HAFALAN_JENIS_LABEL[o.jenis] || o.jenis || '', pages: Math.round(o.pages * 10) / 10 };
      })
    } : null;
    return {
      id: item.id,
      tanggal: item.tanggal,
      halaqohName: h ? cleanString_(h.name) : '',
      jenis: item.jenis,
      jenisLabel: HAFALAN_JENIS_LABEL[item.jenis] || item.jenis || '',
      detail: hafalanDetailString_(item),
      pages: Math.round(pages * 10) / 10,
      overlapInfo: overlapInfo,
      nilai: item.nilai,
      nyicil: item.nyicil,
      counted: item.counted,
      catatan: item.catatan
    };
  });

  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      santriName: cleanString_(santri.name),
      jenisFilter: isHaditsMode ? 'hadits' : 'ziyadah',
      netTotal: netTotal,
      posisiAwal: posisiAwal,
      netBreakdown: netBreakdown,
      items: result
    }
  };
}

// Posisi halaman terakhir seorang santri di satu jenis+juz tertentu -- dipakai frontend utk
// kasih hint "lanjutan mulai dari halaman berapa" + warning non-blocking kalau halaman yang
// diisi gak nyambung. Entri yang tidak "counted" (nyicil/di bawah ambang batas/gagal nilai)
// TIDAK menggeser posisi -- santri harus mengulang halaman yang sama sampai genap.
function handleHafalanHarianLastPosisi_(request, session) {
  var santriId = cleanString_(request.santriId);
  var jenis = cleanString_(request.jenis);
  var juz = cleanString_(request.juz);
  var tanggal = cleanString_(request.tanggal);
  var excludeId = cleanString_(request.excludeId);
  var empty = { lastHalaman: null, lastTanggal: null, expectedNext: null, isJuzSelesai: false };
  if (!santriId || !jenis || !juz || !CORE_QURAN_JENIS_[jenis]) {
    return { ok: true, timestamp: nowIso_(), data: empty };
  }

  var dataset = loadDataset_();
  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
  var accessibleSantriIds = {};
  accessible.forEach(function (h) { (h.santriIds || []).forEach(function (sid) { accessibleSantriIds[sid] = true; }); });
  if (!accessibleSantriIds[santriId]) {
    return { ok: true, timestamp: nowIso_(), data: empty };
  }

  var normTanggal = tanggal ? normalizeDateOnly_(tanggal) : '';
  var hState = readSheetStateWhere_('hafalanHarian', '"id_santri" = ? AND "jenis" = ?', [santriId, jenis]);
  var candidates = hState.rows.map(normalizeHafalanHarian_).filter(function (item) {
    if (!item.active || item.juz !== juz) return false;
    if (excludeId && item.id === excludeId) return false;
    if (!item.counted) return false;
    if (normTanggal && item.tanggal > normTanggal) return false;
    return true;
  });
  candidates.sort(function (a, b) {
    if (a.tanggal !== b.tanggal) return a.tanggal < b.tanggal ? 1 : -1;
    return (parseInt(b.id, 10) || 0) - (parseInt(a.id, 10) || 0);
  });
  var last = candidates[0];
  if (!last) return { ok: true, timestamp: nowIso_(), data: empty };

  var lastHal = Math.floor(parseFloat(last.halamanSampai));
  var maxHal = getJuzHalamanMax_(juz);
  var isJuzSelesai = lastHal >= maxHal;
  return {
    ok: true,
    timestamp: nowIso_(),
    data: {
      lastHalaman: lastHal,
      lastTanggal: last.tanggal,
      expectedNext: isJuzSelesai ? null : lastHal + 1,
      isJuzSelesai: isJuzSelesai
    }
  };
}

// Audit kontinuitas: scan semua entri 5 jenis inti santri di satu halaqoh, kelompokkan per
// (santri, jenis, juz), urutkan tanggal, lalu tandai pasangan entri yang "halaman dari"-nya
// TIDAK nyambung dari "halaman sampai" entri sebelumnya (+1) -- baik loncat (kelewat) maupun
// mundur/tumpang-tindih. Entri yang tidak "counted" diabaikan (nyicil dianggap tidak
// menggeser posisi, jadi tidak bisa jadi acuan kontinuitas).
function handleHafalanHarianAuditKontinuitas_(request, session) {
  var dataset = loadDataset_();
  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
  var accessibleIdMap = {};
  accessible.forEach(function (h) { accessibleIdMap[h.id] = true; });

  var halaqohId = cleanString_(request.halaqohId);
  if (!halaqohId || !accessibleIdMap[halaqohId]) {
    return { ok: true, timestamp: nowIso_(), data: { items: [] } };
  }
  var halaqohObj = dataset.indexes.halaqohById[halaqohId] || null;
  var rosterIds = {};
  (halaqohObj ? halaqohObj.santriIds || [] : []).forEach(function (sid) { rosterIds[sid] = true; });

  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var bulan = cleanString_(request.bulan); // 'YYYY-MM', opsional

  // Cuma santri di roster halaqoh ini yang dipakai (pakai idx_hafalanHarian_santri) -- bukan
  // scan seluruh tabel. Filter JS `if (!rosterIds[item.santriId])` di bawah tetap sumber kebenaran.
  var rosterIdList = Object.keys(rosterIds);
  var hState = rosterIdList.length
    ? readSheetStateWhere_(
        'hafalanHarian',
        '"id_santri" IN (' + rosterIdList.map(function () { return '?'; }).join(', ') + ')',
        rosterIdList
      )
    : { rows: [] };
  var items = hState.rows.map(normalizeHafalanHarian_).filter(function (item) {
    if (!item.active) return false;
    if (!item.jenis || !CORE_QURAN_JENIS_[item.jenis]) return false;
    if (!rosterIds[item.santriId]) return false;
    if (!item.counted) return false;
    if (!item.juz) return false;
    if (tahunAjaranId && item.tahunAjaranId !== tahunAjaranId) return false;
    if (bulan && item.tanggal.slice(0, 7) !== bulan) return false;
    var d = parseFloat(item.halamanDari), s = parseFloat(item.halamanSampai);
    return !isNaN(d) && !isNaN(s);
  });

  var groups = {};
  items.forEach(function (item) {
    var key = item.santriId + '|' + item.jenis + '|' + item.juz;
    if (!groups[key]) groups[key] = [];
    groups[key].push(item);
  });

  var issues = [];
  Object.keys(groups).forEach(function (key) {
    var list = groups[key];
    list.sort(function (a, b) {
      if (a.tanggal !== b.tanggal) return a.tanggal < b.tanggal ? -1 : 1;
      return (parseInt(a.id, 10) || 0) - (parseInt(b.id, 10) || 0);
    });
    var juz = list[0].juz;
    var maxHal = getJuzHalamanMax_(juz);
    for (var i = 1; i < list.length; i++) {
      var prev = list[i - 1], cur = list[i];
      var prevDari = Math.floor(parseFloat(prev.halamanDari));
      var prevSampai = Math.floor(parseFloat(prev.halamanSampai));
      var curDari = Math.floor(parseFloat(cur.halamanDari));
      var curSampai = Math.floor(parseFloat(cur.halamanSampai));
      if (prevSampai >= maxHal) continue; // juz sebelumnya sudah selesai -- wajar beda konteks
      if (curDari === prevSampai + 1) continue; // nyambung normal
      var s = dataset.indexes.santriById[prev.santriId];
      // 3 tipe: 'loncat' (ada halaman kelewat), 'sama' (rentang dari-sampai PERSIS duplikat
      // entri sebelumnya -- kemungkinan besar salah input dobel), 'tumpang' (mundur & beririsan
      // tapi rentangnya beda dari entri sebelumnya). Keputusan 2026-08-03: 'sama' dianggap
      // lebih parah drpd 'tumpang' krn indikasi duplikat data, bukan cuma mundur biasa.
      var kontinuitasType;
      if (curDari > prevSampai + 1) kontinuitasType = 'loncat';
      else if (curDari === prevDari && curSampai === prevSampai) kontinuitasType = 'sama';
      else kontinuitasType = 'tumpang';
      issues.push({
        santriId: prev.santriId,
        santriName: s ? cleanString_(s.name) : prev.santriId,
        jenis: prev.jenis,
        jenisLabel: HAFALAN_JENIS_LABEL[prev.jenis] || prev.jenis,
        juz: juz,
        prevTanggal: prev.tanggal,
        prevHalamanDari: prevDari,
        prevHalamanSampai: prevSampai,
        nextTanggal: cur.tanggal,
        nextHalamanDari: curDari,
        nextHalamanSampai: curSampai,
        type: kontinuitasType,
        gap: curDari - (prevSampai + 1)
      });
    }
  });

  issues.sort(function (a, b) {
    if (a.santriName !== b.santriName) return a.santriName.localeCompare(b.santriName);
    if (a.juz !== b.juz) return parseInt(a.juz, 10) - parseInt(b.juz, 10);
    return a.prevTanggal < b.prevTanggal ? -1 : 1;
  });

  return { ok: true, timestamp: nowIso_(), data: { items: issues } };
}

// Cek apakah suatu angka kelipatan 0.25 (0, 0.25, 0.5, 0.75, 1, 1.25, dst) -- dipakai buat
// batasi presisi input halaman/nomor supaya tidak ada angka aneh spt 2.2 atau 2.35.
// SYNC: samakan dengan isQuarterMultiple() di frontend/pages/hafalanHarian/index.html kalau berubah.
function isQuarterMultiple_(value) {
  var scaled = value * 4;
  return Math.abs(scaled - Math.round(scaled)) < 1e-6;
}

// Cek apakah suatu angka bilangan bulat (tanpa pecahan) -- dipakai utk field yg secara
// alami tidak punya konsep "sebagian" (nomor hadits/adzkar, level mufrodat).
function isWholeNumber_(value) {
  return Math.abs(value - Math.round(value)) < 1e-9;
}

function handleHafalanHarianSave_(request, session) {
  var dataset = loadDataset_();
  var record = parseRecordPayload_(request);
  var halaqohId = cleanString_(record.halaqohId || record.id_halaqoh);
  var santriId = cleanString_(record.santriId || record.id_santri);
  var rawJenis = cleanString_(record.jenis) || 'ziyadah';
  var isAwal = rawJenis.indexOf('awal_') === 0;
  // awal entries don't need a specific date, so default to today when omitted; a supplied
  // date must still be a genuine calendar date.
  var tanggal = isAwal
    ? (record.tanggal ? assertValidDateOnly_(record.tanggal, 'Tanggal') : nowIso_().slice(0, 10))
    : assertValidDateOnly_(record.tanggal, 'Tanggal');

  if (!halaqohId) throw createError_('Halaqoh wajib dipilih.', 400);
  if (!santriId) throw createError_('Santri wajib dipilih.', 400);

  var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
  var halaqoh = accessible.filter(function (h) { return h.id === halaqohId; })[0] || null;
  if (!halaqoh) throw createError_('Halaqoh tidak ditemukan atau tidak dapat diakses.', 404);

  var santriIsMember = (halaqoh.santriIds || []).indexOf(santriId) !== -1;
  if (!isAwal) {
    // SELALU direkonstruksi sesuai tanggal entrinya (bukan cuma fallback saat bukan anggota
    // sekarang, dan TANPA pengecualian role -- keputusan user 2026-08-11: berlaku sama utk
    // semua orang termasuk Admin/SuperAdmin/Koordinator Halaqoh) -- supaya pengampu halaqoh
    // TUJUAN tidak bisa isi/edit data santri utk tanggal SEBELUM dia beneran pindah kesini,
    // walau sekarang sudah jadi anggota. Sebaliknya, santri yang sudah pindah KELUAR tetap
    // bisa dilengkapi entrinya di halaqoh LAMA utk tanggal sebelum kepindahannya.
    var pindahRowsForMembership = readSheetState_('riwayatPindahHalaqoh').rows.filter(function (r) {
      return cleanString_(r.id_halaqoh_asal) === halaqoh.id || cleanString_(r.id_halaqoh_tujuan) === halaqoh.id;
    });
    var rosterAsOfTanggal = reconstructHalaqohMembershipIds_(halaqoh.santriIds, halaqoh.id, pindahRowsForMembership, tanggal);
    santriIsMember = rosterAsOfTanggal.indexOf(santriId) !== -1;
  }
  if (!santriIsMember) {
    throw createError_('Santri tidak terdaftar di halaqoh ini pada tanggal tersebut.', 400);
  }

  // Satu entri = satu item ber-jenis (anti-tabrakan input). Default ziyadah utk kompatibilitas.
  var jenis = rawJenis;
  var kategori = HAFALAN_JENIS[jenis];
  if (!kategori) throw createError_('Jenis hafalan tidak dikenal: ' + jenis, 400);

  // Hafalan awal: validasi tahun ajaran + upsert (satu per santri per jenis per TA)
  var awalTahunAjaranId = '';
  if (isAwal) {
    awalTahunAjaranId = cleanString_(record.tahunAjaranId || record.tahun_ajaran_id);
    if (!awalTahunAjaranId) throw createError_('Tahun ajaran wajib diisi untuk hafalan awal.', 400);
    requireTahunAjaranNotLocked_(awalTahunAjaranId);
  }

  var state = readSheetState_('hafalanHarian');
  var requestedId = cleanString_(record.id);
  var existing = requestedId ? findSheetRowById_(state.rows, requestedId) : null;

  if (requestedId && !existing) {
    throw createError_('Data hafalan yang akan diubah tidak ditemukan.', 404);
  }

  var isCoreQuranJenis = kategori === 'quran' && !isAwal && CORE_QURAN_JENIS_[jenis];
  var isIqroHarian = kategori === 'iqro' && !isAwal;
  var isTalaqqiHarian = kategori === 'talaqqi' && !isAwal && TALAQQI_HARIAN_JENIS_[jenis];

  var nilaiRaw = cleanString_(record.nilai);
  if (nilaiRaw !== '') {
    var nilaiNum = parseFloat(nilaiRaw);
    if (isNaN(nilaiNum) || nilaiNum < 0 || nilaiNum > 100) {
      throw createError_('Nilai harus angka 0–100.', 400);
    }
  } else if (isCoreQuranJenis || isIqroHarian || isTalaqqiHarian) {
    throw createError_('Nilai wajib diisi (0–100) untuk jenis ini.', 400);
  }

  // Tulis semua kolom item (kolom yang tak relevan dikosongkan agar baris konsisten dgn jenisnya).
  var writable = {
    tanggal: tanggal,
    id_halaqoh: halaqoh.id,
    id_santri: santriId,
    id_pengurus: cleanString_(session.id),
    jenis: jenis,
    juz: '', halaman_dari: '', halaman_sampai: '', level: '', level_sampai: '', jumlah: '', jumlah_sampai: '', nomor: '', nomor_sampai: '',
    nilai: nilaiRaw,
    nyicil: '',
    tahun_ajaran_id: isAwal ? awalTahunAjaranId : cleanString_(halaqoh.tahunAjaranId),
    ziyadah: '', muroja_sabaqi: '', muroja_manzili: '',
    catatan: cleanString_(record.catatan),
    status: STATUS_LABELS.hafalanHarian.active,
    updated_at: nowIso_()
  };
  if (isCoreQuranJenis) {
    // 5 jenis inti Al-Qur'an: halaman WAJIB bilangan bulat (tidak ada lagi kelipatan 0.25).
    writable.juz = cleanString_(record.juz);
    if (!writable.juz) throw createError_('Juz wajib diisi.', 400);
    var chlDari = cleanString_(record.halamanDari || record.halaman_dari);
    var chlSampai = cleanString_(record.halamanSampai || record.halaman_sampai);
    if (!chlDari || !chlSampai) {
      throw createError_('Halaman dari dan halaman sampai wajib diisi keduanya.', 400);
    }
    var chlD = parseFloat(chlDari), chlS = parseFloat(chlSampai);
    if (isNaN(chlD) || isNaN(chlS) || !isWholeNumber_(chlD) || !isWholeNumber_(chlS)) {
      throw createError_('Halaman dari/sampai harus bilangan bulat (1, 2, 3, ...), tidak boleh pecahan.', 400);
    }
    if (chlD < 1) throw createError_('Halaman dari minimal 1.', 400);
    if (chlS < chlD) throw createError_('Halaman sampai tidak boleh lebih kecil dari halaman dari.', 400);
    var cMaxHal = getJuzHalamanMax_(writable.juz);
    if (chlS > cMaxHal) throw createError_('Halaman sampai tidak boleh melebihi ' + cMaxHal + ' (Juz ' + (writable.juz || '?') + ').', 400);

    var nyicilFlag = (jenis === 'ziyadah' || jenis === 'ziyadah_ulang') && isTruthy_(record.nyicil);
    if (nyicilFlag) {
      if (chlD !== chlS) throw createError_('Setoran nyicil harus dicatat di 1 halaman yang sama (halaman dari = halaman sampai).', 400);
      if (!cleanString_(record.catatan)) throw createError_('Catatan wajib diisi untuk setoran nyicil.', 400);
    }
    writable.halaman_dari = String(chlD);
    writable.halaman_sampai = String(chlS);
    writable.nyicil = nyicilFlag ? '1' : '';
  } else if (isTalaqqiHarian) {
    // Talaqqi/Tahsin/Tilawah harian: Nama Surat (bukan Juz) + AYAT (bukan halaman) WAJIB
    // bilangan bulat, dibatasi maksimal sesuai jumlah ayat surat yang dipilih.
    var surat = cleanString_(record.juz || record.surat);
    if (!surat) throw createError_('Nama surat wajib dipilih.', 400);
    if (!SURAT_SET_[surat]) throw createError_('Nama surat tidak dikenal: ' + surat, 400);
    writable.juz = surat;
    var thlDari = cleanString_(record.halamanDari || record.halaman_dari);
    var thlSampai = cleanString_(record.halamanSampai || record.halaman_sampai);
    if (!thlDari || !thlSampai) {
      throw createError_('Ayat dari dan ayat sampai wajib diisi keduanya.', 400);
    }
    var thlD = parseFloat(thlDari), thlS = parseFloat(thlSampai);
    if (isNaN(thlD) || isNaN(thlS) || !isWholeNumber_(thlD) || !isWholeNumber_(thlS)) {
      throw createError_('Ayat dari/sampai harus bilangan bulat (1, 2, 3, ...), tidak boleh pecahan.', 400);
    }
    if (thlD < 1) throw createError_('Ayat dari minimal 1.', 400);
    if (thlS < thlD) throw createError_('Ayat sampai tidak boleh lebih kecil dari ayat dari.', 400);
    var suratMaxAyat = SURAT_AYAT_MAX_[surat];
    if (suratMaxAyat && thlS > suratMaxAyat) {
      throw createError_('Ayat sampai tidak boleh melebihi ' + suratMaxAyat + ' (jumlah ayat surat ' + surat + ').', 400);
    }
    writable.halaman_dari = String(thlD);
    writable.halaman_sampai = String(thlS);
  } else if (kategori === 'quran' || kategori === 'talaqqi') {
    writable.juz = cleanString_(record.juz);
    var hlDari = cleanString_(record.halamanDari || record.halaman_dari);
    var hlSampai = cleanString_(record.halamanSampai || record.halaman_sampai);
    var hasHlDari = hlDari !== '', hasHlSampai = hlSampai !== '';
    if (!hasHlDari || !hasHlSampai) {
      throw createError_('Halaman dari dan halaman sampai wajib diisi keduanya.', 400);
    }
    if (hasHlDari && hasHlSampai) {
      var hlD = parseFloat(hlDari), hlS = parseFloat(hlSampai);
      if (!isQuarterMultiple_(hlD) || !isQuarterMultiple_(hlS)) {
        throw createError_('Halaman dari/sampai harus kelipatan 0.25 (contoh: 0, 0.25, 0.5, 0.75, 1, 1.25, ...).', 400);
      }
      if (hlS < hlD) throw createError_('Halaman sampai tidak boleh lebih kecil dari halaman dari.', 400);
      var maxHal = getJuzHalamanMax_(writable.juz);
      if (hlS > maxHal) throw createError_('Halaman sampai tidak boleh melebihi ' + maxHal + ' (Juz ' + (writable.juz || '?') + ').', 400);
    }
    writable.halaman_dari = hlDari;
    writable.halaman_sampai = hlSampai;
  } else if (isIqroHarian) {
    // Iqro' harian: halaman WAJIB bilangan bulat + boleh nyicil (tidak dianggap, catatan wajib).
    var ijilid = cleanString_(record.juz);
    var ijilidNum = parseInt(ijilid, 10);
    if (ijilid && (isNaN(ijilidNum) || ijilidNum < 1 || ijilidNum > 6)) {
      throw createError_("Jilid Iqro' harus 1–6.", 400);
    }
    writable.juz = ijilid;
    var cihlDari = cleanString_(record.halamanDari || record.halaman_dari);
    var cihlSampai = cleanString_(record.halamanSampai || record.halaman_sampai);
    if (!cihlDari || !cihlSampai) {
      throw createError_('Halaman dari dan halaman sampai wajib diisi keduanya.', 400);
    }
    var cihlD = parseFloat(cihlDari), cihlS = parseFloat(cihlSampai);
    if (isNaN(cihlD) || isNaN(cihlS) || !isWholeNumber_(cihlD) || !isWholeNumber_(cihlS)) {
      throw createError_('Halaman dari/sampai harus bilangan bulat (1, 2, 3, ...), tidak boleh pecahan.', 400);
    }
    if (cihlD < 1) throw createError_('Halaman dari minimal 1.', 400);
    if (cihlS < cihlD) throw createError_('Halaman sampai tidak boleh lebih kecil dari halaman dari.', 400);

    var iqroNyicilFlag = isTruthy_(record.nyicil);
    if (iqroNyicilFlag) {
      if (cihlD !== cihlS) throw createError_('Setoran nyicil harus dicatat di 1 halaman yang sama (halaman dari = halaman sampai).', 400);
      if (!cleanString_(record.catatan)) throw createError_('Catatan wajib diisi untuk setoran nyicil (mis. jumlah baris yang dibaca).', 400);
    }
    writable.halaman_dari = String(cihlD);
    writable.halaman_sampai = String(cihlS);
    writable.nyicil = iqroNyicilFlag ? '1' : '';
  } else if (kategori === 'iqro') {
    var jilid = cleanString_(record.juz);
    var jilidNum = parseInt(jilid, 10);
    if (jilid && (isNaN(jilidNum) || jilidNum < 1 || jilidNum > 6)) {
      throw createError_("Jilid Iqro' harus 1–6.", 400);
    }
    writable.juz = jilid;
    var ihlDari = cleanString_(record.halamanDari || record.halaman_dari);
    var ihlSampai = cleanString_(record.halamanSampai || record.halaman_sampai);
    var ihasHlDari = ihlDari !== '', ihasHlSampai = ihlSampai !== '';
    if (!ihasHlDari || !ihasHlSampai) {
      throw createError_('Halaman dari dan halaman sampai wajib diisi keduanya.', 400);
    }
    if (ihasHlDari && ihasHlSampai) {
      var ihlD = parseFloat(ihlDari), ihlS = parseFloat(ihlSampai);
      if (!isQuarterMultiple_(ihlD) || !isQuarterMultiple_(ihlS)) {
        throw createError_('Halaman dari/sampai harus kelipatan 0.25 (contoh: 0, 0.25, 0.5, 0.75, 1, 1.25, ...).', 400);
      }
      if (ihlS < ihlD) throw createError_('Halaman sampai tidak boleh lebih kecil dari halaman dari.', 400);
    }
    writable.halaman_dari = ihlDari;
    writable.halaman_sampai = ihlSampai;
  } else if (kategori === 'level' && jenis === 'mufrodat') {
    // Mufrodat harian: Level WAJIB dropdown 1-10, Jumlah dari/sampai WAJIB bulat 1-100.
    var mLevel = cleanString_(record.level || record.levelDari);
    var mLevelNum = parseInt(mLevel, 10);
    if (!mLevel || isNaN(mLevelNum) || !isWholeNumber_(parseFloat(mLevel)) || mLevelNum < 1 || mLevelNum > 10) {
      throw createError_('Level wajib dipilih, 1–10.', 400);
    }
    writable.level = String(mLevelNum);
    var mJmlDari = cleanString_(record.jumlah || record.jumlahDari);
    var mJmlSampai = cleanString_(record.jumlah_sampai || record.jumlahSampai);
    if (!mJmlDari || !mJmlSampai) throw createError_('Jumlah dari dan jumlah sampai wajib diisi keduanya.', 400);
    var mJmlD = parseInt(mJmlDari, 10), mJmlS = parseInt(mJmlSampai, 10);
    if (isNaN(mJmlD) || !isWholeNumber_(parseFloat(mJmlDari)) || mJmlD < 1 || mJmlD > 100) {
      throw createError_('Jumlah dari harus bilangan bulat 1–100.', 400);
    }
    if (isNaN(mJmlS) || !isWholeNumber_(parseFloat(mJmlSampai)) || mJmlS < 1 || mJmlS > 100) {
      throw createError_('Jumlah sampai harus bilangan bulat 1–100.', 400);
    }
    if (mJmlS < mJmlD) throw createError_('Jumlah sampai tidak boleh lebih kecil dari jumlah dari.', 400);
    writable.jumlah = String(mJmlD);
    writable.jumlah_sampai = String(mJmlS);
  } else if (kategori === 'level') {
    var lvDari = cleanString_(record.level || record.levelDari);
    if (lvDari !== '') {
      var lvNum = parseFloat(lvDari);
      if (isNaN(lvNum) || !isWholeNumber_(lvNum)) {
        throw createError_('Level harus bilangan bulat (1, 2, 3, ...), tidak boleh pecahan.', 400);
      }
    }
    writable.level = lvDari;
    var jmlDariRaw = cleanString_(record.jumlah || record.jumlahDari);
    var jmlSampaiRaw = cleanString_(record.jumlah_sampai || record.jumlahSampai);
    if (!isAwal && (!jmlDariRaw || !jmlSampaiRaw)) {
      throw createError_('Jumlah dari dan jumlah sampai wajib diisi keduanya.', 400);
    }
    if (jmlDariRaw !== '' || jmlSampaiRaw !== '') {
      var jmlD = parseInt(jmlDariRaw, 10), jmlS = parseInt(jmlSampaiRaw, 10);
      // "Jumlah dari" = 0 berarti posisi awal (belum ada kosakata dihafal sama sekali),
      // sama konsepnya dengan "Halaman dari" = 0 di Ziyadah/Sabaqi/dkk.
      if (isNaN(jmlD) || jmlD < 0) throw createError_('Jumlah dari minimal 0.', 400);
      if (jmlD > 100) throw createError_('Jumlah dari maksimal 100.', 400);
      if (isNaN(jmlS) || jmlS < 0) throw createError_('Jumlah sampai minimal 0.', 400);
      if (jmlS > 100) throw createError_('Jumlah sampai maksimal 100.', 400);
      if (jmlS < jmlD) throw createError_('Jumlah sampai tidak boleh lebih kecil dari jumlah dari.', 400);
      writable.jumlah = String(jmlD);
      writable.jumlah_sampai = String(jmlS);
    }
  } else if (kategori === 'nomor' && (jenis === 'hadits' || jenis === 'adzkar')) {
    // Hadits/Adzkar harian: nomor WAJIB bulat + boleh nyicil (tidak dianggap, catatan wajib).
    // Adzkar dibatasi maksimal 1-72.
    var hnDari = cleanString_(record.nomor || record.nomorDari);
    var hnSampai = cleanString_(record.nomorSampai || record.nomor_sampai);
    if (!hnDari || !hnSampai) throw createError_('Nomor dari dan nomor sampai wajib diisi keduanya.', 400);
    var hnD = parseFloat(hnDari), hnS = parseFloat(hnSampai);
    if (isNaN(hnD) || isNaN(hnS) || !isWholeNumber_(hnD) || !isWholeNumber_(hnS)) {
      throw createError_('Nomor dari/sampai harus bilangan bulat (1, 2, 3, ...), tidak boleh pecahan.', 400);
    }
    if (hnD < 1) throw createError_('Nomor dari minimal 1.', 400);
    if (hnS < hnD) throw createError_('Nomor sampai tidak boleh lebih kecil dari nomor dari.', 400);
    if (jenis === 'adzkar' && hnS > 72) throw createError_('Nomor sampai tidak boleh melebihi 72.', 400);

    var hadzkNyicilFlag = isTruthy_(record.nyicil);
    if (hadzkNyicilFlag) {
      if (hnD !== hnS) throw createError_('Setoran nyicil harus dicatat di 1 nomor yang sama (nomor dari = nomor sampai).', 400);
      if (!cleanString_(record.catatan)) throw createError_('Catatan wajib diisi untuk setoran nyicil.', 400);
    }
    writable.nomor = String(hnD);
    writable.nomor_sampai = String(hnS);
    writable.nyicil = hadzkNyicilFlag ? '1' : '';
  } else if (kategori === 'nomor') {
    var nmDari = cleanString_(record.nomor || record.nomorDari);
    var nmSampai = cleanString_(record.nomorSampai || record.nomor_sampai);
    if (!nmDari || !nmSampai) throw createError_('Nomor dari dan nomor sampai wajib diisi keduanya.', 400);
    var nmD = parseFloat(nmDari), nmS = parseFloat(nmSampai);
    if (isNaN(nmD) || isNaN(nmS)) throw createError_('Nomor dari dan nomor sampai harus berupa angka.', 400);
    if (!isWholeNumber_(nmD) || !isWholeNumber_(nmS)) {
      throw createError_('Nomor dari/sampai harus bilangan bulat (1, 2, 3, ...), tidak boleh pecahan.', 400);
    }
    if (nmS < nmD) throw createError_('Nomor sampai tidak boleh lebih kecil dari nomor dari.', 400);
    writable.nomor = nmDari;
    writable.nomor_sampai = nmSampai;
  } else if (kategori === 'catatan') {
    if (!cleanString_(record.catatan)) throw createError_('Catatan/alasan wajib diisi.', 400);
  }

  if (existing) {
    updateSheetRow_(state, existing._rowNumber, writable);
    return {
      ok: true,
      timestamp: nowIso_(),
      data: { id: requestedId, message: 'Data hafalan berhasil diperbarui.' }
    };
  }

  writable.id = String(nextId_(state.rows));
  writable.created_at = nowIso_();
  appendSheetRow_(state, writable);
  return {
    ok: true,
    timestamp: nowIso_(),
    data: { id: writable.id, message: 'Data hafalan berhasil ditambahkan.' }
  };
}

function handleHafalanHarianDelete_(request, session) {
  var record = parseRecordPayload_(request);
  var id = cleanString_(record.id);
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('hafalanHarian');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data hafalan tidak ditemukan.', 404);

  var perms = session && session.permissions;
  if (!(perms && (perms.isSuperAdmin || perms.isAdmin || perms.isHalaqohCoordinator))) {
    var dataset = loadDataset_();
    var accessible = getAccessibleHafalanHalaqoh_(session, dataset);
    var accessibleIdSet = {};
    accessible.forEach(function (h) { accessibleIdSet[h.id] = true; });
    if (!accessibleIdSet[cleanString_(existing.id_halaqoh)]) {
      throw createError_('Anda hanya bisa menghapus data hafalan di halaqoh yang Anda ampu.', 403);
    }
  }

  deleteSheetRows_(state, [existing._rowNumber]);
  return {
    ok: true,
    timestamp: nowIso_(),
    data: { id: id, message: 'Data hafalan berhasil dihapus.' }
  };
}

function handleHafalanHarianHapusSemua_(request, session) {
  requireSuperAdmin_(session);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var result;
  if (tahunAjaranId) {
    result = DB.prepare('DELETE FROM hafalanHarian WHERE tahun_ajaran_id = ?').run(tahunAjaranId);
  } else {
    result = DB.prepare('DELETE FROM hafalanHarian').run();
  }
  var msg = tahunAjaranId
    ? 'Data hafalan harian untuk TA tersebut berhasil dihapus.'
    : 'Semua data hafalan harian berhasil dihapus.';
  return { ok: true, timestamp: nowIso_(), data: { deleted: result.changes, message: msg } };
}

/* ── Ujian Hafalan ── */
function canAccessUjianHafalan_(session) {
  if (!session || session.role !== 'pengurus' || !session.permissions) return false;
  return canAccessLevel_(session, 'misiTahfizh', 'manage', function (s) {
    var p = s.permissions;
    return !!(p.isAdmin || p.isHalaqohCoordinator || p.isPengampuHalaqoh || p.isPengujiHafalan);
  });
}

function canGradeUjianHafalan_(session) {
  if (!session || !session.permissions) return false;
  var p = session.permissions;
  return !!(p.isSuperAdmin || p.isAdmin || p.isHalaqohCoordinator || p.isPengujiHafalan);
}

var UJIAN_ADZKAR_KATEGORI_LABELS = {
  bacaan_sholat: 'Bacaan Sholat',
  bacaan_setelah_sholat: 'Bacaan Setelah Sholat',
  dzikir_pagi: 'Dzikir Pagi',
  dzikir_petang: 'Dzikir Petang'
};

// Label materi ujian per tipe: juziyyah/sertifikasi/uas pakai Juz, mufrodat pakai Level (1-10),
// adzkar pakai nama kategori tetap (bukan angka).
function buildUjianMateriLabel_(tipe, juzMulaiRaw, juzAkhirRaw) {
  if (tipe === 'mufrodat') {
    return 'Level ' + (parseInt(juzMulaiRaw) || 0);
  }
  if (tipe === 'adzkar') {
    var kategori = cleanString_(juzMulaiRaw);
    return UJIAN_ADZKAR_KATEGORI_LABELS[kategori] || kategori || '-';
  }
  var jm = parseInt(juzMulaiRaw) || 0;
  var ja = parseInt(juzAkhirRaw) || jm;
  return (tipe === 'juziyyah' || jm === ja) ? 'Juz ' + jm : 'Juz ' + jm + '–' + ja;
}

function getAccessibleUjianHalaqoh_(session, dataset) {
  if (!session || !session.permissions) return [];
  var p = session.permissions;
  var allHalaqoh = (dataset.halaqoh || []).filter(function(h) { return h.active; });
  if (p.isSuperAdmin || p.isAdmin || p.isHalaqohCoordinator || p.isPengujiHafalan) {
    return allHalaqoh;
  }
  return getAccessibleHalaqohAttendanceItems_(session, dataset);
}

function normalizeUjianHafalan_(row) {
  var status = normalizeStatusForSheet_('ujianHafalan', row.status || STATUS_LABELS.ujianHafalan.active);
  return {
    id: cleanString_(row.id),
    tipe: cleanString_(row.tipe),
    halaqohId: cleanString_(row.id_halaqoh),
    santriId: cleanString_(row.id_santri),
    pengampuId: cleanString_(row.id_pengampu),
    pengujiId: cleanString_(row.id_penguji),
    namaPenguji: cleanString_(row.nama_penguji),
    tahunAjaranId: cleanString_(row.id_tahun_ajaran),
    tanggalDaftar: normalizeDateOnly_(row.tanggal_daftar),
    tanggalMulaiPersiapan: normalizeDateOnly_(row.tanggal_mulai_persiapan),
    tanggalSiap: normalizeDateOnly_(row.tanggal_siap),
    tanggalUjian: normalizeDateOnly_(row.tanggal_ujian),
    juzMulai: cleanString_(row.juz_mulai),
    juzAkhir: cleanString_(row.juz_akhir),
    nilaiPerJuz: cleanString_(row.nilai_per_juz),
    nilai: cleanString_(row.nilai),
    lulus: cleanString_(row.lulus),
    tahap: cleanString_(row.tahap) || 'diajukan',
    catatan: cleanString_(row.catatan),
    status: status,
    active: isActiveStatus_(status),
    record: clonePlainObject_(row)
  };
}

function handleUjianHafalanList_(request, session) {
  var dataset = loadDataset_();
  var accessible = getAccessibleUjianHalaqoh_(session, dataset);
  var accessibleIdSet = {};
  accessible.forEach(function(h) { accessibleIdSet[h.id] = true; });

  var halaqohId = cleanString_(request.halaqohId);
  var tipe = cleanString_(request.tipe);
  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var tahap = cleanString_(request.tahap);
  var genderFilter = cleanString_(request.genderFilter).toLowerCase();
  var search = cleanString_(request.search).toLowerCase();
  var page = Math.max(1, toInt_(request.page, 1));
  var pageSize = clamp_(toInt_(request.pageSize, 10), 1, 100);

  var ujianState = readSheetState_('ujianHafalan');
  var allUjian = ujianState.rows.map(normalizeUjianHafalan_).filter(function(u) {
    if (!u.active) return false;
    if (!accessibleIdSet[u.halaqohId]) return false;
    // Strict filter: bila tahunAjaranId dipilih, hanya record yang persis cocok
    // yang ditampilkan (record tanpa tahun ajaran dikecualikan saat filter aktif,
    // namun tetap muncul saat filter "Semua tahun ajaran" dipilih).
    if (tahunAjaranId && u.tahunAjaranId !== tahunAjaranId) return false;
    return true;
  });

  // Detailed ujian list for one halaqoh + tipe
  if (halaqohId && tipe) {
    var halaqoh = accessible.filter(function(h) { return h.id === halaqohId; })[0] || null;
    if (!halaqoh) throw createError_('Halaqoh tidak ditemukan.', 404);
    var items = allUjian.filter(function(u) {
      return u.halaqohId === halaqohId && u.tipe === tipe;
    });
    // "Semua" (tahap kosong) = semua kecuali yg dibatalkan. Pilih tahap "batal" secara eksplisit
    // kalau memang mau lihat yg dibatalkan.
    if (tahap) {
      var tahapSet = tahap.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
      items = items.filter(function(u) { return tahapSet.indexOf(u.tahap) !== -1; });
    } else {
      items = items.filter(function(u) { return u.tahap !== 'batal'; });
    }
    items.sort(function(a, b) { return (b.tanggalDaftar || '').localeCompare(a.tanggalDaftar || ''); });
    var itemsPage = paginate_(items, page, pageSize);
    var enriched = itemsPage.items.map(function(u) {
      var santri = dataset.indexes.santriById[u.santriId];
      var pengampu = dataset.indexes.pengurusById ? dataset.indexes.pengurusById[u.pengampuId] : null;
      var penguji = dataset.indexes.pengurusById ? dataset.indexes.pengurusById[u.pengujiId] : null;
      var juzLabel = buildUjianMateriLabel_(u.tipe, u.juzMulai, u.juzAkhir);
      return {
        id: u.id, tipe: u.tipe, santriId: u.santriId,
        santriName: santri ? cleanString_(santri.name) : u.santriId,
        santriGender: santri ? normalizeSantriGender_(santri.jenisKelamin || santri.gender) : '',
        juzMulai: u.juzMulai, juzAkhir: u.juzAkhir, juzLabel: juzLabel,
        tanggalDaftar: u.tanggalDaftar,
        tanggalMulaiPersiapan: u.tanggalMulaiPersiapan,
        tanggalSiap: u.tanggalSiap, tanggalUjian: u.tanggalUjian,
        nilai: u.nilai, nilaiPerJuz: u.nilaiPerJuz,
        lulus: u.lulus, tahap: u.tahap, catatan: u.catatan,
        pengampuId: u.pengampuId,
        pengampuName: pengampu ? cleanString_(pengampu.name) : u.pengampuId,
        pengujiId: u.pengujiId,
        // Penguji sekarang teks bebas (nama_penguji), diisi manual saat menilai — bukan lagi rujukan id_penguji.
        // Fallback ke lookup id_penguji lama utk data lama yang belum punya nama_penguji.
        pengujiName: u.namaPenguji || (penguji ? cleanString_(penguji.name) : u.pengujiId),
        record: u.record
      };
    });
    var santriList = (halaqoh.santriIds || []).map(function(sid) {
      var s = dataset.indexes.santriById[sid];
      return { id: sid, name: s ? cleanString_(s.name) : sid };
    });
    return { ok: true, timestamp: nowIso_(), data: {
      items: enriched,
      halaqoh: { id: halaqoh.id, name: cleanString_(halaqoh.name), santriList: santriList },
      isPenguji: canGradeUjianHafalan_(session),
      page: itemsPage.page, pageSize: itemsPage.pageSize, total: itemsPage.total, totalPages: itemsPage.totalPages
    }};
  }

  // Queue mode: flat enriched list for penguji
  if (cleanString_(request.listMode) === 'queue') {
    var queueItems = allUjian;
    if (tipe) queueItems = queueItems.filter(function(u) { return u.tipe === tipe; });

    // Tahap filter — bisa gabungan beberapa tahap sekaligus (dipisah koma), mis. default
    // "diajukan,dijadwalkan". "Semua Tahap" (kosong) = semua kecuali yg dibatalkan; kirim
    // "batal" eksplisit kalau memang mau lihat yg dibatalkan.
    var queueTahap = cleanString_(request.tahap);
    if (queueTahap) {
      var tahapSet = queueTahap.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
      queueItems = queueItems.filter(function(u) { return tahapSet.indexOf(u.tahap) !== -1; });
    } else {
      queueItems = queueItems.filter(function(u) { return u.tahap !== 'batal'; });
    }

    var halaqohMap = {};
    accessible.forEach(function(h) { halaqohMap[h.id] = h; });

    // Gender filter — pakai gender santri (bukan gender halaqoh) supaya akurat juga utk halaqoh campur
    var wantGender = genderFilter === 'ikhwan' ? 'male' : genderFilter === 'akhowat' ? 'female' : '';
    if (wantGender) {
      queueItems = queueItems.filter(function(u) {
        var s = dataset.indexes.santriById[u.santriId];
        var g = s ? normalizeSantriGender_(s.jenisKelamin || s.gender) : '';
        return g === wantGender;
      });
    }

    // Cari berdasarkan nama santri atau nama halaqoh
    if (search) {
      queueItems = queueItems.filter(function(u) {
        var s = dataset.indexes.santriById[u.santriId];
        var hq = halaqohMap[u.halaqohId];
        var santriName = s ? cleanString_(s.name).toLowerCase() : '';
        var halaqohName = hq ? cleanString_(hq.name).toLowerCase() : '';
        return santriName.indexOf(search) !== -1 || halaqohName.indexOf(search) !== -1;
      });
    }

    // Urutkan: default "siap" (tanggal siap diuji), atau "daftar"/"ujian"
    var queueSort = cleanString_(request.sort);
    var sortField = queueSort === 'daftar' ? 'tanggalDaftar' : queueSort === 'ujian' ? 'tanggalUjian' : 'tanggalSiap';
    queueItems = queueItems.slice().sort(function(a, b) {
      return (a[sortField] || '').localeCompare(b[sortField] || '');
    });

    var queuePage = paginate_(queueItems, page, pageSize);
    var enrichedQueue = queuePage.items.map(function(u) {
      var santri = dataset.indexes.santriById[u.santriId];
      var hq = halaqohMap[u.halaqohId];
      var penguji = dataset.indexes.pengurusById ? dataset.indexes.pengurusById[u.pengujiId] : null;
      var pengampuNames = (hq && hq.pengampuIds || []).slice(0, 3).map(function(id) {
        var p = dataset.indexes.pengurusById ? dataset.indexes.pengurusById[id] : null;
        return p ? cleanString_(p.name) : '';
      }).filter(Boolean);
      var juzLabel = buildUjianMateriLabel_(u.tipe, u.juzMulai, u.juzAkhir);
      return {
        id: u.id, tipe: u.tipe,
        santriId: u.santriId, santriName: santri ? cleanString_(santri.name) : u.santriId,
        santriGender: santri ? normalizeSantriGender_(santri.jenisKelamin || santri.gender) : '',
        halaqohId: u.halaqohId, halaqohName: hq ? cleanString_(hq.name) : u.halaqohId,
        halaqohGender: hq ? cleanString_(hq.genderGroup) : '',
        pengampuNames: pengampuNames,
        juzMulai: u.juzMulai, juzAkhir: u.juzAkhir, juzLabel: juzLabel,
        tanggalDaftar: u.tanggalDaftar,
        tanggalMulaiPersiapan: u.tanggalMulaiPersiapan,
        tanggalSiap: u.tanggalSiap, tanggalUjian: u.tanggalUjian,
        nilai: u.nilai, nilaiPerJuz: u.nilaiPerJuz,
        lulus: u.lulus, tahap: u.tahap, catatan: u.catatan,
        pengampuId: u.pengampuId, pengujiId: u.pengujiId,
        pengujiName: u.namaPenguji || (penguji ? cleanString_(penguji.name) : (u.pengujiId ? u.pengujiId : '')),
        record: u.record
      };
    });
    return { ok: true, timestamp: nowIso_(), data: {
      items: enrichedQueue,
      isPenguji: canGradeUjianHafalan_(session),
      page: queuePage.page, pageSize: queuePage.pageSize, total: queuePage.total, totalPages: queuePage.totalPages
    }};
  }

  // Summary list (halaqoh cards with counts) — filter by tipe if provided
  var summaryUjian = tipe ? allUjian.filter(function(u) { return u.tipe === tipe; }) : allUjian;
  var countsByHalaqoh = {};
  summaryUjian.forEach(function(u) {
    var hid = u.halaqohId;
    if (!countsByHalaqoh[hid]) {
      countsByHalaqoh[hid] = { diajukan: 0, dijadwalkan: 0, selesai: 0 };
    }
    var st = u.tahap;
    if (st === 'diajukan' || st === 'dijadwalkan') {
      countsByHalaqoh[hid][st]++;
    } else if (UJIAN_SELESAI_TAHAP_[st]) {
      countsByHalaqoh[hid].selesai++;
    }
  });
  // Filter halaqoh sesuai tahun ajaran, gender, dan pencarian nama — tiru pola nilaiUas
  // (halaqoh terikat ke tahun ajaran tertentu, jadi daftar kartu juga harus terfilter).
  var filteredHalaqoh = accessible.filter(function(h) {
    if (tahunAjaranId && cleanString_(h.tahunAjaranId) !== tahunAjaranId) return false;
    if (genderFilter && cleanString_(h.genderGroup).toLowerCase().indexOf(genderFilter) === -1) return false;
    if (search && cleanString_(h.name).toLowerCase().indexOf(search) === -1) return false;
    return true;
  });
  var cardsPage = paginate_(filteredHalaqoh, page, pageSize);
  var halaqohList = cardsPage.items.map(function(h) {
    var pengampuNames = (h.pengampuIds || []).map(function(id) {
      var p = dataset.indexes.pengurusById ? dataset.indexes.pengurusById[id] : null;
      return p ? cleanString_(p.name) : '';
    }).filter(Boolean);
    return {
      id: h.id, name: cleanString_(h.name),
      genderGroup: cleanString_(h.genderGroup),
      santriCount: (h.santriIds || []).length,
      active: h.active,
      pengampuNames: pengampuNames,
      counts: countsByHalaqoh[h.id] || { diajukan: 0, dijadwalkan: 0, selesai: 0 }
    };
  });
  var tahunAjaranList = (dataset.tahunAjaran || []).map(normalizeTahunAjaranSafe_).map(function(t) {
    return { id: t.id, name: t.namaDisplay || t.nama, isAktif: !!t.isAktif };
  });
  return { ok: true, timestamp: nowIso_(), data: {
    halaqohList: halaqohList,
    tahunAjaranList: tahunAjaranList,
    isPenguji: canGradeUjianHafalan_(session),
    page: cardsPage.page, pageSize: cardsPage.pageSize, total: cardsPage.total, totalPages: cardsPage.totalPages
  }};
}

// Status tahap "selesai" lama (+ field kelulusan terpisah) digantikan tahap Lulus/Tidak Lulus
// (Ziyadah Ulang)/Mengulang langsung -- field "Kelulusan" dinonaktifkan di form, tapi data lama
// dgn tahap "selesai" tetap didukung apa adanya (tidak dimigrasi).
var UJIAN_TAHAP_LULUS_MAP_ = { lulus: '1', tidak_lulus: '0', mengulang: '2' };
var UJIAN_VALID_TAHAP_ = { diajukan: true, dijadwalkan: true, selesai: true, batal: true, lulus: true, tidak_lulus: true, mengulang: true };
var UJIAN_SELESAI_TAHAP_ = { selesai: true, lulus: true, tidak_lulus: true, mengulang: true };
var KKM_UJIAN_HAFALAN_ = 70; // Nilai di bawah ini tidak boleh dinyatakan Lulus.

function handleUjianHafalanSave_(request, session) {
  var dataset = loadDataset_();
  var accessible = getAccessibleUjianHalaqoh_(session, dataset);
  var record = parseRecordPayload_(request);
  var halaqohId = cleanString_(record.halaqohId || record.id_halaqoh);
  var santriId = cleanString_(record.santriId || record.id_santri);
  var tipe = cleanString_(record.tipe);
  var isPenguji = canGradeUjianHafalan_(session);

  var halaqoh = accessible.filter(function(h) { return h.id === halaqohId; })[0] || null;
  if (!halaqoh) throw createError_('Halaqoh tidak ditemukan atau tidak dapat diakses.', 404);
  var validTipe = { juziyyah: true, sertifikasi: true, uas: true, mufrodat: true, adzkar: true };
  if (!validTipe[tipe]) throw createError_('Tipe ujian tidak valid.', 400);

  var juzMulai, juzAkhir;
  if (tipe === 'mufrodat') {
    var level = parseInt(cleanString_(record.juzMulai)) || 0;
    if (level < 1 || level > 10) throw createError_('Level mufrodat harus antara 1–10.', 400);
    juzMulai = level;
    juzAkhir = level;
  } else if (tipe === 'adzkar') {
    var kategori = cleanString_(record.juzMulai);
    if (!UJIAN_ADZKAR_KATEGORI_LABELS[kategori]) throw createError_('Kategori adzkar tidak valid.', 400);
    juzMulai = kategori;
    juzAkhir = kategori;
  } else {
    juzMulai = parseInt(cleanString_(record.juzMulai)) || 0;
    juzAkhir = parseInt(cleanString_(record.juzAkhir)) || juzMulai;
    if (juzMulai < 1 || juzMulai > 30) throw createError_('Juz mulai harus antara 1–30.', 400);
    if (juzAkhir < juzMulai || juzAkhir > 30) throw createError_('Juz akhir tidak valid.', 400);
  }

  var ujianState = readSheetState_('ujianHafalan');
  var requestedId = cleanString_(record.id);
  var existing = requestedId ? findSheetRowById_(ujianState.rows, requestedId) : null;
  if (requestedId && !existing) throw createError_('Data ujian tidak ditemukan.', 404);

  var now = nowIso_();
  var writable = {
    tipe: tipe,
    id_halaqoh: halaqohId,
    id_santri: santriId,
    id_pengampu: existing ? cleanString_(existing.id_pengampu) : cleanString_(session.id),
    id_tahun_ajaran: cleanString_(record.tahunAjaranId || record.id_tahun_ajaran),
    tanggal_daftar: existing ? cleanString_(existing.tanggal_daftar) : normalizeDateOnly_(now),
    tanggal_mulai_persiapan: record.tanggalMulaiPersiapan ? assertValidDateOnly_(record.tanggalMulaiPersiapan, 'Tanggal mulai persiapan') : '',
    tanggal_siap: record.tanggalSiap ? assertValidDateOnly_(record.tanggalSiap, 'Tanggal siap') : '',
    juz_mulai: String(juzMulai),
    juz_akhir: String(juzAkhir),
    catatan: cleanString_(record.catatan),
    status: STATUS_LABELS.ujianHafalan.active,
    updated_at: now
  };

  if (isPenguji) {
    // Penguji sekarang teks bebas yg diketik manual (autofill nama yg login, tapi bisa diedit) —
    // bukan lagi id_penguji yg dikunci ke akun yg login.
    writable.nama_penguji = cleanString_(record.namaPenguji) || cleanString_(session.name);
    writable.tanggal_ujian = record.tanggalUjian ? assertValidDateOnly_(record.tanggalUjian, 'Tanggal ujian') : '';
    writable.nilai = cleanString_(record.nilai);
    writable.nilai_per_juz = cleanString_(record.nilaiPerJuz);
    var tahap = cleanString_(record.tahap);
    writable.tahap = UJIAN_VALID_TAHAP_[tahap]
      ? tahap : (existing ? cleanString_(existing.tahap) || 'diajukan' : 'diajukan');

    // "Diajukan"/"Batal" belum butuh data penilaian — begitu tahap dimajukan (dijadwalkan dst.)
    // tanggal ujian & nama penguji wajib ada. Utk tahap yang sudah "selesai" (lulus/tidak_lulus/
    // mengulang/selesai lama), nilai wajib diisi & tidak boleh dinyatakan Lulus di bawah KKM.
    var tahapButuhPenilaian = writable.tahap !== 'diajukan' && writable.tahap !== 'batal';
    if (tahapButuhPenilaian) {
      if (!writable.nama_penguji) throw createError_('Nama penguji wajib diisi.', 400);
      if (!writable.tanggal_ujian) throw createError_('Tanggal ujian wajib diisi.', 400);
    }
    if (UJIAN_SELESAI_TAHAP_[writable.tahap] && tipe !== 'uas') {
      if (writable.nilai === '') throw createError_('Nilai wajib diisi kalau status tahap sudah dinyatakan selesai/lulus/tidak lulus/mengulang.', 400);
      var nilaiNum_ = parseFloat(writable.nilai);
      if (isNaN(nilaiNum_) || nilaiNum_ < 0 || nilaiNum_ > 100) throw createError_('Nilai harus berupa angka antara 0-100.', 400);
      if (writable.tahap === 'lulus' && nilaiNum_ < KKM_UJIAN_HAFALAN_) {
        throw createError_('Nilai ' + nilaiNum_ + ' di bawah KKM (' + KKM_UJIAN_HAFALAN_ + ') — tidak bisa dinyatakan Lulus. Pilih status Tidak Lulus (Ziyadah Ulang) atau Mengulang.', 400);
      }
    }

    // Field "Kelulusan" dinonaktifkan di form -- untuk tahap baru (lulus/tidak_lulus/mengulang)
    // nilainya diturunkan langsung dari tahap, bukan dari input kelulusan terpisah.
    writable.lulus = UJIAN_TAHAP_LULUS_MAP_[writable.tahap] || cleanString_(record.lulus);
  } else {
    writable.tahap = existing ? cleanString_(existing.tahap) || 'diajukan' : 'diajukan';
  }

  if (existing) {
    updateSheetRow_(ujianState, existing._rowNumber, writable);
    return { ok: true, timestamp: now, data: { id: requestedId, message: 'Data ujian berhasil diperbarui.' } };
  }
  writable.id = String(nextId_(ujianState.rows));
  writable.created_at = now;
  appendSheetRow_(ujianState, writable);
  return { ok: true, timestamp: now, data: { id: writable.id, message: 'Data ujian berhasil ditambahkan.' } };
}

function handleUjianHafalanDelete_(request, session) {
  var record = parseRecordPayload_(request);
  var id = cleanString_(record.id);
  if (!id) throw createError_('ID wajib diisi.', 400);
  var ujianState = readSheetState_('ujianHafalan');
  var existing = findSheetRowById_(ujianState.rows, id);
  if (!existing) throw createError_('Data ujian tidak ditemukan.', 404);
  deleteSheetRows_(ujianState, [existing._rowNumber]);
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: 'Data ujian berhasil dihapus.' } };
}

function handleUjianHafalanSetStatus_(request, session) {
  if (!canGradeUjianHafalan_(session)) throw createError_('Tidak punya izin untuk mengubah status ujian.', 403);
  var record = parseRecordPayload_(request);
  var id = cleanString_(record.id);
  if (!id) throw createError_('ID wajib diisi.', 400);
  var ujianState = readSheetState_('ujianHafalan');
  var existing = findSheetRowById_(ujianState.rows, id);
  if (!existing) throw createError_('Data ujian tidak ditemukan.', 404);
  var tahap = cleanString_(record.tahap);
  if (!UJIAN_VALID_TAHAP_[tahap]) throw createError_('Tahap tidak valid.', 400);
  var writable = { tahap: tahap, updated_at: nowIso_() };
  if (tahap === 'dijadwalkan') {
    writable.tanggal_ujian = record.tanggalUjian ? assertValidDateOnly_(record.tanggalUjian, 'Tanggal ujian') : '';
    writable.nama_penguji = cleanString_(record.namaPenguji) || cleanString_(session.name);
  }
  if (UJIAN_SELESAI_TAHAP_[tahap]) {
    writable.nilai = cleanString_(record.nilai);
    writable.nilai_per_juz = cleanString_(record.nilaiPerJuz);
    writable.lulus = UJIAN_TAHAP_LULUS_MAP_[tahap] || cleanString_(record.lulus);
    writable.tanggal_ujian = record.tanggalUjian ? assertValidDateOnly_(record.tanggalUjian, 'Tanggal ujian') : cleanString_(existing.tanggal_ujian);
    writable.nama_penguji = cleanString_(record.namaPenguji) || cleanString_(session.name);
  }
  updateSheetRow_(ujianState, existing._rowNumber, writable);
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: 'Status ujian berhasil diperbarui.' } };
}

function parseUjianHafalanTempelText_(text) {
  var blocks = text.split(/\n[ \t]*\n/);
  var entries = [];
  blocks.forEach(function (block) {
    block = block.trim();
    if (!block) return;
    var lines = block.split('\n');
    var entry = {};
    lines.forEach(function (line) {
      var colonIdx = line.indexOf(':');
      if (colonIdx < 1) return;
      var key = line.slice(0, colonIdx).trim().toUpperCase().replace(/[\s-]+/g, '_');
      var val = line.slice(colonIdx + 1).trim();
      entry[key] = val;
    });
    if (entry['SANTRI']) entries.push(entry);
  });
  return entries;
}

function handleUjianHafalanDeleteAll_(request, session) {
  requireSuperAdmin_(session);
  var record = parseRecordPayload_(request);
  var tipe = cleanString_(record.tipe);
  var tahunAjaranId = cleanString_(record.tahunAjaranId);
  var deleteAllValidTipe = { juziyyah: true, sertifikasi: true, mufrodat: true, adzkar: true };
  if (!deleteAllValidTipe[tipe]) throw createError_('Tipe ujian tidak valid.', 400);
  var ujianState = readSheetState_('ujianHafalan');
  var toDelete = [];
  ujianState.rows.forEach(function (row) {
    var u = normalizeUjianHafalan_(row);
    if (!u.active) return;
    if (u.tipe !== tipe) return;
    if (tahunAjaranId && u.tahunAjaranId !== tahunAjaranId) return;
    toDelete.push(row._rowNumber);
  });
  if (toDelete.length) deleteSheetRows_(ujianState, toDelete);
  return { ok: true, timestamp: nowIso_(), data: { deleted: toDelete.length, message: toDelete.length + ' data ujian berhasil dihapus.' } };
}

function handleUjianHafalanQuickImportPreview_(request, session) {
  requireAdminOrSuperAdmin_(session);
  var record = parseRecordPayload_(request);
  var text = String(record.text || '').trim();
  if (!text) throw createError_('Teks tempelan kosong.', 400);
  var dataset = loadDataset_();
  var entries = parseUjianHafalanTempelText_(text);
  if (!entries.length) throw createError_('Tidak ada record yang bisa diparsing. Pastikan format benar (tiap record diawali SANTRI:).', 400);

  var santriByName = {};
  (dataset.santri || []).forEach(function (s) {
    var norm = normalizeSantri_(s);
    if (!norm.active) return;
    var key = (norm.name || '').toLowerCase().trim();
    if (key) santriByName[key] = norm;
  });

  var halaqohByName = {};
  (dataset.halaqoh || []).forEach(function (h) {
    if (!h.active) return;
    var key = cleanString_(h.name || '').toLowerCase().trim();
    if (key) halaqohByName[key] = h;
  });

  var tahunByName = {};
  var tahunAktif = null;
  (dataset.tahunAjaran || []).forEach(function (t) {
    var norm = normalizeTahunAjaran_(t);
    var key = (norm.namaDisplay || norm.nama || '').toLowerCase().trim();
    if (key) tahunByName[key] = norm;
    if (norm.isAktif) tahunAktif = norm;
  });

  var validTahap = { diajukan: true, dijadwalkan: true, selesai: true, batal: true };

  var previews = entries.map(function (entry, idx) {
    var warnings = [], errors = [];
    var santriName = entry['SANTRI'] || '';
    var santri = santriByName[santriName.toLowerCase().trim()];
    if (!santri) errors.push('Santri "' + santriName + '" tidak ditemukan.');
    var halaqohName = entry['HALAQOH'] || '';
    var halaqoh = halaqohByName[halaqohName.toLowerCase().trim()];
    if (!halaqoh) errors.push('Halaqoh "' + halaqohName + '" tidak ditemukan.');
    var tipe = (entry['TIPE'] || '').toLowerCase().trim();
    if (tipe !== 'juziyyah' && tipe !== 'sertifikasi') errors.push('TIPE tidak valid (harus juziyyah atau sertifikasi).');
    var juzMulai, juzAkhir;
    if (tipe === 'juziyyah') {
      juzMulai = juzAkhir = parseInt(entry['JUZ'] || entry['JUZ_MULAI'] || '0') || 0;
    } else {
      juzMulai = parseInt(entry['JUZ_MULAI'] || '0') || 0;
      juzAkhir = parseInt(entry['JUZ_AKHIR'] || entry['JUZ_MULAI'] || '0') || 0;
    }
    if (juzMulai < 1 || juzMulai > 30) errors.push('JUZ tidak valid (harus 1–30).');
    var tahunNama = entry['TAHUN_AJARAN'] || '';
    var tahun = tahunNama ? (tahunByName[tahunNama.toLowerCase().trim()] || null) : tahunAktif;
    if (!tahun) warnings.push('Tahun ajaran tidak ditemukan, akan pakai tahun ajaran aktif.');
    var tahap = (entry['TAHAP'] || 'diajukan').toLowerCase().trim();
    if (!validTahap[tahap]) { warnings.push('TAHAP tidak dikenal, default ke "diajukan".'); tahap = 'diajukan'; }
    return {
      index: idx + 1,
      santriName: santriName, santriId: santri ? santri.id : null,
      halaqohName: halaqohName, halaqohId: halaqoh ? cleanString_(halaqoh.id) : null,
      tipe: tipe, juzMulai: juzMulai, juzAkhir: juzAkhir,
      tahunAjaranId: tahun ? tahun.id : null,
      tanggalMulai: entry['TANGGAL_MULAI'] || '',
      tanggalSiap: entry['TANGGAL_SIAP'] || '',
      tahap: tahap, catatan: entry['CATATAN'] || '',
      warnings: warnings, errors: errors,
      canSave: errors.length === 0
    };
  });
  return { ok: true, timestamp: nowIso_(), data: { previews: previews } };
}

function handleUjianHafalanQuickImport_(request, session) {
  requireAdminOrSuperAdmin_(session);
  var record = parseRecordPayload_(request);
  var entries = Array.isArray(record.entries) ? record.entries : [];
  if (!entries.length) throw createError_('Tidak ada data untuk disimpan.', 400);
  var ujianState = readSheetState_('ujianHafalan');
  var now = nowIso_();
  var saved = 0;
  entries.forEach(function (e) {
    if (!e.santriId || !e.halaqohId || !e.tipe || !e.juzMulai) return;
    var juzMulai = parseInt(e.juzMulai);
    var juzAkhir = parseInt(e.juzAkhir) || juzMulai;
    var writable = {
      id: String(nextId_(ujianState.rows)),
      tipe: e.tipe,
      id_halaqoh: e.halaqohId,
      id_santri: e.santriId,
      id_pengampu: cleanString_(session.id),
      id_penguji: '',
      id_tahun_ajaran: e.tahunAjaranId || '',
      tanggal_daftar: normalizeDateOnly_(now),
      tanggal_mulai_persiapan: e.tanggalMulai ? assertValidDateOnly_(e.tanggalMulai, 'Tanggal mulai persiapan') : '',
      tanggal_siap: e.tanggalSiap ? assertValidDateOnly_(e.tanggalSiap, 'Tanggal siap') : '',
      tanggal_ujian: '',
      juz_mulai: String(juzMulai),
      juz_akhir: String(juzAkhir),
      nilai_per_juz: '', nilai: '', lulus: '',
      tahap: e.tahap || 'diajukan',
      catatan: cleanString_(e.catatan),
      status: STATUS_LABELS.ujianHafalan.active,
      created_at: now, updated_at: now
    };
    appendSheetRow_(ujianState, writable);
    saved++;
  });
  return { ok: true, timestamp: now, data: { saved: saved, message: saved + ' data ujian berhasil ditempel.' } };
}

function handleUjianHafalanQuickImportExport_(request, session) {
  requireAdminOrSuperAdmin_(session);
  var record = parseRecordPayload_(request);
  var dataset = loadDataset_();
  var ujianState = readSheetState_('ujianHafalan');
  var santriMap = dataset.indexes.santriById;
  var halaqohMap = dataset.indexes.halaqohById;
  var tahunMap = {};
  (dataset.tahunAjaran || []).forEach(function (t) {
    var norm = normalizeTahunAjaran_(t);
    tahunMap[norm.id] = norm;
  });
  var filterTahunAjaranId = cleanString_(record.tahunAjaranId);
  var blocks = [];
  ujianState.rows.forEach(function (row) {
    var u = normalizeUjianHafalan_(row);
    if (!u.active) return;
    if (filterTahunAjaranId && u.tahunAjaranId !== filterTahunAjaranId) return;
    var santri = santriMap[u.santriId];
    var halaqoh = halaqohMap[u.halaqohId];
    if (!santri || !halaqoh) return;
    var tahun = tahunMap[u.tahunAjaranId];
    var lines = [];
    lines.push('SANTRI: ' + (santri.name || ''));
    lines.push('HALAQOH: ' + cleanString_(halaqoh.name || ''));
    lines.push('TIPE: ' + u.tipe);
    if (u.tipe === 'juziyyah') {
      lines.push('JUZ: ' + u.juzMulai);
    } else {
      lines.push('JUZ_MULAI: ' + u.juzMulai);
      lines.push('JUZ_AKHIR: ' + u.juzAkhir);
    }
    if (tahun) lines.push('TAHUN_AJARAN: ' + (tahun.namaDisplay || tahun.nama || ''));
    if (u.tanggalMulaiPersiapan) lines.push('TANGGAL_MULAI: ' + u.tanggalMulaiPersiapan);
    if (u.tanggalSiap) lines.push('TANGGAL_SIAP: ' + u.tanggalSiap);
    lines.push('TAHAP: ' + (u.tahap || 'diajukan'));
    if (u.catatan) lines.push('CATATAN: ' + u.catatan);
    blocks.push(lines.join('\n'));
  });
  var text = blocks.join('\n\n');
  var ts = nowIso_().replace(/[:.]/g, '-').slice(0, 19);
  var tahunLabel = filterTahunAjaranId && tahunMap[filterTahunAjaranId]
    ? '-' + (tahunMap[filterTahunAjaranId].namaDisplay || tahunMap[filterTahunAjaranId].nama || filterTahunAjaranId).replace(/\s+/g, '-')
    : '';
  return { ok: true, timestamp: nowIso_(), data: { text: text, count: blocks.length, filename: 'ujian-hafalan-tempel' + tahunLabel + '-' + ts + '.txt' } };
}

function canAccessNilaiUas_(session) {
  if (!session || session.role !== 'pengurus' || !session.permissions) return false;
  return canAccessLevel_(session, 'misiTahfizh', 'manage', function (s) {
    var p = s.permissions;
    return !!(p.isAdmin || p.isHalaqohCoordinator || p.isPengampuHalaqoh);
  });
}

// Konfigurasi kolom per komponen UAS. max>0 = batas jumlah entri (Al-Qur'an = 30).
var UAS_KOMPONEN = {
  quran:    { entries: 'entries_quran',    kkm: 'kkm_quran',    nilai: 'nilai_quran',    pengisi: 'pengisi_quran_id',    tanggal: 'tanggal_quran',    max: 30 },
  mufrodat: { entries: 'entries_mufrodat', kkm: 'kkm_mufrodat', nilai: 'nilai_mufrodat', pengisi: 'pengisi_mufrodat_id', tanggal: 'tanggal_mufrodat', max: 0 },
  hadits:   { entries: 'entries_hadits',   kkm: 'kkm_hadits',   nilai: 'nilai_hadits',   pengisi: 'pengisi_hadits_id',   tanggal: 'tanggal_hadits',   max: 0 },
  adzkar:   { entries: 'entries_adzkar',   kkm: 'kkm_adzkar',   nilai: 'nilai_adzkar',   pengisi: 'pengisi_adzkar_id',   tanggal: 'tanggal_adzkar',   max: 0 }
};

// Parse JSON entri nilai → array { ket, nilai } yang sudah dibersihkan (buang baris kosong total).
function parseUasEntries_(raw) {
  if (!raw) return [];
  var arr;
  try { arr = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return []; }
  if (!Array.isArray(arr)) return [];
  return arr.map(function (e) {
    return { ket: cleanString_(e && e.ket), nilai: cleanString_(e && e.nilai) };
  }).filter(function (e) { return e.ket !== '' || e.nilai !== ''; });
}

// Normalisasi input entri dari klien + batasi jumlah maksimum (mis. Al-Qur'an 30).
function normalizeUasEntriesInput_(raw, max) {
  var list = parseUasEntries_(raw);
  if (max && max > 0 && list.length > max) list = list.slice(0, max);
  return list;
}

// KKM: simpan apa adanya jika angka 0–1000, selain itu kosong.
function clampKkm_(value) {
  var n = parseFloat(value);
  if (isNaN(n) || n < 0) return '';
  if (n > 1000) n = 1000;
  return String(Math.round(n * 100) / 100);
}

// Bangun array entri untuk satu komponen, dengan fallback dari kolom lama (data sebelum fitur multi-nilai).
function buildUasEntries_(row, komponen) {
  var cfg = UAS_KOMPONEN[komponen];
  var list = parseUasEntries_(row[cfg.entries]);
  if (list.length) return list;
  var legacyNilai = cleanString_(row[cfg.nilai]);
  if (!legacyNilai) return [];
  var ket = '';
  if (komponen === 'quran') {
    var jm = cleanString_(row.juz_mulai_quran), ja = cleanString_(row.juz_akhir_quran);
    if (jm && ja && ja !== jm) ket = 'Juz ' + jm + '–' + ja;
    else if (jm) ket = 'Juz ' + jm;
  } else if (komponen === 'mufrodat') {
    var lvl = cleanString_(row.level_mufrodat);
    if (lvl) ket = 'Level ' + lvl;
  } else if (komponen === 'hadits') {
    ket = cleanString_(row.kitab_hadits);
  }
  return [{ ket: ket, nilai: legacyNilai }];
}

function normalizeNilaiUas_(row) {
  var status = normalizeStatusForSheet_('nilaiUas', row.status || STATUS_LABELS.nilaiUas.active);
  return {
    id: cleanString_(row.id),
    santriId: cleanString_(row.id_santri),
    halaqohId: cleanString_(row.id_halaqoh),
    tahunAjaranId: cleanString_(row.id_tahun_ajaran),
    entriesQuran: buildUasEntries_(row, 'quran'),
    kkmQuran: cleanString_(row.kkm_quran),
    nilaiQuran: cleanString_(row.nilai_quran),
    juzMulaiQuran: cleanString_(row.juz_mulai_quran),
    juzAkhirQuran: cleanString_(row.juz_akhir_quran),
    pengisiQuranId: cleanString_(row.pengisi_quran_id),
    tanggalQuran: cleanString_(row.tanggal_quran),
    entriesMufrodat: buildUasEntries_(row, 'mufrodat'),
    kkmMufrodat: cleanString_(row.kkm_mufrodat),
    nilaiMufrodat: cleanString_(row.nilai_mufrodat),
    levelMufrodat: cleanString_(row.level_mufrodat),
    pengisiMufrodatId: cleanString_(row.pengisi_mufrodat_id),
    tanggalMufrodat: cleanString_(row.tanggal_mufrodat),
    entriesHadits: buildUasEntries_(row, 'hadits'),
    kkmHadits: cleanString_(row.kkm_hadits),
    nilaiHadits: cleanString_(row.nilai_hadits),
    kitabHadits: cleanString_(row.kitab_hadits),
    pengisiHaditsId: cleanString_(row.pengisi_hadits_id),
    tanggalHadits: cleanString_(row.tanggal_hadits),
    entriesAdzkar: buildUasEntries_(row, 'adzkar'),
    kkmAdzkar: cleanString_(row.kkm_adzkar),
    nilaiAdzkar: cleanString_(row.nilai_adzkar),
    pengisiAdzkarId: cleanString_(row.pengisi_adzkar_id),
    tanggalAdzkar: cleanString_(row.tanggal_adzkar),
    catatan: cleanString_(row.catatan),
    status: status,
    active: isActiveStatus_(status),
    _rowNumber: row._rowNumber
  };
}

function handleNilaiUasList_(request, session) {
  if (!canAccessNilaiUas_(session)) throw createError_('Akses ditolak.', 403);
  var dataset = loadDataset_();
  var accessible = getAccessibleUjianHalaqoh_(session, dataset);
  var accessibleIdSet = {};
  accessible.forEach(function (h) { accessibleIdSet[h.id] = true; });

  var tahunAjaranId = cleanString_(request.tahunAjaranId);
  var halaqohId = cleanString_(request.halaqohId);

  var state = readSheetState_('nilaiUas');
  var allRecords = state.rows.map(normalizeNilaiUas_).filter(function (r) {
    if (!r.active) return false;
    if (!accessibleIdSet[r.halaqohId]) return false;
    if (tahunAjaranId && r.tahunAjaranId !== tahunAjaranId) return false;
    if (halaqohId && r.halaqohId !== halaqohId) return false;
    return true;
  });

  var pengurusById = dataset.indexes.pengurusById || {};
  var enriched = allRecords.map(function (r) {
    var santri = dataset.indexes.santriById[r.santriId];
    var pQuran = r.pengisiQuranId ? (pengurusById[r.pengisiQuranId] || null) : null;
    var pMufrodat = r.pengisiMufrodatId ? (pengurusById[r.pengisiMufrodatId] || null) : null;
    var pHadits = r.pengisiHaditsId ? (pengurusById[r.pengisiHaditsId] || null) : null;
    var pAdzkar = r.pengisiAdzkarId ? (pengurusById[r.pengisiAdzkarId] || null) : null;
    return {
      id: r.id,
      santriId: r.santriId,
      santriName: santri ? cleanString_(santri.name) : r.santriId,
      halaqohId: r.halaqohId,
      tahunAjaranId: r.tahunAjaranId,
      entriesQuran: r.entriesQuran, kkmQuran: r.kkmQuran,
      nilaiQuran: r.nilaiQuran, juzMulaiQuran: r.juzMulaiQuran, juzAkhirQuran: r.juzAkhirQuran,
      pengisiQuranName: pQuran ? cleanString_(pQuran.name) : '', tanggalQuran: r.tanggalQuran,
      entriesMufrodat: r.entriesMufrodat, kkmMufrodat: r.kkmMufrodat,
      nilaiMufrodat: r.nilaiMufrodat, levelMufrodat: r.levelMufrodat,
      pengisiMufrodatName: pMufrodat ? cleanString_(pMufrodat.name) : '', tanggalMufrodat: r.tanggalMufrodat,
      entriesHadits: r.entriesHadits, kkmHadits: r.kkmHadits,
      nilaiHadits: r.nilaiHadits, kitabHadits: r.kitabHadits,
      pengisiHaditsName: pHadits ? cleanString_(pHadits.name) : '', tanggalHadits: r.tanggalHadits,
      entriesAdzkar: r.entriesAdzkar, kkmAdzkar: r.kkmAdzkar,
      nilaiAdzkar: r.nilaiAdzkar,
      pengisiAdzkarName: pAdzkar ? cleanString_(pAdzkar.name) : '', tanggalAdzkar: r.tanggalAdzkar,
      catatan: r.catatan
    };
  });

  var halaqohList = accessible.filter(function (h) {
    return !tahunAjaranId || cleanString_(h.tahunAjaranId) === tahunAjaranId;
  }).map(function (h) {
    var santriList = (h.santriIds || []).map(function (sid) {
      var s = dataset.indexes.santriById[sid];
      return { id: sid, name: s ? cleanString_(s.name) : sid };
    });
    return { id: h.id, name: cleanString_(h.name), genderGroup: cleanString_(h.genderGroup || ''), santriList: santriList };
  });

  var tahunAjaranList = (dataset.tahunAjaran || []).map(function (ta) {
    return { id: ta.id, nama: ta.nama, namaDisplay: ta.namaDisplay, isAktif: ta.isAktif };
  });

  return { ok: true, timestamp: nowIso_(), data: { records: enriched, halaqohList: halaqohList, tahunAjaranList: tahunAjaranList } };
}

function handleNilaiUasSave_(request, session) {
  if (!canAccessNilaiUas_(session)) throw createError_('Akses ditolak.', 403);
  var record = parseRecordPayload_(request);
  var komponen = cleanString_(record.komponen);
  var santriId = cleanString_(record.santriId);
  var tahunAjaranId = cleanString_(record.tahunAjaranId);
  var halaqohId = cleanString_(record.halaqohId);
  if (!komponen || !santriId || !tahunAjaranId) throw createError_('Data tidak lengkap.', 400);
  requireTahunAjaranNotLocked_(tahunAjaranId);

  var pengurusId = session.pengurus_id || '';
  var today = nowIso_().slice(0, 10);
  var state = readSheetState_('nilaiUas');

  var existingRow = null;
  var existingRowNumber = null;
  for (var i = 0; i < state.rows.length; i++) {
    var r = state.rows[i];
    if (cleanString_(r.id_santri) === santriId && cleanString_(r.id_tahun_ajaran) === tahunAjaranId && isActiveStatus_(normalizeStatusForSheet_('nilaiUas', r.status || STATUS_LABELS.nilaiUas.active))) {
      existingRow = r;
      existingRowNumber = r._rowNumber;
      break;
    }
  }

  var cfg = UAS_KOMPONEN[komponen];
  if (!cfg) throw createError_('Komponen tidak dikenal: ' + komponen, 400);
  var entries = normalizeUasEntriesInput_(record.entries, cfg.max);
  var patch = {};
  patch[cfg.entries] = JSON.stringify(entries);
  patch[cfg.kkm] = clampKkm_(record.kkm);
  patch[cfg.nilai] = entries.length ? entries[0].nilai : ''; // sinkron kolom lama (fallback)
  patch[cfg.pengisi] = pengurusId;
  patch[cfg.tanggal] = today;

  if (existingRow && existingRowNumber) {
    updateStateRow_(state, existingRowNumber, patch);
  } else {
    var newRow = { id: String(nextId_(state.rows)), id_santri: santriId, id_halaqoh: halaqohId, id_tahun_ajaran: tahunAjaranId, status: STATUS_LABELS.nilaiUas.active };
    Object.keys(patch).forEach(function (k) { newRow[k] = patch[k]; });
    appendSheetRow_(state, newRow);
  }

  return { ok: true, timestamp: nowIso_(), data: { message: 'Nilai berhasil disimpan.' } };
}

function handleNilaiUasDelete_(request, session) {
  if (!session || !session.permissions || !(session.permissions.isSuperAdmin || session.permissions.isAdmin)) {
    throw createError_('Hanya admin yang dapat menghapus data nilai UAS.', 403);
  }
  var record = parseRecordPayload_(request);
  var id = cleanString_(record.id);
  if (!id) throw createError_('ID tidak ditemukan.', 400);
  var state = readSheetState_('nilaiUas');
  var target = state.rows.filter(function (r) { return cleanString_(r.id) === id; })[0];
  if (!target) throw createError_('Data tidak ditemukan.', 404);
  requireTahunAjaranNotLocked_(cleanString_(target.id_tahun_ajaran));
  deleteSheetRows_(state, [target._rowNumber]);
  return { ok: true, timestamp: nowIso_(), data: { message: 'Data berhasil dihapus.' } };
}

function getAccessibleKelasAttendanceItems_(session, dataset) {
  return (dataset && dataset.kelasSiang ? dataset.kelasSiang : []).filter(function (kelas) {
    return kelas.active && canAccessKelasRecord_(session, kelas.id);
  });
}

function findAccessibleKelasAttendanceItem_(session, kelasId, dataset) {
  var target = cleanString_(kelasId);
  return getAccessibleKelasAttendanceItems_(session, dataset).filter(function (kelas) {
    return cleanString_(kelas.id) === target;
  })[0] || null;
}

function canAccessKelasRecord_(session, kelasId) {
  if (!session || session.role !== 'pengurus' || !session.permissions) {
    return false;
  }
  if (canAccessLevel_(session, 'kelasSiangNilai', 'manageAllKelas', function (s) {
    var p = s.permissions; return !!(p.isAdmin || p.canManageKelasSiang);
  })) {
    return true;
  }
  if (!canAccessLevel_(session, 'kelasSiangNilai', 'manage', function (s) { return !!(s.permissions && s.permissions.canManageNilaiUp); })) {
    return false;
  }
  return (session.kelasIds || []).indexOf(cleanString_(kelasId)) !== -1;
}

function assertCanManageKelasRecord_(session, kelasId) {
  if (!canAccessKelasRecord_(session, kelasId)) {
    throw createError_('Akun ini hanya bisa mengisi nilai UP untuk kelas yang diajar.', 403);
  }
}

// ── Santri Sakit handlers ────────────────────────────────────────────────────

function handleSantriSakitList_(request, session) {
  var state = readSheetState_('santriSakit');
  var santriIdFilter = cleanString_(request.santriId || '');
  var statusFilter = cleanString_(request.status || '').toLowerCase();
  var tahunAjaranFilter = cleanString_(request.tahunAjaranId || '');
  var dariTanggal = cleanString_(request.dariTanggal || '');
  var sampaiTanggal = cleanString_(request.sampaiTanggal || '');
  var qFilter = cleanString_(request.q || '').toLowerCase();
  var sortBy = cleanString_(request.sortBy || 'updated');
  var genderFilter = cleanString_(request.gender || '').toLowerCase();

  var dataset = loadDataset_();
  var genderMap = {};
  var statusMap = {};
  (dataset.santri || []).forEach(function (s) {
    if (!s.id) return;
    genderMap[String(s.id)] = normalizeSantriGender_(s.jenisKelamin || s.gender || '');
    statusMap[String(s.id)] = getSantriStatusKey_(s.status || '');
  });

  // Stats kartu ringkasan: dihitung dari semua data pada tahun ajaran yang sama,
  // tanpa terpengaruh filter status/pencarian/halaman.
  var statsRows = tahunAjaranFilter
    ? state.rows.filter(function (r) { return cleanString_(r.tahun_ajaran_id) === tahunAjaranFilter; })
    : state.rows;
  var stats = { sakit: 0, sembuh: 0, dihapus: 0 };
  var sakitLabel = STATUS_LABELS.santriSakit.active.toLowerCase();
  var sembuhLabel = STATUS_LABELS.santriSakit.sembuh.toLowerCase();
  statsRows.forEach(function (r) {
    if (isTruthy_(r.is_deleted)) { stats.dihapus += 1; return; }
    var s = cleanString_(r.status || '').toLowerCase();
    if (s === sakitLabel) stats.sakit += 1;
    else if (s === sembuhLabel) stats.sembuh += 1;
  });

  var rows = state.rows.filter(function (r) {
    if (santriIdFilter && cleanString_(r.santri_id) !== santriIdFilter) return false;
    var deleted = isTruthy_(r.is_deleted);
    if (statusFilter === 'dihapus') {
      if (!deleted) return false;
    } else if (statusFilter) {
      if (deleted || cleanString_(r.status || '').toLowerCase() !== statusFilter) return false;
    } else if (deleted) {
      return false;
    }
    if (tahunAjaranFilter && cleanString_(r.tahun_ajaran_id) !== tahunAjaranFilter) return false;
    if (genderFilter && genderMap[String(r.santri_id)] !== genderFilter) return false;
    var tgl = cleanString_(r.tanggal_mulai || '');
    if (dariTanggal && tgl < dariTanggal) return false;
    if (sampaiTanggal && tgl > sampaiTanggal) return false;
    if (qFilter) {
      var hay = [r.santri_nama, r.keterangan, r.tempat_perawatan, r.input_by_nama, r.catatan].join(' ').toLowerCase();
      if (hay.indexOf(qFilter) === -1) return false;
    }
    return true;
  });

  if (sortBy === 'nama_az') rows.sort(function (a, b) { return (a.santri_nama || '').localeCompare(b.santri_nama || ''); });
  else if (sortBy === 'nama_za') rows.sort(function (a, b) { return (b.santri_nama || '').localeCompare(a.santri_nama || ''); });
  else if (sortBy === 'tanggal_asc') rows.sort(function (a, b) { return (a.tanggal_mulai || '').localeCompare(b.tanggal_mulai || ''); });
  else if (sortBy === 'tanggal_desc') rows.sort(function (a, b) { return (b.tanggal_mulai || '').localeCompare(a.tanggal_mulai || ''); });
  else rows.sort(function (a, b) { return (b.updated_at || b.created_at || '').localeCompare(a.updated_at || a.created_at || ''); });

  var page = parseInt(request.page, 10) || 1;
  var pageSize = Math.min(parseInt(request.pageSize, 10) || 50, 200);
  var total = rows.length;
  var items = rows.slice((page - 1) * pageSize, page * pageSize).map(function (r) {
    var mapped = mapSantriSakitRow_(r);
    mapped.santriGender = genderMap[String(r.santri_id)] || '';
    mapped.santriStatus = statusMap[String(r.santri_id)] || 'active';
    return mapped;
  });
  return { ok: true, timestamp: nowIso_(), data: { total: total, page: page, pageSize: pageSize, items: items, stats: stats } };
}

function handleSantriSakitSave_(request, session) {
  var record = parseRecordPayload_(request);
  var santriId = cleanString_(record.santri_id || '');
  var keterangan = cleanString_(record.keterangan || '');
  if (!santriId) throw createError_('Santri wajib dipilih.', 400);
  var tanggalMulai = assertValidDateOnly_(record.tanggal_mulai, 'Tanggal mulai sakit');

  var dataset = loadDataset_();
  var santri = dataset.santri.filter(function (s) { return cleanString_(s.id) === santriId; })[0];
  if (!santri) throw createError_('Santri tidak ditemukan.', 404);

  var state = readSheetState_('santriSakit');
  var writable = {
    id: String(nextId_(state.rows)),
    santri_id: santriId,
    santri_nama: santri.name || santri.namaLengkap || '',
    santri_no_induk: santri.noInduk || '',
    tanggal_mulai: tanggalMulai,
    jam_mulai: cleanString_(record.jam_mulai || ''),
    tanggal_sembuh: record.tanggal_sembuh ? assertValidDateOnly_(record.tanggal_sembuh, 'Tanggal sembuh') : '',
    jam_sembuh: cleanString_(record.jam_sembuh || ''),
    keterangan: keterangan,
    tempat_perawatan: cleanString_(record.tempat_perawatan || ''),
    boleh_masuk: normalizeSantriSakitBolehMasuk_(record.boleh_masuk),
    alasan: cleanString_(record.alasan || ''),
    penanganan: cleanString_(record.penanganan || ''),
    status: 'Sakit',
    input_by_id: String(session.id || ''),
    input_by_nama: String(session.name || ''),
    tahun_ajaran_id: cleanString_(record.tahun_ajaran_id || ''),
    catatan: cleanString_(record.catatan || '')
  };
  appendSheetRow_(state, writable);
  return { ok: true, timestamp: nowIso_(), data: { id: writable.id, message: 'Data sakit berhasil dicatat.' } };
}

function handleSantriSakitSetStatus_(request, session) {
  var id = cleanString_(request.id || '');
  var newStatus = cleanString_(request.status || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('santriSakit');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);
  var patch = { status: newStatus || 'Sembuh' };
  if (newStatus === 'Sembuh' && cleanString_(request.tanggal_sembuh || '')) patch.tanggal_sembuh = cleanString_(request.tanggal_sembuh);
  else if (newStatus === 'Sembuh' && !cleanString_(existing.tanggal_sembuh || '')) patch.tanggal_sembuh = nowIso_().slice(0, 10);
  if (newStatus === 'Sembuh' && request.jam_sembuh !== undefined) patch.jam_sembuh = cleanString_(request.jam_sembuh);
  updateSheetRow_(state, existing._rowNumber, patch);
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: 'Status diperbarui.' } };
}

function handleSantriSakitSetDeleted_(request, session) {
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('santriSakit');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);
  var deleted = isTruthy_(request.deleted);
  updateSheetRow_(state, existing._rowNumber, { is_deleted: deleted ? '1' : '0', updated_at: nowIso_() });
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: deleted ? 'Data ditandai dihapus.' : 'Data dipulihkan.' } };
}

var SANTRI_SAKIT_BOLEH_MASUK_VALUES = ['semua', 'halaqoh', 'kelas', 'wajib_halaqoh', 'wajib_kelas', 'tidak'];

function normalizeSantriSakitBolehMasuk_(rawValue) {
  var v = cleanString_(rawValue).toLowerCase();
  if (SANTRI_SAKIT_BOLEH_MASUK_VALUES.indexOf(v) !== -1) return v;
  // Kompatibilitas data lama: dulu kolom ini menyimpan boolean TRUE/FALSE
  // (boleh masuk keduanya, atau tidak boleh masuk keduanya sama sekali).
  if (v === '') return 'semua';
  return isTruthy_(v) ? 'semua' : 'tidak';
}

function santriSakitBolehHalaqoh_(rawValue) {
  var v = normalizeSantriSakitBolehMasuk_(rawValue);
  return v === 'semua' || v === 'halaqoh' || v === 'wajib_halaqoh';
}

function santriSakitBolehKelas_(rawValue) {
  var v = normalizeSantriSakitBolehMasuk_(rawValue);
  return v === 'semua' || v === 'kelas' || v === 'wajib_kelas';
}

function mapSantriSakitRow_(r) {
  var fotos = [];
  try { fotos = JSON.parse(r.fotos_json || '[]'); } catch (e) {}
  return { id: r.id, santriId: r.santri_id, santriNama: r.santri_nama, santriNoInduk: r.santri_no_induk, tanggalMulai: r.tanggal_mulai, jamMulai: r.jam_mulai, tanggalSembuh: r.tanggal_sembuh, jamSembuh: r.jam_sembuh, keterangan: r.keterangan, tempatPerawatan: r.tempat_perawatan, bolehMasuk: normalizeSantriSakitBolehMasuk_(r.boleh_masuk), bolehHalaqoh: santriSakitBolehHalaqoh_(r.boleh_masuk), bolehKelas: santriSakitBolehKelas_(r.boleh_masuk), alasan: r.alasan, penanganan: r.penanganan, status: r.status, isDeleted: isTruthy_(r.is_deleted), inputById: r.input_by_id, inputByNama: r.input_by_nama, tahunAjaranId: r.tahun_ajaran_id, catatan: r.catatan, fotos: fotos, editHistory: r.edit_history, createdAt: r.created_at, updatedAt: r.updated_at };
}

function handleSantriSakitUpdate_(request, session) {
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('santriSakit');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);
  var patch = {
    tanggal_mulai: request.tanggal_mulai ? assertValidDateOnly_(request.tanggal_mulai, 'Tanggal mulai sakit') : cleanString_(existing.tanggal_mulai || ''),
    jam_mulai: cleanString_(request.jam_mulai !== undefined ? request.jam_mulai : existing.jam_mulai || ''),
    tanggal_sembuh: request.tanggal_sembuh !== undefined
      ? (request.tanggal_sembuh ? assertValidDateOnly_(request.tanggal_sembuh, 'Tanggal sembuh') : '')
      : cleanString_(existing.tanggal_sembuh || ''),
    jam_sembuh: cleanString_(request.jam_sembuh !== undefined ? request.jam_sembuh : existing.jam_sembuh || ''),
    keterangan: cleanString_(request.keterangan || existing.keterangan || ''),
    tempat_perawatan: cleanString_(request.tempat_perawatan || existing.tempat_perawatan || ''),
    boleh_masuk: normalizeSantriSakitBolehMasuk_(request.boleh_masuk !== undefined ? request.boleh_masuk : existing.boleh_masuk),
    alasan: cleanString_(request.alasan !== undefined ? request.alasan : existing.alasan || ''),
    penanganan: cleanString_(request.penanganan !== undefined ? request.penanganan : existing.penanganan || ''),
    status: cleanString_(request.status || existing.status || ''),
    catatan: cleanString_(request.catatan !== undefined ? request.catatan : existing.catatan || ''),
    tahun_ajaran_id: cleanString_(request.tahun_ajaran_id || existing.tahun_ajaran_id || ''),
    updated_at: nowIso_()
  };
  updateSheetRow_(state, existing._rowNumber, patch);
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: 'Data berhasil diperbarui.' } };
}

function handleSantriSakitFotoUpload_(request, session) {
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('santriSakit');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);
  var dataUrl = String(request.dataUrl || '');
  var mimeMatch = dataUrl.match(/^data:([a-z/+]+);base64,/);
  if (!mimeMatch) throw createError_('Format file tidak valid.', 400);
  var mimeType = mimeMatch[1];
  var ext = ALLOWED_SANTRI_SAKIT_FOTO_MIME[mimeType];
  if (!ext) throw createError_('Tipe file tidak diizinkan.', 400);
  var bytes = Buffer.from(dataUrl.slice(dataUrl.indexOf(',') + 1), 'base64');
  if (bytes.length > MAX_SANTRI_SAKIT_FOTO_BYTES) throw createError_('Ukuran foto melebihi batas 10 MB.', 400);
  var originalName = cleanString_(request.name || 'foto') + '.' + ext;
  var filename = id + '-' + Date.now() + '-' + Math.random().toString(36).slice(2) + '.' + ext;
  fs.mkdirSync(SANTRI_SAKIT_FOTOS_DIR, { recursive: true });
  fs.writeFileSync(path.join(SANTRI_SAKIT_FOTOS_DIR, filename), bytes);
  var fotos = [];
  try { fotos = JSON.parse(existing.fotos_json || '[]'); } catch (e) {}
  fotos.push({ name: originalName, path: SANTRI_SAKIT_FOTOS_DIR_NAME + '/' + filename, size: bytes.length, type: mimeType, uploadedAt: nowIso_() });
  updateSheetRow_(state, existing._rowNumber, { fotos_json: JSON.stringify(fotos), updated_at: nowIso_() });
  return { ok: true, timestamp: nowIso_(), data: { fotos: fotos } };
}

function handleSantriSakitFotoDelete_(request, session) {
  var id = cleanString_(request.id || '');
  var fotoPath = cleanString_(request.path || '');
  if (!id || !fotoPath) throw createError_('ID dan path foto wajib diisi.', 400);
  var state = readSheetState_('santriSakit');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);
  var fotos = [];
  try { fotos = JSON.parse(existing.fotos_json || '[]'); } catch (e) {}
  var idx = fotos.findIndex(function (f) { return f && f.path === fotoPath; });
  if (idx !== -1) {
    try { fs.unlinkSync(path.join(FRONTEND_DIR, fotoPath)); } catch (e) {}
    fotos.splice(idx, 1);
  }
  updateSheetRow_(state, existing._rowNumber, { fotos_json: JSON.stringify(fotos), updated_at: nowIso_() });
  return { ok: true, timestamp: nowIso_(), data: { fotos: fotos } };
}

function handleSantriSakitDeleteAll_(session) {
  requireSuperAdmin_(session);
  var state = readSheetState_('santriSakit');
  state.rows.forEach(function (row) {
    var fotos = [];
    try { fotos = JSON.parse(row.fotos_json || '[]'); } catch (e) {}
    fotos.forEach(function (f) {
      if (f && f.path) { try { fs.unlinkSync(path.join(FRONTEND_DIR, f.path)); } catch (e) {} }
    });
  });
  var rowNumbers = state.rows.map(function (r) { return r._rowNumber; });
  if (rowNumbers.length) deleteSheetRows_(state, rowNumbers);
  return { ok: true, timestamp: nowIso_(), data: { count: rowNumbers.length, message: rowNumbers.length ? 'Semua data santri sakit berhasil dihapus.' : 'Data sudah kosong.' } };
}

// ── Buku Digital handlers ─────────────────────────────────────────────────────

function canOpenBuku_(perms, akses) {
  if (!akses || akses === 'semua') return true;
  if (akses === 'terbatas') return !!(perms && (perms.isSuperAdmin || perms.isAdmin || perms.isAcademic || perms.canManageBuku));
  if (akses === 'dikunci') return !!(perms && perms.isSuperAdmin);
  return true;
}

function mapBukuRow_(r, perms) {
  var canOpen = canOpenBuku_(perms, r.akses);
  return {
    id: r.id,
    judul: r.judul,
    penulis: r.penulis,
    pelajaran: r.pelajaran,
    deskripsi: r.deskripsi,
    fileType: r.file_type,
    fileName: r.file_name,
    fileSize: r.file_size ? Number(r.file_size) : null,
    hasFile: !!(r.file_path),
    hasQuill: !!(r.quill_content),
    quillContent: canOpen ? (r.quill_content || '') : '',
    akses: r.akses || 'semua',
    canDownload: r.can_download === '1' || r.can_download === 1,
    uploadedByNama: r.uploaded_by_nama,
    status: r.status,
    canOpen: canOpen,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function handleBukuList_(request, session) {
  requirePengurus_(session);
  var perms = session.permissions || {};
  var state = readSheetState_('bukuDigital');
  var q = cleanString_(request.q || '').toLowerCase();
  var pelajaran = cleanString_(request.pelajaran || '');
  var akses = cleanString_(request.akses || '');
  var fileType = cleanString_(request.fileType || '');
  var rows = state.rows.filter(function(r) {
    if (cleanString_(r.status || '') === 'arsip') return false;
    if (pelajaran && cleanString_(r.pelajaran || '') !== pelajaran) return false;
    if (akses && cleanString_(r.akses || 'semua') !== akses) return false;
    if (fileType && cleanString_(r.file_type || '') !== fileType) return false;
    if (q) {
      var hay = [r.judul, r.penulis, r.pelajaran, r.deskripsi].join(' ').toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  });
  rows.sort(function(a, b) { return (b.created_at || '').localeCompare(a.created_at || ''); });
  var pelajaranList = Array.from(new Set(state.rows.filter(function(r) { return r.pelajaran; }).map(function(r) { return r.pelajaran; }))).sort();
  return { ok: true, timestamp: nowIso_(), data: { items: rows.map(function(r) { return mapBukuRow_(r, perms); }), pelajaranList: pelajaranList } };
}

function handleBukuSave_(request, session) {
  requirePengurus_(session);
  if (!canManageAddon_(session, 'bukuDigital', ADDON_MANAGE_FALLBACK_.bukuDigital)) throw createError_('Hanya Admin, Akademik, Super Admin, atau jabatan yang diatur di Kelola Addons.', 403);
  var judul = cleanString_(request.judul || '');
  if (!judul) throw createError_('Judul buku wajib diisi.', 400);
  var akses = cleanString_(request.akses || 'semua');
  if (!['semua', 'terbatas', 'dikunci'].includes(akses)) akses = 'semua';
  var state = readSheetState_('bukuDigital');
  var id = String(nextId_(state.rows));
  var writable = {
    id: id,
    judul: judul,
    penulis: cleanString_(request.penulis || ''),
    pelajaran: cleanString_(request.pelajaran || ''),
    deskripsi: cleanString_(request.deskripsi || ''),
    file_path: '',
    file_type: cleanString_(request.fileType || 'pdf'),
    file_name: '',
    file_size: '',
    quill_content: '',
    akses: akses,
    can_download: request.canDownload === true || request.canDownload === '1' || request.canDownload === 1 ? '1' : '0',
    uploaded_by: cleanString_(session.id || ''),
    uploaded_by_nama: cleanString_(session.name || ''),
    status: 'aktif',
  };
  appendSheetRow_(state, writable);
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: 'Buku berhasil ditambahkan.' } };
}

function handleBukuUpdate_(request, session) {
  requirePengurus_(session);
  if (!canManageAddon_(session, 'bukuDigital', ADDON_MANAGE_FALLBACK_.bukuDigital)) throw createError_('Hanya Admin, Akademik, Super Admin, atau jabatan yang diatur di Kelola Addons.', 403);
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('bukuDigital');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Buku tidak ditemukan.', 404);
  var akses = cleanString_(request.akses || existing.akses || 'semua');
  if (!['semua', 'terbatas', 'dikunci'].includes(akses)) akses = existing.akses || 'semua';
  var writable = {
    judul: cleanString_(request.judul || existing.judul),
    penulis: cleanString_(request.penulis != null ? request.penulis : existing.penulis),
    pelajaran: cleanString_(request.pelajaran != null ? request.pelajaran : existing.pelajaran),
    deskripsi: cleanString_(request.deskripsi != null ? request.deskripsi : existing.deskripsi),
    akses: akses,
    can_download: request.canDownload === true || request.canDownload === '1' || request.canDownload === 1 ? '1' : (request.canDownload === false || request.canDownload === '0' || request.canDownload === 0 ? '0' : existing.can_download),
  };
  updateSheetRow_(state, existing._rowNumber, writable);
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: 'Buku berhasil diperbarui.' } };
}

function handleBukuDelete_(request, session) {
  requirePengurus_(session);
  if (!canManageAddon_(session, 'bukuDigital', ADDON_MANAGE_FALLBACK_.bukuDigital)) throw createError_('Hanya Admin, Akademik, Super Admin, atau jabatan yang diatur di Kelola Addons.', 403);
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('bukuDigital');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Buku tidak ditemukan.', 404);
  if (existing.file_path) {
    try { fs.unlinkSync(path.join(FRONTEND_DIR, existing.file_path)); } catch (_) {}
  }
  deleteSheetRows_(state, [existing._rowNumber]);
  return { ok: true, timestamp: nowIso_(), data: { message: 'Buku berhasil dihapus.' } };
}

function handleBukuQuillSave_(request, session) {
  requirePengurus_(session);
  if (!canManageAddon_(session, 'bukuDigital', ADDON_MANAGE_FALLBACK_.bukuDigital)) throw createError_('Hanya Admin, Akademik, Super Admin, atau jabatan yang diatur di Kelola Addons.', 403);
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('bukuDigital');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Buku tidak ditemukan.', 404);
  updateSheetRow_(state, existing._rowNumber, { quill_content: request.quillContent || '', file_type: 'quill', updated_at: nowIso_() });
  return { ok: true, timestamp: nowIso_(), data: { message: 'Konten quill berhasil disimpan.' } };
}

// ── Bank Soal handlers ────────────────────────────────────────────────────────

function mapBankSoalRow_(r, canManageAll, perms) {
  var canManage = !!canManageAll;
  var isOwner = !!(perms && r.uploaded_by && r.uploaded_by === (perms._uploadedBy || ''));
  return {
    id: r.id,
    judul: r.judul,
    pelajaran: r.pelajaran,
    jenis: r.jenis,
    tingkat: r.tingkat,
    tahunAjaranId: r.tahun_ajaran_id,
    tahunAjaranLabel: r.tahun_ajaran_label,
    deskripsi: r.deskripsi,
    fileType: r.file_type,
    fileName: r.file_name,
    fileSize: r.file_size ? Number(r.file_size) : null,
    hasFile: !!(r.file_path),
    hasQuill: !!(r.quill_content),
    quillContent: r.quill_content || '',
    uploadedBy: r.uploaded_by,
    uploadedByNama: r.uploaded_by_nama,
    status: r.status,
    canEdit: canManage || isOwner,
    canDelete: canManage || isOwner,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    editHistory: r.edit_history || '',
  };
}

function handleBankSoalList_(request, session) {
  requirePengurus_(session);
  var perms = session.permissions || {};
  var clonedPerms = Object.assign({}, perms, { _uploadedBy: cleanString_(session.id || '') });
  var canManageAllSoal = canAccessLevel_(session, 'bankSoal', 'manageAllSoal', function (s) { return !!(s.permissions && s.permissions.canManageSoal); });
  var state = readSheetState_('bankSoal');
  var q = cleanString_(request.q || '').toLowerCase();
  var pelajaran = cleanString_(request.pelajaran || '');
  var jenis = cleanString_(request.jenis || '');
  var tingkat = cleanString_(request.tingkat || '');
  var tahunAjaranId = cleanString_(request.tahunAjaranId || '');
  var rows = state.rows.filter(function(r) {
    if (cleanString_(r.status || '') === 'arsip') return false;
    if (pelajaran && cleanString_(r.pelajaran || '') !== pelajaran) return false;
    if (jenis && cleanString_(r.jenis || '') !== jenis) return false;
    if (tingkat && cleanString_(r.tingkat || '') !== tingkat) return false;
    if (tahunAjaranId && cleanString_(r.tahun_ajaran_id || '') !== tahunAjaranId) return false;
    if (q) {
      var hay = [r.judul, r.pelajaran, r.jenis, r.tingkat, r.tahun_ajaran_label, r.deskripsi, r.uploaded_by_nama].join(' ').toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  });
  rows.sort(function(a, b) { return (b.created_at || '').localeCompare(a.created_at || ''); });
  var pelajaranList = Array.from(new Set(state.rows.filter(function(r) { return r.pelajaran; }).map(function(r) { return r.pelajaran; }))).sort();
  var jenisList = Array.from(new Set(state.rows.filter(function(r) { return r.jenis; }).map(function(r) { return r.jenis; }))).sort();
  var tingkatList = Array.from(new Set(state.rows.filter(function(r) { return r.tingkat; }).map(function(r) { return r.tingkat; }))).sort();
  return { ok: true, timestamp: nowIso_(), data: { items: rows.map(function(r) { return mapBankSoalRow_(r, canManageAllSoal, clonedPerms); }), pelajaranList: pelajaranList, jenisList: jenisList, tingkatList: tingkatList, canUploadSoal: !!(perms.canUploadSoal), canManageSoal: canManageAllSoal } };
}

