// ── Izin Pulang handlers ─────────────────────────────────────────────────────

function handleIzinPulangList_(request, session) {
  var state = readSheetState_('izinPulang');
  var santriIdFilter = cleanString_(request.santriId || '');
  var statusFilter = cleanString_(request.status || '').toLowerCase();
  var dariTanggal = cleanString_(request.dariTanggal || '');
  var sampaiTanggal = cleanString_(request.sampaiTanggal || '');
  var tahunAjaranFilter = cleanString_(request.tahunAjaranId || '');
  var qFilter = cleanString_(request.q || '').toLowerCase();
  var genderFilter = cleanString_(request.gender || '').toLowerCase();

  var genderMap = {};
  var izinStatusMap = {};
  try {
    var ds = loadDataset_();
    (ds.santri || []).forEach(function (s) {
      if (!s.id) return;
      genderMap[cleanString_(s.id)] = normalizeSantriGender_(s.jenisKelamin);
      izinStatusMap[cleanString_(s.id)] = getSantriStatusKey_(s.status || '');
    });
  } catch (_) {}

  // Stats kartu ringkasan: dihitung dari semua data pada tahun ajaran yang sama saja,
  // tanpa terpengaruh filter rentang tanggal/status/pencarian/halaman.
  var izinLabel = STATUS_LABELS.izinPulang.active.toLowerCase();
  var kembaliLabel = STATUS_LABELS.izinPulang.kembali.toLowerCase();
  var todayForStats = nowIso_().slice(0, 10);
  var stats = { izin: 0, kembali: 0, terlambat: 0, dihapus: 0 };
  state.rows.forEach(function (r) {
    if (tahunAjaranFilter && cleanString_(r.tahun_ajaran_id) !== tahunAjaranFilter) return;
    if (isTruthy_(r.is_deleted)) { stats.dihapus += 1; return; }
    var s = cleanString_(r.status || '').toLowerCase();
    if (s === izinLabel) {
      stats.izin += 1;
      var rencana = cleanString_(r.tanggal_kembali_rencana || '');
      if (rencana && rencana < todayForStats) stats.terlambat += 1;
    } else if (s === kembaliLabel) {
      stats.kembali += 1;
    }
  });

  var rows = state.rows.filter(function (r) {
    if (santriIdFilter && cleanString_(r.santri_id) !== santriIdFilter) return false;
    if (tahunAjaranFilter && cleanString_(r.tahun_ajaran_id) !== tahunAjaranFilter) return false;
    if (genderFilter && genderMap[cleanString_(r.santri_id)] !== genderFilter) return false;
    var deleted = isTruthy_(r.is_deleted);
    if (statusFilter === 'dihapus') {
      if (!deleted) return false;
    } else if (statusFilter) {
      if (deleted || cleanString_(r.status || '').toLowerCase() !== statusFilter) return false;
    } else if (deleted) {
      return false;
    }
    var tgl = cleanString_(r.tanggal_izin || '');
    if (dariTanggal && tgl < dariTanggal) return false;
    if (sampaiTanggal && tgl > sampaiTanggal) return false;
    if (qFilter) {
      var hay = [r.santri_nama, r.keperluan, r.izin_oleh, r.input_by_nama, r.catatan].join(' ').toLowerCase();
      if (hay.indexOf(qFilter) === -1) return false;
    }
    return true;
  });
  var sortBy = cleanString_(request.sortBy || 'updated');
  rows.sort(function (a, b) {
    if (sortBy === 'nama_az') return (a.santri_nama || '').localeCompare(b.santri_nama || '', 'id');
    if (sortBy === 'nama_za') return (b.santri_nama || '').localeCompare(a.santri_nama || '', 'id');
    if (sortBy === 'tanggal_asc') return (a.tanggal_izin || '').localeCompare(b.tanggal_izin || '');
    if (sortBy === 'tanggal_desc') return (b.tanggal_izin || '').localeCompare(a.tanggal_izin || '');
    if (sortBy === 'rencana') return (a.tanggal_kembali_rencana || '').localeCompare(b.tanggal_kembali_rencana || '');
    var ua = b.updated_at || b.created_at || ''; var ub = a.updated_at || a.created_at || '';
    return ua.localeCompare(ub);
  });

  var page = parseInt(request.page, 10) || 1;
  var pageSize = Math.min(parseInt(request.pageSize, 10) || 50, 200);
  var total = rows.length;
  var items = rows.slice((page - 1) * pageSize, page * pageSize).map(function (r) {
    var mapped = mapIzinPulangRow_(r);
    mapped.santriGender = genderMap[cleanString_(r.santri_id)] || '';
    mapped.santriStatus = izinStatusMap[cleanString_(r.santri_id)] || 'active';
    return mapped;
  });
  return { ok: true, timestamp: nowIso_(), data: { total: total, page: page, pageSize: pageSize, items: items, stats: stats } };
}

