function mapIzinPulangRow_(r) {
  var fotos = [];
  try { fotos = JSON.parse(r.fotos_json || '[]'); } catch (e) {}
  return { id: r.id, santriId: r.santri_id, santriNama: r.santri_nama, santriNoInduk: r.santri_no_induk, tanggalIzin: r.tanggal_izin, jamIzin: r.jam_izin, tanggalKembaliRencana: r.tanggal_kembali_rencana, jamKembaliRencana: r.jam_kembali_rencana, tanggalKembaliAktual: r.tanggal_kembali_aktual, jamKembaliAktual: r.jam_kembali_aktual, keperluan: r.keperluan, izinOleh: r.izin_oleh, status: r.status, isDeleted: isTruthy_(r.is_deleted), inputById: r.input_by_id, inputByNama: r.input_by_nama, tahunAjaranId: r.tahun_ajaran_id, catatan: r.catatan, hukumanKeterlambatan: cleanString_(r.hukuman_keterlambatan || ''), fotos: fotos, createdAt: r.created_at, updatedAt: r.updated_at, editHistory: r.edit_history || '' };
}

function handleIzinPulangFotoUpload_(request, session) {
  var id = cleanString_(request.id || '');
  if (!id) throw createError_('ID wajib diisi.', 400);
  var state = readSheetState_('izinPulang');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);

  var dataUrl = cleanString_(request.dataUrl || '');
  var originalName = cleanString_(request.name || '') || 'foto';
  if (!dataUrl) throw createError_('Data foto diperlukan.', 400);
  if (dataUrl.length > MAX_IZIN_PULANG_FOTO_BYTES * 1.4) throw createError_('Ukuran foto maksimal 10 MB.', 400);

  var match = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) throw createError_('Format foto tidak valid.', 400);
  var mimeType = match[1].toLowerCase();
  var ext = ALLOWED_IZIN_PULANG_FOTO_MIME[mimeType];
  if (!ext) throw createError_('Hanya file gambar (JPG, PNG, WEBP, GIF) yang diizinkan.', 400);
  var bytes = Buffer.from(match[2], 'base64');
  if (bytes.length > MAX_IZIN_PULANG_FOTO_BYTES) throw createError_('Ukuran foto maksimal 10 MB.', 400);

  var safeName = originalName.replace(/[^a-zA-Z0-9._\-]/g, '_').slice(0, 60);
  var filename = id + '-' + Date.now() + '-' + crypto.randomBytes(4).toString('hex') + '-' + safeName;
  if (!filename.endsWith('.' + ext)) filename = filename.replace(/\.[^.]*$/, '') + '.' + ext;
  fs.mkdirSync(IZIN_PULANG_FOTOS_DIR, { recursive: true });
  fs.writeFileSync(path.join(IZIN_PULANG_FOTOS_DIR, filename), bytes);

  var fotos = [];
  try { fotos = JSON.parse(existing.fotos_json || '[]'); } catch (e) {}
  fotos.push({ name: originalName, path: IZIN_PULANG_FOTOS_DIR_NAME + '/' + filename, size: bytes.length, type: mimeType, uploadedAt: nowIso_() });
  updateSheetRow_(state, existing._rowNumber, { fotos_json: JSON.stringify(fotos), updated_at: nowIso_() });
  return { ok: true, timestamp: nowIso_(), data: { fotos: fotos } };
}

function handleIzinPulangFotoDelete_(request, session) {
  var id = cleanString_(request.id || '');
  var fotoIndex = Number(request.fotoIndex);
  if (!id) throw createError_('ID wajib diisi.', 400);
  if (isNaN(fotoIndex)) throw createError_('fotoIndex diperlukan.', 400);
  var state = readSheetState_('izinPulang');
  var existing = findSheetRowById_(state.rows, id);
  if (!existing) throw createError_('Data tidak ditemukan.', 404);
  var fotos = [];
  try { fotos = JSON.parse(existing.fotos_json || '[]'); } catch (e) {}
  if (fotoIndex < 0 || fotoIndex >= fotos.length) throw createError_('Foto tidak ditemukan.', 404);
  var removed = fotos.splice(fotoIndex, 1)[0];
  if (removed && removed.path) {
    try { fs.unlinkSync(path.join(FRONTEND_DIR, removed.path)); } catch (e) {}
  }
  updateSheetRow_(state, existing._rowNumber, { fotos_json: JSON.stringify(fotos), updated_at: nowIso_() });
  return { ok: true, timestamp: nowIso_(), data: { fotos: fotos } };
}

function handleIzinPulangDeleteAll_(session) {
  requireSuperAdmin_(session);
  var state = readSheetState_('izinPulang');
  state.rows.forEach(function (row) {
    var fotos = [];
    try { fotos = JSON.parse(row.fotos_json || '[]'); } catch (e) {}
    fotos.forEach(function (f) {
      if (f && f.path) { try { fs.unlinkSync(path.join(FRONTEND_DIR, f.path)); } catch (e) {} }
    });
  });
  var rowNumbers = state.rows.map(function (r) { return r._rowNumber; });
  if (rowNumbers.length) deleteSheetRows_(state, rowNumbers);
  return { ok: true, timestamp: nowIso_(), data: { count: rowNumbers.length, message: rowNumbers.length ? 'Semua data izin pulang berhasil dihapus.' : 'Data sudah kosong.' } };
}

// ── Pelanggaran Jenis handlers ───────────────────────────────────────────────

function handlePelanggaranJenisList_(request) {
  var state = readSheetState_('pelanggaranJenis');
  var statusFilter = cleanString_(request.status || '');
  var rows = state.rows.filter(function (r) {
    if (!statusFilter || statusFilter.toLowerCase() === 'all') return true;
    return cleanString_(r.status || '').toLowerCase() === statusFilter.toLowerCase();
  });
  rows.sort(function (a, b) {
    var katOrder = { berat: 0, sedang: 1, ringan: 2 };
    var ka = katOrder[cleanString_(a.kategori || '').toLowerCase()] !== undefined ? katOrder[cleanString_(a.kategori || '').toLowerCase()] : 9;
    var kb = katOrder[cleanString_(b.kategori || '').toLowerCase()] !== undefined ? katOrder[cleanString_(b.kategori || '').toLowerCase()] : 9;
    if (ka !== kb) return ka - kb;
    return (a.nama || '').localeCompare(b.nama || '', 'id');
  });
  return { ok: true, timestamp: nowIso_(), data: { items: rows.map(mapPelanggaranJenisRow_) } };
}

function handlePelanggaranJenisSave_(request, session) {
  if (!canAccessLevel_(session, 'pelanggaranKondisi', 'manage', function (s) { var p = s.permissions; return !!(p && (p.isAdmin || p.isKsantrian)); })) {
    throw createError_('Hanya Admin, Kesantrian, atau jabatan yang diatur di Kelola Addons yang dapat mengelola jenis pelanggaran.', 403);
  }
  var record = parseRecordPayload_(request);
  var state = readSheetState_('pelanggaranJenis');
  var existing = findSheetRowById_(state.rows, record.id);
  var nama = cleanString_(record.nama || (existing ? existing.nama : ''));
  var kategori = cleanString_(record.kategori || (existing ? existing.kategori : ''));
  if (!nama) throw createError_('Nama jenis pelanggaran wajib diisi.', 400);
  if (['berat', 'sedang', 'ringan'].indexOf(kategori.toLowerCase()) === -1) throw createError_('Kategori harus: berat, sedang, atau ringan.', 400);
  var writable = { nama: nama, kategori: kategori.toLowerCase(), deskripsi: cleanString_(record.deskripsi || (existing ? existing.deskripsi : '')), status: 'Aktif' };
  var id;
  if (cleanString_(record.id) && existing) {
    updateSheetRow_(state, existing._rowNumber, writable);
    id = cleanString_(record.id);
  } else {
    writable.id = String(nextId_(state.rows));
    appendSheetRow_(state, writable);
    id = writable.id;
  }
  return { ok: true, timestamp: nowIso_(), data: { id: id, message: existing ? 'Jenis pelanggaran diperbarui.' : 'Jenis pelanggaran ditambahkan.' } };
}

function mapPelanggaranJenisRow_(r) {
  return { id: r.id, nama: r.nama, kategori: r.kategori, deskripsi: r.deskripsi, status: r.status, createdAt: r.created_at, updatedAt: r.updated_at };
}

// ── Pelanggaran handlers ─────────────────────────────────────────────────────

function handlePelanggaranList_(request, session) {
  var state = readSheetState_('pelanggaran');
  var santriIdFilter = cleanString_(request.santriId || '');
  var kategoriFilter = cleanString_(request.kategori || '').toLowerCase();
  var statusFilter = cleanString_(request.status || '').toLowerCase();
  var statusHukumanFilter = cleanString_(request.statusHukuman || '').toLowerCase();
  var genderFilter = cleanString_(request.gender || '').toLowerCase();
  var tahunAjaranFilter = cleanString_(request.tahunAjaranId || '');
  var dariTanggal = cleanString_(request.dariTanggal || '');
  var sampaiTanggal = cleanString_(request.sampaiTanggal || '');
  var qFilter = cleanString_(request.q || '').toLowerCase();
  var sortBy = cleanString_(request.sortBy || 'tanggal_desc');

  var dataset = loadDataset_();
  var genderMap = {};
  var pelanggaranStatusMap = {};
  (dataset.santri || []).forEach(function (s) {
    if (!s.id) return;
    genderMap[String(s.id)] = normalizeSantriGender_(s.jenisKelamin || s.gender || '');
    pelanggaranStatusMap[String(s.id)] = getSantriStatusKey_(s.status || '');
  });

  // Stats kartu ringkasan: dihitung dari semua data pada tahun ajaran yang sama,
  // tanpa terpengaruh filter kategori/status hukuman/pencarian/halaman.
  var stats = { berat: 0, sedang: 0, ringan: 0, menunggu: 0, dihapus: 0 };
  state.rows.forEach(function (r) {
    if (tahunAjaranFilter && cleanString_(r.tahun_ajaran_id) !== tahunAjaranFilter) return;
    if (cleanString_(r.status || '').toLowerCase() === 'dihapus') { stats.dihapus += 1; return; }
    var kat = cleanString_(r.kategori || '').toLowerCase();
    if (kat === 'berat') stats.berat += 1;
    else if (kat === 'sedang') stats.sedang += 1;
    else if (kat === 'ringan') stats.ringan += 1;
    if ((cleanString_(r.status_hukuman || '').toLowerCase() || 'menunggu') === 'menunggu') stats.menunggu += 1;
  });

  var rows = state.rows.filter(function (r) {
    var deleted = cleanString_(r.status || '').toLowerCase() === 'dihapus';
    if (statusFilter === 'dihapus') {
      if (!deleted) return false;
    } else if (deleted) {
      return false;
    }
    if (santriIdFilter && cleanString_(r.santri_id) !== santriIdFilter) return false;
    if (kategoriFilter && cleanString_(r.kategori || '').toLowerCase() !== kategoriFilter) return false;
    if (statusHukumanFilter && cleanString_(r.status_hukuman || '').toLowerCase() !== statusHukumanFilter) return false;
    if (genderFilter) {
      var rGender = genderMap[String(r.santri_id)] || '';
      if (genderFilter === 'l' && rGender !== 'male') return false;
      if (genderFilter === 'p' && rGender !== 'female') return false;
    }
    if (tahunAjaranFilter && cleanString_(r.tahun_ajaran_id) !== tahunAjaranFilter) return false;
    var tgl = cleanString_(r.tanggal || '');
    if (dariTanggal && tgl < dariTanggal) return false;
    if (sampaiTanggal && tgl > sampaiTanggal) return false;
    if (qFilter) {
      var haystack = [r.santri_nama, r.jenis_nama, r.deskripsi, r.input_by_nama, r.hukuman].join(' ').toLowerCase();
      if (haystack.indexOf(qFilter) === -1) return false;
    }
    return true;
  });

  if (sortBy === 'updated') rows.sort(function (a, b) { return (b.updated_at || b.created_at || '').localeCompare(a.updated_at || a.created_at || ''); });
  else if (sortBy === 'nama_az') rows.sort(function (a, b) { return (a.santri_nama || '').localeCompare(b.santri_nama || ''); });
  else if (sortBy === 'nama_za') rows.sort(function (a, b) { return (b.santri_nama || '').localeCompare(a.santri_nama || ''); });
  else if (sortBy === 'tanggal_asc') rows.sort(function (a, b) { return (a.tanggal || a.created_at || '').localeCompare(b.tanggal || b.created_at || ''); });
  else rows.sort(function (a, b) { return (b.tanggal || b.created_at || '').localeCompare(a.tanggal || a.created_at || ''); });

  var page = parseInt(request.page, 10) || 1;
  var pageSize = Math.min(parseInt(request.pageSize, 10) || 50, 200);
  var total = rows.length;
  var items = rows.slice((page - 1) * pageSize, page * pageSize).map(function (r) {
    var mapped = mapPelanggaranRow_(r);
    mapped.santriGender = genderMap[String(r.santri_id)] || '';
    mapped.santriStatus = pelanggaranStatusMap[String(r.santri_id)] || 'active';
    return mapped;
  });

  return { ok: true, timestamp: nowIso_(), data: { total: total, page: page, pageSize: pageSize, items: items, stats: stats } };
}

var ZOOM_TAMPILAN_KAMERA_OPTIONS_ = [
  '', 'sesuai', 'lainnya', 'gambar', 'gelap', 'dinding', 'blur', 'eternit', 'pintu',
  'ruangan', 'jendela', 'foto', 'lantai', 'nama', 'kipas_angin', 'gorden', 'meja', 'kursi', 'lemari'
];

function handleZoomSantriList_(request) {
  var dataset = loadDataset_();
  var now = new Date();
  var bulan = cleanString_(request.bulan || '') || String(now.getMonth() + 1);
  var tahun = cleanString_(request.tahun || '') || String(now.getFullYear());
  var q = cleanString_(request.q || '').toLowerCase();
  var genderFilter = cleanString_(request.gender || '').toLowerCase();
  var page = Math.max(1, parseInt(request.page, 10) || 1);
  var pageSize = Math.min(Math.max(1, parseInt(request.pageSize, 10) || 25), 9999);

  var bulanPadded = bulan.length === 1 ? '0' + bulan : bulan;
  var bulanPrefix = tahun + '-' + bulanPadded;

  var zoomState = readSheetState_('zoom_kehadiran');
  var zoomMap = {};
  zoomState.rows.forEach(function (row) {
    if (cleanString_(row.bulan) !== bulan || cleanString_(row.tahun) !== tahun) return;
    var sId = cleanString_(row.santri_id);
    var pekan = cleanString_(row.pekan);
    if (!sId || !pekan) return;
    if (!zoomMap[sId]) zoomMap[sId] = {};
    zoomMap[sId][pekan] = {
      id: cleanString_(row.id),
      status: cleanString_(row.status) || 'tidak_ada_keterangan',
      jam_masuk: cleanString_(row.jam_masuk || ''),
      kamera_on: cleanString_(row.kamera_on || ''),
      tampilan_kamera: cleanString_(row.tampilan_kamera || ''),
      tampilan_kamera_lainnya: cleanString_(row.tampilan_kamera_lainnya || ''),
      keabsahan: cleanString_(row.keabsahan || ''),
      keterangan: cleanString_(row.keterangan || ''),
      editHistory: cleanString_(row.edit_history || '')
    };
  });

  var pelanggaranState = readSheetState_('pelanggaran');
  var pelMap = {};
  pelanggaranState.rows.forEach(function (row) {
    if (cleanString_(row.status || '').toLowerCase() === 'dihapus') return;
    var tgl = cleanString_(row.tanggal || '');
    if (tgl.indexOf(bulanPrefix) !== 0) return;
    var sId = cleanString_(row.santri_id);
    if (!sId) return;
    if (!pelMap[sId]) pelMap[sId] = [];
    pelMap[sId].push({
      jenisNama: cleanString_(row.jenis_nama || ''),
      kategori: cleanString_(row.kategori || '').toLowerCase(),
      deskripsi: cleanString_(row.deskripsi || ''),
      tanggal: cleanString_(row.tanggal || '')
    });
  });

  var kunjunganState = readSheetState_('zoom_kunjungan');
  var kunjunganMap = {};
  var lastModMap = {};
  kunjunganState.rows.forEach(function (row) {
    if (cleanString_(row.bulan) !== bulan || cleanString_(row.tahun) !== tahun) return;
    var sId = cleanString_(row.santri_id);
    if (!sId) return;
    kunjunganMap[sId] = {
      statusDijenguk: cleanString_(row.status_dijenguk || ''),
      statusKeluar: cleanString_(row.status_keluar || ''),
      catatan: cleanString_(row.catatan || ''),
      editHistory: cleanString_(row.edit_history || ''),
      hasRecord: true
    };
    var t = cleanString_(row.updated_at || row.created_at || '');
    if (t && (!lastModMap[sId] || t > lastModMap[sId])) lastModMap[sId] = t;
  });
  zoomState.rows.forEach(function (row) {
    if (cleanString_(row.bulan) !== bulan || cleanString_(row.tahun) !== tahun) return;
    var sId = cleanString_(row.santri_id);
    if (!sId) return;
    var t = cleanString_(row.updated_at || row.created_at || '');
    if (t && (!lastModMap[sId] || t > lastModMap[sId])) lastModMap[sId] = t;
  });

  var santriList = (dataset.santri || []).filter(function (s) {
    if (!s.id) return false;
    var sk = getSantriStatusKey_(s.status);
    if (sk === 'inactive') return false;
    var g = normalizeSantriGender_(s.jenisKelamin);
    if (genderFilter === 'l' && g !== 'male') return false;
    if (genderFilter === 'p' && g !== 'female') return false;
    if (q) {
      var hay = [s.name, s.namaLengkap, s.noInduk, s.namaPanggilan, s.record && s.record.ayah_nama, s.record && s.record.ibu_nama, s.record && s.record.wali_nama].filter(Boolean).join(' ').toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  });

  santriList.sort(function (a, b) {
    var ta = lastModMap[String(a.id)] || '';
    var tb = lastModMap[String(b.id)] || '';
    if (ta !== tb) return tb > ta ? 1 : -1;
    return (a.name || a.namaLengkap || '').localeCompare(b.name || b.namaLengkap || '', 'id');
  });

  var total = santriList.length;
  var items = santriList.slice((page - 1) * pageSize, page * pageSize).map(function (s) {
    var sId = String(s.id);
    var zoom = zoomMap[sId] || {};
    var pelItems = pelMap[sId] || [];
    var pelCount = pelItems.length;
    var hasBerat = pelItems.some(function (p) { return p.kategori === 'berat'; });
    var pelList = pelItems.slice(0, 3);
    var hadirCount = 0;
    for (var p = 1; p <= 4; p++) {
      var pk = zoom[String(p)];
      if (pk && (pk.status === 'hadir' || pk.status === 'terlambat')) hadirCount++;
    }
    var kunjungan = kunjunganMap[sId] || { statusDijenguk: '', statusKeluar: '', catatan: '' };
    return {
      id: sId,
      name: s.name || s.namaLengkap || '',
      noInduk: s.noInduk || '',
      ayahNama: cleanString_(s.record && s.record.ayah_nama || ''),
      ibuNama: cleanString_(s.record && s.record.ibu_nama || ''),
      waliNama: cleanString_(s.record && s.record.wali_nama || ''),
      gender: normalizeSantriGender_(s.jenisKelamin) || '',
      statusKey: getSantriStatusKey_(s.status),
      zoom: zoom,
      pelanggaranCount: pelCount,
      pelanggaranList: pelList,
      hasBerat: hasBerat,
      hadirCount: hadirCount,
      statusDijenguk: kunjungan.statusDijenguk,
      statusKeluar: kunjungan.statusKeluar,
      kunjunganCatatan: kunjungan.catatan,
      kunjunganEditHistory: kunjungan.editHistory || '',
      kunjunganHasRecord: !!kunjungan.hasRecord
    };
  });

  return { ok: true, timestamp: nowIso_(), data: { total: total, page: page, pageSize: pageSize, items: items, bulan: bulan, tahun: tahun } };
}

function handleZoomKehadiranSave_(request) {
  var santriId = cleanString_(request.santri_id || '');
  var bulan = cleanString_(request.bulan || '');
  var tahun = cleanString_(request.tahun || '');
  var pekan = cleanString_(request.pekan || '');
  if (!santriId || !bulan || !tahun || !pekan) {
    throw createError_('santri_id, bulan, tahun, dan pekan diperlukan.', 400);
  }

  var state = readSheetState_('zoom_kehadiran');
  var existing = null;
  for (var i = 0; i < state.rows.length; i++) {
    var row = state.rows[i];
    if (
      cleanString_(row.santri_id) === santriId &&
      cleanString_(row.bulan) === bulan &&
      cleanString_(row.tahun) === tahun &&
      cleanString_(row.pekan) === pekan
    ) {
      existing = row;
      break;
    }
  }

  var statusVal = cleanString_(request.status || '') || 'tidak_ada_keterangan';
  var kameraVal = cleanString_(request.kamera_on || '');
  if (['1', '0', ''].indexOf(kameraVal) === -1) kameraVal = '';
  var tampilanKameraVal = cleanString_(request.tampilan_kamera || '');
  if (ZOOM_TAMPILAN_KAMERA_OPTIONS_.indexOf(tampilanKameraVal) === -1) tampilanKameraVal = '';
  var keabsahanVal = cleanString_(request.keabsahan || '');
  if (['sah', 'tidak_sah', ''].indexOf(keabsahanVal) === -1) keabsahanVal = '';
  var patch = {
    status: statusVal,
    jam_masuk: cleanString_(request.jam_masuk || ''),
    kamera_on: kameraVal,
    tampilan_kamera: tampilanKameraVal,
    tampilan_kamera_lainnya: tampilanKameraVal === 'lainnya' ? cleanString_(request.tampilan_kamera_lainnya || '') : '',
    keabsahan: keabsahanVal,
    keterangan: cleanString_(request.keterangan || '')
  };

  if (existing) {
    updateSheetRow_(state, existing._rowNumber, patch);
    return { ok: true, timestamp: nowIso_(), data: { id: cleanString_(existing.id), message: 'Kehadiran zoom diperbarui.' } };
  }

  var fresh = readSheetState_('zoom_kehadiran');
  var writable = Object.assign({ id: String(nextId_(fresh.rows)), santri_id: santriId, bulan: bulan, tahun: tahun, pekan: pekan }, patch);
  appendSheetRow_(fresh, writable);
  return { ok: true, timestamp: nowIso_(), data: { id: writable.id, message: 'Kehadiran zoom disimpan.' } };
}

function handleZoomKunjunganSave_(request, session) {
  var santriId = cleanString_(request.santri_id || '');
  var bulan = cleanString_(request.bulan || '');
  var tahun = cleanString_(request.tahun || '');
  if (!santriId || !bulan || !tahun) throw createError_('santri_id, bulan, dan tahun diperlukan.', 400);
  var statusDijenguk = cleanString_(request.status_dijenguk || '');
  var statusKeluar = cleanString_(request.status_keluar || '');
  var catatan = cleanString_(request.catatan || '');
  var valid = ['boleh', 'tidak_boleh', ''];
  if (valid.indexOf(statusDijenguk) === -1) throw createError_('status_dijenguk tidak valid.', 400);
  if (valid.indexOf(statusKeluar) === -1) throw createError_('status_keluar tidak valid.', 400);
  var state = readSheetState_('zoom_kunjungan');
  var existing = null;
  for (var i = 0; i < state.rows.length; i++) {
    var row = state.rows[i];
    if (cleanString_(row.santri_id) === santriId && cleanString_(row.bulan) === bulan && cleanString_(row.tahun) === tahun) {
      existing = row; break;
    }
  }
  var patch = { status_dijenguk: statusDijenguk, status_keluar: statusKeluar, catatan: catatan, updated_by: cleanString_(session.name || String(session.id || '')), updated_at: nowIso_() };
  if (existing) {
    updateSheetRow_(state, existing._rowNumber, patch);
    return { ok: true, timestamp: nowIso_(), data: { id: cleanString_(existing.id), message: 'Status kunjungan diperbarui.' } };
  }
  var fresh = readSheetState_('zoom_kunjungan');
  var writable = Object.assign({ id: String(nextId_(fresh.rows)), santri_id: santriId, bulan: bulan, tahun: tahun, created_at: nowIso_() }, patch);
  appendSheetRow_(fresh, writable);
  return { ok: true, timestamp: nowIso_(), data: { id: writable.id, message: 'Status kunjungan disimpan.' } };
}

function handleSantriKondisiPelanggaran_(request, session) {
  if (session.role !== 'santri') throw createError_('Akses ditolak.', 403);
  var santriId = cleanString_(String(session.id));
  var bulan = cleanString_(request.bulan || '');
  var page = Math.max(1, parseInt(request.page, 10) || 1);
  var pageSize = 10;
  var state = readSheetState_('pelanggaran');
  var rows = state.rows.filter(function (r) {
    if (cleanString_(r.santri_id) !== santriId) return false;
    if (bulan && !cleanString_(r.tanggal || '').startsWith(bulan)) return false;
    return true;
  }).sort(function (a, b) {
    return cleanString_(b.tanggal || '') > cleanString_(a.tanggal || '') ? 1 : -1;
  });
  var total = rows.length;
  var items = rows.slice((page - 1) * pageSize, page * pageSize).map(function (r) {
    return { id: r.id, tanggal: r.tanggal, jenisNama: r.jenis_nama, kategori: r.kategori, deskripsi: r.deskripsi, hukuman: r.hukuman, statusHukuman: r.status_hukuman, catatan: r.catatan, inputByNama: r.input_by_nama };
  });
  return { ok: true, timestamp: nowIso_(), data: { total: total, page: page, pageSize: pageSize, items: items } };
}

