function saveJamDigitalSettings_() {
  var s = jamDigitalState;
  var data = {
    namaMasjid:          s.namaMasjid,
    prayerApi:           s.prayerApi,
    geoLocation:         s.geoLocation,
    myquranCityId:       s.myquranCityId,
    myquranCityName:     s.myquranCityName,
    doNotDisturbEnabled: s.doNotDisturbEnabled,
    preAdzanLockMinutes: s.preAdzanLockMinutes,
    adzanSoundRepeat:    s.adzanSoundRepeat,
    iqomahSoundRepeat:   s.iqomahSoundRepeat,
    iqomahMinutes:       s.iqomahMinutes,
    blackScreenAfterIqomahMinutes: s.blackScreenAfterIqomahMinutes,
    audioFiles:          s.audioFiles,
    audioVersion:        s.audioVersion,
    logoFile:            s.logoFile,
    logoVersion:         s.logoVersion,
    runningText:         s.runningText,
    textSlides:          s.textSlides,
    sleepSchedule:       s.sleepSchedule,
    masterVolume:        s.masterVolume,
    masterMuted:         s.masterMuted
  };
  try {
    var json = JSON.stringify(data);
    var exists = DB.prepare('SELECT id FROM "jam_digital_settings" WHERE id = 1').get();
    if (exists) {
      DB.prepare('UPDATE "jam_digital_settings" SET settings_json = ? WHERE id = 1').run(json);
    } else {
      DB.prepare('INSERT INTO "jam_digital_settings" (id, settings_json) VALUES (1, ?)').run(json);
    }
  } catch (_) {}
}

