  // ── Jam Digital: reset audio ke default (hapus file kustom) ────────────────
  app.post('/api/jam-digital/reset-audio',
    express.json(),
    function (req, res) {
      applyNoStoreHeaders_(res);
      var token = (req.body && req.body.token) || '';
      var session = null;
      try { session = authenticateRequest_(token, false, ''); } catch (_) {}
      var p = (session && session.permissions) ? session.permissions : {};
      if (!canManageAddon_(session, 'jamDigital', ADDON_MANAGE_FALLBACK_.jamDigital)) {
        return res.status(403).json({ ok: false, error: { message: 'Akses ditolak.', code: 403 } });
      }
      var kind = String((req.body && req.body.kind) || 'alarm').toLowerCase();
      if (!['alarm', 'adzan', 'iqomah', 'all'].includes(kind)) kind = 'alarm';
      if (!jamDigitalState.audioFiles) jamDigitalState.audioFiles = {};
      if (kind === 'all') {
        jamDigitalState.audioFiles = {};
      } else {
        delete jamDigitalState.audioFiles[kind];
      }
      jamDigitalState.audioVersion = (jamDigitalState.audioVersion || 0) + 1;
      jamDigitalState.updatedAt = new Date().toISOString();
      saveJamDigitalSettings_();
      broadcastJamDigitalState_();
      res.json({ ok: true, data: jamDigitalState });
    }
  );

