function formatExportTimestamp_(value) {
  return cleanString_(value).replace(/[T:\s]+/g, '-');
}

function parseRequest_(e, method) {
  var params = clonePlainObject_(e && e.parameter ? e.parameter : {});
  var body = {};
  if (method === 'POST' && e && e.postData && e.postData.contents) {
    body = safeJsonParse_(e.postData.contents) || {};
  }
  var request = mergeObjects_(params, body);
  request.record = normalizeStructuredValue_(request.record);
  request.jabatanIds = normalizeStructuredValue_(request.jabatanIds);
  request.pengampuIds = normalizeStructuredValue_(request.pengampuIds);
  request.badalIds = normalizeStructuredValue_(request.badalIds);
  request.santriIds = normalizeStructuredValue_(request.santriIds);
  request.pembinaIds = normalizeStructuredValue_(request.pembinaIds);
  request.pengajarIds = normalizeStructuredValue_(request.pengajarIds);
  request.records = normalizeStructuredValue_(request.records);
  request.drafts = normalizeStructuredValue_(request.drafts);
  request.ids = normalizeStructuredValue_(request.ids);
  request.entries = normalizeStructuredValue_(request.entries);
  request.groups = normalizeStructuredValue_(request.groups);
  request.sheetKeys = normalizeStructuredValue_(request.sheetKeys);
  request.active = normalizeBooleanMaybe_(request.active);
  return request;
}

function parseRecordPayload_(request) {
  var hasNestedRecord = request.record && typeof request.record === 'object';
  var record = hasNestedRecord ? clonePlainObject_(request.record) : clonePlainObject_(request);
  delete record.action;
  delete record.page;
  delete record.pageSize;
  delete record.q;
  if (!hasNestedRecord) {
    delete record.status;
  }
  delete record.token;
  delete record.sheetKey;
  delete record.sheetKeys;
  delete record.ids;
  delete record.records;
  return request && request.importMode ? stripImportMetadataFields_(record) : record;
}

function jsonResponse_(payload) {
  return payload;
}

function getSpreadsheet_() {
  return null;
}

function getHeaderRow_(sheet) {
  if (sheet.getLastRow() === 0 || sheet.getLastColumn() === 0) {
    return [];
  }
  return sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
}

function findMissingColumns_(headerRow, schemaColumns) {
  var remaining = {};
  headerRow.forEach(function (header) {
    var key = cleanString_(header);
    remaining[key] = (remaining[key] || 0) + 1;
  });

  var missing = [];
  schemaColumns.forEach(function (column) {
    var key = cleanString_(column.header);
    if (remaining[key]) {
      remaining[key] -= 1;
      return;
    }
    missing.push(column);
  });
  return missing;
}

function isEmptyRow_(values) {
  for (var i = 0; i < values.length; i += 1) {
    if (cleanString_(values[i]) !== '') {
      return false;
    }
  }
  return true;
}

function findSheetRowById_(rows, id) {
  var target = cleanString_(id);
  for (var i = 0; i < rows.length; i += 1) {
    if (cleanString_(rows[i].id) === target) {
      return rows[i];
    }
  }
  return null;
}

function findById_(items, id) {
  var target = cleanString_(id);
  for (var i = 0; i < items.length; i += 1) {
    if (cleanString_(items[i].id) === target) {
      return items[i];
    }
  }
  return null;
}

function nextId_(rows) {
  var maxId = 0;
  rows.forEach(function (row) {
    var current = parseInt(cleanString_(row.id), 10);
    if (!isNaN(current) && current > maxId) {
      maxId = current;
    }
  });
  return maxId + 1;
}

function indexById_(items) {
  var map = {};
  items.forEach(function (item) {
    map[item.id] = item;
  });
  return map;
}

function labelFromIndex_(index, id) {
  return index[id] ? index[id].name : 'ID ' + id;
}

function tahunAjaranNamaFromIndex_(index, id) {
  if (!id) return '';
  return index[id] ? (index[id].namaDisplay || index[id].nama) : '';
}

function collectDuplicates_(items, fieldName, label) {
  var counter = {};
  items.forEach(function (item) {
    var value = cleanString_(item[fieldName]);
    if (!value) {
      return;
    }
    if (!counter[value]) {
      counter[value] = [];
    }
    counter[value].push({ id: item.id, name: item.name });
  });

  var duplicates = [];
  Object.keys(counter).forEach(function (value) {
    if (counter[value].length > 1) {
      duplicates.push({
        value: value,
        field: label,
        items: counter[value]
      });
    }
  });
  return duplicates;
}

function buildSummaryCount_(items) {
  var total = items.length;
  var active = items.filter(function (item) { return item.active; }).length;
  return {
    total: total,
    active: active,
    inactive: total - active
  };
}

function miniSantriIssue_(santri, rel) {
  return {
    id: santri.id,
    name: santri.name,
    noInduk: santri.noInduk,
    halaqohCount: rel.halaqohIds.length,
    kelasCount: rel.kelasIds.length,
    reguCount: rel.reguIds.length
  };
}

function buildFrozenSantriPlacementIssue_(santri, rel) {
  var issue = miniSantriIssue_(santri, rel);
  var missingParts = [];
  if (!rel.halaqohIds.length) {
    missingParts.push('belum masuk halaqoh');
  }
  if (rel.kelasIds.length < 3) {
    missingParts.push('kelas aktif baru ' + rel.kelasIds.length + '/3');
  }
  if (!rel.reguIds.length) {
    missingParts.push('belum masuk regu');
  }
  if (!missingParts.length) {
    return null;
  }
  issue.missingParts = missingParts;
  return issue;
}

function buildEntityGenderMismatchIssue_(item, entityType, dataset) {
  var expectedKey = getEntityGenderGroupKey_(item && item.genderGroup);
  var mismatchedSantri = [];
  if (expectedKey !== 'ikhwan' && expectedKey !== 'akhowat') {
    return null;
  }
  (item && item.santriIds ? item.santriIds : []).forEach(function (santriId) {
    var santri = dataset.indexes.santriById[santriId];
    var santriGenderKey;
    if (!santri) {
      return;
    }
    santriGenderKey = getSantriGenderGroupKey_(santri);
    if (santriGenderKey && santriGenderKey !== expectedKey) {
      mismatchedSantri.push(santri.name);
    }
  });
  if (!mismatchedSantri.length) {
    return null;
  }
  return {
    id: item.id,
    name: item.name,
    entity: entityType,
    genderGroup: item.genderGroup,
    mismatchCount: mismatchedSantri.length,
    mismatchNames: mismatchedSantri
  };
}

function pushIssueGroup_(groups, key, title, severity, items, shortText) {
  if (!items.length) {
    return;
  }
  groups.push({
    key: key,
    title: title,
    severity: severity,
    count: items.length,
    shortText: shortText,
    items: items
  });
}

function buildSpotlight_(issueGroups) {
  return issueGroups.slice(0, 4).map(function (group) {
    return {
      title: group.title,
      severity: group.severity,
      count: group.count,
      preview: group.items.slice(0, 4)
    };
  });
}

function sortIssueGroups_(a, b) {
  var rank = { high: 0, medium: 1, low: 2, neutral: 3 };
  var aRank = rank[a.severity] !== undefined ? rank[a.severity] : 99;
  var bRank = rank[b.severity] !== undefined ? rank[b.severity] : 99;
  if (aRank !== bRank) {
    return aRank - bRank;
  }
  return b.count - a.count;
}

function sortByActiveThenName_(a, b) {
  if (a.active !== b.active) {
    return a.active ? -1 : 1;
  }
  return cleanString_(a.name).localeCompare(cleanString_(b.name));
}

