function nowIso_() {
  var formatter = new Intl.DateTimeFormat('sv-SE', {
    timeZone: APP_TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });
  var parts = formatter.formatToParts(new Date());
  var map = {};
  parts.forEach(function (part) {
    map[part.type] = part.value;
  });
  return map.year + '-' + map.month + '-' + map.day + 'T' + map.hour + ':' + map.minute + ':' + map.second;
}

function generateToken_(prefix) {
  var raw = crypto.randomUUID().replace(/-/g, '').substring(0, 10).toUpperCase();
  return (prefix || 'TOK') + '-' + raw;
}

// Kolom 'token' di sheet pengurus/santri menyimpan DAFTAR token aktif (JSON array),
// bukan satu token tunggal lagi — supaya satu akun bisa login bersamaan di beberapa
// perangkat (dibatasi jumlahnya lewat getMaxLoginSessions_()). Data lama (pre-migrasi)
// yang masih berupa satu string token polos otomatis diperlakukan sebagai daftar isi 1.
function parseSessionTokens_(raw) {
  var text = cleanString_(raw);
  if (!text) return [];
  try {
    var parsed = JSON.parse(text);
    if (Array.isArray(parsed)) {
      return parsed.map(function (t) { return cleanString_(t); }).filter(Boolean);
    }
  } catch (e) { /* bukan JSON: anggap token tunggal lama */ }
  return [text];
}

function stringifySessionTokens_(tokens) {
  return JSON.stringify(tokens || []);
}

function createError_(message, code) {
  var error = new Error(message);
  error.code = code || 500;
  return error;
}

/* ===================== Dashboard Audit ===================== */

function dashboardPage_(allItems, request) {
  var LIMIT = 10;
  var page = Math.max(1, parseInt(cleanString_(request.page || '')) || 1);
  var start = (page - 1) * LIMIT;
  return { items: allItems.slice(start, start + LIMIT), total: allItems.length, page: page, limit: LIMIT };
}

function buildPjMap_(dataset) {
  var map = {};
  (dataset.pengurus || []).filter(function(p) { return p.active; }).forEach(function(p) {
    map[p.id] = (dataset.jabatanByPengurus[p.id] || []).filter(function(r) { return r.active; }).map(function(r) {
      var j = dataset.indexes.jabatanById[r.idJabatan];
      return j ? normalizeAccessText_(cleanString_(j.name)) : '';
    }).filter(Boolean);
  });
  return map;
}
function pjHasKw_(pjMap, pid, kws) {
  var labels = pjMap[pid] || [];
  return labels.some(function(lbl) { return kws.some(function(kw) { return lbl.indexOf(kw) !== -1; }); });
}

function countStatusAll_(dataset) {
  var santri = { aktif: 0, tidakAktif: 0, dibekukan: 0 };
  (dataset.santri || []).forEach(function (s) {
    var k = getSantriStatusKey_(s.status);
    if (k === 'active') santri.aktif++;
    else if (k === 'dibekukan') santri.dibekukan++;
    else santri.tidakAktif++;
  });
  var pengurus = { aktif: 0, tidakAktif: 0, dibekukan: 0 };
  (dataset.pengurus || []).forEach(function (p) {
    var k = getPengurusStatusKey_(p.status);
    if (k === 'active') pengurus.aktif++;
    else if (k === 'dibekukan') pengurus.dibekukan++;
    else pengurus.tidakAktif++;
  });
  return { santri: santri, pengurus: pengurus };
}

function handleDashboardAdminAudit_(session, request) {
  var dataset = loadDataset_();
  var activeSantri = dataset.santri.filter(function (s) { return getSantriStatusKey_(s.status) === 'active'; });

  var santriDataCheck = [];
  activeSantri.forEach(function (s) {
    var mf = [];
    if (!cleanString_(s.name)) mf.push('Nama');
    if (!cleanString_(s.noInduk)) mf.push('NIS');
    if (!cleanString_(s.tempatLahir)) mf.push('Tempat Lahir');
    if (!cleanString_(s.tanggalLahir)) mf.push('Tanggal Lahir');
    if (!cleanString_(s.jenisKelamin || s.gender)) mf.push('Jenis Kelamin');
    if (!cleanString_(s.alamat)) mf.push('Alamat');
    if (mf.length) santriDataCheck.push({ id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk), missingFields: mf });
  });

  // Kegiatan SOP audits (shared: juga muncul di SDM)
  var activeKegiatanSop = (dataset.kegiatanSop || []).filter(function(k) { return k.active; });
  var kegiatanTanpaJabatan = [], kegiatanTanpaJabatanUtama = [], kegiatanTanpaKategori = [];
  activeKegiatanSop.forEach(function(rawK) {
    var k = enrichKegiatanSop_(rawK, dataset);
    var base = { id: k.id, name: k.name };
    if (!k.pjLabels.length) kegiatanTanpaJabatan.push(base);
    if (!k.jabatanUtama.length) kegiatanTanpaJabatanUtama.push(base);
    if (!cleanString_(k.description)) kegiatanTanpaKategori.push(base);
  });

  var duplikatNik = collectDuplicates_(dataset.santri, 'nik', 'NIK');
  var duplikatNoInduk = collectDuplicates_(dataset.santri, 'noInduk', 'NIS');

  var santriDibekukan = dataset.santri.filter(function(s) { return getSantriStatusKey_(s.status) === 'dibekukan'; }).map(function(s) {
    return { id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk) };
  });

  // Audit akademik santri (2026-08-03): tiap santri aktif wajib TEPAT 1 halaqoh, TEPAT 3
  // kelas siang, TEPAT 1 regu pada tahun ajaran aktif -- kurang ATAU lebih sama-sama
  // dianggap pelanggaran (bukan cuma "belum lengkap"). Direkap di sini (Dashboard Admin)
  // sebagai rekap terpusat untuk semua 3 jenis sekaligus, selain juga muncul terpisah per
  // jenis di dashboard role terkait: halaqoh -> handleDashboardKoordAudit_ (section
  // santriHalaqoh, sudah ada sebelumnya), kelas siang -> handleDashboardAkademikAudit_
  // (section kelasSalah), regu -> handleDashboardKesantrianAudit_ (section santriRegu).
  var aktiveTaAdmin = (dataset.tahunAjaran || []).find(function (ta) { return ta.isAktif; });
  var aktiveTaIdAdmin = aktiveTaAdmin ? aktiveTaAdmin.id : '';
  var halaqohAktifIdsAdmin = {};
  (dataset.halaqoh || []).filter(function (h) { return h.active && (!aktiveTaIdAdmin || h.tahunAjaranId === aktiveTaIdAdmin); }).forEach(function (h) { halaqohAktifIdsAdmin[h.id] = true; });
  var kelasAktifIdsAdmin = {};
  (dataset.kelasSiang || []).filter(function (k) { return k.active && (!aktiveTaIdAdmin || k.tahunAjaranId === aktiveTaIdAdmin); }).forEach(function (k) { kelasAktifIdsAdmin[k.id] = true; });
  var reguAktifIdsAdmin = {};
  (dataset.regu || []).filter(function (r) { return r.active && (!aktiveTaIdAdmin || r.tahunAjaranId === aktiveTaIdAdmin); }).forEach(function (r) { reguAktifIdsAdmin[r.id] = true; });

  var membershipAdmin = dataset.membership.santri;
  var santriHalaqohSalah = [];
  var santriKelasSalah = [];
  var santriReguSalah = [];
  activeSantri.forEach(function (s) {
    var rel = membershipAdmin[s.id] || { halaqohIds: [], kelasIds: [], reguIds: [] };
    var hAktif = (rel.halaqohIds || []).filter(function (id) { return !!halaqohAktifIdsAdmin[id]; });
    if (hAktif.length !== 1) santriHalaqohSalah.push({
      id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
      jumlahHalaqoh: hAktif.length,
      halaqohNames: hAktif.map(function (id) { var h = dataset.indexes.halaqohById[id]; return h ? cleanString_(h.name) : id; })
    });
    var kAktif = (rel.kelasIds || []).filter(function (id) { return !!kelasAktifIdsAdmin[id]; });
    if (kAktif.length !== 3) santriKelasSalah.push({
      id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
      jumlahKelas: kAktif.length,
      kelasNames: kAktif.map(function (id) { var k = dataset.indexes.kelasById[id]; return k ? cleanString_(k.name) : id; })
    });
    var rAktif = (rel.reguIds || []).filter(function (id) { return !!reguAktifIdsAdmin[id]; });
    if (rAktif.length !== 1) santriReguSalah.push({
      id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
      jumlahRegu: rAktif.length,
      reguNames: rAktif.map(function (id) { var r = dataset.indexes.reguById[id]; return r ? cleanString_(r.name) : id; })
    });
  });

  var section = cleanString_(request.section || '');
  if (section === 'santriData') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(santriDataCheck, request) };
  if (section === 'santriDibekukan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(santriDibekukan, request) };
  if (section === 'santriHalaqoh') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(santriHalaqohSalah, request) };
  if (section === 'santriKelas') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(santriKelasSalah, request) };
  if (section === 'santriRegu') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(santriReguSalah, request) };
  if (section === 'kegiatanTanpaJabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaJabatan, request) };
  if (section === 'kegiatanTanpaJabatanUtama') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaJabatanUtama, request) };
  if (section === 'kegiatanTanpaKategori') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaKategori, request) };
  if (section === 'duplikatNik') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(duplikatNik, request) };
  if (section === 'duplikatNoInduk') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(duplikatNoInduk, request) };

  var sc = countStatusAll_(dataset);

  return { ok: true, timestamp: nowIso_(), data: {
    counts: {
      santriData: santriDataCheck.length,
      santriDibekukan: santriDibekukan.length,
      santriHalaqoh: santriHalaqohSalah.length,
      santriKelas: santriKelasSalah.length,
      santriRegu: santriReguSalah.length,
      kegiatanTanpaJabatan: kegiatanTanpaJabatan.length,
      kegiatanTanpaJabatanUtama: kegiatanTanpaJabatanUtama.length,
      kegiatanTanpaKategori: kegiatanTanpaKategori.length,
      duplikatNik: duplikatNik.length,
      duplikatNoInduk: duplikatNoInduk.length
    },
    stats: {
      santriAktif: sc.santri.aktif, santriTidakAktif: sc.santri.tidakAktif, santriDibekukan: sc.santri.dibekukan,
      pengurusAktif: sc.pengurus.aktif, pengurusTidakAktif: sc.pengurus.tidakAktif, pengurusDibekukan: sc.pengurus.dibekukan
    }
  }};
}

function handleDashboardKoordAudit_(session, request) {
  var dataset = loadDataset_();
  var aktiveTa = (dataset.tahunAjaran || []).find(function (ta) { return ta.isAktif; });
  var aktiveTaId = aktiveTa ? aktiveTa.id : '';
  var selectedTaId = cleanString_(request.tahunAjaranId || '') || aktiveTaId;
  var selectedTa = selectedTaId ? (dataset.tahunAjaran || []).find(function (ta) { return ta.id === selectedTaId; }) : aktiveTa;
  var activeHalaqoh = dataset.halaqoh.filter(function (h) { return h.active && (!selectedTaId || h.tahunAjaranId === selectedTaId); });

  var absensiHalaqohIds = {};
  readSheetState_('absensiHalaqoh').rows.forEach(function (r) {
    if (cleanString_(r.status || '').toLowerCase() !== 'nonaktif') absensiHalaqohIds[cleanString_(r.id_halaqoh)] = true;
  });

  var tidakAbsen = [];
  activeHalaqoh.forEach(function (h) {
    if (!absensiHalaqohIds[h.id]) tidakAbsen.push({
      id: h.id, name: cleanString_(h.name),
      pengampuNames: (h.pengampuIds || []).map(function (pid) { var pg = dataset.indexes.pengurusById[pid]; return pg ? cleanString_(pg.name) : pid; })
    });
  });

  var allKw = (ACCESS_CONTROL.pengampuHalaqohJabatanKeywords || ['pengampu']).concat(ACCESS_CONTROL.halaqohCoordinatorJabatanKeywords || ['koordinator halaqoh']);
  var halaqohPengampuIds = {};
  activeHalaqoh.forEach(function (h) { (h.pengampuIds || []).forEach(function (pid) { halaqohPengampuIds[pid] = true; }); });

  var pengampuAktif = [];
  var pengampuTanpaHalaqoh = [];
  dataset.pengurus.filter(function (p) { return p.active; }).forEach(function (p) {
    var labels = (dataset.jabatanByPengurus[p.id] || []).filter(function (r) { return r.active; }).map(function (r) {
      var j = dataset.indexes.jabatanById[r.idJabatan]; return j ? normalizeAccessText_(cleanString_(j.name)) : '';
    }).filter(Boolean);
    if (labels.some(function (lbl) { return allKw.some(function (kw) { return lbl.indexOf(kw) !== -1; }); })) {
      pengampuAktif.push(p.id);
      if (!halaqohPengampuIds[p.id]) pengampuTanpaHalaqoh.push({ id: p.id, name: cleanString_(p.name), jabatanLabels: labels });
    }
  });

  var halaqohKosong = [];
  activeHalaqoh.forEach(function (h) {
    var noPengampu = (h.pengampuIds || []).length === 0;
    var noSantri = (h.santriIds || []).length === 0;
    if (noPengampu || noSantri) halaqohKosong.push({
      id: h.id, name: cleanString_(h.name),
      noPengampu: noPengampu, noSantri: noSantri,
      pengampuCount: (h.pengampuIds || []).length,
      santriCount: (h.santriIds || []).length
    });
  });

  // Gender mismatch
  var halaqohGender = [];
  activeHalaqoh.forEach(function(h) {
    var issue = buildEntityGenderMismatchIssue_(h, 'halaqoh', dataset);
    if (issue) halaqohGender.push(issue);
  });
  // Pengampu tidak berjabatan
  var pengampuKw = ACCESS_CONTROL.pengampuHalaqohJabatanKeywords || ['pengampu'];
  var pjMap = buildPjMap_(dataset);
  var seenPengampuTidakBerjabatan = {};
  var pengampuTidakBerjabatan = [];
  activeHalaqoh.forEach(function(h) {
    (h.pengampuIds || []).concat(h.badalIds || []).forEach(function(pid) {
      var key = pid + '|' + h.id;
      if (seenPengampuTidakBerjabatan[key]) return;
      seenPengampuTidakBerjabatan[key] = true;
      var p = dataset.indexes.pengurusById[pid];
      if (!p) return;
      if (!pjHasKw_(pjMap, pid, pengampuKw)) {
        pengampuTidakBerjabatan.push({ pengurusId: pid, pengurusName: cleanString_(p.name), entityId: h.id, entityName: cleanString_(h.name) });
      }
    });
  });

  var halaqohAktifIds = {};
  activeHalaqoh.forEach(function (h) { halaqohAktifIds[h.id] = true; });
  var activeSantri = dataset.santri.filter(function (s) { return getSantriStatusKey_(s.status) === 'active'; });
  var membership = dataset.membership.santri;
  var santriHalaqoh = [];
  activeSantri.forEach(function (s) {
    var rel = membership[s.id] || { halaqohIds: [] };
    var hAktif = (rel.halaqohIds || []).filter(function (id) { return !!halaqohAktifIds[id]; });
    if (hAktif.length !== 1) santriHalaqoh.push({
      id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
      jumlahHalaqoh: hAktif.length,
      halaqohNames: hAktif.map(function (id) { var h = dataset.indexes.halaqohById[id]; return h ? cleanString_(h.name) : id; })
    });
  });

  var section = cleanString_(request.section || '');
  var taObj = selectedTa ? { id: selectedTa.id, nama: cleanString_(selectedTa.nama), isAktif: !!selectedTa.isAktif } : null;
  if (section === 'absensi') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(tidakAbsen, request)) };
  if (section === 'pengampu') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(pengampuTanpaHalaqoh, request)) };
  if (section === 'halaqohKosong') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(halaqohKosong, request)) };
  if (section === 'santriHalaqoh') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(santriHalaqoh, request)) };
  if (section === 'halaqohGender') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(halaqohGender, request)) };
  if (section === 'pengampuTidakBerjabatan') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(pengampuTidakBerjabatan, request)) };

  var sudahAbsen = activeHalaqoh.length - tidakAbsen.length;
  var taList = (dataset.tahunAjaran || []).map(function (ta) { return { id: ta.id, nama: cleanString_(ta.nama), isAktif: !!ta.isAktif }; });
  var sc = countStatusAll_(dataset);

  return { ok: true, timestamp: nowIso_(), data: {
    tahunAjaran: taObj,
    tahunAjaranList: taList,
    aktiveTaId: aktiveTaId,
    counts: { absensi: tidakAbsen.length, pengampu: pengampuTanpaHalaqoh.length, halaqohKosong: halaqohKosong.length, santriHalaqoh: santriHalaqoh.length, halaqohGender: halaqohGender.length, pengampuTidakBerjabatan: pengampuTidakBerjabatan.length },
    stats: {
      santriAktif: sc.santri.aktif, santriTidakAktif: sc.santri.tidakAktif, santriDibekukan: sc.santri.dibekukan,
      pengurusAktif: sc.pengurus.aktif, pengurusTidakAktif: sc.pengurus.tidakAktif, pengurusDibekukan: sc.pengurus.dibekukan,
      halaqohAktif: activeHalaqoh.length,
      sudahAbsensi: sudahAbsen,
      belumAbsensi: tidakAbsen.length,
      pengampuAktif: pengampuAktif.length
    }
  }};
}

function handleDashboardAkademikAudit_(session, request) {
  var dataset = loadDataset_();
  var aktiveTa = (dataset.tahunAjaran || []).find(function (ta) { return ta.isAktif; });
  var aktiveTaId = aktiveTa ? aktiveTa.id : '';
  var selectedTaId = cleanString_(request.tahunAjaranId || '') || aktiveTaId;
  var selectedTa = selectedTaId ? (dataset.tahunAjaran || []).find(function (ta) { return ta.id === selectedTaId; }) : aktiveTa;
  var activeKelas = dataset.kelasSiang.filter(function (k) { return k.active && (!selectedTaId || k.tahunAjaranId === selectedTaId); });

  var kelasAktifIds = {};
  var kelasPengajarIds = {};
  activeKelas.forEach(function (k) {
    kelasAktifIds[k.id] = true;
    (k.pengajarIds || []).forEach(function (pid) { kelasPengajarIds[pid] = true; });
    (k.badalIds || []).forEach(function (pid) { kelasPengajarIds[pid] = true; });
  });

  var pengajarKw = ACCESS_CONTROL.pengajarJabatanKeywords || ['pengajar', 'guru'];
  var pengajarAktif = [];
  var guruTanpaKelas = [];
  dataset.pengurus.filter(function (p) { return p.active; }).forEach(function (p) {
    var labels = (dataset.jabatanByPengurus[p.id] || []).filter(function (r) { return r.active; }).map(function (r) {
      var j = dataset.indexes.jabatanById[r.idJabatan]; return j ? normalizeAccessText_(cleanString_(j.name)) : '';
    }).filter(Boolean);
    if (labels.some(function (lbl) { return pengajarKw.some(function (kw) { return lbl.indexOf(kw) !== -1; }); })) {
      pengajarAktif.push(p.id);
      if (!kelasPengajarIds[p.id]) guruTanpaKelas.push({ id: p.id, name: cleanString_(p.name), jabatanLabels: labels });
    }
  });

  var kelasKosong = [];
  activeKelas.forEach(function (k) {
    var noPengajar = (k.pengajarIds || []).length === 0 && (k.badalIds || []).length === 0;
    var noSantri = (k.santriIds || []).length === 0;
    if (noPengajar || noSantri) kelasKosong.push({
      id: k.id, name: cleanString_(k.name),
      noPengajar: noPengajar, noSantri: noSantri,
      santriCount: (k.santriIds || []).length
    });
  });

  var activeSantri = dataset.santri.filter(function (s) { return getSantriStatusKey_(s.status) === 'active'; });
  var membership = dataset.membership.santri;

  // Santri aktif wajib TEPAT 3 kelas siang aktif (2026-08-03) -- kurang ATAU lebih dari 3
  // sama-sama pelanggaran, sama prinsipnya dgn santriHalaqoh di handleDashboardKoordAudit_
  // yg sudah lebih dulu mengecek "!== 1" (bukan cuma "< 1").
  var kelasSalah = [];
  activeSantri.forEach(function (s) {
    var rel = membership[s.id] || { kelasIds: [] };
    var kAktif = (rel.kelasIds || []).filter(function (id) { return !!kelasAktifIds[id]; });
    if (kAktif.length !== 3) kelasSalah.push({
      id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
      jumlahKelas: kAktif.length,
      kelasNames: kAktif.map(function (id) { var k = dataset.indexes.kelasById[id]; return k ? cleanString_(k.name) : id; })
    });
  });

  var genderMismatch = [];
  activeSantri.forEach(function (s) {
    var santriGender = normalizeSantriGender_(cleanString_(s.jenisKelamin || s.gender || ''));
    if (!santriGender) return;
    var rel = membership[s.id] || { kelasIds: [] };
    (rel.kelasIds || []).forEach(function (kid) {
      if (!kelasAktifIds[kid]) return;
      var k = dataset.indexes.kelasById[kid];
      if (!k) return;
      var gk = cleanString_(k.gender_group || '').toLowerCase();
      if (!gk || gk === 'campur') return;
      if ((gk === 'ikhwan' && santriGender === 'female') || (gk === 'akhowat' && santriGender === 'male')) {
        genderMismatch.push({
          id: s.id + '_' + kid,
          santriNama: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
          kelasNama: cleanString_(k.name),
          santriGender: santriGender, kelasGenderGroup: gk
        });
      }
    });
  });

  // Pengajar tidak berjabatan
  var pengajarKwAudit = ACCESS_CONTROL.pengajarJabatanKeywords || ['pengajar', 'guru'];
  var pjMapAkademik = buildPjMap_(dataset);
  var seenPengajarTidakBerjabatan = {};
  var pengajarTidakBerjabatan = [];
  activeKelas.forEach(function(k) {
    (k.pengajarIds || []).concat(k.badalIds || []).forEach(function(pid) {
      var key = pid + '|' + k.id;
      if (seenPengajarTidakBerjabatan[key]) return;
      seenPengajarTidakBerjabatan[key] = true;
      var p = dataset.indexes.pengurusById[pid];
      if (!p) return;
      if (!pjHasKw_(pjMapAkademik, pid, pengajarKwAudit)) {
        pengajarTidakBerjabatan.push({ pengurusId: pid, pengurusName: cleanString_(p.name), entityId: k.id, entityName: cleanString_(k.name) });
      }
    });
  });
  // kelasGender
  var kelasGender = [];
  activeKelas.forEach(function(k) {
    var issue = buildEntityGenderMismatchIssue_(k, 'kelasSiang', dataset);
    if (issue) kelasGender.push(issue);
  });

  var section = cleanString_(request.section || '');
  var taObj = selectedTa ? { id: selectedTa.id, nama: cleanString_(selectedTa.nama), isAktif: !!selectedTa.isAktif } : null;
  if (section === 'guru') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(guruTanpaKelas, request)) };
  if (section === 'kelasKosong') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(kelasKosong, request)) };
  if (section === 'kelasSalah') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(kelasSalah, request)) };
  if (section === 'genderMismatch') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(genderMismatch, request)) };
  if (section === 'kelasGender') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(kelasGender, request)) };
  if (section === 'pengajarTidakBerjabatan') return { ok: true, timestamp: nowIso_(), data: Object.assign({ tahunAjaran: taObj }, dashboardPage_(pengajarTidakBerjabatan, request)) };

  var taList = (dataset.tahunAjaran || []).map(function (ta) { return { id: ta.id, nama: cleanString_(ta.nama), isAktif: !!ta.isAktif }; });
  var sc = countStatusAll_(dataset);

  return { ok: true, timestamp: nowIso_(), data: {
    tahunAjaran: taObj,
    tahunAjaranList: taList,
    aktiveTaId: aktiveTaId,
    counts: { guru: guruTanpaKelas.length, kelasKosong: kelasKosong.length, kelasSalah: kelasSalah.length, genderMismatch: genderMismatch.length, kelasGender: kelasGender.length, pengajarTidakBerjabatan: pengajarTidakBerjabatan.length },
    stats: {
      santriAktif: sc.santri.aktif, santriTidakAktif: sc.santri.tidakAktif, santriDibekukan: sc.santri.dibekukan,
      pengurusAktif: sc.pengurus.aktif, pengurusTidakAktif: sc.pengurus.tidakAktif, pengurusDibekukan: sc.pengurus.dibekukan,
      kelasAktif: activeKelas.length,
      pengajarAktif: pengajarAktif.length,
      guruTanpaKelas: guruTanpaKelas.length
    }
  }};
}

function handleDashboardSdmAudit_(session, request) {
  requirePengurus_(session);
  var dataset = loadDataset_();
  var aktiveTa = (dataset.tahunAjaran || []).find(function (ta) { return ta.isAktif; });
  var aktiveTaId = aktiveTa ? aktiveTa.id : '';

  var pengurusTanpaJabatan = [];
  var activePengurus = (dataset.pengurus || []).filter(function (p) { return p.active; });
  activePengurus.forEach(function (p) {
    var aktif = (dataset.jabatanByPengurus[p.id] || []).filter(function (r) { return r.active; });
    if (aktif.length === 0) pengurusTanpaJabatan.push({ id: p.id, name: cleanString_(p.name) });
  });

  // Pengampu tanpa halaqoh (audit yang sama juga ada di handleDashboardKoordAudit_ / pages/dashboardKoordHalaqoh)
  var pengampuKwSdm = (ACCESS_CONTROL.pengampuHalaqohJabatanKeywords || ['pengampu']).concat(ACCESS_CONTROL.halaqohCoordinatorJabatanKeywords || ['koordinator halaqoh']);
  var activeHalaqohSdm = (dataset.halaqoh || []).filter(function (h) { return h.active && (!aktiveTaId || h.tahunAjaranId === aktiveTaId); });
  var halaqohPengampuIdsSdm = {};
  activeHalaqohSdm.forEach(function (h) { (h.pengampuIds || []).forEach(function (pid) { halaqohPengampuIdsSdm[pid] = true; }); });
  var pengampuTanpaHalaqoh = [];
  activePengurus.forEach(function (p) {
    var labels = (dataset.jabatanByPengurus[p.id] || []).filter(function (r) { return r.active; }).map(function (r) {
      var j = dataset.indexes.jabatanById[r.idJabatan]; return j ? normalizeAccessText_(cleanString_(j.name)) : '';
    }).filter(Boolean);
    if (labels.some(function (lbl) { return pengampuKwSdm.some(function (kw) { return lbl.indexOf(kw) !== -1; }); })) {
      if (!halaqohPengampuIdsSdm[p.id]) pengampuTanpaHalaqoh.push({ id: p.id, name: cleanString_(p.name), jabatanLabels: labels });
    }
  });

  // Pengampu/pengajar/pembina tidak menjabat sesuai tugasnya (audit yang sama juga ada di
  // handleDashboardKoordAudit_ / dashboardKoordHalaqoh, handleDashboardAkademikAudit_ / dashboardAkademik,
  // dan handleDashboardKesantrianAudit_ / dashboardKesantrian — diulang di sini agar terlihat terpusat di SDM)
  var pjMapSdm = buildPjMap_(dataset);

  var pengampuKwTidakBerjabatan = ACCESS_CONTROL.pengampuHalaqohJabatanKeywords || ['pengampu'];
  var seenPengampuTidakBerjabatanSdm = {};
  var pengampuTidakBerjabatan = [];
  activeHalaqohSdm.forEach(function (h) {
    (h.pengampuIds || []).concat(h.badalIds || []).forEach(function (pid) {
      var key = pid + '|' + h.id;
      if (seenPengampuTidakBerjabatanSdm[key]) return;
      seenPengampuTidakBerjabatanSdm[key] = true;
      var p = dataset.indexes.pengurusById[pid];
      if (!p) return;
      if (!pjHasKw_(pjMapSdm, pid, pengampuKwTidakBerjabatan)) {
        pengampuTidakBerjabatan.push({ pengurusId: pid, pengurusName: cleanString_(p.name), entityId: h.id, entityName: cleanString_(h.name) });
      }
    });
  });

  var activeKelasSdm = (dataset.kelasSiang || []).filter(function (k) { return k.active && (!aktiveTaId || k.tahunAjaranId === aktiveTaId); });
  var pengajarKwSdm = ACCESS_CONTROL.pengajarJabatanKeywords || ['pengajar', 'guru'];
  var seenPengajarTidakBerjabatanSdm = {};
  var pengajarTidakBerjabatan = [];
  activeKelasSdm.forEach(function (k) {
    (k.pengajarIds || []).concat(k.badalIds || []).forEach(function (pid) {
      var key = pid + '|' + k.id;
      if (seenPengajarTidakBerjabatanSdm[key]) return;
      seenPengajarTidakBerjabatanSdm[key] = true;
      var p = dataset.indexes.pengurusById[pid];
      if (!p) return;
      if (!pjHasKw_(pjMapSdm, pid, pengajarKwSdm)) {
        pengajarTidakBerjabatan.push({ pengurusId: pid, pengurusName: cleanString_(p.name), entityId: k.id, entityName: cleanString_(k.name) });
      }
    });
  });

  var activeReguSdm = (dataset.regu || []).filter(function (r) { return r.active && (!aktiveTaId || r.tahunAjaranId === aktiveTaId); });
  var seenPembinaTidakBerjabatanSdm = {};
  var pembinaTidakBerjabatan = [];
  activeReguSdm.forEach(function (r) {
    (r.pembinaIds || []).forEach(function (pid) {
      var key = pid + '|' + r.id;
      if (seenPembinaTidakBerjabatanSdm[key]) return;
      seenPembinaTidakBerjabatanSdm[key] = true;
      var p = dataset.indexes.pengurusById[pid];
      if (!p) return;
      if (!pjHasKw_(pjMapSdm, pid, ['pembina'])) {
        pembinaTidakBerjabatan.push({ pengurusId: pid, pengurusName: cleanString_(p.name), entityId: r.id, entityName: cleanString_(r.name) });
      }
    });
  });

  // Kegiatan SOP audits (shared dgn Admin + khusus SDM)
  var jabatanNamaSet = {};
  (dataset.jabatan || []).filter(function(j) { return j.active; }).forEach(function(j) {
    jabatanNamaSet[normalizeAccessText_(cleanString_(j.name))] = true;
  });
  var activeKegiatanSop = (dataset.kegiatanSop || []).filter(function(k) { return k.active; });
  var kegiatanTanpaJabatan = [], kegiatanTanpaJabatanUtama = [], kegiatanTanpaKategori = [], kegiatanTanpaSop = [], kegiatanJabatanHilang = [];
  activeKegiatanSop.forEach(function(rawK) {
    var k = enrichKegiatanSop_(rawK, dataset);
    var base = { id: k.id, name: k.name };
    if (!k.pjLabels.length) kegiatanTanpaJabatan.push(base);
    if (!k.jabatanUtama.length) kegiatanTanpaJabatanUtama.push(base);
    if (!cleanString_(k.description)) kegiatanTanpaKategori.push(base);
    if (!k.sopText) kegiatanTanpaSop.push(base);
    var seenBroken = {};
    k.sopItems.forEach(function(si) {
      if (!si.pjLabel) return;
      var normalized = normalizeAccessText_(si.pjLabel);
      if (!jabatanNamaSet[normalized] && !seenBroken[normalized]) {
        seenBroken[normalized] = true;
        kegiatanJabatanHilang.push({ id: k.id, name: k.name, pjLabel: si.pjLabel });
      }
    });
  });

  // Relasi rusak
  var invalidRelasi = [];
  (dataset.halaqoh || []).filter(function(h) { return h.active; }).forEach(function(h) {
    (h.santriIds || []).forEach(function(sid) { if (!dataset.indexes.santriById[sid]) invalidRelasi.push({ entity: 'Halaqoh', entityName: cleanString_(h.name), field: 'santri', missingId: sid }); });
    (h.pengampuIds || []).concat(h.badalIds || []).forEach(function(pid) { if (!dataset.indexes.pengurusById[pid]) invalidRelasi.push({ entity: 'Halaqoh', entityName: cleanString_(h.name), field: 'pengampu', missingId: pid }); });
  });
  (dataset.kelasSiang || []).filter(function(k) { return k.active; }).forEach(function(k) {
    (k.santriIds || []).forEach(function(sid) { if (!dataset.indexes.santriById[sid]) invalidRelasi.push({ entity: 'Kelas', entityName: cleanString_(k.name), field: 'santri', missingId: sid }); });
    (k.pengajarIds || []).concat(k.badalIds || []).forEach(function(pid) { if (!dataset.indexes.pengurusById[pid]) invalidRelasi.push({ entity: 'Kelas', entityName: cleanString_(k.name), field: 'pengajar', missingId: pid }); });
  });
  (dataset.regu || []).filter(function(r) { return r.active; }).forEach(function(r) {
    (r.santriIds || []).forEach(function(sid) { if (!dataset.indexes.santriById[sid]) invalidRelasi.push({ entity: 'Regu', entityName: cleanString_(r.name), field: 'santri', missingId: sid }); });
    (r.pembinaIds || []).forEach(function(pid) { if (!dataset.indexes.pengurusById[pid]) invalidRelasi.push({ entity: 'Regu', entityName: cleanString_(r.name), field: 'pembina', missingId: pid }); });
  });

  var section = cleanString_(request.section || '');
  if (section === 'pengurusTanpaJabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(pengurusTanpaJabatan, request) };
  if (section === 'pengampuTanpaHalaqoh') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(pengampuTanpaHalaqoh, request) };
  if (section === 'pengampuTidakBerjabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(pengampuTidakBerjabatan, request) };
  if (section === 'pengajarTidakBerjabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(pengajarTidakBerjabatan, request) };
  if (section === 'pembinaTidakBerjabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(pembinaTidakBerjabatan, request) };
  if (section === 'kegiatanTanpaJabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaJabatan, request) };
  if (section === 'kegiatanTanpaJabatanUtama') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaJabatanUtama, request) };
  if (section === 'kegiatanTanpaKategori') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaKategori, request) };
  if (section === 'kegiatanTanpaSop') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanTanpaSop, request) };
  if (section === 'kegiatanJabatanHilang') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(kegiatanJabatanHilang, request) };
  if (section === 'invalidRelasi') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(invalidRelasi, request) };

  var sc = countStatusAll_(dataset);
  return { ok: true, timestamp: nowIso_(), data: {
    counts: {
      pengurusTanpaJabatan: pengurusTanpaJabatan.length,
      pengampuTanpaHalaqoh: pengampuTanpaHalaqoh.length,
      pengampuTidakBerjabatan: pengampuTidakBerjabatan.length,
      pengajarTidakBerjabatan: pengajarTidakBerjabatan.length,
      pembinaTidakBerjabatan: pembinaTidakBerjabatan.length,
      kegiatanTanpaJabatan: kegiatanTanpaJabatan.length,
      kegiatanTanpaJabatanUtama: kegiatanTanpaJabatanUtama.length,
      kegiatanTanpaKategori: kegiatanTanpaKategori.length,
      kegiatanTanpaSop: kegiatanTanpaSop.length,
      kegiatanJabatanHilang: kegiatanJabatanHilang.length,
      invalidRelasi: invalidRelasi.length
    },
    stats: {
      santriAktif: sc.santri.aktif, santriTidakAktif: sc.santri.tidakAktif, santriDibekukan: sc.santri.dibekukan,
      pengurusAktif: sc.pengurus.aktif, pengurusTidakAktif: sc.pengurus.tidakAktif, pengurusDibekukan: sc.pengurus.dibekukan,
      pengurusBerJabatan: activePengurus.length - pengurusTanpaJabatan.length,
      pengurusTanpaJabatan: pengurusTanpaJabatan.length
    }
  }};
}

function handleDashboardKesantrianAudit_(session, request) {
  var bulan = cleanString_(request.bulan || '');
  if (!/^\d{4}-\d{2}$/.test(bulan)) bulan = nowIso_().slice(0, 7);
  var dataset = loadDataset_();
  var aktiveTa = (dataset.tahunAjaran || []).find(function (ta) { return ta.isAktif; });
  var aktiveTaId = aktiveTa ? aktiveTa.id : '';
  var selectedTaId = cleanString_(request.tahunAjaranId || '') || aktiveTaId;
  var selectedTa = selectedTaId ? (dataset.tahunAjaran || []).find(function (ta) { return ta.id === selectedTaId; }) : aktiveTa;

  var jenisByName = {};
  readSheetState_('pelanggaranJenis').rows.filter(function (r) { return cleanString_(r.status || '').toLowerCase() !== 'nonaktif'; }).forEach(function (r) {
    var nama = cleanString_(r.nama || '').toLowerCase();
    if (nama) jenisByName[nama] = cleanString_(r.kategori || '').toLowerCase();
  });

  var rekap = { ringan: 0, sedang: 0, berat: 0 };
  var detail = [];
  readSheetState_('pelanggaran').rows.forEach(function (r) {
    if (cleanString_(r.status || '').toLowerCase() === 'dihapus') return;
    var tgl = cleanString_(r.tanggal || r.created_at || '');
    if (tgl.slice(0, 7) !== bulan) return;
    var kategori = cleanString_(r.kategori || '').toLowerCase() || jenisByName[cleanString_(r.jenis_nama || '').toLowerCase()] || '';
    if (rekap[kategori] !== undefined) rekap[kategori]++;
    detail.push({ tanggal: tgl, santriNama: cleanString_(r.santri_nama || ''), jenisNama: cleanString_(r.jenis_nama || ''), kategori: kategori, deskripsi: cleanString_(r.deskripsi || '') });
  });
  detail.sort(function (a, b) { return b.tanggal.localeCompare(a.tanggal); });

  var reguKosong = [];
  (dataset.regu || []).filter(function (r) { return r.active && (!selectedTaId || r.tahunAjaranId === selectedTaId); }).forEach(function (r) {
    var noPembina = (r.pembinaIds || []).length === 0;
    var noSantri = (r.santriIds || []).length === 0;
    if (noPembina || noSantri) reguKosong.push({
      id: r.id, name: cleanString_(r.name),
      noPembina: noPembina, noSantri: noSantri,
      pembinaCount: (r.pembinaIds || []).length,
      santriCount: (r.santriIds || []).length
    });
  });

  // Gender mismatch regu
  var reguGender = [];
  (dataset.regu || []).filter(function(r) { return r.active && (!selectedTaId || r.tahunAjaranId === selectedTaId); }).forEach(function(r) {
    var issue = buildEntityGenderMismatchIssue_(r, 'regu', dataset);
    if (issue) reguGender.push(issue);
  });
  // Pembina tidak berjabatan
  var pjMapKesantrian = buildPjMap_(dataset);
  var seenPembinaTidakBerjabatan = {};
  var pembinaTidakBerjabatan = [];
  (dataset.regu || []).filter(function(r) { return r.active && (!selectedTaId || r.tahunAjaranId === selectedTaId); }).forEach(function(r) {
    (r.pembinaIds || []).forEach(function(pid) {
      var key = pid + '|' + r.id;
      if (seenPembinaTidakBerjabatan[key]) return;
      seenPembinaTidakBerjabatan[key] = true;
      var p = dataset.indexes.pengurusById[pid];
      if (!p) return;
      if (!pjHasKw_(pjMapKesantrian, pid, ['pembina'])) {
        pembinaTidakBerjabatan.push({ pengurusId: pid, pengurusName: cleanString_(p.name), entityId: r.id, entityName: cleanString_(r.name) });
      }
    });
  });

  // Santri aktif wajib TEPAT 1 regu aktif (2026-08-03) -- tidak ada regu ATAU lebih dari 1
  // regu sama-sama pelanggaran, sama pola dgn santriHalaqoh di handleDashboardKoordAudit_.
  var reguAktifIdsForSantri = {};
  (dataset.regu || []).filter(function (r) { return r.active && (!selectedTaId || r.tahunAjaranId === selectedTaId); }).forEach(function (r) { reguAktifIdsForSantri[r.id] = true; });
  var membershipKesantrian = dataset.membership.santri;
  var santriRegu = [];
  (dataset.santri || []).filter(function (s) { return getSantriStatusKey_(s.status) === 'active'; }).forEach(function (s) {
    var rel = membershipKesantrian[s.id] || { reguIds: [] };
    var rAktif = (rel.reguIds || []).filter(function (id) { return !!reguAktifIdsForSantri[id]; });
    if (rAktif.length !== 1) santriRegu.push({
      id: s.id, name: cleanString_(s.name), noInduk: cleanString_(s.noInduk),
      jumlahRegu: rAktif.length,
      reguNames: rAktif.map(function (id) { var r = dataset.indexes.reguById[id]; return r ? cleanString_(r.name) : id; })
    });
  });

  var section = cleanString_(request.section || '');
  if (section === 'pelanggaran') return { ok: true, timestamp: nowIso_(), data: Object.assign({ bulan: bulan, rekap: rekap }, dashboardPage_(detail, request)) };
  if (section === 'reguKosong') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(reguKosong, request) };
  if (section === 'reguGender') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(reguGender, request) };
  if (section === 'pembinaTidakBerjabatan') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(pembinaTidakBerjabatan, request) };
  if (section === 'santriRegu') return { ok: true, timestamp: nowIso_(), data: dashboardPage_(santriRegu, request) };

  var activeSantri = (dataset.santri || []).filter(function (s) { return getSantriStatusKey_(s.status) === 'active'; });
  var activeReguAll = (dataset.regu || []).filter(function (r) { return r.active && (!selectedTaId || r.tahunAjaranId === selectedTaId); });
  var activeJenis = readSheetState_('pelanggaranJenis').rows.filter(function (r) { return cleanString_(r.status || '').toLowerCase() !== 'nonaktif'; });
  var taList = (dataset.tahunAjaran || []).map(function (ta) { return { id: ta.id, nama: cleanString_(ta.nama), isAktif: !!ta.isAktif }; });

  var sc = countStatusAll_(dataset);
  return { ok: true, timestamp: nowIso_(), data: {
    bulan: bulan, rekap: rekap, total: detail.length,
    tahunAjaranList: taList, aktiveTaId: aktiveTaId,
    counts: { reguKosong: reguKosong.length, reguGender: reguGender.length, pembinaTidakBerjabatan: pembinaTidakBerjabatan.length, santriRegu: santriRegu.length },
    stats: {
      santriAktif: sc.santri.aktif, santriTidakAktif: sc.santri.tidakAktif, santriDibekukan: sc.santri.dibekukan,
      pengurusAktif: sc.pengurus.aktif, pengurusTidakAktif: sc.pengurus.tidakAktif, pengurusDibekukan: sc.pengurus.dibekukan,
      reguAktif: activeReguAll.length, jenisAktif: activeJenis.length
    }
  }};
}

// ── Backup & Restore ──────────────────────────────────────────────────────────

function listBackups_() {
  if (!fs.existsSync(BACKUP_DIR)) return [];
  return fs.readdirSync(BACKUP_DIR)
    .filter(function (f) { return f.endsWith('.zip'); })
    .map(function (f) {
      var stat = fs.statSync(path.join(BACKUP_DIR, f));
      return { filename: f, size: stat.size, createdAt: stat.mtime.toISOString() };
    })
    .sort(function (a, b) { return b.filename.localeCompare(a.filename); });
}

function pruneOldBackups_() {
  listBackups_().slice(BACKUP_MAX_COUNT).forEach(function (b) {
    try { fs.unlinkSync(path.join(BACKUP_DIR, b.filename)); } catch (_) {}
  });
}

// adm-zip calls fs.chmodSync() after every file write/extract; some hosts (e.g. Hostinger)
// reject chmod even on files the process itself just created, which would otherwise abort
// an already-successful write. The file content is complete by then, so tolerate EACCES.
function withChmodTolerant_(fn) {
  var original = fs.chmodSync;
  fs.chmodSync = function () {
    try { return original.apply(fs, arguments); } catch (e) { if (e && e.code === 'EACCES') return; throw e; }
  };
  try {
    return fn();
  } finally {
    fs.chmodSync = original;
  }
}

// File "inti" backup (semua KECUALI media upload): database SQLite + sidecar WAL/SHM +
// semua JSON pengaturan penting. Dipakai bareng oleh backup lengkap, backup legacy, dan
// tombol "Download Database Saja".
//   [{ type:'file', src, name }]  -> 1 file, ditaruh di path `name` di dalam zip
// Struktur `data/...` HARUS tetap -- restoreFromBackupZip_ membacanya persis begitu.
// -wal / -shm ikut sebagai jaring pengaman kalau PRAGMA wal_checkpoint(TRUNCATE) belum/tidak
// sempat menyatukan WAL ke file utama (mis. checkpoint dilempar). Urutan: main -> -wal -> -shm.
function collectDbCoreEntries_() {
  var entries = [];
  [DB_PATH, DB_PATH + '-wal', DB_PATH + '-shm'].forEach(function (src) {
    if (fs.existsSync(src)) entries.push({ type: 'file', src: src, name: 'data/' + path.basename(src) });
  });
  [MAINTENANCE_PATH, AUDIT_SETTINGS_PATH, AUDIT_BAWAHAN_SETTINGS_PATH, BACKUP_SETTINGS_PATH, APP_THEME_PATH].forEach(function (src) {
    if (src && fs.existsSync(src)) entries.push({ type: 'file', src: src, name: 'data/' + path.basename(src) });
  });
  // Sengaja HANYA pengaturan ringan WA (enabled/grup tujuan) yg ikut, BUKAN kredensial sesi WA
  // (folder data/whatsapp-auth) -- itu setara akses penuh ke akun WA, tidak boleh ikut ke file
  // backup yg bisa dibagikan/disimpan di tempat lain.
  try {
    var waSettingsPath_ = require('./whatsapp.js').settingsPath;
    if (waSettingsPath_ && fs.existsSync(waSettingsPath_)) entries.push({ type: 'file', src: waSettingsPath_, name: 'data/' + path.basename(waSettingsPath_) });
  } catch (e) {}
  return entries;
}

// Daftar isi backup: file inti (selalu ikut) + folder media upload (`files/<nama>/...`).
// selectedFolderNames: null/undefined = semua folder media (perilaku lama); array = HANYA
// folder yg namanya ada di dalamnya yg diikutkan (lihat backupSettingsState.selectedFolders).
//   [{ type:'dir', src, name }]  -> seluruh isi folder src, di bawah prefix `name`
function collectBackupEntries_(selectedFolderNames) {
  var entries = collectDbCoreEntries_();
  var dirs = Array.isArray(selectedFolderNames)
    ? BACKUP_FILE_DIRS_.filter(function (d) { return selectedFolderNames.indexOf(d.name) !== -1; })
    : BACKUP_FILE_DIRS_;
  dirs.forEach(function (d) {
    if (fs.existsSync(d.src) && fs.readdirSync(d.src).length > 0) {
      entries.push({ type: 'dir', src: d.src, name: 'files/' + d.name });
    }
  });
  return entries;
}

// Ukuran total sebuah folder (rekursif, byte). Dipakai buat tampilan checklist folder di
// halaman backup -- iteratif (bukan rekursi fungsi) supaya aman utk folder yg sangat dalam/besar.
function dirSizeBytes_(dirPath) {
  var total = 0;
  var stack = [dirPath];
  while (stack.length) {
    var cur = stack.pop();
    var stat;
    try { stat = fs.statSync(cur); } catch (e) { continue; }
    if (stat.isDirectory()) {
      var children;
      try { children = fs.readdirSync(cur); } catch (e) { children = []; }
      children.forEach(function (c) { stack.push(path.join(cur, c)); });
    } else {
      total += stat.size;
    }
  }
  return total;
}

function newBackupFilename_() {
  var ts = new Date().toISOString().replace(/:/g, '-').replace(/\..+/, '');
  return 'backup-' + ts + '.zip';
}

// Sisa file *.part (backup yang mati di tengah jalan sebelum di-rename) -- dibersihkan tiap
// job baru mulai supaya tidak menumpuk. listBackups_ sendiri sudah mengabaikannya (bukan .zip).
function sweepStaleBackupParts_() {
  try {
    fs.readdirSync(BACKUP_DIR).forEach(function (f) {
      if (f.endsWith('.part')) { try { fs.unlinkSync(path.join(BACKUP_DIR, f)); } catch (_) {} }
    });
  } catch (_) {}
}

// Jalur BARU: streaming zip ke disk pakai archiver. Puncak RAM ~puluhan MB berapa pun besar
// media-nya (archiver mengalirkan 1 entri demi 1 entri lewat gzip ke write-stream, ada
// backpressure). Balikin Promise<{ filename, size, createdAt }>. Tulis ke `<nama>.part` dulu
// lalu rename -> listBackups_ tak pernah lihat file separuh jadi.
function createBackupStreaming_(selectedFolderNames) {
  return new Promise(function (resolve, reject) {
    try { DB.exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch (_) {}
    var filename = newBackupFilename_();
    var outPath = path.join(BACKUP_DIR, filename);
    var partPath = outPath + '.part';
    var output = fs.createWriteStream(partPath);
    // level 1: media (jpg/mp4/pdf) praktis tak terkompres, jadi jangan buang CPU di level tinggi;
    // yang mengecil signifikan cuma SQLite + JSON, dan level 1 sudah cukup buat itu.
    var archive = archiver('zip', { zlib: { level: 1 } });
    var settled = false;
    function fail(err) {
      if (settled) return; settled = true;
      try { archive.abort(); } catch (_) {}
      try { output.destroy(); } catch (_) {}
      try { fs.unlinkSync(partPath); } catch (_) {}
      reject(err instanceof Error ? err : new Error(String(err && err.message || err)));
    }
    // Diekspos ke backupJobState supaya backup.cancel bisa menghentikan job yg sedang jalan.
    backupJobState._cancelFn = function () { fail(new Error('Dibatalkan oleh pengguna.')); };
    output.on('close', function () {
      if (settled) return; settled = true;
      try {
        fs.renameSync(partPath, outPath);
        backupJobState.phase = 'pruning';
        pruneOldBackups_();
        resolve({ filename: filename, size: fs.statSync(outPath).size, createdAt: nowIso_() });
      } catch (e) { reject(e); }
    });
    output.on('error', fail);
    archive.on('error', fail);
    archive.on('warning', function (err) { if (!err || err.code !== 'ENOENT') fail(err); });
    archive.on('entry', function (entry) { backupJobState.currentFile = (entry && entry.name) || ''; });
    archive.on('progress', function (p) {
      if (p && p.fs && typeof p.fs.processedBytes === 'number') backupJobState.bytes = p.fs.processedBytes;
    });
    archive.pipe(output);
    backupJobState.phase = 'archiving';
    collectBackupEntries_(selectedFolderNames).forEach(function (e) {
      if (e.type === 'file') archive.file(e.src, { name: e.name });
      else archive.directory(e.src, e.name);
    });
    archive.finalize();
  });
}

// Jalur LAMA (fallback kalau `archiver` belum ke-install di host): adm-zip, sinkron, seluruhnya
// di RAM. Dipertahankan cuma sebagai jaring pengaman -- inilah yang OOM di hosting.
function createBackupLegacy_(selectedFolderNames) {
  try { DB.exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch (_) {}
  var zip = new AdmZip();
  collectBackupEntries_(selectedFolderNames).forEach(function (e) {
    if (e.type === 'file') zip.addLocalFile(e.src, path.posix.dirname(e.name));
    else zip.addLocalFolder(e.src, e.name);
  });
  var filename = newBackupFilename_();
  var outPath = path.join(BACKUP_DIR, filename);
  withChmodTolerant_(function () { zip.writeZip(outPath); });
  pruneOldBackups_();
  return { filename: filename, size: fs.statSync(outPath).size, createdAt: nowIso_() };
}

// Mulai job backup di latar belakang. Balik langsung (tidak menunggu selesai). trigger =
// 'manual' | 'auto'. Cuma 1 job jalan sekaligus.
function startBackupJob_(trigger, selectedFolderNames) {
  if (backupJobState.running) return false;
  sweepStaleBackupParts_();
  backupJobState.running = true;
  backupJobState.phase = 'preparing';
  backupJobState.trigger = trigger || 'manual';
  backupJobState.startedAt = nowIso_();
  backupJobState.finishedAt = '';
  backupJobState.currentFile = '';
  backupJobState.bytes = 0;
  backupJobState.result = null;
  backupJobState.error = '';
  backupJobState.cancelRequested = false;
  backupJobState._cancelFn = null;

  var runner = archiver
    ? createBackupStreaming_(selectedFolderNames)
    : new Promise(function (resolve, reject) { try { resolve(createBackupLegacy_(selectedFolderNames)); } catch (e) { reject(e); } });

  runner.then(function (result) {
    backupJobState.result = result;
    backupJobState.phase = 'done';
    if (backupJobState.trigger === 'auto') {
      backupSettingsState.lastAutoBackupAt = nowIso_();
      saveBackupSettings_();
    }
    console.log('[backup] Backup selesai (' + backupJobState.trigger + '):', result.filename, '(' + Math.round(result.size / 1024) + ' KB)');
  }).catch(function (e) {
    if (backupJobState.cancelRequested) {
      backupJobState.phase = 'cancelled';
      backupJobState.error = '';
      console.log('[backup] Backup dibatalkan oleh pengguna (' + backupJobState.trigger + ').');
    } else {
      backupJobState.error = (e && e.message) || String(e);
      backupJobState.phase = 'error';
      console.error('[backup] Backup gagal (' + backupJobState.trigger + '):', backupJobState.error);
    }
  }).then(function () {
    backupJobState.running = false;
    backupJobState.finishedAt = nowIso_();
    backupJobState.cancelRequested = false;
    backupJobState._cancelFn = null;
  });
  return true;
}

// Batalkan job backup yg sedang jalan. Balik false kalau tidak ada job jalan, atau job jalan
// di jalur legacy (adm-zip sinkron) yg tidak bisa diinterupsi di tengah proses.
function cancelBackupJob_() {
  if (!backupJobState.running || typeof backupJobState._cancelFn !== 'function') return false;
  backupJobState.cancelRequested = true;
  backupJobState._cancelFn();
  return true;
}

// Pilihan folder media yg aktif dipakai (shared antara trigger manual & otomatis).
function currentBackupFolderSelection_() {
  return Array.isArray(backupSettingsState.selectedFolders) ? backupSettingsState.selectedFolders : null;
}

function handleBackupList_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  return { ok: true, timestamp: nowIso_(), data: { items: listBackups_() } };
}

function backupJobStatusData_() {
  return {
    running: backupJobState.running,
    phase: backupJobState.phase,
    trigger: backupJobState.trigger,
    startedAt: backupJobState.startedAt,
    finishedAt: backupJobState.finishedAt,
    currentFile: backupJobState.currentFile,
    bytes: backupJobState.bytes,
    result: backupJobState.result,
    error: backupJobState.error,
    streaming: !!archiver,
    cancellable: backupJobState.running && typeof backupJobState._cancelFn === 'function'
  };
}

function handleBackupCreate_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  var started = startBackupJob_('manual', currentBackupFolderSelection_());
  return { ok: true, timestamp: nowIso_(), data: Object.assign({
    started: started,
    message: started ? 'Backup dimulai. Proses berjalan di latar belakang.' : 'Backup lain sedang berjalan.'
  }, backupJobStatusData_()) };
}

function handleBackupCancel_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  if (!backupJobState.running) throw createError_('Tidak ada proses backup yang sedang berjalan.', 400);
  var cancelled = cancelBackupJob_();
  if (!cancelled) throw createError_('Backup ini tidak bisa dibatalkan (berjalan di mode kompatibilitas tanpa streaming).', 400);
  return { ok: true, timestamp: nowIso_(), data: Object.assign({ message: 'Membatalkan backup…' }, backupJobStatusData_()) };
}

function handleBackupSources_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  var coreBytes = 0;
  collectDbCoreEntries_().forEach(function (e) {
    try { coreBytes += fs.statSync(e.src).size; } catch (ex) {}
  });
  var folders = BACKUP_FILE_DIRS_.map(function (d) {
    var exists = fs.existsSync(d.src);
    var fileCount = 0;
    if (exists) { try { fileCount = fs.readdirSync(d.src).length; } catch (ex) {} }
    return {
      name: d.name,
      label: d.label || d.name,
      sizeBytes: exists ? dirSizeBytes_(d.src) : 0,
      empty: !exists || fileCount === 0
    };
  });
  return { ok: true, timestamp: nowIso_(), data: {
    core: { sizeBytes: coreBytes },
    folders: folders,
    selectedFolders: currentBackupFolderSelection_()
  } };
}

function handleBackupStatus_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  return { ok: true, timestamp: nowIso_(), data: backupJobStatusData_() };
}

function handleBackupDelete_(request, session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  var filename = cleanString_(request.filename || '');
  if (!filename || !filename.endsWith('.zip') || filename.indexOf('/') !== -1 || filename.indexOf('..') !== -1) throw createError_('Nama file tidak valid.', 400);
  var filePath = path.join(BACKUP_DIR, filename);
  if (!fs.existsSync(filePath)) throw createError_('File backup tidak ditemukan.', 404);
  fs.unlinkSync(filePath);
  return { ok: true, timestamp: nowIso_(), data: { message: 'Backup dihapus.' } };
}

function restoreFromBackupZip_(zipBuffer) {
  var zip = new AdmZip(zipBuffer);
  var tmpDir = path.join(os.tmpdir(), 'ps-restore-' + Date.now());
  fs.mkdirSync(tmpDir, { recursive: true });
  try {
    withChmodTolerant_(function () { zip.extractAllTo(tmpDir, true); });
    var dbSrc = path.join(tmpDir, 'data', path.basename(DB_PATH));
    if (!fs.existsSync(dbSrc)) throw createError_('File backup tidak valid: tidak mengandung file database.', 400);
    try { DB.exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch (_) {}
    DB.close();
    // Buang sidecar WAL/SHM milik DB LAMA supaya tidak nyampur dgn DB baru (mismatch -shm =
    // satu-satunya hal yg bisa bikin korup). Lalu salin DB baru + -wal dari backup (kalau ada);
    // -shm SENGAJA tidak disalin -- SQLite membangun ulang dari -wal saat file dibuka.
    try { fs.rmSync(DB_PATH + '-wal', { force: true }); } catch (_) {}
    try { fs.rmSync(DB_PATH + '-shm', { force: true }); } catch (_) {}
    fs.copyFileSync(dbSrc, DB_PATH);
    var walSrc = path.join(tmpDir, 'data', path.basename(DB_PATH) + '-wal');
    if (fs.existsSync(walSrc)) fs.copyFileSync(walSrc, DB_PATH + '-wal');
    var maintSrc = path.join(tmpDir, 'data', 'maintenance.json');
    if (fs.existsSync(maintSrc)) fs.copyFileSync(maintSrc, MAINTENANCE_PATH);
    var auditSettingsSrc = path.join(tmpDir, 'data', 'auditSettings.json');
    if (fs.existsSync(auditSettingsSrc)) fs.copyFileSync(auditSettingsSrc, AUDIT_SETTINGS_PATH);
    var auditBawahanSettingsSrc = path.join(tmpDir, 'data', 'auditBawahanSettings.json');
    if (fs.existsSync(auditBawahanSettingsSrc)) fs.copyFileSync(auditBawahanSettingsSrc, AUDIT_BAWAHAN_SETTINGS_PATH);
    var backupSettingsSrc = path.join(tmpDir, 'data', 'backupSettings.json');
    if (fs.existsSync(backupSettingsSrc)) fs.copyFileSync(backupSettingsSrc, BACKUP_SETTINGS_PATH);
    var appThemeSrc = path.join(tmpDir, 'data', 'appTheme.json');
    if (fs.existsSync(appThemeSrc)) fs.copyFileSync(appThemeSrc, APP_THEME_PATH);
    try {
      var waModuleRestore_ = require('./whatsapp.js');
      var waSettingsSrc_ = path.join(tmpDir, 'data', 'whatsappSettings.json');
      if (fs.existsSync(waSettingsSrc_)) { fs.copyFileSync(waSettingsSrc_, waModuleRestore_.settingsPath); waModuleRestore_.reloadSettings(); waModuleRestore_.init(); }
    } catch (e) {}
    var filesSrc = path.join(tmpDir, 'files');
    if (fs.existsSync(filesSrc)) {
      BACKUP_FILE_DIRS_.forEach(function (d) {
        var src = path.join(filesSrc, d.name);
        if (fs.existsSync(src)) {
          fs.rmSync(d.src, { recursive: true, force: true });
          fs.cpSync(src, d.src, { recursive: true });
        }
      });
    }
    DB = new DatabaseSync(DB_PATH);
    applyDbConnectionPragmas_(DB);
    // Lipat -wal (kalau tadi disalin dari backup) ke file utama lalu bersihkan sidecar.
    try { DB.exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch (_) {}
    ensureSchema_();
    try { maintenanceState = JSON.parse(fs.readFileSync(MAINTENANCE_PATH, 'utf8')); } catch (_) { maintenanceState = { active: false, message: '', setBy: '', setAt: '' }; }
    try { auditSettingsState = Object.assign({}, AUDIT_SETTINGS_DEFAULTS, JSON.parse(fs.readFileSync(AUDIT_SETTINGS_PATH, 'utf8'))); } catch (_) { auditSettingsState = Object.assign({}, AUDIT_SETTINGS_DEFAULTS); }
    try { auditBawahanSettingsState = Object.assign({}, AUDIT_BAWAHAN_SETTINGS_DEFAULTS, JSON.parse(fs.readFileSync(AUDIT_BAWAHAN_SETTINGS_PATH, 'utf8'))); } catch (_) { auditBawahanSettingsState = Object.assign({}, AUDIT_BAWAHAN_SETTINGS_DEFAULTS); }
    try { appThemeState = Object.assign({}, APP_THEME_DEFAULTS, JSON.parse(fs.readFileSync(APP_THEME_PATH, 'utf8'))); } catch (_) { appThemeState = Object.assign({}, APP_THEME_DEFAULTS); }
    // Muat ulang setelan backup dari file yg baru dipulihkan (kalau ada) & pasang ulang timer.
    try {
      var restoredBackupSettings = JSON.parse(fs.readFileSync(BACKUP_SETTINGS_PATH, 'utf8'));
      if (restoredBackupSettings && typeof restoredBackupSettings === 'object') {
        backupSettingsState.enabled = restoredBackupSettings.enabled !== false;
        backupSettingsState.intervalHours = BACKUP_INTERVAL_OPTIONS_HOURS.indexOf(parseInt(restoredBackupSettings.intervalHours, 10)) !== -1
          ? parseInt(restoredBackupSettings.intervalHours, 10) : 24;
        backupSettingsState.lastAutoBackupAt = String(restoredBackupSettings.lastAutoBackupAt || '');
        backupSettingsState.selectedFolders = Array.isArray(restoredBackupSettings.selectedFolders)
          ? restoredBackupSettings.selectedFolders.map(String) : null;
        runAutoBackupTimer_();
      }
    } catch (_) {}
    return { ok: true, timestamp: nowIso_(), data: { message: 'Data berhasil dipulihkan dari backup.' } };
  } finally {
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch (_) {}
  }
}

function saveBackupSettings_() {
  try { fs.writeFileSync(BACKUP_SETTINGS_PATH, JSON.stringify(backupSettingsState), 'utf8'); } catch (e) {}
}

function runAutoBackupTimer_() {
  if (autoBackupTimerHandle) {
    clearInterval(autoBackupTimerHandle);
    autoBackupTimerHandle = null;
  }
  if (!backupSettingsState.enabled) return;
  var intervalMs = backupSettingsState.intervalHours * 60 * 60 * 1000;
  autoBackupTimerHandle = setInterval(function () {
    // startBackupJob_ jalan di latar belakang & update lastAutoBackupAt sendiri kalau sukses.
    // Kalau job sebelumnya masih jalan (atau baru saja), dilewati -- tidak menumpuk.
    if (backupJobState.running) return;
    startBackupJob_('auto', currentBackupFolderSelection_());
  }, intervalMs);
}

function scheduleAutoBackup_() {
  setTimeout(runAutoBackupTimer_, 60 * 1000);
}

function handleBackupSettingsGet_(session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  var nextRunAt = '';
  if (backupSettingsState.enabled) {
    var base = backupSettingsState.lastAutoBackupAt ? new Date(backupSettingsState.lastAutoBackupAt).getTime() : Date.now();
    nextRunAt = new Date(base + backupSettingsState.intervalHours * 60 * 60 * 1000).toISOString();
  }
  return { ok: true, timestamp: nowIso_(), data: {
    enabled: backupSettingsState.enabled,
    intervalHours: backupSettingsState.intervalHours,
    lastAutoBackupAt: backupSettingsState.lastAutoBackupAt,
    nextRunAt: nextRunAt,
    intervalOptions: BACKUP_INTERVAL_OPTIONS_HOURS,
    selectedFolders: currentBackupFolderSelection_()
  } };
}

// enabled/intervalHours & selectedFolders masing2 opsional -- request cuma perlu kirim field
// yg mau diubah (halaman backup punya 2 tombol "Simpan" terpisah utk 2 kelompok setelan ini).
function handleBackupSettingsSave_(request, session) {
  if (!session || !session.permissions || !(session.permissions.canDelete || session.permissions.isAdmin)) throw createError_('Hanya admin atau super admin.', 403);
  if (request.enabled !== undefined || request.intervalHours !== undefined) {
    var enabled = String(request.enabled) === 'true' || request.enabled === true;
    var intervalHours = parseInt(request.intervalHours, 10);
    if (BACKUP_INTERVAL_OPTIONS_HOURS.indexOf(intervalHours) === -1) {
      throw createError_('Interval tidak valid. Pilih 6, 12, 24, atau 48 jam.', 400);
    }
    backupSettingsState.enabled = enabled;
    backupSettingsState.intervalHours = intervalHours;
  }
  if (request.selectedFolders !== undefined) {
    var rawSelectedFolders = request.selectedFolders;
    if (rawSelectedFolders === 'all' || rawSelectedFolders === '') {
      backupSettingsState.selectedFolders = null;
    } else {
      var parsedSelectedFolders;
      try {
        parsedSelectedFolders = typeof rawSelectedFolders === 'string' ? JSON.parse(rawSelectedFolders) : rawSelectedFolders;
      } catch (e) {
        throw createError_('Format pilihan folder tidak valid.', 400);
      }
      if (!Array.isArray(parsedSelectedFolders)) throw createError_('Format pilihan folder tidak valid.', 400);
      backupSettingsState.selectedFolders = parsedSelectedFolders.map(String);
    }
  }
  saveBackupSettings_();
  runAutoBackupTimer_();
  return handleBackupSettingsGet_(session);
}

